-- =============================================
-- 다시 실행했을 때: 이전 실행을 먼저 정리함
--   예전에는 스크립트를 한 번 더 실행하면 전에 돌던 반복문/연결/전역 값(getgenv)이 그대로 남아서
--   새로 켠 기능이 안 돌거나(켜진 줄 아는 전역 값 때문에) 두 벌이 같이 돌았음.
--   이제는 새 실행이 시작되기 전에 옛 실행의 기능을 모두 끄고, 옛 UI 를 닫고, 전역 값을 초기화함.
--   getgenv()._8minOnCleanup(fn) 으로 정리 함수를 등록하면 다음 재실행(또는 Unload) 때 불림.
-- =============================================
do
    local genv = getgenv()
    local previous = genv._8minInstance

    if previous then
        for _, fn in ipairs(previous.cleanups) do
            pcall(fn)
        end

        pcall(function()
            if type(genv.VA_Cleanup) == "function" then
                genv.VA_Cleanup()
            end
        end)

        -- 옛 연결 / 켜짐 표시
        for _, key in ipairs({
            "fGrabConnection", "LoopGrabInputConnection", "HyperGrabConnection",
            "SlowHoldConnection", "FKeyInputConnection",
        }) do
            local connection = genv[key]

            if connection ~= nil then
                pcall(function() connection:Disconnect() end)
                genv[key] = nil
            end
        end

        for _, key in ipairs({
            "LoopGrabActive", "FTargetGrabActive", "KickGrabActive", "FKeyAttackActive",
        }) do
            genv[key] = false
        end

        genv.FTargetGrabPlayer = nil

        -- 옛 실행이 들고 있는 설정 표를 비움: 옛 반복문은 켜진 표시가 사라져서 스스로 멈추고, 새 실행은 깨끗한 표로 시작함
        for _, key in ipairs({ "runtimeFlags", "state" }) do
            local old = genv[key]

            if type(old) == "table" then
                pcall(table.clear, old)
            end

            genv[key] = nil
        end

        _G.ShurikenAntiKick = false
        _G.FakePosEnabled = false

        -- 옛 라이브러리를 닫으면 옛 UI 가 지워지고, Library.Unloaded 를 보는 옛 반복문(감독 포함)이 모두 끝남
        pcall(function()
            if previous.library and previous.library ~= Library then
                previous.library:Unload()
            end
        end)
    end

    local instance = { library = Library, cleanups = {}, id = (previous and previous.id or 0) + 1 }

    genv._8minInstance = instance
    genv._8minOnCleanup = function(fn)
        if type(fn) == "function" then
            table.insert(instance.cleanups, fn)
        end
    end

    -- 허브를 닫을 때도 같은 정리를 함
    pcall(function()
        Library:OnUnload(function()
            for _, fn in ipairs(instance.cleanups) do
                pcall(fn)
            end
        end)
    end)
end

-- =============================================
-- 오래 도는 반복 작업 감독 : getgenv()._8minLoop(이름, 본문, 계속할지)
--   에러가 나서 반복문이 죽어도 잠깐 뒤에 다시 시작함. (캐릭터가 죽거나 리셋되는 순간에 한 번 난 에러 때문에
--   그 기능이 끝까지 멈춰 있던 문제를 막음.) 돌려받은 함수를 task.spawn 에 넘기면 됨.
--   본문이 정상적으로 끝나거나, '계속할지' 가 false/nil 을 돌려주거나, 허브를 닫으면 다시 시작하지 않음.
-- =============================================
getgenv()._8minLoop = function(name, body, wanted)
    return function(...)
        local args = table.pack(...)
        local restarts = 0
        local lastWarn = -math.huge

        local function stillWanted()
            if Library.Unloaded then
                return false
            end

            if wanted then
                local okWanted, result = pcall(wanted)

                if okWanted and not result then
                    return false
                end
            end

            return true
        end

        while true do
            local startedAt = os.clock()
            local ok, err = pcall(body, table.unpack(args, 1, args.n))

            if ok then
                return
            end

            if not stillWanted() then
                return
            end

            if os.clock() - startedAt > 15 then
                restarts = 0
            end

            restarts += 1

            if os.clock() - lastWarn > 5 then
                lastWarn = os.clock()
                warn(("[8min] %s: %s (restarting)"):format(tostring(name), tostring(err)))
            end

            task.wait(math.min(0.1 * restarts, 2))

            if not stillWanted() then
                return
            end
        end
    end
end

-- =============================================
-- 알림 (메인 아이콘 + 제목 + 내용) : getgenv()._8minNotify(text, title, kind)
-- kind: "success" | "fail" | "warn" | "info"
-- =============================================
do
    local Players = game:GetService("Players")
    local TweenService = game:GetService("TweenService")
    local CoreGui = game:GetService("CoreGui")
    local LP = Players.LocalPlayer

    local KIND_COLORS = {
        success = Color3.fromRGB(80, 200, 120),
        fail = Color3.fromRGB(235, 80, 80),
        warn = Color3.fromRGB(245, 180, 50),
        info = Color3.fromRGB(150, 150, 160),
    }

    local gui, holder
    local function ensureGui()
        if gui and gui.Parent then return end
        local old = (gethui and gethui() or CoreGui):FindFirstChild("8minNotify")
        if old then old:Destroy() end
        gui = Instance.new("ScreenGui")
        gui.Name = "8minNotify"
        gui.ResetOnSpawn = false
        gui.IgnoreGuiInset = true
        gui.DisplayOrder = 1000
        local ok = pcall(function() gui.Parent = (gethui and gethui()) or CoreGui end)
        if not ok then gui.Parent = LP:WaitForChild("PlayerGui") end
        holder = Instance.new("Frame")
        holder.BackgroundTransparency = 1
        -- 코인 표시 바로 아래, 오른쪽 위에 표시
        holder.AnchorPoint = Vector2.new(1, 0)
        holder.Position = UDim2.new(1, -16, 0, 100)
        holder.Size = UDim2.fromOffset(380, 700)
        holder.Parent = gui
        local layout = Instance.new("UIListLayout")
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.VerticalAlignment = Enum.VerticalAlignment.Top
        layout.Padding = UDim.new(0, 8)
        layout.Parent = holder
    end

    local order = 0
    getgenv()._8minNotify = function(text, title, kind)
        local okAll = pcall(function()
            ensureGui()
            order = order + 1
            local color = KIND_COLORS[kind or "info"] or KIND_COLORS.info
            if getgenv()._8minNotifySound ~= false then
                pcall(function()
                    local snd = Instance.new("Sound")
                    snd.SoundId = getgenv()._8minNotifySoundId or "rbxassetid://140207837688369"
                    snd.Volume = getgenv()._8minNotifyVolume or 1
                    snd.Parent = game:GetService("SoundService")
                    snd.Ended:Connect(function() snd:Destroy() end)
                    snd:Play()
                    task.delay(5, function() if snd then snd:Destroy() end end)
                end)
            end

            local toast = Instance.new("Frame")
            toast.LayoutOrder = order
            toast.Size = UDim2.fromOffset(290, 0)
            toast.AutomaticSize = Enum.AutomaticSize.Y
            toast.BackgroundColor3 = Color3.fromRGB(20, 20, 22)
            toast.BackgroundTransparency = 0.05
            toast.Parent = holder
            Instance.new("UICorner", toast).CornerRadius = UDim.new(0, 10)
            local stroke = Instance.new("UIStroke", toast)
            stroke.Color = color
            stroke.Transparency = 0.5
            local pad = Instance.new("UIPadding", toast)
            pad.PaddingTop = UDim.new(0, 7) pad.PaddingBottom = UDim.new(0, 7)
            pad.PaddingLeft = UDim.new(0, 12) pad.PaddingRight = UDim.new(0, 12)

            -- 메인 아이콘 (qr-code). 라이브러리에서 못 가져오면 노란 8 글자로 대신함
            local iconHolder = Instance.new("Frame")
            iconHolder.BackgroundTransparency = 1
            iconHolder.Size = UDim2.fromOffset(28, 28)
            iconHolder.Parent = toast
            local info
            pcall(function() info = Library:GetIcon("qr-code") end)
            if info and info.Url then
                local img = Instance.new("ImageLabel")
                img.BackgroundTransparency = 1
                img.Size = UDim2.fromScale(1, 1)
                img.Image = info.Url
                if info.ImageRectOffset then img.ImageRectOffset = info.ImageRectOffset end
                if info.ImageRectSize then img.ImageRectSize = info.ImageRectSize end
                img.ImageColor3 = Color3.fromRGB(255, 205, 40)
                img.Parent = iconHolder
            else
                local lbl = Instance.new("TextLabel")
                lbl.BackgroundTransparency = 1
                lbl.Size = UDim2.fromScale(1, 1)
                lbl.Text = "8"
                lbl.Font = Enum.Font.GothamBlack
                lbl.TextSize = 24
                lbl.TextColor3 = Color3.fromRGB(255, 205, 40)
                lbl.Parent = iconHolder
            end

            local content = Instance.new("Frame")
            content.BackgroundTransparency = 1
            content.Position = UDim2.fromOffset(38, 0)
            content.Size = UDim2.new(1, -38, 0, 0)
            content.AutomaticSize = Enum.AutomaticSize.Y
            content.Parent = toast
            local list = Instance.new("UIListLayout", content)
            list.Padding = UDim.new(0, 2)

            local t = Instance.new("TextLabel")
            t.BackgroundTransparency = 1
            t.Size = UDim2.new(1, 0, 0, 17)
            t.Font = Enum.Font.GothamBold
            t.TextSize = 12
            t.TextXAlignment = Enum.TextXAlignment.Left
            t.TextColor3 = color
            t.Text = tostring(title or "8min")
            t.LayoutOrder = 1
            t.Parent = content

            local d = Instance.new("TextLabel")
            d.BackgroundTransparency = 1
            d.Size = UDim2.new(1, 0, 0, 0)
            d.AutomaticSize = Enum.AutomaticSize.Y
            d.Font = Enum.Font.Gotham
            d.TextSize = 10
            d.TextWrapped = true
            d.TextXAlignment = Enum.TextXAlignment.Left
            d.TextYAlignment = Enum.TextYAlignment.Top
            d.TextColor3 = Color3.fromRGB(225, 225, 230)
            d.Text = tostring(text)
            d.LayoutOrder = 2
            d.Parent = content

            task.delay(5, function()
                pcall(function()
                    local tw = TweenService:Create(toast, TweenInfo.new(0.4), { BackgroundTransparency = 1 })
                    TweenService:Create(t, TweenInfo.new(0.4), { TextTransparency = 1 }):Play()
                    TweenService:Create(d, TweenInfo.new(0.4), { TextTransparency = 1 }):Play()
                    TweenService:Create(stroke, TweenInfo.new(0.4), { Transparency = 1 }):Play()
                    tw:Play()
                    tw.Completed:Wait()
                    toast:Destroy()
                end)
                pcall(function() toast:Destroy() end)
            end)
        end)
        if not okAll then
            pcall(function() Library:Notify(tostring(title or "8min") .. ": " .. tostring(text), 5) end)
        end
    end
end

