        for _, d in ipairs(root:GetDescendants()) do
            if d:IsA("TextLabel") and d.Text == "8min_rich_probe" then found = d return end
        end
    end
    pcall(function() scan(gethui and gethui() or game:GetService("CoreGui")) end)
