local FrameTimer = tick()
local FrameCounter = 0
local FPS = 60

RunService.RenderStepped:Connect(function()
    FrameCounter += 1
    if (tick() - FrameTimer) >= 1 then
        FPS = FrameCounter
        FrameTimer = tick()
        FrameCounter = 0
    end
    
    local pingVal = 0
    pcall(function()
        pingVal = math.floor(Stats.Network.ServerStatsItem['Data Ping']:GetValue())
    end)

    local fpsN, pingN = math.floor(FPS), pingVal
    local function hex(c) return string.format("#%02X%02X%02X", c.R*255, c.G*255, c.B*255) end
    local RED, ORANGE, GREEN, BLUE = Color3.fromRGB(255,70,70), Color3.fromRGB(255,160,40), Color3.fromRGB(70,220,90), Color3.fromRGB(70,150,255)
    local fpsCol = (fpsN <= 60 and RED) or (fpsN <= 120 and ORANGE) or (fpsN <= 300 and GREEN) or BLUE
    local pingCol = (pingN <= 90 and BLUE) or (pingN <= 130 and GREEN) or (pingN <= 500 and ORANGE) or RED
    if getgenv()._8minInfoRich then
        DraggableLabel:SetText(('8min | <font color="%s">%d fps</font> | <font color="%s">%d ms</font>'):format(hex(fpsCol), fpsN, hex(pingCol), pingN))
    else
        DraggableLabel:SetText(('8min | %d fps | %d ms'):format(fpsN, pingN))
    end
end)

