local H = {}
function H.charp()
    local character = LocalPlayer.Character
    if not character then return nil, nil, nil end
    local rootPart = character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("Torso")
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    return character, rootPart, humanoid
end

function H.resetVelocity(part)
    if part and part:IsA("BasePart") then
        part.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
        part.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
    end
end

function H.findNicePart(model)
    if typeof(model) ~= "Instance" or not model:IsA("Model") then return nil end
    for _, child in pairs(model:GetChildren()) do
        if child:IsA("BasePart") and child.CanQuery and child.Name ~= "Button" then
            return child
        end
    end
    return nil
end

local settings = {
    CounterMethod = "Kill",
    TargetedLimbCA = "All",
    AntiLagSens = 3,
    AGType = "Normal",
    GucciType = "CreatureBlobman",
    AntiInputType = "FoodHamburger",
    InputLgDelay = 0.05,
    AILTransparency = 1,
    NKOffset = 15,
    NKDelayMode = "Slower but better",
}

local runtimeFlags = {
