--=============================================
;(function()

-- 아이콘 이름 자동 선택: 후보 중 라이브러리에 있는 첫 이름 사용 (없으면 첫 후보)
local function PickIconHome(candidates)
    for _, name in ipairs(candidates) do
        local ok, found = pcall(function() return Library:GetIcon(name) end)
        if ok and found then
            return name
        end
    end
    return candidates[1]
end

-- 플레이어 프리뷰 카드 (3D 미리보기 + 이름 + 상태 + 좌표 + TP / View 버튼)
getgenv()._8minProfileCard = function(group, opts)
    opts = opts or {}
    local container = group and group.Container
    if not container then return nil end
    local P = game:GetService("Players")
    local RS = game:GetService("RunService")
    local me = P.LocalPlayer
    local target = nil
    local viewing = false

    local card = Instance.new("Frame")
    card.Name = "ProfileCard"
    card.Size = UDim2.new(1, 0, 0, 380)
    card.BackgroundColor3 = Color3.fromRGB(12, 12, 18)
    card.BorderSizePixel = 0
    Instance.new("UICorner", card).CornerRadius = UDim.new(0, 10)
    local st = Instance.new("UIStroke", card)
    st.Color = Color3.fromRGB(60, 60, 80) st.Transparency = 0.2 st.Thickness = 1
    local grad = Instance.new("UIGradient", card)
    grad.Rotation = 90
    grad.Color = ColorSequence.new(Color3.fromRGB(8, 8, 20), Color3.fromRGB(26, 14, 40))

    local function lbl(y, h, size, font, color, text)
        local t = Instance.new("TextLabel")
        t.BackgroundTransparency = 1
        t.Position = UDim2.new(0, 0, 0, y)
        t.Size = UDim2.new(1, 0, 0, h)
        t.Font = font
        t.TextSize = size
        t.TextColor3 = color
        t.Text = text or ""
        t.TextTruncate = Enum.TextTruncate.AtEnd
        t.ZIndex = 3
        t.Parent = card
        return t
    end
    local WHITE = Color3.fromRGB(255, 255, 255)
    local nameL = lbl(6, 22, 20, Enum.Font.GothamBlack, WHITE, "No player selected")
    local userL = lbl(27, 18, 15, Enum.Font.GothamBold, Color3.fromRGB(190, 195, 215), "")

    -- 아바타 미리보기 (뷰포트) + 뷰포트가 안될 때를 위한 얼굴 사진
    local viewport = Instance.new("ViewportFrame")
    viewport.Position = UDim2.new(0, 0, 0, 48)
    viewport.Size = UDim2.new(1, 0, 0, 210)
    viewport.BackgroundTransparency = 1
    viewport.Ambient = Color3.fromRGB(180, 180, 190)
    viewport.LightColor = Color3.fromRGB(255, 255, 255)
    viewport.ZIndex = 2
    viewport.Parent = card
    local cam = Instance.new("Camera")
    cam.FieldOfView = 38
    viewport.CurrentCamera = cam
    cam.Parent = viewport
    local headImg = Instance.new("ImageLabel")
    headImg.BackgroundTransparency = 1
    headImg.AnchorPoint = Vector2.new(0.5, 0.5)
    headImg.Position = UDim2.new(0.5, 0, 0, 153)
    headImg.Size = UDim2.fromOffset(120, 120)
    headImg.ZIndex = 1
    headImg.Parent = card

    local statL = lbl(262, 18, 14, Enum.Font.GothamBold, Color3.fromRGB(80, 220, 120), "")
    local studL = lbl(281, 18, 14, Enum.Font.GothamBold, Color3.fromRGB(210, 214, 230), "")
    local posL = lbl(300, 18, 13, Enum.Font.GothamBold, Color3.fromRGB(150, 156, 185), "")

    local function mkBtn(x, w, text)
        local b = Instance.new("TextButton")
        b.AnchorPoint = Vector2.new(0, 0)
        b.Position = UDim2.new(x, x == 0 and 10 or 4, 0, 332)
        b.Size = UDim2.new(w, x == 0 and -14 or -14, 0, 34)
        b.BackgroundColor3 = Color3.fromRGB(34, 34, 46)
        b.AutoButtonColor = true
        b.Font = Enum.Font.GothamBlack
        b.TextSize = 15
        b.TextColor3 = WHITE
        b.Text = text
        b.ZIndex = 3
        b.Parent = card
        Instance.new("UICorner", b).CornerRadius = UDim.new(0, 8)
        return b
    end
    local emptyL
    if opts.emptyText then
        emptyL = Instance.new("TextLabel")
        emptyL.BackgroundTransparency = 1
        emptyL.Size = UDim2.new(1, 0, 1, 0)
        emptyL.Font = Enum.Font.GothamMedium
        emptyL.TextSize = 15
        emptyL.TextColor3 = Color3.fromRGB(120, 124, 145)
        emptyL.Text = opts.emptyText
        emptyL.ZIndex = 4
        emptyL.Parent = card
    end
    local tpBtn = mkBtn(0, 0.5, "TP")
    local viewBtn = mkBtn(0.5, 0.5, "View")

    local function stopView()
        viewing = false
        viewBtn.Text = "View"
        pcall(function()
            local h = me.Character and me.Character:FindFirstChildOfClass("Humanoid")
            if h then workspace.CurrentCamera.CameraSubject = h end
        end)
    end

    tpBtn.MouseButton1Click:Connect(function()
        pcall(function()
            local tr = target and target.Character and target.Character:FindFirstChild("HumanoidRootPart")
            local mr = me.Character and me.Character:FindFirstChild("HumanoidRootPart")
            if tr and mr then mr.CFrame = tr.CFrame * CFrame.new(0, 0, 3) end
        end)
    end)
    viewBtn.MouseButton1Click:Connect(function()
        pcall(function()
            if viewing then stopView() return end
            local h = target and target.Character and target.Character:FindFirstChildOfClass("Humanoid")
            if h then
                workspace.CurrentCamera.CameraSubject = h
                viewing = true
                viewBtn.Text = "Unview"
            end
        end)
    end)

    local clone, cloneOf, pairsList = nil, nil, {}
    local function rebuildClone()
        if clone then clone:Destroy() clone = nil end
        cloneOf = nil
        pairsList = {}
        local ch = target and target.Character
        if not ch then return end
        local ok, c = pcall(function()
            local wasArch = ch.Archivable
            ch.Archivable = true
            local cc = ch:Clone()
            ch.Archivable = wasArch
            return cc
        end)
        if ok and c then
            for _, d in ipairs(c:GetDescendants()) do
                if d:IsA("Script") or d:IsA("LocalScript") or d:IsA("Sound") then pcall(function() d:Destroy() end) end
            end
            local h = c:FindFirstChildOfClass("Humanoid")
            if h then h.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None end
            -- 원본 파츠 <-> 복제 파츠 짝 만들기 (실시간으로 회전/위치를 그대로 따라가게)
            local o = ch:GetDescendants()
            local cl = c:GetDescendants()
            local j = 1
            for i = 1, #o do
                local op = o[i]
                if op:IsA("BasePart") then
                    local cp
                    for k = j, #cl do
                        if cl[k].Name == op.Name and cl[k].ClassName == op.ClassName then cp = cl[k] j = k + 1 break end
                    end
                    if cp then
                        cp.Anchored = true
                        table.insert(pairsList, { op, cp })
                    end
                end
            end
            c.Parent = viewport
            clone, cloneOf = c, ch
        end
    end

    -- 매 프레임: 상대 캐릭터의 실제 움직임(회전 포함)을 그대로 복사, 카메라는 월드 고정 방향
    local orbit = 0
    local syncConn = RS.RenderStepped:Connect(function(dt)
        if not card.Parent then return end
        if not target or card.AbsoluteSize.X <= 0 then return end
        pcall(function()
            local ch = target.Character
            if cloneOf ~= ch then rebuildClone() end
            if not clone then return end
            for _, pr in ipairs(pairsList) do
                if pr[1].Parent then pr[2].CFrame = pr[1].CFrame end
            end
            local cr = clone:FindFirstChild("HumanoidRootPart")
            if cr then
                -- 턴테이블: 카메라가 캐릭터 둘레를 계속 돌면서 보여줌 (상대의 실제 움직임도 같이 반영됨)
                orbit = orbit + dt * 1.3
                local c0 = cr.Position + Vector3.new(0, 0.4, 0)
                local off = Vector3.new(math.sin(orbit) * 8, 1.8 + math.sin(orbit * 0.5) * 1.2, math.cos(orbit) * 8)
                cam.CFrame = CFrame.lookAt(c0 + off, c0)
            end
        end)
    end)
    card.Destroying:Connect(function() syncConn:Disconnect() end)

    local function refresh()
        if not target then return end
        local ch = target.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        local root = ch and ch:FindFirstChild("HumanoidRootPart")
        if hum and hum.Health > 0 then
            statL.Text = string.format("● Alive   HP %d/%d", math.floor(hum.Health), math.floor(hum.MaxHealth))
            statL.TextColor3 = Color3.fromRGB(80, 220, 120)
        else
            statL.Text = "● Dead / Not loaded"
            statL.TextColor3 = Color3.fromRGB(230, 80, 80)
        end
        if root then
            local mr = me.Character and me.Character:FindFirstChild("HumanoidRootPart")
            local d = mr and (mr.Position - root.Position).Magnitude or 0
            studL.Text = string.format("%d Studs", math.floor(d))
            local p = root.Position
            posL.Text = string.format("X %d   Y %d   Z %d", math.floor(p.X), math.floor(p.Y), math.floor(p.Z))
        else
            studL.Text = "- Studs"
            posL.Text = "X -   Y -   Z -"
        end
        headImg.Visible = not (clone and root)
    end

    task.spawn(function()
        while card.Parent do
            task.wait(0.25)
            if target and card.AbsoluteSize.X > 0 then pcall(refresh) end
        end
    end)

    local obj = {}
    local function applyEmpty(isEmpty)
        if not emptyL then return end
        emptyL.Visible = isEmpty
        for _, o in ipairs({ nameL, userL, statL, studL, posL, tpBtn, viewBtn, viewport, headImg }) do
            o.Visible = not isEmpty
        end
        card.Size = UDim2.new(1, 0, 0, isEmpty and 290 or 380)
        pcall(function() if group.Resize then group:Resize() end end)
    end
    function obj.Set(p)
        if viewing then stopView() end
        applyEmpty(p == nil)
        target = p
        if clone then clone:Destroy() clone = nil end
        cloneOf = nil
        if p then
            nameL.Text = p.DisplayName
            userL.Text = "@" .. p.Name
            headImg.Image = string.format("rbxthumb://type=AvatarHeadShot&id=%d&w=420&h=420", p.UserId)
            headImg.Visible = true
            pcall(refresh)
        else
            nameL.Text = "No player selected"
            userL.Text = ""
            statL.Text, studL.Text, posL.Text = "", "", ""
            headImg.Image = ""
        end
    end
    card.Parent = container
    obj.Card = card
    if emptyL then applyEmpty(true) end
    pcall(function() if group.Resize then group:Resize() end end)
    return obj
end

