--=============================================
-- 3D 전신 아바타 (드래그로 회전 + 자동 회전)
--=============================================
local function buildAvatarModel()
    local model = nil

    -- 1순위: 내 캐릭터 복제 (지금 입고 있는 모습 그대로)
    pcall(function()
        local char = plr.Character
        if char then
            char.Archivable = true
            model = char:Clone()
        end
    end)

    -- 2순위: 내 아바타 설정으로 새로 만들기
    if not model then
        pcall(function()
            model = Players:CreateHumanoidModelFromUserId(plr.UserId)
        end)
    end

    if not model then
        return nil
    end

    -- 뷰포트에서는 필요 없는 스크립트/도구 제거
    for _, d in ipairs(model:GetDescendants()) do
        if d:IsA("LuaSourceContainer") or d:IsA("Tool") or d:IsA("ForceField") then
            pcall(function() d:Destroy() end)
        end
    end

    local hum = model:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function() hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None end)
    end

    pcall(function() model:PivotTo(CFrame.new(0, 0, 0)) end)
    return model
end

-- 전신이 화면에 꽉 차도록 카메라를 직접 맞춤 (기본 자동 맞춤은 캐릭터가 작게 나옴)
local function makeAvatarCamera(model)
    local cam = Instance.new("Camera")
    cam.FieldOfView = 30
    local cf, size = model:GetBoundingBox()
    local dist = (size.Y / 2) / math.tan(math.rad(cam.FieldOfView / 2)) * 1.15
    local center = cf.Position
    cam.CFrame = CFrame.lookAt(center + Vector3.new(0, size.Y * 0.05, -dist), center)
    return cam
end

local avatarModel = buildAvatarModel()
local viewportOk = false

if avatarModel then
    -- 1차: 직접 맞춘 카메라로
    local ok, viewport = pcall(function()
        return UserGroup:AddViewport("UserAvatar3D", {
            Object = avatarModel,
            Camera = makeAvatarCamera(avatarModel),
            Clone = false,        -- 원본을 그대로 써야 아래에서 직접 돌릴 수 있음
            AutoFocus = false,
            Interactive = true,   -- 마우스로 드래그해서 회전
            Height = 280,
        })
    end)
    viewportOk = ok and viewport ~= nil

    -- 2차: 라이브러리 자동 맞춤으로
    if not viewportOk then
        local ok2, viewport2 = pcall(function()
            return UserGroup:AddViewport("UserAvatar3DAuto", {
                Object = avatarModel,
                Clone = false,
                AutoFocus = true,
                Interactive = true,
                Height = 280,
            })
        end)
        viewportOk = ok2 and viewport2 ~= nil
    end
end

if viewportOk then
    local spinEnabled = true

    UserGroup:AddToggle("AvatarAutoRotate", {
        Text = "Auto Rotate Avatar",
        Default = true,
        Callback = function(Value)
            spinEnabled = Value
        end,
    })

    RunService.RenderStepped:Connect(function(dt)
        if not spinEnabled or not avatarModel or not avatarModel.Parent then
            return
        end
        pcall(function()
            avatarModel:PivotTo(avatarModel:GetPivot() * CFrame.Angles(0, dt * 0.9, 0))
        end)
    end)
else
    -- 뷰포트를 못 쓰는 라이브러리면: 전신 사진(2D)으로 대체
    local content = nil
    pcall(function()
        content = Players:GetUserThumbnailAsync(
            plr.UserId,
            Enum.ThumbnailType.AvatarThumbnail, -- 전신
            Enum.ThumbnailSize.Size420x420
        )
    end)
    if content then
        pcall(function()
            UserGroup:AddImage("UserAvatar", {
                Image = content,
                Height = 260,
            })
        end)
    end
end

