--=============================================
local friendsCountLabel = FriendsGroup:AddLabel("Friends in server : ...")
local friendsListLabel = FriendsGroup:AddLabel("Checking...", true)
local friendLabels = {}
local friendCard
FriendsGroup:AddDropdown("FriendPreviewTarget", {
    Text = "Friend Preview",
    Values = { "---" },
    Default = 1,
    Callback = function(Value)
        local nm = friendLabels[Value]
        if friendCard then pcall(friendCard.Set, nm and Players:FindFirstChild(nm) or nil) end
    end,
})
pcall(function() friendCard = getgenv()._8minProfileCard(FriendsGroup) end)

local friendCache = {}   -- [UserId] = true/false (한 번 확인한 결과를 잠깐 재사용)
local friendsBusy = false
local friendsPending = false

local function refreshFriends()
    if friendsBusy then
        friendsPending = true -- 확인 중에 또 바뀌면 끝나고 한 번 더
        return
    end
    friendsBusy = true

    repeat
        friendsPending = false

        local names = {}
        local others = 0

        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= plr then
                others = others + 1
                local isFriend = friendCache[p.UserId]
                if isFriend == nil then
                    local ok, res = pcall(function() return plr:IsFriendsWith(p.UserId) end)
                    if ok then
                        isFriend = res == true
                        friendCache[p.UserId] = isFriend
                    else
                        isFriend = false
                    end
                end
                if isFriend then
                    table.insert(names, p.Name)
                    friendLabels[string.format("%s (@%s)", p.DisplayName, p.Name)] = p.Name
                end
            end
        end

        local listText = "None"
        if #names > 0 then
            local shown = {}
            for i = 1, math.min(#names, 6) do
                shown[i] = names[i]
            end
            listText = table.concat(shown, ", ")
            if #names > 6 then
                listText = listText .. string.format(" +%d more", #names - 6)
            end
        end

        pcall(function()
            friendsCountLabel:SetText(string.format("Friends in server : %d / %d", #names, others))
            friendsListLabel:SetText(listText)
        end)
        pcall(function()
            local vals = { "---" }
            for k, nm in pairs(friendLabels) do
                local pl = Players:FindFirstChild(nm)
                if pl then table.insert(vals, k) else friendLabels[k] = nil end
            end
            Options.FriendPreviewTarget:SetValues(vals)
        end)
    until not friendsPending

    friendsBusy = false
end

task.spawn(refreshFriends)

Players.PlayerAdded:Connect(function()
    task.spawn(refreshFriends)
end)

Players.PlayerRemoving:Connect(function(leaving)
    friendCache[leaving.UserId] = nil
    task.delay(0.2, refreshFriends) -- 나간 사람이 목록에서 빠진 뒤에 갱신
end)

-- 새로 친구가 된 경우를 반영하려고 가끔 캐시를 비우고 다시 확인
task.spawn(getgenv()._8minLoop("update-check", function()
    while task.wait(90) do
        friendCache = {}
        refreshFriends()
    end
end))

