-- ---------- Flight (영상 속 비행 스크립트) ----------
-- 땅 위 일정 높이에 떠서(BodyPosition) 이동하고, 이동하면 몸이 앞으로 기울고(BodyGyro),
-- 가만히 있으면 서서 둥실둥실 흔들림. 팔/다리 모양은 아래 애니메이션 ID 의 포즈를 겹쳐서 만듦.
local FLY_TILT = 60       -- 이동할 때 몸이 앞으로 기울어지는 각도 (도)
local FLY_TILTSPD = 10    -- 기울어지는 속도
local FLY_BANK = 100      -- 방향을 틀 때 몸이 옆으로 기우는 정도
local FLY_ACCEL = 10      -- 가속/감속 속도
local FLY_BOB = -0.5      -- 위아래 흔들림 크기 (스터드)
local FLY_BOBF = 2        -- 위아래 흔들림 빠르기
local FLY_IDLETILT = 5    -- 가만히 있을 때 앞뒤로 살짝 흔들리는 각도
local FLY_IDLETILTF = 2   -- 그 빠르기
local FLY_SIDETILT = 3    -- 가만히 있을 때 옆으로 살짝 흔들리는 각도
local FLY_HEIGHT = 4      -- 땅에서 떠 있는 높이 (스터드)

local FLY_KEYS = {
    W = Vector3.new(0, 0, -1),
    S = Vector3.new(0, 0, 1),
    A = Vector3.new(-1, 0, 0),
    D = Vector3.new(1, 0, 0),
}

local FLY_MOVE_ANIM = "rbxassetid://97171309"
local FLY_SLOW_IDLE_ANIM = "rbxassetid://80979216"
local FLY_IDLE_ANIMS = {
    "rbxassetid://233087184", "rbxassetid://162861977", "rbxassetid://160737450",
    "rbxassetid://80979207", "rbxassetid://287325678", "rbxassetid://80979216",
}

local FlightEnabled = false
local flyHumanoid, flyRoot = nil, nil
local flyBodyPosition, flyBodyGyro = nil, nil
local flyGroundY, flySmoothY, flyHeightOffset = 0, 0, 0
local flyTime = 0
local flyInputs = {}
local flySpeedFactor = 0
local flyLastTilt = 0
local flyLastYaw = 0
local flyLastDirection = Vector3.zero
local flyBank = 0
local flyVelocity = Vector3.zero
local flyMoveTrack = nil
local flyIdleTracks = {}
local flyConnections = {}

local function loadFlyMove()
    if flyMoveTrack then
        pcall(function()
            flyMoveTrack:Stop()
            flyMoveTrack:Destroy()
        end)
    end
    local animation = Instance.new("Animation")
    animation.AnimationId = FLY_MOVE_ANIM
    flyMoveTrack = flyHumanoid:LoadAnimation(animation)
    flyMoveTrack.Looped = true
    flyMoveTrack:AdjustSpeed(0)
end

local function playFlyMove()
    if flyMoveTrack and not flyMoveTrack.IsPlaying then
        flyMoveTrack:Play(0.4)
        flyMoveTrack:AdjustSpeed(0)
    end
end

local function stopFlyMove()
    if flyMoveTrack and flyMoveTrack.IsPlaying then
        flyMoveTrack:Stop(0.4)
    end
end

local function loadFlyIdle()
    for _, track in ipairs(flyIdleTracks) do
        pcall(function()
            if track.IsPlaying then track:Stop() end
            track:Destroy()
        end)
    end
    flyIdleTracks = {}
    for _, id in ipairs(FLY_IDLE_ANIMS) do
        local animation = Instance.new("Animation")
        animation.AnimationId = id
        local track = flyHumanoid:LoadAnimation(animation)
        track.Looped = true
        table.insert(flyIdleTracks, track)
    end
end

local function playFlyIdle()
    if flyMoveTrack and flyMoveTrack.IsPlaying then return end
    for _, track in ipairs(flyIdleTracks) do
        if not track.IsPlaying then
            track:Play(0.4)
            if track.Animation.AnimationId == FLY_SLOW_IDLE_ANIM then
                track:AdjustSpeed(0.5)
            else
                track:AdjustSpeed(0)
            end
        end
    end
end

local function stopFlyIdle()
    for _, track in ipairs(flyIdleTracks) do
        if track.IsPlaying then track:Stop(0.4) end
    end
end

local function anyFlyKeyHeld()
    for _, key in ipairs({ "W", "A", "S", "D" }) do
        if flyInputs[key] then return true end
    end
    return false
end

local function stopFly()
    for _, connection in ipairs(flyConnections) do
        connection:Disconnect()
    end
    flyConnections = {}

    if flyBodyPosition then flyBodyPosition:Destroy() flyBodyPosition = nil end
    if flyBodyGyro then flyBodyGyro:Destroy() flyBodyGyro = nil end

    if flyHumanoid and flyHumanoid.Parent then
        flyHumanoid.PlatformStand = false
    end
    stopFlyIdle()
    stopFlyMove()
    for _, track in ipairs(flyIdleTracks) do pcall(function() track:Destroy() end) end
    flyIdleTracks = {}
    if flyMoveTrack then pcall(function() flyMoveTrack:Destroy() end) flyMoveTrack = nil end

    flyInputs = {}
    flyVelocity = Vector3.zero
    flySpeedFactor = 0
end

local function startFly()
    stopFly()

    local _, humanoid, root = getCharacterParts()
    if not (humanoid and root) then return end
    flyHumanoid, flyRoot = humanoid, root

    flyVelocity = Vector3.zero
    flyTime = 0
    flyInputs = {}
    flySpeedFactor = 0
    flyLastTilt = 0
    flyLastDirection = Vector3.zero
    flyBank = 0
    flyHeightOffset = 0

    humanoid.PlatformStand = true

    -- 시작할 때 바라보는 방향: 마우스를 고정(Shift Lock)했으면 카메라 방향, 아니면 지금 캐릭터 방향
    if UserInputService.MouseBehavior == Enum.MouseBehavior.LockCenter then
        local _, yaw = workspace.CurrentCamera.CFrame:ToEulerAnglesYXZ()
        root.CFrame = CFrame.new(root.Position) * CFrame.Angles(0, yaw, 0)
        flyLastYaw = yaw
    else
        local _, yaw = root.CFrame:ToEulerAnglesYXZ()
        flyLastYaw = yaw
    end

    loadFlyMove()

    -- 지금 서 있는 자리의 바닥 높이를 기준으로 그 위 FLY_HEIGHT 에 뜸
    local raycastParams = RaycastParams.new()
    raycastParams.FilterDescendantsInstances = { LocalPlayer.Character }
    raycastParams.FilterType = Enum.RaycastFilterType.Exclude
    local hit = Workspace:Raycast(root.Position, Vector3.new(0, -1000, 0), raycastParams)
    flyGroundY = hit and hit.Position.Y or 0
    flySmoothY = flyGroundY + FLY_HEIGHT

    flyBodyPosition = Instance.new("BodyPosition")
    flyBodyPosition.MaxForce = Vector3.new(1e9, 1e9, 1e9)
    flyBodyPosition.D = 800
    flyBodyPosition.P = 40000
    flyBodyPosition.Position = root.Position
    flyBodyPosition.Parent = root

    flyBodyGyro = Instance.new("BodyGyro")
    flyBodyGyro.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
    flyBodyGyro.P = 1e4
    flyBodyGyro.CFrame = root.CFrame
    flyBodyGyro.Parent = root

    stopFlyIdle()
    loadFlyIdle()
    playFlyIdle()
    stopFlyMove()

    -- 키를 누르면 이동 포즈, 모두 떼면 가만히 있는 포즈
    table.insert(flyConnections, UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if gameProcessed then return end
        if FLY_KEYS[input.KeyCode.Name] then
            flyInputs[input.KeyCode.Name] = true
            stopFlyIdle()
            playFlyMove()
        end
    end))

    table.insert(flyConnections, UserInputService.InputEnded:Connect(function(input, gameProcessed)
        if gameProcessed then return end
        if flyInputs[input.KeyCode.Name] then
            flyInputs[input.KeyCode.Name] = nil
            if not anyFlyKeyHeld() then
                stopFlyMove()
                playFlyIdle()
            end
        end
    end))

    table.insert(flyConnections, RunService.RenderStepped:Connect(function(dt)
        if not (flyRoot and flyRoot.Parent) then return end

        local inputVector = Vector3.zero
        for key, held in pairs(flyInputs) do
            if held and FLY_KEYS[key] then
                inputVector = inputVector + FLY_KEYS[key]
            end
        end
        if inputVector.Magnitude > 0 then inputVector = inputVector.Unit end

        local _, cameraYaw = workspace.CurrentCamera.CFrame:ToEulerAnglesYXZ()
        local cameraCFrame = CFrame.Angles(0, cameraYaw, 0)
        local worldVector = cameraCFrame:VectorToWorldSpace(inputVector)
        worldVector = Vector3.new(worldVector.X, 0, worldVector.Z)

        local moving = worldVector.Magnitude > 0
        local direction = Vector3.zero
        if moving then
            direction = worldVector.Unit
            flyLastDirection = direction
        elseif flyVelocity.Magnitude > 0 then
            direction = flyLastDirection
        end

        local topSpeed = FlightSpeedValue * 50
        if moving then
            flySpeedFactor = math.clamp(flySpeedFactor + 0.5 * dt, 0, 1)
            flyVelocity = flyVelocity:Lerp(direction * (topSpeed * flySpeedFactor), math.clamp(FLY_ACCEL * dt, 0, 1))
        else
            flySpeedFactor = 0
            flyVelocity = flyVelocity:Lerp(Vector3.zero, math.clamp(FLY_ACCEL * dt, 0, 1))
        end

        flyTime = flyTime + dt

        -- 가만히 있을 때: 앞뒤/옆으로 살짝씩 흔들림
        local idleWave = (math.sin(flyTime * FLY_IDLETILTF) + 1) / 2
        local idleTilt = -FLY_IDLETILT * idleWave
        local sideTilt = 0
        if not moving then
            sideTilt = FLY_SIDETILT * math.sin(flyTime * -1 + math.pi)
        end

        -- 이동하면 몸이 앞으로 FLY_TILT 도 기울어짐 (부드럽게)
        local targetTilt = moving and -FLY_TILT or 0
        flyLastTilt = flyLastTilt + (targetTilt - flyLastTilt) * math.clamp(dt * FLY_TILTSPD, 0, 1)
        local currentTilt = flyLastTilt + idleTilt

        -- 바라보는 방향: Shift Lock 이면 카메라 방향, 아니면 가는 방향
        local previousYaw = flyLastYaw
        if moving then
            if UserInputService.MouseBehavior == Enum.MouseBehavior.LockCenter then
                local _, yaw = cameraCFrame:ToEulerAnglesYXZ()
                flyLastYaw = yaw
            elseif flyVelocity.Magnitude > 0.1 then
                flyLastYaw = math.atan2(-flyVelocity.X, -flyVelocity.Z)
            end
        end

        -- 방향을 틀 때 몸이 옆으로 기울어짐
        local yawDelta = flyLastYaw - previousYaw
        local clampedYawDelta = math.clamp(yawDelta, -math.rad(10), math.rad(10))
        local targetBank = (clampedYawDelta / math.rad(10)) * FLY_BANK
        flyBank = flyBank + (targetBank - flyBank) * math.clamp(dt * 5, 0, 1)

        -- 위아래로 둥실둥실 (Space/Ctrl 로 높이도 조절)
        local bob = math.sin(flyTime * FLY_BOBF) * FLY_BOB
        local vertical = 0
        if UserInputService:IsKeyDown(Enum.KeyCode.Space) then vertical = vertical + 1 end
        if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then vertical = vertical - 1 end
        flyHeightOffset = flyHeightOffset + vertical * 40 * dt

        local targetY = flyGroundY + FLY_HEIGHT + flyHeightOffset + bob
        flySmoothY = flySmoothY + (targetY - flySmoothY) * (1 - math.exp(-dt * 10))

        if flyBodyPosition then
            flyBodyPosition.Position = Vector3.new(
                flyRoot.Position.X + flyVelocity.X * dt,
                flySmoothY,
                flyRoot.Position.Z + flyVelocity.Z * dt
            )
        end

        if flyBodyGyro then
            flyBodyGyro.CFrame = CFrame.new(Vector3.new(flyRoot.Position.X, flySmoothY, flyRoot.Position.Z))
                * CFrame.Angles(0, flyLastYaw, 0)
                * CFrame.Angles(0, 0, math.rad(flyBank + sideTilt))
                * CFrame.Angles(math.rad(currentTilt), 0, 0)
        end
    end))
end

local FlightToggle = CharacterGroup:AddCheckbox("FlyToggle", {
    Text = "Flight",
    Default = false,
    Callback = function(Value)
        FlightEnabled = Value
        if Value then startFly() else stopFly() end
    end,
})
addKeyPicker(FlightToggle, "FlightKey", "Flight keybind")

-- 죽거나 리스폰하면 비행을 다시 시작.
-- 새 캐릭터가 다 로드될 때까지 기다리며 시작될 때까지 다시 시도함 (예전에는 1초 뒤에 딱 한 번만 시도해서, 로딩이 느리면 비행이 꺼진 채로 남았음)
LocalPlayer.CharacterAdded:Connect(function(character)
    if not FlightEnabled then return end

    stopFly()
    task.wait(1)

    for _ = 1, 40 do
        if not FlightEnabled or LocalPlayer.Character ~= character then return end

        startFly()

        if flyRoot and flyRoot.Parent and flyRoot:IsDescendantOf(character) then
            return
        end

        task.wait(0.25)
    end
end)

-- ---------- Walkspeed ----------
-- 게임이 WalkSpeed 값을 되돌려 버려도 되도록, 값을 바꾸는 대신 걷는 방향으로 직접 조금씩 더 이동시킴.
-- 목표 속도(슬라이더 값)에서 지금 걷는 속도(보통 16)를 뺀 만큼만 더해서, 합친 속도가 슬라이더 값이 되게 함
local walkConnection = nil

local WalkToggle = CharacterGroup:AddCheckbox("WalkToggle", {
    Text = "Walkspeed",
    Default = false,
    Callback = function(Value)
        if walkConnection then
            walkConnection:Disconnect()
            walkConnection = nil
        end
        if Value then
            walkConnection = RunService.Stepped:Connect(function(_, deltaTime)
                local _, humanoid, root = getCharacterParts()
                if not (humanoid and root) then return end

                local moveDirection = humanoid.MoveDirection
                if moveDirection.Magnitude < 0.01 then return end

                local extraSpeed = WalkSpeedValue - humanoid.WalkSpeed
                if extraSpeed > 0 then
                    root.CFrame = root.CFrame + moveDirection * (extraSpeed * deltaTime)
                end
            end)
        end
    end,
})
addKeyPicker(WalkToggle, "WalkSpeedKey", "Walkspeed keybind")

-- ---------- Jump Power ----------
local JumpConnection = nil
local JumpEnabled = false
local jumpOriginal = nil

local JumpToggle = CharacterGroup:AddCheckbox("JumpToggle", {
    Text = "Jump Power",
    Default = false,
    Callback = function(Value)
        JumpEnabled = Value
        if Value then
            local _, humanoid = getCharacterParts()
            if humanoid and not jumpOriginal then
                jumpOriginal = { UseJumpPower = humanoid.UseJumpPower, JumpPower = humanoid.JumpPower, JumpHeight = humanoid.JumpHeight }
            end
            if JumpConnection then JumpConnection:Disconnect() end
            JumpConnection = RunService.Heartbeat:Connect(function()
                if not JumpEnabled then return end
                local _, hum = getCharacterParts()
                if hum then
                    hum.UseJumpPower = true
                    hum.JumpPower = JumpPowerValue
                end
            end)
        else
            if JumpConnection then JumpConnection:Disconnect() JumpConnection = nil end
            local _, hum = getCharacterParts()
            if hum then
                local original = jumpOriginal
                if original then
                    -- false 값도 그대로 복구 (이전 코드는 false 를 true 로 바꿔버렸음)
                    hum.UseJumpPower = original.UseJumpPower
                    hum.JumpPower = original.JumpPower
                    hum.JumpHeight = original.JumpHeight
                end
            end
            jumpOriginal = nil
        end
    end,
})
addKeyPicker(JumpToggle, "JumpPowerKey", "Jump Power keybind")

