-- ---------- Noclip ----------
local NoclipConnection = nil
local NoclipEnabled = false

local noclipSaved = {}   -- [파트] = 원래 CanCollide 값 (노클립이 바꾼 파트만 기록)

local function restoreNoclip()
    for part, original in pairs(noclipSaved) do
        pcall(function()
            if part and part.Parent then part.CanCollide = original end
        end)
    end
    noclipSaved = {}
end

local NoclipToggle = CharacterGroup:AddCheckbox("NoclipToggle", {
    Text = "Noclip",
    Default = false,
    Callback = function(Value)
        NoclipEnabled = Value
        if NoclipConnection then
            NoclipConnection:Disconnect()
            NoclipConnection = nil
        end
        if Value then
            NoclipConnection = RunService.Stepped:Connect(function()
                if not NoclipEnabled then return end
                local character = getCharacterParts()
                if character then
                    for _, part in ipairs(character:GetDescendants()) do
                        if part:IsA("BasePart") and part.CanCollide then
                            noclipSaved[part] = true
                            part.CanCollide = false
                        end
                    end
                end
            end)
        else
            -- 끄면 노클립이 꺼뒀던 충돌을 원래대로 복구
            restoreNoclip()
        end
    end,
})
addKeyPicker(NoclipToggle, "NoclipKey", "Noclip keybind")

