-- ---------- Jerk Off ----------
local JERK_ANIM_ID = "rbxassetid://168268306"
local JerkTrack = nil
local JerkEnabled = false
local JerkStyle = "IY"

local function StopJerk()
    if JerkTrack then
        pcall(function()
            JerkTrack:Stop()
            JerkTrack:Destroy()
        end)
        JerkTrack = nil
    end
end

local function StartJerk()
    StopJerk()
    local _, humanoid = getCharacterParts()
    if not humanoid then return end
    local animator = humanoid:FindFirstChildOfClass("Animator")
    if not animator then
        animator = Instance.new("Animator")
        animator.Parent = humanoid
    end
    local animation = Instance.new("Animation")
    animation.AnimationId = JERK_ANIM_ID
    local success, track = pcall(function()
        return animator:LoadAnimation(animation)
    end)
    animation:Destroy()
    if not success or not track then return end
    JerkTrack = track
    JerkTrack.Priority = Enum.AnimationPriority.Action
    JerkTrack.Looped = true
    JerkTrack:Play()
    task.spawn(function()
        while JerkEnabled and JerkTrack == track do
            -- IY: 0.1초마다 되감기 / Fast: 0.05초마다 되감기
            if JerkStyle == "Fast" then
                task.wait(0.05)
            else
                task.wait(0.1)
            end
            if track.IsPlaying then
                pcall(function()
                    track.TimePosition = 0.3
                end)
            end
        end
    end)
end

-- 죽거나 리스폰하면 다시 시작 (새 캐릭터가 만들어지면 재생 중이던 애니메이션이 같이 사라져서, 예전에는 꺼진 채로 남았음)
LocalPlayer.CharacterAdded:Connect(function(character)
    if not JerkEnabled then return end

    StopJerk()
    character:WaitForChild("Humanoid", 10)
    task.wait(0.5)

    for _ = 1, 20 do
        if not JerkEnabled or LocalPlayer.Character ~= character then return end

        StartJerk()

        if JerkTrack then return end

        task.wait(0.5)
    end
end)

local JerkOffToggle = CharacterGroup:AddCheckbox("JerkOffToggle", {
    Text = "Jerk Off",
    Default = false,
    Callback = function(Value)
        JerkEnabled = Value
        if Value then StartJerk() else StopJerk() end
    end,
})
addKeyPicker(JerkOffToggle, "JerkOffKey", "Jerk Off keybind")

CharacterGroup:AddDropdown("JerkOffStyle", {
