    Default = 1,
    Tooltip = "Fast: rewinds twice as often as IY (every 0.05s).",
    Callback = function(Value)
        JerkStyle = Value
    end,
})

-- =============================================
-- Teleporting
-- =============================================
local TeleportGroup = Tabs.Player:AddRightGroupbox("Teleporting", PickIconPlayer({ "house", "home" }))

local LOCATIONS = {
    "TudorHouse", "PinkRoofHouse", "SpookyHouse", "GlassHouse", "Factory", "Barn",
    "BlueHouse", "Train", "JapaneseHouse", "Safe Platform",
}
local selectedLocation = LOCATIONS[1]
local safePlatform = nil
local loopMode = "Floor"      -- "Floor" = 그 집 바닥에 계속 이동 / "Float" = 바닥 위에 떠 있기
local floatHeight = 8
local STAND_HEIGHT = 3.5      -- 캐릭터 중심이 바닥에서 떨어져 있어야 하는 높이

-- 하늘 위에 만드는 안전한 발판
local function getSafePlatform()
    if safePlatform and safePlatform.Parent then
        return safePlatform
    end
    local platform = Instance.new("Part")
    platform.Name = "SafePlatform8min"
    platform.Anchored = true
    platform.CanCollide = true
    platform.Size = Vector3.new(200, 2, 200)
    platform.Position = Vector3.new(0, 5000, 0)
    platform.Material = Enum.Material.SmoothPlastic
    platform.Color = Color3.fromRGB(60, 60, 70)
    platform.Parent = Workspace
    safePlatform = platform
    return platform
end

-- 이름으로 건물을 찾음 (한 번 찾은 건 기억해 둬서 매번 월드를 뒤지지 않음)
local instanceCache = {}
local function resolveLocationInstance(name)
    local cached = instanceCache[name]
    if cached and cached.Parent then
        return cached
    end

    local instance = nil
    if name == "Train" then
        pcall(function()
            instance = Workspace.Map.AlwaysHereTweenedObjects.Train.Object.ObjectModel
        end)
    end
    instance = instance or Workspace:FindFirstChild(name, true)
    instanceCache[name] = instance
    return instance
end

-- 선택한 장소의 "꼭대기 위" 위치 (장소를 고르는 순간 한 번 이동할 때 사용)
local function getLocationCFrame(name)
    if name == "Safe Platform" then
        local platform = getSafePlatform()
        return CFrame.new(platform.Position + Vector3.new(0, platform.Size.Y / 2 + 4, 0))
    end

    local instance = resolveLocationInstance(name)
    if not instance then
        return nil
    end

    if instance:IsA("Model") then
        local boxCFrame, boxSize = instance:GetBoundingBox()
        return CFrame.new(boxCFrame.Position + Vector3.new(0, boxSize.Y / 2 + 5, 0))
    elseif instance:IsA("BasePart") then
        return CFrame.new(instance.Position + Vector3.new(0, instance.Size.Y / 2 + 5, 0))
    end
    return nil
end

-- 장소의 "바닥" 위치. 건물이면 1층에서 가장 넓은 바닥판의 윗면을 찾음
local function getFloorPoint(name)
    if name == "Safe Platform" then
        local platform = getSafePlatform()
        return platform.Position + Vector3.new(0, platform.Size.Y / 2, 0)
    end

    local instance = resolveLocationInstance(name)
    if not instance then
        return nil
    end

    if instance:IsA("BasePart") then
        return instance.Position + Vector3.new(0, instance.Size.Y / 2, 0)
    elseif instance:IsA("Model") then
        local boxCFrame, boxSize = instance:GetBoundingBox()
        local minY = boxCFrame.Position.Y - boxSize.Y / 2

        -- 집 맨 아래층(건물 바닥에서 6스터드 이내)에 있는 부품 중, 집 가운데 근처에서 가장 넓은 것 = 1층 바닥판
        local best, bestArea = nil, 0
        for _, part in ipairs(instance:GetDescendants()) do
            if part:IsA("BasePart") and part.CanCollide then
                local topY = part.Position.Y + part.Size.Y / 2
                if topY <= minY + 6 then
                    local nearCenter = math.abs(part.Position.X - boxCFrame.Position.X) <= boxSize.X * 0.35
                        and math.abs(part.Position.Z - boxCFrame.Position.Z) <= boxSize.Z * 0.35
                    local area = part.Size.X * part.Size.Z
                    if nearCenter and area > bestArea then
                        best, bestArea = part, area
                    end
                end
            end
        end
        if best then
            return Vector3.new(best.Position.X, best.Position.Y + best.Size.Y / 2, best.Position.Z)
        end

        -- 못 찾으면 집 한가운데 맨 아래 위치
        return Vector3.new(boxCFrame.Position.X, minY, boxCFrame.Position.Z)
    end
    return nil
end

-- 반복 이동용 목표: Floor = 바닥에 서기, Float = 바닥 위에 떠 있기
local floorCache = {}
local function getLoopTarget(name)
    local cached = floorCache[name]
    local floor
    local ttl = (name == "Train") and 0.3 or 5
    if cached and os.clock() - cached.time < ttl then
        floor = cached.point
    else
        floor = getFloorPoint(name)
        floorCache[name] = { point = floor, time = os.clock() }
    end
    if not floor then
        return nil
    end
    local height = (loopMode == "Float") and floatHeight or STAND_HEIGHT
    return CFrame.new(floor + Vector3.new(0, height, 0))
end

local function teleportTo(cframe)
    local _, _, root = getCharacterParts()
    if root and cframe then
        root.CFrame = cframe
        root.AssemblyLinearVelocity = Vector3.zero
        return true
    end
    return false
end

local function teleportToSelectedLocation()
    local target = getLoopTarget(selectedLocation)
    if not target then
        pcall(function() Library:Notify("Location not found: " .. tostring(selectedLocation), 4) end)
        return false
    end
    return teleportTo(target)
end

