-- 반복 이동: 간격 제한 없이 매 프레임, 그것도 물리 계산 전(Stepped)과 후(Heartbeat) 두 번씩 이동
local function makeLoop(getTargetName)
    local connections = {}
    local function step()
        local target = getLoopTarget(getTargetName())
        if target then
            teleportTo(target)
        end
    end
    return function(enabled)
        for _, connection in ipairs(connections) do
            connection:Disconnect()
        end
        connections = {}
        if enabled then
            connections[1] = RunService.Stepped:Connect(step)
            connections[2] = RunService.Heartbeat:Connect(step)
        end
    end
end

