-- ============================================================
-- Remotes
-- ============================================================
local remotes = {}
local remoteRoot = nil

local function locateRemoteRoot()
    local function isRemoteRoot(c)
        return c and c:FindFirstChild("GrabEvents")
            and c:FindFirstChild("MenuToys")
            and c:FindFirstChild("CharacterEvents")
    end
    if isRemoteRoot(ReplicatedStorage) then return ReplicatedStorage end
    for _, d in ipairs(ReplicatedStorage:GetDescendants()) do
        if isRemoteRoot(d) then return d end
    end
    return ReplicatedStorage
end

local function refreshRemotes()
    remoteRoot = locateRemoteRoot()
    local grabEvents = ReplicatedStorage:FindFirstChild("GrabEvents")
    local menuToys = remoteRoot and remoteRoot:FindFirstChild("MenuToys")
    local characterEvents = remoteRoot and remoteRoot:FindFirstChild("CharacterEvents")
    local playerEvents = remoteRoot and remoteRoot:FindFirstChild("PlayerEvents")

    remotes.sno = grabEvents and grabEvents:FindFirstChild("SetNetworkOwner") or nil
    remotes.dgl = grabEvents and grabEvents:FindFirstChild("DestroyGrabLine") or nil
    remotes.Struggle = characterEvents and characterEvents:FindFirstChild("Struggle") or nil
    remotes.RagdollRemote = characterEvents and characterEvents:FindFirstChild("RagdollRemote") or nil
    remotes.spe = playerEvents and playerEvents:FindFirstChild("StickyPartEvent") or nil
    remotes.spawnEvent = menuToys and menuToys:FindFirstChild("SpawnToyRemoteFunction") or nil
    remotes.destroyToyEvent = menuToys and menuToys:FindFirstChild("DestroyToy") or nil
end
refreshRemotes()

local function fireRemote(remote, ...)
    if not remote then return false end
    local ok, res = pcall(function(...)
        if remote:IsA("RemoteFunction") then return remote:InvokeServer(...) end
        remote:FireServer(...)
        return true
    end, ...)
    return ok, res
end

-- ============================================================
-- H 헬퍼
-- ============================================================
local H = {}
local state = {
    States = { Owning = false, Spawning = false, Ragdolling = false },
    FailedToys = {},
    GrabbableParts = setmetatable({}, {__mode = "k"}),
}

function H.charp(player)
    player = player or LocalPlayer
    local c = player and player.Character
    if not c then return nil, nil, nil end
    local root = c:FindFirstChild("HumanoidRootPart") or c:FindFirstChild("Torso")
    local hum = c:FindFirstChildWhichIsA("Humanoid")
    return c, root, hum
end

function H.ispartowner(part)
    if typeof(part) ~= "Instance" or not part:IsA("BasePart") then return false end
    if part.Name == "HumanoidRootPart" then
        local parent = part.Parent
        if parent then
            local head = parent:FindFirstChild("Head")
            if head then
                local owner = head:FindFirstChild("PartOwner")
                if owner then return owner.Value == LocalPlayer.Name end
            end
        end
    end
    local owner = part:FindFirstChild("PartOwner")
    if owner and owner.Value == LocalPlayer.Name then return true end
    local parent = part.Parent
    if not parent then return false end
    owner = parent:FindFirstChild("PartOwner", true)
    if not owner then return false end
    return owner.Value == LocalPlayer.Name
end

function H.grab(part, cframe)
    local _, localRoot, humanoid = H.charp()
    if not localRoot or not humanoid or humanoid.Health == 0 then return end
    if not part or not part.Parent or not part:IsA("BasePart") then return end
    refreshRemotes()
    if not remotes.sno then return end
    local src = cframe or localRoot.CFrame
    if typeof(src) ~= "CFrame" then return end
    src = src * CFrame.new(0, 1.593, 0)
    local grabCF = CFrame.new(src.Position, part.Position)
    remotes.sno:FireServer(part, grabCF)
end

function H.sno(part, duration)
    if typeof(part) ~= "Instance" or not part:IsA("BasePart") or not part.Parent then return false end
    local character, localRoot, humanoid = H.charp()
    local localHead = character and character:FindFirstChild("Head")
    local ragdolled = humanoid and humanoid:FindFirstChild("Ragdolled")
    if not character or not localHead or not localRoot or not humanoid or not ragdolled or humanoid.Health <= 0 then
        return false
    end
    if H.ispartowner(part) then return true end
    state.States.Owning = true
    local started = tick()
    local timeout = tonumber(duration) or 0.65
    while part.Parent and not H.ispartowner(part) and humanoid.Health ~= 0
        and localRoot.Parent and tick() - started < timeout do
        RunService.Heartbeat:Wait()
        H.grab(part)
    end
    state.States.Owning = false
    return H.ispartowner(part)
end

function H.unsno(part)
    if not part then return false end
    refreshRemotes()
    if remotes.dgl then return fireRemote(remotes.dgl, part) end
    return false
end

function H.findNicePart(model)
    if typeof(model) ~= "Instance" or not model:IsA("Model") then return nil end
    local cached = state.GrabbableParts[model]
    if cached and cached.Parent and cached.CanQuery and cached.Name ~= "Button" then return cached end
    for _, child in pairs(model:GetChildren()) do
        if child:IsA("BasePart") and child.CanQuery and child.Name ~= "Button" then
            state.GrabbableParts[model] = child
            return child
        end
    end
    return nil
end

function H.st(name, cframe)
    if type(name) ~= "string" or state.FailedToys[name] then return nil end
    local _, root = H.charp()
    if not root or state.States.Spawning then return nil end

    refreshRemotes()
    if not remotes.spawnEvent or not remotes.spawnEvent:IsA("RemoteFunction") then return nil end
    local spawnedFolder = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
    if not spawnedFolder then return nil end

    state.States.Spawning = true

    local childConn, heartbeatConn = nil, nil
    local savedCF = root.CFrame
    local result = nil

    local function cleanup()
        if heartbeatConn then heartbeatConn:Disconnect(); heartbeatConn = nil end
        if childConn then childConn:Disconnect(); childConn = nil end
        state.States.Spawning = false
    end

    local ok, err = pcall(function()
        local base = root.CFrame + Vector3.new(0, 15, 0)
        local requested = typeof(cframe) == "CFrame" and cframe or base
        local spawnCF = CFrame.new(requested.Position) + Vector3.new(0, 0, 20)
        local rotate = Workspace:FindFirstChild("RotateOrientPart")
        local rotation = rotate and rotate.Rotation or Vector3.zero

        childConn = spawnedFolder.ChildAdded:Connect(function(child)
            if child.Name == name then
                result = child
                if childConn then childConn:Disconnect(); childConn = nil end
            end
        end)
        savedCF = root.CFrame
        local function invokeSpawn()
            fireRemote(remotes.spawnEvent, name, spawnCF, rotation)
        end
        task.spawn(invokeSpawn)
        local started = tick()
        while true do
            RunService.Heartbeat:Wait()
            if result or tick() - started > 1.3 then break end
        end
    end)
    cleanup()
    if not ok then return nil end
    if not result then
        state.FailedToys[name] = true
        task.delay(2, function() state.FailedToys[name] = nil end)
    end
    return result
end

function H.dt(model)
    if typeof(model) ~= "Instance" or not model:IsA("Model") then return false end
    refreshRemotes()
    if not remotes.destroyToyEvent then return false end
    local ok = fireRemote(remotes.destroyToyEvent, model)
    return ok == true
end

-- 소환 자리 기다리기: 다른 소환이 끝나고 소환 쿨타임(CanSpawnToy)도 끝난 "그 순간"을 잡아서 true 를 돌려줌.
-- 둘을 따로 기다리면 그 사이에 다른 기능(구찌/안티킥/H.st)이 끼어들어서 같은 쿨타임을 두고 요청이 겹침.
-- true 를 받은 쪽은 양보(task.wait 등) 없이 바로 state.States.Spawning = true 를 걸어야 함.
-- 락이 10초 넘게 계속 걸려 있으면(소환 도중 스레드가 죽은 경우) 죽은 락으로 보고 풀어 줌.
-- 락이 lockLimit 초 넘게 안 풀리면 false, "another spawn is running". 쿨타임이 coolLimit 초 넘게 안 끝나면 그냥 진행(true).
H.spawnLockSince = nil

function H.waitSpawnSlot(stillWanted, lockLimit, coolLimit)
    local canSpawn = LocalPlayer:FindFirstChild("CanSpawnToy")
    local lockStart, coolStart = nil, nil

    while stillWanted() do
        local now = tick()
        local locked = state.States.Spawning == true
        local cooling = canSpawn ~= nil and canSpawn.Value == false

        if locked then
            lockStart = lockStart or now
            H.spawnLockSince = H.spawnLockSince or now

            if now - H.spawnLockSince > 10 then
                state.States.Spawning = false
                H.spawnLockSince = nil
                locked = false
            elseif now - lockStart >= lockLimit then
                return false, "another spawn is running"
            end
        else
            lockStart = nil
            H.spawnLockSince = nil
        end

        if cooling then
            coolStart = coolStart or now
        else
            coolStart = nil
        end

        if not locked and (not cooling or now - coolStart >= coolLimit) then
            return true
        end

        task.wait()
    end

    return false
end

function H.ragdoll(subject, duration)
    local character, targetPart, humanoid = nil, nil, nil
    if typeof(subject) ~= "Instance" then return end

    if subject:IsA("Player") then
        character = subject.Character
        if character then
            targetPart = character:FindFirstChild("Torso")
            humanoid = character:FindFirstChild("Humanoid")
        end
    elseif subject:IsA("Model") then
        character = subject
        targetPart = character:FindFirstChild("Torso")
        humanoid = character:FindFirstChild("Humanoid")
    elseif subject:IsA("BasePart") then
        targetPart = subject
        if subject.Parent and subject.Parent:IsA("Model") then
            character = subject.Parent
            humanoid = character:FindFirstChild("Humanoid")
        end
    else return end

    if not targetPart or not targetPart:IsA("BasePart")
        or not targetPart.Parent or not humanoid then return end

    local ragdolled = humanoid:FindFirstChild("Ragdolled")
    if not ragdolled or ragdolled.Value ~= false then return end
    if state.States.Ragdolling then return end

    targetPart.CanCollide = false
    state.States.Ragdolling = true

    local spawnedFolder = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
    if not spawnedFolder then
        state.States.Ragdolling = false
        return
    end

    local toy = spawnedFolder:FindFirstChild("RagdollRSC")
    if not toy then
        toy = H.st("PalletLightBrown")
    end
    if not toy then
        state.States.Ragdolling = false
        return
    end

    local soundPart = toy:WaitForChild("SoundPart", 0.5)
    if not soundPart or not soundPart:IsA("BasePart") then
        state.States.Ragdolling = false
        H.dt(toy)
        return
    end

    local main = toy:WaitForChild("Main", 0.5)
    if not main or not main:IsA("BasePart") then
        state.States.Ragdolling = false
        H.dt(toy)
        return
    end

    pcall(function()
        for _, desc in ipairs(toy:GetDescendants()) do
            if desc:IsA("BasePart") then
                desc.CanCollide = false
                desc.CanTouch = true
                desc.CanQuery = false
                desc.Massless = true
                desc.CustomPhysicalProperties = PhysicalProperties.new(0.01, 0.01, 0.01, 0.01, 0.01)
            end
        end
    end)

    if not H.sno(soundPart) then
        state.States.Ragdolling = false
        H.dt(toy)
        return
    end

    toy.Name = "RagdollRSC"

    local bodyPosition = main:FindFirstChild("RagdollBP")
    if bodyPosition and not bodyPosition:IsA("BodyPosition") then
        bodyPosition:Destroy()
        bodyPosition = nil
    end

    if not bodyPosition then
        bodyPosition = Instance.new("BodyPosition")
        bodyPosition.Name = "RagdollBP"
        bodyPosition.D = 1500
        bodyPosition.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
        bodyPosition.Position = Vector3.new(0, 100000, 0)
        bodyPosition.Parent = main
    else
        bodyPosition.D = 1500
        bodyPosition.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
        bodyPosition.Position = Vector3.new(0, 100000, 0)
    end

    local started = tick()
    while toy.Parent and soundPart.Parent and targetPart.Parent
        and ragdolled.Parent and ragdolled.Value ~= true
        and tick() - started <= 0.5 do
        soundPart.Position = targetPart.Position
        soundPart.Velocity = Vector3.new(0, -10, 0)
        task.wait(0.1)
    end

    state.States.Ragdolling = false
    return ragdolled.Value
end
