-- 주의: Roblox 에는 settings() 라는 함수가 따로 있어서, 표(table)일 때만 그 값을 쓰고
-- 아니면 이 파일 안에서만 쓰는 새 표를 사용함
local settings
if type(getgenv().settings) == "table" then
    settings = getgenv().settings
else
    settings = {}
    if getgenv().settings == nil then
        getgenv().settings = settings
    end
end
settings.AntiLagSens = settings.AntiLagSens or 3   -- 최소 FPS 기준
settings.AGType = settings.AGType or "Anti-Kill"
settings.GucciType = settings.GucciType or "CreatureBlobman"

-- 알림 아이콘: 종류(kind)에 따라 앞에 아이콘을 붙임.
-- 라이브러리가 Icon 항목을 지원하면 그 아이콘도 같이 쓰고, 지원하지 않아도 제목 앞의 이모지로 아이콘이 보임.
local NOTIFY_ICONS = {
    success = { emoji = "✅", lucide = "shield-check" },
    fail = { emoji = "❌", lucide = "shield-x" },
    warn = { emoji = "⚠️", lucide = "triangle-alert" },
    info = { emoji = "ℹ️", lucide = "info" },
}

local function notify(text, title, kind)
    -- 메인 아이콘이 붙는 공용 알림을 우선 사용
    local main = getgenv()._8minNotify
    if title == "Gucci" and getgenv()._8minNotifyGucci == false then return end
    if title == "Break Plot" and getgenv()._8minNotifyBreakPlot == false then return end
    if main then
        main(text, title, kind)
        return
    end
    local icon = NOTIFY_ICONS[kind or "info"] or NOTIFY_ICONS.info
    local shown = pcall(function()
        Library:Notify({
            Title = icon.emoji .. " " .. tostring(title or "8min"),
            Description = tostring(text),
            Time = 5,
            Icon = icon.lucide,
        })
    end)
    if not shown then
        pcall(function() Library:Notify(icon.emoji .. " " .. tostring(text), 5) end)
    end
end

-- 필요한 리모트가 이미 있으면 다시 찾지 않음 (없을 때만, 그것도 1초에 한 번까지만 찾음)
local lastRemoteRefresh = 0
local function ensureRemotes()
    local complete = remotes.sno and remotes.sno.Parent
        and remotes.destroyToyEvent and remotes.destroyToyEvent.Parent
        and remotes.spe and remotes.spe.Parent
        and remotes.spawnEvent and remotes.spawnEvent.Parent
        and remotes.RagdollRemote and remotes.RagdollRemote.Parent
    if complete then return end
    if os.clock() - lastRemoteRefresh < 1 then return end
    lastRemoteRefresh = os.clock()
    refreshRemotes()
end

-- 구찌 적용 지연 (초). 좌석을 뺐다 넣는 단계를 기다리는 시간. 기본 0.3 이 원래 값. 낮추면 빨라지지만 너무 낮으면 적용이 안 될 수 있음
settings.GucciDelay = settings.GucciDelay or 0.3
settings.GucciMode = settings.GucciMode or "Original"

-- 좌석을 뺐다 넣는 단계를 기다리는 시간(초).
--   Original: 원래 값 0.3 (가장 안정적)
--   Auto: 내 핑에 맞춰서 0.15~0.3 사이. 서버가 앞 단계를 처리할 시간(왕복 1.5배 + 0.08초)만 기다림
--   Custom: 슬라이더 값 그대로
local function getGucciDelay()
    local mode = settings.GucciMode
    if mode == "Custom" then
        return settings.GucciDelay or 0.3
    elseif mode == "Auto" then
        local pingSeconds = 0
        pcall(function()
            pingSeconds = Stats.Network.ServerStatsItem["Data Ping"]:GetValue() / 1000
        end)
        return math.clamp(pingSeconds * 1.5 + 0.08, 0.15, 0.3)
    end
    return 0.3
end

-- 헬퍼에 없는 함수는 간단히 채워 둠 (Anti Grab 이 호출함)
if not H.resetVelocity then
    H.resetVelocity = function(part)
        if not part then return end
        pcall(function()
            part.AssemblyLinearVelocity = Vector3.zero
            part.AssemblyAngularVelocity = Vector3.zero
        end)
    end
end

-- 안티 그랩이 쓰는 함수들. 원래 메인 스크립트의 H 에 들어 있던 것인데 이 파일에는 없어서,
-- 이미 있으면 그걸 쓰고(덮어쓰지 않음) 없을 때만 아래 기본 동작으로 채움.
if not H.ToggleCollisions then
    -- 캐릭터 부품의 충돌을 켜고 끔 (잡혀 있는 동안 다른 물체와 부딪히지 않게)
    H.ToggleCollisions = function(character, enabled)
        if not character then return end
        for _, part in ipairs(character:GetChildren()) do
            if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                part.CanCollide = enabled
            end
        end
    end
end

if not H.RepositionLimbs then
    -- 목이 끊겨 팔다리가 따로 놀 때, 몸통 기준 제자리로 되돌림 (R6 기준 위치)
    H.RepositionLimbs = function(character)
        local torso = character and character:FindFirstChild("Torso")
        if not torso then return end
        local offsets = {
            ["Head"] = CFrame.new(0, 1.5, 0),
            ["Left Arm"] = CFrame.new(-1.5, 0, 0),
            ["Right Arm"] = CFrame.new(1.5, 0, 0),
            ["Left Leg"] = CFrame.new(-0.5, -2, 0),
            ["Right Leg"] = CFrame.new(0.5, -2, 0),
        }
        for name, offset in pairs(offsets) do
            local part = character:FindFirstChild(name)
            if part then
                part.CFrame = torso.CFrame * offset
            end
        end
    end
end

-- =============================================
-- [Antis 탭 그룹박스 및 안티 그랩 설정]
-- =============================================
-- 아이콘 이름 자동 선택: 후보 중 라이브러리에 있는 첫 이름 사용 (확인이 안 되면 첫 후보)
local function PickIconAntis(candidates)
    for _, name in ipairs(candidates) do
        local ok, found = pcall(function() return Library:GetIcon(name) end)
        if ok and found then
            return name
        end
    end
    return candidates[1]
end

