-- =============================================
-- Resonance 원본 안티 그랩이 쓰는 헬퍼 (원본 그대로)
-- =============================================
local adapters = (getgenv and getgenv().ResonanceExtractAdapters) or {}

local function recoveredYield(duration)
    local waitTime = duration or 0
    local started = tick()
    repeat
        RunService.Heartbeat:Wait()
    until tick() - started >= waitTime
    return true
end

if not H.resetVelocity then
function H.resetVelocity(part)
    if part and part:IsA("BasePart") then
        part.AssemblyLinearVelocity = Vector3.zero
        part.AssemblyAngularVelocity = Vector3.zero
    end
end
end

function H.ExtraEscape()
    local _, rootPart, humanoid = H.charp()

    if not rootPart
        or not humanoid
        or humanoid.Health == 0
        or state.States.Escaping
    then
        return
    end

    local inPlot = LocalPlayer:FindFirstChild("InPlot")

    if not inPlot or inPlot.Value then
        return
    end

    state.States.Escaping = true

    -- 중간에 에러가 나도 "Escaping" 상태가 켜진 채로 남지 않게 보호해서 실행 (남으면 이 기능이 다시는 안 켜졌음)
    local ok, result = pcall(function()
        local waypoints = Workspace:FindFirstChild("Waypoints")
        local tudorHouse =
            waypoints
            and waypoints:FindFirstChild("TudorHouse")

        if not tudorHouse then
            return
        end

        local toy = H.st(
            "TractorGreen",
            tudorHouse.CFrame
        )

        if not toy then
            return
        end

        local seat =
            toy:WaitForChild(
                "VehicleSeat",
                1
            )

        if not seat then
            return H.dt(toy)
        end

        local started = tick()
        local escaped = false

        humanoid.Sit = false
        seat:Sit(humanoid)

        local connection =
            seat.ChildAdded:Connect(function(child)
                if child.Name == "SeatWeld" then
                    child.Enabled = false
                    escaped = true
                    child:Destroy()
                end
            end)

        while true do
            recoveredYield()

            if escaped then
                break
            end

            if tick() - started > 0.7 then
                break
            end
        end

        connection:Disconnect()
        humanoid.Sit = false

        return H.dt(toy)
    end)

    state.States.Escaping = false

    if not ok then
        warn("[Anti Grab] ExtraEscape: " .. tostring(result))

        return nil
    end

    return result
end

function H.ToggleCollisions(character, enabled, skipRagdollLimb, lowPhysical)
    if adapters.ToggleCollisions then
        return adapters.ToggleCollisions(
            character,
            enabled,
            skipRagdollLimb,
            lowPhysical
        )
    end

    if typeof(character) ~= "Instance"
        or not character:IsA("Model")
    then
        return
    end

    for _, child in pairs(
        character:GetChildren()
    ) do
        if child:IsA("BasePart") then
            if enabled then
                if child.Name == "Torso"
                    or child.Name == "Head"
                then
                    child.CanCollide = true
                end
            else
                child.CanCollide = false

                if not skipRagdollLimb then
                    local ragdollPart =
                        child:FindFirstChild(
                            "RagdollLimbPart"
                        )

                    if ragdollPart then
                        ragdollPart.CanCollide =
                            false
                    end
                end
            end

            if child.Name ~= "HumanoidRootPart" then
                local properties = nil

                if lowPhysical then
                    properties =
                        PhysicalProperties.new(
                            0.01,
                            0.01,
                            0.01,
                            0.01,
                            0.01
                        )
                end

                child.CustomPhysicalProperties =
                    properties
            end
        end
    end
end

function H.ToggleMotor6D(character, enabled, force)
    if adapters.ToggleMotor6D then
        return adapters.ToggleMotor6D(character, enabled, force)
    end

    if typeof(character) ~= "Instance" or not character:IsA("Model") then
        return false
    end

    local humanoid = character:FindFirstChild("Humanoid")
    local torso = character:FindFirstChild("Torso")
    if not humanoid or not torso then
        return false
    end

    local ragdolled = humanoid:FindFirstChild("Ragdolled")
    if not ragdolled then
        return false
    end

    if ragdolled.Value ~= true then
        for _, child in pairs(torso:GetChildren()) do
            if child:IsA("Motor6D") then
                child.Enabled = enabled
            end
        end
        return true
    end

    if not force then
        return false
    end

    local limbs = {
        "Left Leg",
        "Right Leg",
        "Left Arm",
        "Right Arm",
        "Head",
    }

    for _, name in pairs(limbs) do
        local part = character:FindFirstChild(name)
        if part then
            local socket = part:FindFirstChild("BallSocketConstraint")
            if socket then
                socket.Enabled = enabled
            end
        end
    end

    return true
end

function H.RepositionLimbs(character, resetVelocity)
    if adapters.RepositionLimbs then
        return adapters.RepositionLimbs(character, resetVelocity)
    end

    if typeof(character) ~= "Instance" or not character:IsA("Model") then
        return false
    end

    local root = character:FindFirstChild("HumanoidRootPart")
    if not root then
        return false
    end

    local weldHRP = root:FindFirstChild("WeldHRP")
    local torso = character:FindFirstChild("Torso")
    if not torso then
        return false
    end

    local neck = torso:FindFirstChild("Neck")
    if neck and neck.Enabled == true then
        return false
    end

    if weldHRP and not weldHRP.Parent then
        weldHRP = nil
    end

    for limbName, offset in pairs(state.LimbOffsetsRL) do
        local part = character:FindFirstChild(limbName)
        if part and part:IsA("BasePart") then
            part.CFrame = root.CFrame * offset
            if resetVelocity then
                H.resetVelocity(part)
            end
        end
    end

    return true
end

local antiGrabConnection = nil
local antiGrabSavedCFrame = nil

-- 복귀 강도 (몸부림 / 레그돌을 프레임당 몇 번 보낼지)
local AG_STRUGGLE_PER_FRAME = 4    -- 몸부림(Struggle)
local AG_RAGDOLL_PER_FRAME = 3     -- 레그돌(RagdollRemote)
local AG_START_BURST = 10          -- 잡히는 순간 한 번에 몰아서 보내는 몸부림 횟수

local function agStruggleBurst(n)
    if not remotes.Struggle then return end
    for _ = 1, n do
        fireRemote(remotes.Struggle)
    end
end


local function stopAntiGrab()
    if antiGrabConnection then
        antiGrabConnection:Disconnect()
        antiGrabConnection = nil
    end

    state.States["Anti Grab"] = false

    local _, _, humanoid = H.charp()

    if humanoid then
        if settings.AGType == "Anti-Kill" then
            task.delay(0.1, function()
                if humanoid.Parent then
                    humanoid.Sit = false
                end
            end)
        end

        humanoid.AutoRotate = true
    end
end

local function startAntiGrabIfNeeded()
    if not runtimeFlags.AntiGrab
        or not IsHeld.Value
        or state.States["Anti Grab"]
    then
        return
    end

    refreshRemotes()

    agStruggleBurst(AG_START_BURST)

    local character, rootPart, humanoid = H.charp()
    local torso =
        character
        and character:FindFirstChild("Torso")

    local neck =
        torso
        and torso:FindFirstChild("Neck")

    if not humanoid or not torso then
        return
    end

    humanoid.RequiresNeck = false
    H.resetVelocity(rootPart or torso)

    antiGrabSavedCFrame = torso.CFrame
    state.States["Anti Grab"] = true

    local buggy =
        settings.AGType
        == "Escapes Anything, but buggy"

    local antiKill =
        settings.AGType
        == "Anti-Kill"

    local noRagdoll =
        settings.AGType
        == "No Ragdoll"

    if buggy then
        task.spawn(H.ExtraEscape)
    end

    local lastExtraEscape = tick()

    antiGrabConnection =
        RunService.Heartbeat:Connect(function(dt)
            -- 죽었거나 리스폰해서 캐릭터가 바뀌었으면 이 연결을 끝냄.
            -- (안 끝내면 "Anti Grab" 상태가 켜진 채로 남아서, 새 캐릭터에는 안티 그랩이 다시 켜지지 않았음)
            if LocalPlayer.Character ~= character
                or not humanoid.Parent
                or not torso.Parent
                or humanoid.Health <= 0
            then
                state.States["Anti Grab"] = false

                if antiGrabConnection then
                    antiGrabConnection:Disconnect()

                    antiGrabConnection = nil
                end

                return
            end

            agStruggleBurst(AG_STRUGGLE_PER_FRAME)

            if rootPart
                and not buggy
                and not noRagdoll
                and remotes.RagdollRemote
            then
                for _ = 1, AG_RAGDOLL_PER_FRAME do
                    fireRemote(
                        remotes.RagdollRemote,
                        rootPart,
                        antiKill and 0.11 or 0
                    )
                end
            end

            if buggy then
                local now = tick()

                if now - lastExtraEscape > 2 then
                    task.spawn(H.ExtraEscape)
                    lastExtraEscape = tick()
                end
            end

            local moveDirection =
                humanoid.MoveDirection

            local speed = 16

            if humanoid.WalkSpeed > 16 then
                speed = humanoid.WalkSpeed
            end

            if moveDirection.Magnitude > 0 then
                antiGrabSavedCFrame =
                    antiGrabSavedCFrame
                    + (
                        moveDirection.Unit
                        * speed
                        * dt
                    )

                local horizontal =
                    Vector3.new(
                        moveDirection.X,
                        0,
                        moveDirection.Z
                    )

                if horizontal.Magnitude > 0 then
                    local position =
                        antiGrabSavedCFrame.Position

                    local look =
                        CFrame.lookAt(
                            position,
                            position
                                + horizontal.Unit
                        )

                    antiGrabSavedCFrame =
                        antiGrabSavedCFrame:Lerp(
                            look,
                            0.12
                        )
                end
            end

            H.resetVelocity(
                rootPart or torso
            )

            torso.CFrame =
                antiGrabSavedCFrame

            humanoid.Sit =
                antiKill

            task.spawn(
                H.ToggleCollisions,
                character,
                false
            )

            if not neck
                or not neck.Enabled
            then
                task.spawn(
                    H.RepositionLimbs,
                    character
                )
            end

            for _, track in ipairs(
                humanoid:GetPlayingAnimationTracks()
            ) do
                local animation =
                    track.Animation

                if animation
                    and animation.AnimationId
                        == "rbxassetid://7047322890"
                then
                    track:Stop()
                end
            end

            if rootPart then
                local scream =
                    rootPart:FindFirstChild(
                        "Scream"
                    )

                if scream then
                    scream.Playing = false
                end
            end

            if not IsHeld.Value
                or not runtimeFlags.AntiGrab
            then
                state.States["Anti Grab"] =
                    false

                if antiKill then
                    task.delay(
                        0.1,
                        function()
                            if humanoid.Parent then
                                humanoid.Sit = false
                            end
                        end
                    )
                end

                humanoid.AutoRotate =
                    true

                if antiGrabConnection then
                    antiGrabConnection:Disconnect()

                    antiGrabConnection =
                        nil
                end

                -- 풀린 직후 복귀 강화: 레그돌 해제 + 위치/속도 고정을 몇 프레임 더 밀어 넣음
                task.spawn(function()
                    local savedCF = antiGrabSavedCFrame
                    for _ = 1, 8 do
                        if not humanoid.Parent or not torso.Parent then
                            break
                        end
                        agStruggleBurst(2)
                        if rootPart and remotes.RagdollRemote then
                            fireRemote(remotes.RagdollRemote, rootPart, 0)
                        end
                        pcall(function()
                            H.resetVelocity(rootPart or torso)
                            if savedCF then
                                torso.CFrame = savedCF
                            end
                            humanoid.PlatformStand = false
                            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
                        end)
                        RunService.Heartbeat:Wait()
                    end
                end)
            end
        end)
end

-- 에러가 나도 이 감시 루프가 죽지 않게 한 번씩 보호해서 돌림 (예전에는 한 번 에러가 나면 안티 그랩이 끝까지 멈췄음)
task.spawn(getgenv()._8minLoop("bg-3292", function()
    local lastWarn = 0

    while task.wait(0.03) do
        local ok, err = pcall(function()
            if runtimeFlags.AntiGrab then
                startAntiGrabIfNeeded()
            elseif state.States["Anti Grab"] then
                stopAntiGrab()
            end
        end)

        if not ok then
            -- 시작하다 중간에 에러가 났으면 "켜짐" 상태만 남아서 다시는 시작하지 않으므로 되돌림
            if state.States["Anti Grab"] and not antiGrabConnection then
                state.States["Anti Grab"] = false
            end

            if os.clock() - lastWarn > 5 then
                lastWarn = os.clock()
                warn("[Anti Grab] " .. tostring(err))
            end
        end
    end
end))

-- ==========================================
-- Gucci Anti Grab 로직 구간
-- ==========================================
-- =============================================
-- Resonance 원본 구찌 / 안티 킥이 쓰는 보조 함수 (없을 때만 추가)
-- =============================================
state.AKType = state.AKType or "Shuriken"
state.LimbOffsetsRL = state.LimbOffsetsRL or {
    Head = CFrame.new(0, 1.5, 0),
    ["Left Arm"] = CFrame.new(-1.5, 0, 0),
    ["Right Arm"] = CFrame.new(1.5, 0, 0),
    ["Left Leg"] = CFrame.new(-0.5, -2, 0),
    ["Right Leg"] = CFrame.new(0.5, -2, 0),
    Torso = CFrame.new(),
}
state.AntiKickSettings = state.AntiKickSettings or {
    Highlight = false,
    HighlightFill = Color3.new(1, 0, 0),
    HighlightOutl = Color3.new(1, 1, 1),
    HighlightFT = 0.5,
    HighlightOT = 0,
    Transparency = 0.9,
}

if not H.teleport then
function H.teleport(subject, target, offset)
    if not subject then
        return false
    end

    local part = subject
    if typeof(subject) == "Instance" and subject:IsA("Model") then
        part = subject.PrimaryPart or subject:FindFirstChildWhichIsA("BasePart", true)
    end
    if typeof(part) ~= "Instance" or not part:IsA("BasePart") then
        return false
    end

    local targetCFrame = nil
    if typeof(target) == "CFrame" then
        targetCFrame = target
    elseif typeof(target) == "Vector3" then
        targetCFrame = CFrame.new(target)
    elseif typeof(target) == "Instance" then
        if target:IsA("BasePart") then
            targetCFrame = target.CFrame
        elseif target:IsA("Model") then
            targetCFrame = target:GetPivot()
        end
    end
    if not targetCFrame then
        return false
    end
    if typeof(offset) == "CFrame" then
        targetCFrame = targetCFrame * offset
    end

    part.CFrame = targetCFrame
    H.resetVelocity(part)
    return true
end
end

if not H.isnetworkowner then
function H.isnetworkowner(part)
    if typeof(part) ~= "Instance" or not part:IsA("BasePart") then
        return false
    end

    local checkPart = part
    if part.Massless and part.AssemblyRootPart then
        checkPart = part.AssemblyRootPart
    end
    if not checkPart or checkPart.Anchored then
        return false
    end

    if type(isnetworkowner) == "function" then
        local ok, owned = pcall(isnetworkowner, checkPart)
        if ok and type(owned) == "boolean" then
            return owned
        end
    end

    local ok, receiveAge = pcall(function()
        return checkPart.ReceiveAge
    end)
    return ok and receiveAge == 0
end
end

local gucciWorkerGeneration = 0
local gucciActiveCleanup = nil
local gucciStartedGeneration = 0   -- 가장 최근에 시작한 워커 번호 (워커가 에러로 죽었을 때 다시 시작해도 되는지 확인용)
local gucciLastErrorNotify = 0

-- 탈것 상태 (워커가 바뀌어도 유지): "claimed" = 구찌가 쓰려고 가져간 것, "reaped" = 이미 지우라고 요청한 것
local gucciModelState = setmetatable({}, { __mode = "k" })

-- 같은 탈것을 두 번 지우라고 보내지 않음
local function gucciDestroyVehicle(model)
    if typeof(model) ~= "Instance"
        or gucciModelState[model] == "reaped"
    then
        return
    end

    gucciModelState[model] = "reaped"

    H.dt(model)
end

-- 잡혀 있는지 (IsHeld 값이 아직 로드되지 않았어도 에러 없이 처리)
local function gucciIsHeld()
    return IsHeld ~= nil
        and IsHeld.Value == true
end

local function stopGucciAntiGrab()
    gucciWorkerGeneration += 1

    if gucciActiveCleanup then
        local cleanup =
            gucciActiveCleanup

        gucciActiveCleanup = nil
        pcall(cleanup)
    end
end

-- 구찌 적용 값 (시간은 초)
local GUCCI_SIT_WINDOW = 0.9          -- 앉은 뒤 좌석 용접이 생기길 기다리는 최대 시간
local GUCCI_RESIT_INTERVAL = 0.12     -- 용접이 아직 안 생기면 이 간격으로 다시 앉기를 시도
local GUCCI_RAGDOLL_GRACE = 0.2       -- 레그돌이 이만큼 계속될 때만 실패로 봄 (잠깐 깜빡이는 건 무시)
local GUCCI_SPAWN_TIMEOUT = 2.5       -- 탈것이 나타나길 기다리는 최대 시간
local GUCCI_SPAWN_CFRAME = CFrame.new(100000, 500000, 20)   -- 탈것을 소환하는 먼 하늘 자리

-- 늦게 왔거나 중복으로 생긴 탈것이 '내가 소환한 것'인지 확인 (먼 하늘 자리에 있는 것만 내 것으로 봄).
-- 다른 기능이 같은 이름의 탈것을 평범한 곳에 소환했을 때 그걸 지워 버리지 않으려고
local function gucciLooksLikeOurs(model)
    local ok, near = pcall(function()
        local position =
            model:GetPivot().Position

        return (position - GUCCI_SPAWN_CFRAME.Position).Magnitude < 3000
    end)

    return ok and near == true
end

local function runGucciWorker()
    gucciWorkerGeneration += 1

    local generation =
        gucciWorkerGeneration

    gucciStartedGeneration = generation

    local vehicle = nil
    local seat = nil
    local nicePart = nil
    local vehicleType = nil
    local descendantConnection = nil
    local weldConnection = nil
    local respawned = false
    local spawnFails = 0       -- 연속으로 소환에 실패한 횟수
    local trainWarned = nil
    local trainSkip = {}       -- 앉기에 실패한 기차 좌석 (다른 좌석을 먼저 써 봄)

    local function running()
        return runtimeFlags.GucciAntiGrab
            and generation == gucciWorkerGeneration
    end

    local function cleanup()
        if descendantConnection then
            descendantConnection:Disconnect()

            descendantConnection = nil
        end

        if weldConnection then
            -- 지우라고 보낸 탈것이 서버에서 실제로 사라질 때까지, 늦게 생기는 용접도 끊도록 그대로 둠 (탈것이 지워지면 같이 사라짐).
            -- 기차는 지우지 않으니까 바로 끊음
            if vehicleType == "Train" then
                weldConnection:Disconnect()
            end

            weldConnection = nil
        end

        if vehicle then
            -- 기차는 맵에 원래 있는 거라 지우지 않음
            if vehicleType ~= "Train" then
                gucciDestroyVehicle(vehicle)
            end

            vehicle = nil
        end

        seat = nil
        nicePart = nil
        vehicleType = nil
    end

    gucciActiveCleanup = cleanup

    -- 조건이 될 때까지 기다림 (구찌를 끄거나 종류를 바꾸면 그만둠)
    local function waitUntil(condition, interval, expectedType)
        while running()
            and settings.GucciType == expectedType
        do
            if condition() then
                return true
            end

            task.wait(interval)
        end

        return false
    end

    -- 구찌가 몇 초 만에 됐는지 / 성공했는지 / 왜 실패했는지 알림 (결과가 바뀔 때만 한 번)
    local lastOutcome = nil

    local function reportFailure(reason, elapsed)
        if lastOutcome == "fail" then return end
        lastOutcome = "fail"
        -- 실패했을 때는 몇 초 걸렸는지는 표시하지 않음
        notify(string.format("Failed: %s", reason), "Gucci", "fail")
    end

    local function reportSuccess(total, spawnPart, applyPart)
        if lastOutcome == "success" then return end
        lastOutcome = "success"
        notify(string.format("Success in %.2fs (spawn %.2fs + apply %.2fs)", total, spawnPart, applyPart), "Gucci", "success")
    end

    local function hideDescendant(descendant)
        if descendant:IsA("BasePart") then
            descendant.Transparency = 1
            descendant.CanCollide = false
        elseif descendant:IsA("Decal")
            or descendant:IsA("Texture")
        then
            descendant.Transparency = 1
        elseif descendant.Name
            == "ItemSpawnSound"
        then
            descendant:Destroy()
        end
    end

    -- 맵의 기차에서 비어 있는 좌석을 찾음
    local function findTrainSeat()
        local map =
            Workspace:FindFirstChild(
                "Map"
            )

        local always =
            map
            and map:FindFirstChild(
                "AlwaysHereTweenedObjects"
            )

        local train =
            always
            and always:FindFirstChild(
                "Train"
            )

        local object =
            train
            and train:FindFirstChild(
                "Object"
            )

        local objectModel =
            object
            and object:FindFirstChild(
                "ObjectModel"
            )

        if not objectModel then
            return nil, nil, "Train doesn't exist!"
        end

        local anySeat = nil
        local freeSeat = nil
        local skippedSeat = nil

        for _, descendant in ipairs(objectModel:GetDescendants()) do
            if descendant:IsA("Seat") then
                anySeat = anySeat or descendant

                if descendant.Occupant == nil
                    and not descendant.Disabled
                then
                    if trainSkip[descendant] then
                        skippedSeat = skippedSeat or descendant
                    else
                        freeSeat = freeSeat or descendant
                    end
                end
            end
        end

        if not freeSeat and skippedSeat then
            -- 비어 있는 좌석이 전부 실패한 적 있으면 처음부터 다시 돌아가며 써 봄
            trainSkip = {}
            freeSeat = skippedSeat
        end

        if not anySeat then
            return objectModel, nil, "Train doesn't have seats!"
        end

        if not freeSeat then
            return objectModel, nil, "Train seats are all taken!"
        end

        return objectModel, freeSeat, nil
    end

    -- 내가 주인인 플롯(집)의 물건 폴더 (그 안에 있을 때만). 집 안에서 소환하면 탈것이 이 폴더에 생김
    local function homePlotFolder()
        local plotItems =
            Workspace:FindFirstChild(
                "PlotItems"
            )

        local inPlots =
            plotItems
            and plotItems:FindFirstChild(
                "PlayersInPlots"
            )

        if not (inPlots and inPlots:FindFirstChild(LocalPlayer.Name)) then
            return nil
        end

        local plots =
            Workspace:FindFirstChild(
                "Plots"
            )

        if not plots then
            return nil
        end

        for _, plot in ipairs(plots:GetChildren()) do
            local sign =
                plot:FindFirstChild(
                    "PlotSign"
                )

            local owners =
                sign
                and sign:FindFirstChild(
                    "ThisPlotsOwners"
                )

            if owners then
                for _, owner in ipairs(owners:GetChildren()) do
                    if owner.Value == LocalPlayer.Name then
                        return plotItems:FindFirstChild(plot.Name)
                    end
                end
            end
        end

        return nil
    end

    -- 탈것 소환 (H.st 보다 튼튼하게)
    --  * 소환 쿨타임(CanSpawnToy)이 끝날 때까지 기다림. 쿨타임 중에 보낸 요청은 서버가 그냥 무시해서 실패했음
    --  * 내 집(플롯) 안에서 소환하면 탈것이 플롯 폴더에 생겨서, 그 폴더도 같이 지켜봄
    --  * 남의 플롯 안이면 소환이 막혀 있어서, 소환하는 동안만 플롯 밖에 있는 것처럼 보이게 함
    --  * 시간이 지난 뒤에 늦게 오거나 중복으로 생긴 탈것은 지워서 쌓이지 않게 함
    local function spawnVehicle(name)
        local _, root = H.charp()

        if not root then
            return nil, "no character"
        end

        ensureRemotes()

        local spawnRemote =
            remotes.spawnEvent

        if not spawnRemote
            or not spawnRemote:IsA("RemoteFunction")
        then
            return nil, "spawn remote not found"
        end

        -- 다른 소환이 끝나고 소환 쿨타임(CanSpawnToy)도 끝난 순간에 바로 시작함.
        -- (쿨타임 중에 보낸 요청은 서버가 그냥 무시함. 둘을 따로 기다리면 그 사이에
        --  안티킥 등이 끼어들어서 같은 쿨타임을 두고 요청이 겹치므로 한꺼번에 기다림)
        -- 이 아래부터 state.States.Spawning = true 를 걸 때까지는 양보(task.wait)하면 안 됨
        local slotReady, slotReason =
            H.waitSpawnSlot(
                running,
                1,
                GUCCI_SPAWN_TIMEOUT
            )

        if not slotReady then
            if not running() then
                return nil
            end

            return nil, slotReason
        end

        local canSpawn =
            LocalPlayer:FindFirstChild(
                "CanSpawnToy"
            )

        -- 새로 생기는 순간을 바로 잡으려고, 소환하기 전에 폴더를 지켜봄
        local folders = {}

        local inventory =
            Workspace:FindFirstChild(
                LocalPlayer.Name .. "SpawnedInToys"
            )

        if inventory then
            folders[#folders + 1] = inventory
        end

        local okHome, home =
            pcall(homePlotFolder)

        if okHome and home and home ~= inventory then
            folders[#folders + 1] = home
        end

        if #folders == 0 then
            return nil, "toy folder not found"
        end

        local inPlot =
            LocalPlayer:FindFirstChild(
                "InPlot"
            )

        local inOwnedPlot =
            LocalPlayer:FindFirstChild(
                "InOwnedPlot"
            )

        local hidden =
            inPlot ~= nil
            and inPlot.Value == true
            and not (
                inOwnedPlot ~= nil
                and inOwnedPlot.Value == true
            )

        if hidden and state.States.Owning then
            return nil, "busy"
        end

        local result = nil
        local closed = false
        local connections = {}

        local function onAdded(child)
            if child.Name ~= name then
                return
            end

            if closed or (result and child ~= result) then
                -- 시간이 지나서 늦게 온 것 / 중복으로 생긴 것은 지움.
                -- 다음 소환이 이걸 가져가서 쓸 수도 있어서, 한 박자 뒤에 아무도 안 가져갔을 때만 지움
                task.defer(function()
                    if gucciModelState[child] ~= "claimed"
                        and gucciLooksLikeOurs(child)
                    then
                        gucciDestroyVehicle(child)
                    end
                end)

                return
            end

            result = child
            gucciModelState[child] = "claimed"
        end

        for _, folder in ipairs(folders) do
            connections[#connections + 1] =
                folder.ChildAdded:Connect(onAdded)
        end

        state.States.Spawning = true

        if hidden then
            state.States.Owning = true
        end

        local savedCFrame = root.CFrame
        local heartbeatConnection = nil
        local renderBound = false

        local ok, err = pcall(function()
            local rotate =
                Workspace:FindFirstChild(
                    "RotateOrientPart"
                )

            local rotation =
                rotate
                and rotate.Rotation
                or Vector3.zero

            if hidden then
                local hiddenCFrame =
                    CFrame.new(0, 10, 0)

                pcall(function()
                    RunService:UnbindFromRenderStep(
                        "GucciSpawn"
                    )
                end)

                RunService:BindToRenderStep(
                    "GucciSpawn",
                    Enum.RenderPriority.Camera.Value - 1,
                    function()
                        if root.Parent then
                            root.CFrame = savedCFrame
                        end
                    end
                )

                renderBound = true

                heartbeatConnection =
                    RunService.Heartbeat:Connect(function()
                        if root.Parent then
                            savedCFrame = root.CFrame
                            root.CFrame = hiddenCFrame
                        end
                    end)
            end

            local function invoke()
                local invoked, returned = pcall(function()
                    return spawnRemote:InvokeServer(
                        name,
                        GUCCI_SPAWN_CFRAME,
                        rotation
                    )
                end)

                -- 서버가 만든 탈것을 바로 돌려주는 경우 (아직 월드에 안 들어온 건 ChildAdded 로 기다림)
                if invoked
                    and not closed
                    and result == nil
                    and typeof(returned) == "Instance"
                    and returned.Name == name
                    and returned.Parent ~= nil
                then
                    result = returned
                    gucciModelState[returned] = "claimed"
                end
            end

            task.spawn(invoke)

            local started = tick()
            local lastInvoke = started

            -- 요청이 그냥 무시된 것 같으면 다시 보냄 (서버가 받을 수 있는 상태일 때만).
            -- 남의 플롯 안이면 첫 요청이 막힐 수 있어서 더 자주 보냄. 핑이 높으면 응답이 늦는 거라 그만큼 더 기다림
            local pingSeconds = 0

            pcall(function()
                pingSeconds =
                    Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
                        / 1000
            end)

            local retryEvery =
                math.max(
                    hidden and 0.15 or 0.75,
                    pingSeconds * 2.5
                )

            while result == nil
                and tick() - started < GUCCI_SPAWN_TIMEOUT
                and running()
            do
                task.wait()

                if result == nil
                    and tick() - lastInvoke >= retryEvery
                    and (canSpawn == nil or canSpawn.Value ~= false)
                then
                    lastInvoke = tick()
                    task.spawn(invoke)
                end
            end
        end)

        closed = true

        if renderBound then
            pcall(function()
                RunService:UnbindFromRenderStep(
                    "GucciSpawn"
                )
            end)
        end

        if heartbeatConnection then
            heartbeatConnection:Disconnect()
        end

        if hidden and root.Parent then
            root.CFrame = savedCFrame
        end

        state.States.Spawning = false

        if hidden then
            state.States.Owning = false
        end

        -- 늦게 오는 것까지 잠깐 더 지켜보다가 정리
        task.delay(6, function()
            for _, connection in ipairs(connections) do
                connection:Disconnect()
            end
        end)

        if not ok then
            warn("[Gucci] spawn error: " .. tostring(err))

            return nil, "spawn error"
        end

        if not result then
            return nil, "no response from the server"
        end

        return result, nil
    end

    while running()
        and task.wait()
    do
        local attemptStart = tick()
        local _, rootPart, humanoid =
            H.charp()

        if not humanoid then
            -- 캐릭터가 아직 로딩 중: 잠깐 뒤에 다시 확인
            task.wait(0.1)
            continue
        end

        if humanoid.Health == 0 then
            -- 죽었으면 다시 태어날 때까지 기다림 (이미 새 캐릭터가 있으면 바로 넘어감)
            local deadHumanoid = humanoid

            repeat
                task.wait()

                local _, _, currentHumanoid =
                    H.charp()
            until not running()
                or (
                    currentHumanoid ~= nil
                    and currentHumanoid ~= deadHumanoid
                )

            respawned = true

            task.delay(
                1,
                function()
                    respawned = false
                end
            )

            task.wait(0.16)
            continue
        end

        local ragdolled =
            humanoid:FindFirstChild(
                "Ragdolled"
            )

        if not rootPart
            or not ragdolled
            or gucciIsHeld()
            or ragdolled.Value
            or humanoid.Health <= 0
        then
            continue
        end

        if humanoid.Sit then
            humanoid.Sit = false

            -- 앉은 상태가 풀릴 때까지 잠깐 기다림 (앉은 채로 다시 앉으려 하면 실패함)
            local standStart = tick()

            while humanoid.Sit
                and tick() - standStart < 0.25
                and running()
            do
                task.wait()
            end
        end

        local currentType =
            settings.GucciType

        cleanup()

        if currentType == "Train" then
            local objectModel, trainSeat, why =
                findTrainSeat()

            if not trainSeat then
                if trainWarned ~= why then
                    trainWarned = why

                    notify(
                        why, "Gucci", "fail"
                    )
                end

                -- 기차가 나타나거나 빈 좌석이 생길 때까지 기다림
                waitUntil(
                    function()
                        local _, freeSeat =
                            findTrainSeat()

                        return freeSeat ~= nil
                    end,
                    0.5,
                    currentType
                )

                continue
            end

            trainWarned = nil

            vehicle = objectModel
            seat = trainSeat
            nicePart = nil
            vehicleType = currentType
        else
            local model, why =
                spawnVehicle(
                    currentType
                )

            if not model then
                spawnFails += 1

                if spawnFails >= 2
                    and running()
                then
                    reportFailure(
                        "couldn't spawn the vehicle"
                            .. (why and (" (" .. why .. ")") or ""),
                        tick() - attemptStart
                    )
                end

                -- 바로 다시 소환함. 소환 요청이 즉시 거절되는 경우(리모트 없음 등)에만 프레임마다 반복하지 않게 아주 짧게 쉼
                task.wait(math.min(0.1 * spawnFails, 0.5))
                continue
            end

            spawnFails = 0

            vehicle = model

            seat =
                model:WaitForChild(
                    "VehicleSeat",
                    1.25
                )

            nicePart =
                seat
                and H.findNicePart(
                    model
                )
                or nil

            vehicleType =
                currentType

            for _, descendant in pairs(
                model:GetDescendants()
            ) do
                hideDescendant(
                    descendant
                )
            end

            descendantConnection =
                model.DescendantAdded:Connect(
                    hideDescendant
                )

            if not seat then
                reportFailure(
                    "the vehicle has no seat",
                    tick() - attemptStart
                )

                -- 좌석이 없는 탈것은 바로 지우고 새로 소환
                cleanup()
                continue
            end
        end

        local currentVehicle = vehicle
        local currentSeat = seat
        local currentNicePart = nicePart
        local seatHome = currentSeat.Parent   -- 좌석이 원래 붙어 있던 곳 (기차는 좌석이 하위 모델 안에 있을 수 있음)

        local active = true

        if currentNicePart then
            local oldBP =
                currentNicePart:FindFirstChild(
                    "GucciBP"
                )

            if oldBP then
                oldBP:Destroy()
            end
        end

        currentSeat.Transparency = 1
        currentSeat.CanCollide = false

        local seatWeldBroken = false
        local savedCFrame = rootPart.CFrame
        local started = tick()

        local function breakWeld(weld)
            if weld and not seatWeldBroken then
                weld.Enabled = false
                weld:Destroy()
                seatWeldBroken = true
            end
        end

        -- 좌석에 SeatWeld 가 생기는 순간 바로 끊음.
        -- (예전에는 좌석에 처음 생기는 자식 하나만 보고 이름이 SeatWeld 가 아니면 그대로 끝나 버려서 용접을 놓치곤 했음.
        --  이제는 이름이 SeatWeld 인 것만 골라서 끊고, 실패해도 탈것이 지워질 때까지 계속 지켜봄)
        if weldConnection then
            weldConnection:Disconnect()
        end

        weldConnection =
            currentSeat.ChildAdded:Connect(function(child)
                if child.Name == "SeatWeld"
                    and not seatWeldBroken
                then
                    breakWeld(child)

                    if weldConnection then
                        weldConnection:Disconnect()

                        weldConnection = nil
                    end
                end
            end)

        local ragdollLoopStarted = false

        ensureRemotes()

        task.defer(function()
            while humanoid
                and humanoid.Health > 0
                and active
                and task.wait()
            do
                ragdollLoopStarted = true

                if remotes.RagdollRemote then
                    fireRemote(
                        remotes.RagdollRemote,
                        rootPart,
                        0
                    )
                end
            end

            ragdollLoopStarted = true
        end)

        repeat
            task.wait()
        until ragdollLoopStarted
            or generation
                ~= gucciWorkerGeneration

        if generation
            ~= gucciWorkerGeneration
        then
            active = false
            break
        end

        -- 앉기. 한 번에 안 앉아지면 용접이 생길 때까지 조금씩 다시 앉아 봄
        local function trySit()
            if humanoid.Sit
                and humanoid.SeatPart ~= currentSeat
            then
                humanoid.Sit = false
            end

            pcall(function()
                currentSeat:Sit(humanoid)
            end)
        end

        trySit()

        local lastSit = tick()
        local ragdollSince = nil

        while true do
            task.wait()

            if humanoid.Health <= 0
                or not rootPart.Parent
                or not currentVehicle.Parent
                or not currentSeat.Parent
            then
                break
            end

            if not seatWeldBroken then
                breakWeld(
                    currentSeat:FindFirstChild(
                        "SeatWeld"
                    )
                )
            end

            if ragdolled.Value then
                ragdollSince = ragdollSince or tick()
            else
                ragdollSince = nil
            end

            if gucciIsHeld()
                or (
                    ragdollSince
                    and tick() - ragdollSince >= GUCCI_RAGDOLL_GRACE
                )
                or seatWeldBroken
                or tick() - started > GUCCI_SIT_WINDOW
            then
                break
            end

            if tick() - lastSit >= GUCCI_RESIT_INTERVAL then
                lastSit = tick()
                trySit()
            end
        end

        local seatFailed = false   -- 좌석에 앉지 못해서 실패한 경우 (잡힘/레그돌/탈것 사라짐은 해당 안 됨)

        do
            local nowT = tick()
            if seatWeldBroken then
                reportSuccess(nowT - attemptStart, started - attemptStart, nowT - started)
            elseif humanoid.Health > 0 and generation == gucciWorkerGeneration then
                if gucciIsHeld() then
                    reportFailure("you were grabbed", nowT - attemptStart)
                elseif ragdolled.Value then
                    reportFailure("you were ragdolled", nowT - attemptStart)
                elseif nowT - started > GUCCI_SIT_WINDOW then
                    seatFailed = true

                    reportFailure("seat weld never broke", nowT - attemptStart)
                else
                    reportFailure("vehicle disappeared", nowT - attemptStart)
                end
            end
        end

        if seatWeldBroken then
            humanoid.Sit = false

            task.delay(
                0.15,
                function()
                    active = false
                    task.wait()

                    if remotes.RagdollRemote
                        and rootPart.Parent
                    then
                        fireRemote(
                            remotes.RagdollRemote,
                            rootPart,
                            0.15
                        )
                    end
                end
            )

            if respawned then
                H.teleport(
                    rootPart,
                    savedCFrame
                )
            end

            if currentType ~= "Train"
                and currentNicePart
            then
                local plotItems =
                    Workspace:FindFirstChild(
                        "PlotItems"
                    )

                local inPlotItems =
                    plotItems
                    and currentNicePart:IsDescendantOf(
                        plotItems
                    )

                if inPlotItems
                    or H.isnetworkowner(
                        currentNicePart
                    )
                    or H.sno(
                        currentNicePart
                    )
                then
                    local position =
                        Vector3.new(
                            math.random(
                                -100000,
                                100000
                            ),
                            100000,
                            math.random(
                                -100000,
                                100000
                            )
                        )

                    local bodyPosition =
                        Instance.new(
                            "BodyPosition"
                        )

                    bodyPosition.Name =
                        "GucciBP"

                    bodyPosition.D = 200

                    bodyPosition.MaxForce =
                        Vector3.new(
                            math.huge,
                            math.huge,
                            math.huge
                        )

                    bodyPosition.Position =
                        position

                    currentVehicle.Name =
                        "GucciRSC"

                    bodyPosition.Parent =
                        currentNicePart
                end
            end

            task.delay(
                0.75,
                function()
                    if not currentSeat
                        or not currentSeat.Parent
                        or not currentVehicle
                        or not currentVehicle.Parent
                    then
                        return
                    end

                    currentSeat.Parent =
                        ReplicatedStorage

                    task.wait()

                    if humanoid
                        and humanoid.Parent
                    then
                        humanoid:SetStateEnabled(
                                Enum.HumanoidStateType.Jumping,
                                true
                            )
                    end

                    if currentVehicle
                        and currentVehicle.Parent
                        and currentSeat
                    then
                        currentSeat.Parent =
                            (seatHome and seatHome.Parent)
                                and seatHome
                                or currentVehicle
                    end
                end
            )

            while currentVehicle.Parent
                and currentSeat.Parent
                and humanoid.Parent
                and humanoid.Health > 0
                and not gucciIsHeld()
                and not ragdolled.Value
                and (
                    currentSeat.Occupant == nil
                    or currentSeat.Occupant
                        == humanoid
                )
                and runtimeFlags.GucciAntiGrab
                and settings.GucciType
                    == currentType
                and generation
                    == gucciWorkerGeneration
            do
                task.wait()
            end

            local occupant =
                currentSeat.Occupant

            if occupant
                and occupant ~= humanoid
                and occupant.Parent
            then
                local player =
                    Players:FindFirstChild(
                        occupant.Parent.Name
                    )

                if player then
                    notify(
                        player.DisplayName
                            .. " sat on your gucci!", "Gucci", "warn"
                    )
                end
            end

            if humanoid
                and humanoid.Parent
                and humanoid.Health > 0
            then
                local occupiedSeat =
                    humanoid.SeatPart

                if occupiedSeat
                    and occupiedSeat
                        ~= currentSeat
                then
                    notify(
                        "You can't sit on other Vehicles while in Gucci!",
                        "Gucci", "warn"
                    )
                end

                humanoid.Sit = true
                task.wait(0.05)
                humanoid.Sit = false
                task.wait(0.05)
            end
        end

        -- 실패하든 끝나든 이 탈것은 여기서 끝: 바로 지우고, 다음 루프에서 곧바로 새 탈것을 소환함 (같은 탈것을 다시 쓰지 않고, 쉬지도 않음)
        if weldConnection then
            -- (cleanup 과 같은 이유) 지울 탈것의 용접 감시는 탈것이 사라질 때까지 그대로 둠
            if currentType == "Train" then
                weldConnection:Disconnect()
            end

            weldConnection = nil
        end

        if descendantConnection then
            descendantConnection:Disconnect()

            descendantConnection = nil
        end

        if currentType == "Train" then
            -- 기차는 지우지 않음. 앉기에 실패한 좌석은 건너뛰고 다음 빈 좌석을 씀
            if seatFailed then
                trainSkip[currentSeat] = true
            end
        elseif currentVehicle
            and currentVehicle.Parent
        then
            gucciDestroyVehicle(currentVehicle)
        end

        vehicle = nil
        seat = nil
        nicePart = nil
        vehicleType = nil
        active = false

        if seatWeldBroken then
            task.wait(0.05)
        end
    end

    cleanup()

    if gucciActiveCleanup == cleanup then
        gucciActiveCleanup = nil
    end
end

-- 워커가 에러로 죽으면 알려 주고 자동으로 다시 시작 (예전에는 조용히 멈춰서 구찌가 안 걸린 채로 있었음)
local function runGucciAntiGrab()
    local restarts = 0   -- 연속으로 죽은 횟수 (계속 죽으면 다시 시작하는 간격을 늘려서 서버에 소환/삭제를 반복하지 않게 함)

    while true do
        local startedAt = os.clock()

        local ok, err =
            pcall(runGucciWorker)

        if ok then
            return
        end

        local failedGeneration =
            gucciStartedGeneration

        if os.clock() - startedAt > 15 then
            restarts = 0
        end

        restarts += 1

        warn("[Gucci] " .. tostring(err))

        if gucciActiveCleanup then
            local cleanup =
                gucciActiveCleanup

            gucciActiveCleanup = nil
            pcall(cleanup)
        end

        if not runtimeFlags.GucciAntiGrab
            or gucciWorkerGeneration ~= failedGeneration
        then
            return
        end

        if os.clock() - gucciLastErrorNotify > 5 then
            gucciLastErrorNotify = os.clock()

            notify(
                "Error, restarting: " .. tostring(err),
                "Gucci", "fail"
            )
        end

        task.wait(math.min(0.5 * restarts, 5))

        if not runtimeFlags.GucciAntiGrab
            or gucciWorkerGeneration ~= failedGeneration
        then
            return
        end
    end
end

-- =============================================
-- Anti Kick  ([GUCCI] Anti Grab 바로 아래에 위치)
-- =============================================
local addAntiKickUI
do
    local antiKickGeneration = 0

    local AK_FIRE_INTERVAL = 0.12                  -- 소유권/스티키 요청을 보내는 최소 간격 (핑이 높으면 더 길게). 예전에는 매 프레임 보냈음
    local AK_ATTACH_WINDOW = 1.6                   -- 첫 스티키 요청 뒤 이 시간 안에 안 붙으면 실패로 보고 새 표창으로 바꿈 (핑이 높으면 더 길게)
    local AK_SPAWN_TIMEOUT = 2.5                   -- 표창이 나타나길 기다리는 최대 시간
    local AK_PARTS_WAIT = 3                        -- 표창 안의 부품(StickyPart)이 다 올 때까지 기다리는 최대 시간
    local AK_REAP_RETRY = 2                        -- 지우라고 보낸 표창이 이 시간이 지나도 남아 있으면 다시 지우라고 보냄
    local AK_SPAWN_OFFSET = CFrame.new(0, 12, 20)  -- 소환 위치 (내 몸 기준)
    local AK_STICK_OFFSET = CFrame.new(0, 0, 0) * CFrame.Angles(0, math.rad(90), math.rad(90))

    -- 내가 소환한 표창 (이름을 바꿨거나 다른 폴더에 생겨도 놓치지 않으려고 따로 기억함)
    local akMine = setmetatable({}, { __mode = "k" })
    -- 지우라고 보낸 표창 -> 보낸 시각 (같은 걸 연달아 지우라고 보내지 않음)
    local akReaped = setmetatable({}, { __mode = "k" })
    -- 겉모습을 이미 바꾼 표창
    local akStyled = setmetatable({}, { __mode = "k" })

    -- (예비 표창은 없앰: 안티 킥이 켜져 있어도 표창은 항상 하나만 있어야 함)
    local akStandby = nil

    -- 본체가 살아서 돌고 있는지 알려 주는 신호 (워치독이 오래 멈춰 있으면 다시 시작시킴)
    local akBeat = tick()

    -- 리모트는 필요할 때 헬퍼(remotes)에서 가져옴
    local DestroyRemote, SetNetworkOwner, StickyEvent, SpawnRemote

    local function resolveAntiKickRemotes()
        ensureRemotes()
        DestroyRemote = remotes.destroyToyEvent
        SetNetworkOwner = remotes.sno
        StickyEvent = remotes.spe
        SpawnRemote = remotes.spawnEvent
    end

    -- 기능이 켜져 있는지 (몇 번째 본체인지는 상관없음)
    local function akFeatureOn()
        return _G.ShurikenAntiKick == true
            and not Library.Unloaded
    end

    -- 이 본체가 아직 맡은 일을 해야 하는지 (껐다 켜면 번호가 바뀌어 옛 본체는 멈춤)
    local function akRunning(generation)
        return akFeatureOn()
            and generation == antiKickGeneration
    end

    local function akPing()
        local seconds = 0

        pcall(function()
            seconds =
                Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
                    / 1000
        end)

        return seconds
    end

    -- 방금 지우라고 보낸 표창인지 (서버가 지울 시간을 줌. 그래도 남아 있으면 다시 지우라고 보냄)
    local function akRecentlyReaped(model)
        local reapedAt = akReaped[model]

        return reapedAt ~= nil
            and tick() - reapedAt < AK_REAP_RETRY
    end

    local function akDestroy(model)
        if typeof(model) ~= "Instance"
            or akRecentlyReaped(model)
        then
            return
        end

        akReaped[model] = tick()

        resolveAntiKickRemotes()

        if DestroyRemote then
            pcall(function()
                DestroyRemote:FireServer(model)
            end)
        end
    end

    local function akInventory()
        return Workspace:FindFirstChild(
            LocalPlayer.Name .. "SpawnedInToys"
        )
    end

    -- 내가 주인인 플롯(안에 있든 없든)과 그 물건 폴더
    local function akHomePlot()
        local plots = Workspace:FindFirstChild("Plots")
        local plotItems = Workspace:FindFirstChild("PlotItems")

        if not (plots and plotItems) then
            return nil, nil
        end

        for _, plot in ipairs(plots:GetChildren()) do
            local sign = plot:FindFirstChild("PlotSign")
            local owners = sign and sign:FindFirstChild("ThisPlotsOwners")

            if owners then
                for _, owner in ipairs(owners:GetChildren()) do
                    if owner.Value == LocalPlayer.Name then
                        return plot, plotItems:FindFirstChild(plot.Name)
                    end
                end
            end
        end

        return nil, nil
    end

    -- 지금 있는 곳: "none" = 플롯 밖 / "home" = 내 집 안 / "other" = 남의 플롯 안 (남의 플롯 안에서는 소환이 막힘)
    local function akPlotState()
        local plotItems = Workspace:FindFirstChild("PlotItems")
        local inPlots = plotItems and plotItems:FindFirstChild("PlayersInPlots")

        if not (inPlots and inPlots:FindFirstChild(LocalPlayer.Name)) then
            return "none"
        end

        local plot, folder = akHomePlot()

        if plot and folder then
            return "home", plot, folder
        end

        return "other"
    end

    -- 내 집에 막 들어왔는지 (플롯 타이머가 방금 시작됨). 값을 못 읽으면 아니라고 봄
    local function akPlotFresh(plot)
        local ok, fresh = pcall(function()
            local sign = plot:FindFirstChild("PlotSign")
            local owners = sign:FindFirstChild("ThisPlotsOwners")

            return owners.Value.TimeRemainingNum.Value > 89
        end)

        return ok and fresh == true
    end

    -- 내 표창들: 내 인벤토리의 NinjaShuriken/AntiKick 과 내가 소환해서 기억해 둔 것 (내 집 폴더에 생긴 것 포함)
    local function akKunaiList()
        local list = {}
        local seen = {}

        local function add(model)
            if not seen[model]
                and not akRecentlyReaped(model)
                and model.Parent
                and model:IsA("Model")
            then
                seen[model] = true
                list[#list + 1] = model
            end
        end

        local inventory = akInventory()

        if inventory then
            for _, model in ipairs(inventory:GetChildren()) do
                if model.Name == "AntiKick"
                    or model.Name == "NinjaShuriken"
                then
                    add(model)
                end
            end
        end

        for model in pairs(akMine) do
            add(model)
        end

        return list
    end

    -- 안티킥이 만든(또는 쓰던) 표창인지. 내가 따로 꺼내 둔 평범한 NinjaShuriken 은 아님
    local function akOwned(kunai)
        return akMine[kunai] ~= nil
            or kunai.Name == "AntiKick"
    end

    local function akClearAll()
        resolveAntiKickRemotes()

        akStandby = nil

        for _, model in ipairs(akKunaiList()) do
            if akOwned(model) then
                akDestroy(model)
            end
        end
    end

    -- 이 표창이 지금 내 캐릭터 몸에 용접돼 있는지
    local function akWeldedToCharacter(kunai, character)
        if not (kunai and kunai.Parent and character) then
            return false
        end

        local sticky = kunai:FindFirstChild("StickyPart")
        local weld = sticky and sticky:FindFirstChild("StickyWeld")

        if not weld then
            return false
        end

        local ok, attached = pcall(function()
            local part1 = weld.Part1
            local part0 = weld.Part0

            return (part1 ~= nil and part1:IsDescendantOf(character))
                or (part0 ~= nil and part0:IsDescendantOf(character))
        end)

        return ok and attached == true
    end

    -- 다시 써도 되는 표창인지. 예전에 쓰던 것(이름이 AntiKick 이거나 내가 건드린 것)은 이미 썼을 수 있어서 안 씀.
    -- 건드린 적 없는 NinjaShuriken 은 서버가 아직 안 쓴 것(CanTouch 켜짐)이고 아무 몸에도 안 붙어 있을 때만 씀
    local function akUsable(kunai)
        if kunai.Name == "AntiKick"
            or akStyled[kunai]
        then
            return false
        end

        local sticky = kunai:FindFirstChild("StickyPart")

        if not sticky or sticky.CanTouch == false then
            return false
        end

        local weld = sticky:FindFirstChild("StickyWeld")

        if weld and weld.Part1 then
            return false
        end

        return true
    end

    local function akOwnsPart(part)
        local owner = part and part:FindFirstChild("PartOwner")

        return owner ~= nil
            and owner.Value == LocalPlayer.Name
    end

    -- 표창 겉모습 (몸에 붙은 게 보이도록 두 부품만 보이고 나머지는 숨김, 충돌/접촉 끔)
    local function akStyle(kunai)
        if akStyled[kunai] then
            return
        end

        akStyled[kunai] = true

        pcall(function()
            for _, obj in pairs(kunai:GetChildren()) do
                if obj.Name == "Pyramid" then
                    obj.CanTouch = false
                    obj.CanCollide = false
                    obj.CanQuery = false
                    obj.Transparency = 0

                    if not obj:FindFirstChild("Highlight") then
                        local high = Instance.new("Highlight", obj)
                        high.FillColor = Color3.fromRGB(0, 0, 0)
                    end
                elseif obj.Name == "Main" then
                    obj.CanTouch = false
                    obj.CanCollide = false
                    obj.CanQuery = false
                    obj.Transparency = 0

                    if not obj:FindFirstChild("Highlight") then
                        local high = Instance.new("Highlight", obj)
                        high.FillColor = Color3.fromRGB(255, 255, 255)
                    end
                elseif obj:IsA("BasePart") then
                    obj.CanTouch = false
                    obj.CanCollide = false
                    obj.CanQuery = false
                    obj.Transparency = 1
                end
            end
        end)
    end

    -- 표창 소환 (Gucci 와 같은 방식):
    --  * 다른 소환(구찌 등)이 끝나고 소환 쿨타임(CanSpawnToy)도 끝난 순간에 바로 보냄 (쿨타임 중에 보낸 요청은 서버가 무시함)
    --  * 새로 생기는 순간을 바로 잡으려고 소환하기 전에 폴더(인벤토리 + 내 집)를 지켜봄
    --  * 요청이 무시된 것 같으면 다시 보냄 (쿨타임이 아닐 때만)
    local function akSpawn(generation)
        resolveAntiKickRemotes()

        if not SpawnRemote
            or not SpawnRemote:IsA("RemoteFunction")
        then
            return nil
        end

        -- 이 아래부터 state.States.Spawning = true 를 걸 때까지는 양보(task.wait)하면 안 됨
        local slotReady =
            H.waitSpawnSlot(
                function()
                    return akRunning(generation)
                end,
                1,
                AK_SPAWN_TIMEOUT
            )

        if not slotReady then
            return nil
        end

        local canSpawn =
            LocalPlayer:FindFirstChild("CanSpawnToy")

        local _, hrp, humanoid = H.charp()

        if not hrp
            or not humanoid
            or humanoid.Health <= 0
        then
            return nil
        end

        local plotState, _, homeFolder = akPlotState()

        if plotState == "other" then
            return nil
        end

        local folders = {}
        local inventory = akInventory()

        if plotState == "home" and homeFolder then
            folders[#folders + 1] = homeFolder
        end

        if inventory then
            folders[#folders + 1] = inventory
        end

        if #folders == 0 then
            return nil
        end

        local result = nil
        local closed = false
        local connections = {}

        local function onAdded(child)
            if child.Name ~= "NinjaShuriken" then
                return
            end

            -- 처음 온 것이 이번 소환의 결과. 늦게 왔거나 중복으로 생긴 것도 내 것으로 기억해 두면, 나중에 쓰거나 지움
            akMine[child] = true

            if not akFeatureOn() then
                -- 끈 뒤에 늦게 도착한 것은 바로 지움 (껐다 켠 거라면 새 본체가 가져다 쓰거나 지움)
                task.defer(akDestroy, child)

                return
            end

            if not closed and result == nil then
                result = child
            end
        end

        for _, folder in ipairs(folders) do
            connections[#connections + 1] =
                folder.ChildAdded:Connect(onAdded)
        end

        state.States.Spawning = true

        local spawnCFrame = hrp.CFrame * AK_SPAWN_OFFSET

        local ok, err = pcall(function()
            local function invoke()
                local invoked, returned = pcall(function()
                    return SpawnRemote:InvokeServer(
                        "NinjaShuriken",
                        spawnCFrame,
                        Vector3.new(0, 0, 0)
                    )
                end)

                if invoked
                    and not closed
                    and result == nil
                    and typeof(returned) == "Instance"
                    and returned.Name == "NinjaShuriken"
                    and returned.Parent ~= nil
                then
                    akMine[returned] = true
                    result = returned
                end
            end

            task.spawn(invoke)

            local started = tick()
            local lastInvoke = started
            local retryEvery = math.max(0.75, akPing() * 2.5)

            while result == nil
                and tick() - started < AK_SPAWN_TIMEOUT
                and akRunning(generation)
            do
                task.wait()

                akBeat = tick()

                if result == nil
                    and tick() - lastInvoke >= retryEvery
                    and (canSpawn == nil or canSpawn.Value ~= false)
                then
                    lastInvoke = tick()
                    task.spawn(invoke)
                end
            end
        end)

        closed = true
        state.States.Spawning = false

        -- 늦게 오는 것까지 잠깐 더 지켜보다가 정리 (늦게 온 건 위에서 akMine 에 기억됨)
        task.delay(6, function()
            for _, connection in ipairs(connections) do
                connection:Disconnect()
            end
        end)

        if not ok then
            warn("[Anti Kick] spawn error: " .. tostring(err))

            return nil
        end

        if not result then
            return nil
        end

        if not akRunning(generation) then
            -- 끄는 중에 도착했으면 지움. 껐다 켠 거라면 새 본체가 이어서 쓰도록 둠 (이미 내 것으로 기억돼 있음)
            if not akFeatureOn() then
                akDestroy(result)
            end

            return nil
        end

        -- 이벤트는 모델이 막 생겼을 때 오기 때문에, 안의 부품이 다 올 때까지 기다림
        result:WaitForChild("StickyPart", AK_PARTS_WAIT)

        result.Name = "AntiKick"
        akStyle(result)

        return result
    end

    -- 표창을 몸에 붙임. 붙으면 true, 안 붙으면 false (부른 쪽에서 지우고 새로 소환함).
    --  * 소유권(SetNetworkOwner)을 먼저 받고, 받은 게 확인되면 스티키 요청을 보냄
    --  * 요청은 일정 간격으로만 보냄 (예전에는 한 번만 보내서, 서버가 놓치면 그대로 실패했음)
    local function akAttach(kunai, generation, windowOverride)
        local sticky =
            kunai:FindFirstChild("StickyPart")
            or kunai:WaitForChild("StickyPart", AK_PARTS_WAIT)

        if not sticky then
            return false
        end

        local soundPart =
            kunai:FindFirstChild("SoundPart")
            or kunai:WaitForChild("SoundPart", 1)

        resolveAntiKickRemotes()

        local ping = akPing()
        local interval = math.max(AK_FIRE_INTERVAL, ping * 1.5)
        local window = windowOverride or math.max(AK_ATTACH_WINDOW, ping * 6)
        local ownerWait = math.max(0.35, ping * 2)

        local started = tick()
        local firstSno = nil
        local firstSticky = nil
        local lastSno = -math.huge
        local lastSticky = -math.huge

        while akRunning(generation) do
            akBeat = tick()

            local character, hrp, humanoid = H.charp()

            if not character
                or not hrp
                or not humanoid
                or humanoid.Health <= 0
                or not kunai.Parent
                or not sticky.Parent
            then
                return false
            end

            if akWeldedToCharacter(kunai, character) then
                return true
            end

            local now = tick()
            local owned = soundPart ~= nil and akOwnsPart(soundPart)

            if soundPart
                and not owned
                and SetNetworkOwner
                and now - lastSno >= interval
            then
                lastSno = now
                firstSno = firstSno or now

                pcall(function()
                    SetNetworkOwner:FireServer(soundPart, soundPart.CFrame)
                end)
            end

            -- 소유권이 확인됐거나, 요청을 보낸 지 한참 됐는데도 표시가 안 오면(소유권 표시가 없는 경우) 스티키를 보냄
            local ready =
                soundPart == nil
                or owned
                or (firstSno ~= nil and now - firstSno > ownerWait)

            local firePart = hrp:FindFirstChild("FirePlayerPart")

            if ready
                and firePart
                and StickyEvent
                and now - lastSticky >= interval
            then
                lastSticky = now
                firstSticky = firstSticky or now

                pcall(function()
                    StickyEvent:FireServer(sticky, firePart, AK_STICK_OFFSET)
                end)
            end

            if firstSticky then
                if now - firstSticky > window then
                    return false
                end
            elseif now - started > window + 1 then
                -- 소유권을 못 받아서 스티키를 한 번도 못 보냄
                return false
            end

            task.wait()
        end

        return false
    end

    -- 안티 킥 본체. 에러가 나면 감독(_8minLoop)이 다시 시작시켜 줌.
    -- 캐릭터를 한 번 잡아 두지 않고 매번 다시 가져오기 때문에 죽었다 살아나도 그대로 이어서 동작함
    local function akBody(generation)
        local failStreak = 0
        local current = nil   -- 지금 쓰고 있는 표창
        local homeWaitSince = nil

        local function backoff()
            failStreak += 1

            -- 처음 실패는 바로 다시 시도. 계속 실패하면 조금씩 쉼 (서버에 소환/삭제를 계속 보내지 않게)
            local pause = math.min(0.1 * (failStreak - 1), 0.6)

            if pause > 0 then
                task.wait(pause)
            end
        end

        while akRunning(generation) do
            task.wait()

            akBeat = tick()

            local character, hrp, humanoid = H.charp()

            if not character
                or not hrp
                or not humanoid
                or humanoid.Health <= 0
            then
                -- 캐릭터가 없거나 죽었음: 새 캐릭터가 나올 때까지 기다림. 죽은 몸에 붙어 있던 표창은 지움
                if current then
                    akDestroy(current)

                    current = nil
                end

                task.wait(0.1)
                continue
            end

            if not hrp:FindFirstChild("FirePlayerPart") then
                -- 새 캐릭터는 FirePlayerPart 가 조금 늦게 생김
                task.wait(0.1)
                continue
            end

            local list = akKunaiList()
            local attached = nil

            for _, kunai in ipairs(list) do
                if akWeldedToCharacter(kunai, character) then
                    attached = kunai

                    break
                end
            end

            if attached then
                -- 붙어 있는 건 하나만 남기고 나머지(안 붙은 것, 예전 몸에 붙었던 것)는 지움
                for _, kunai in ipairs(list) do
                    if kunai ~= attached
                        and kunai ~= akStandby
                        and akOwned(kunai)
                    then
                        akDestroy(kunai)
                    end
                end

                current = attached
                failStreak = 0

                akMine[attached] = true
                akStyle(attached)

                -- 붙어 있는 동안 기다림 (떨어지거나, 죽거나, 캐릭터가 바뀌거나, 끌 때까지)
                local nextSweep = tick() + 1

                while akRunning(generation) do
                    task.wait()

                    akBeat = tick()

                    local currentCharacter, _, currentHumanoid = H.charp()

                    if not currentCharacter
                        or not currentHumanoid
                        or currentHumanoid.Health <= 0
                        or not attached.Parent
                        or not akWeldedToCharacter(attached, currentCharacter)
                    then
                        break
                    end

                    -- 1초마다: 늦게 도착했거나 중복으로 생긴 내 표창이 남아 있으면 지움
                    if tick() >= nextSweep then
                        nextSweep = tick() + 1

                        for _, other in ipairs(akKunaiList()) do
                            if other ~= attached
                                and other ~= akStandby
                                and akOwned(other)
                            then
                                akDestroy(other)
                            end
                        end
                    end
                end

                -- 떨어졌으면 다 쓴 표창이라 지우고, 다음 루프에서 바로 새로 붙임
                if attached.Parent then
                    akDestroy(attached)
                end

                current = nil

                continue
            end

            -- 붙은 게 없음: 쓸 만한 표창 하나를 고르고 나머지(내가 쓰던 것)는 지움
            local kunai = nil
            local fromStandby = false

            if current and current.Parent and not akRecentlyReaped(current) then
                kunai = current
            elseif akStandby
                and akStandby.Parent
                and not akRecentlyReaped(akStandby)
            then
                -- 예비 표창이 있으면 소환을 기다리지 않고 바로 씀
                kunai = akStandby
                akStandby = nil
                fromStandby = true
            else
                for _, candidate in ipairs(list) do
                    if akUsable(candidate) then
                        kunai = candidate

                        break
                    end
                end
            end

            for _, other in ipairs(list) do
                if other ~= kunai and other ~= akStandby and akOwned(other) then
                    akDestroy(other)
                end
            end

            if not kunai then
                local plotState, plot = akPlotState()

                -- 남의 플롯 안에서는 소환이 안 되니 기다림. 내 집 안에서는 막 들어왔을 때 바로, 아니면 잠깐 기다린 뒤에도 소환함
                -- (예전에는 집 안에서 처음 소환 시점을 놓치면 영영 안 붙었음)
                if plotState == "home" and not akPlotFresh(plot) then
                    homeWaitSince = homeWaitSince or tick()
                else
                    homeWaitSince = nil
                end

                if plotState == "other"
                    or (
                        plotState == "home"
                        and not akPlotFresh(plot)
                        and tick() - homeWaitSince < 2
                    )
                then
                    task.wait(0.2)
                    continue
                end

                kunai = akSpawn(generation)

                if not kunai then
                    -- 소환이 안 됐을 때만 조금씩 쉼 (아무것도 안 보냈는데 계속 도는 걸 막음)
                    backoff()
                    continue
                end

                failStreak = 0
            else
                kunai.Name = "AntiKick"
                akMine[kunai] = true
                akStyle(kunai)
            end

            current = kunai

            if not akAttach(kunai, generation, fromStandby and 0.9 or nil) then
                -- 안 붙었으면 쉬지 않고 바로 지운 뒤 새로 소환 (다음 루프). 소환 쿨타임이 알아서 속도를 맞춤
                if kunai.Parent then
                    akDestroy(kunai)
                end

                current = nil
            end
        end
    end

    local startAntiKick

    -- 워치독: 켜져 있는데 본체가 오래 멈춰 있으면(스레드가 죽었거나 어딘가에서 안 풀리는 경우) 새로 시작시킴
    local akWatchdogGeneration = 0

    local function startWatchdog()
        akWatchdogGeneration += 1

        local watchGeneration = akWatchdogGeneration

        task.spawn(function()
            while akFeatureOn() and watchGeneration == akWatchdogGeneration do
                task.wait(1)

                if akFeatureOn()
                    and watchGeneration == akWatchdogGeneration
                    and tick() - akBeat > 8
                then
                    akBeat = tick()

                    warn("[Anti Kick] stalled, restarting")
                    startAntiKick()
                end
            end
        end)
    end

    startAntiKick = function()
        antiKickGeneration += 1

        akBeat = tick()

        local generation = antiKickGeneration

        task.spawn(
            getgenv()._8minLoop(
                "Anti Kick",
                function()
                    akBody(generation)
                end,
                function()
                    return akRunning(generation)
                end
            )
        )
    end

    -- 재실행/Unload 때: 돌던 본체를 멈추고 표창을 지움
    getgenv()._8minOnCleanup(function()
        _G.ShurikenAntiKick = false
        antiKickGeneration += 1
        akWatchdogGeneration += 1
        akClearAll()
    end)

    addAntiKickUI = function()
    AntisGroup:AddCheckbox("ShurikenAntiKick", {
        Text = "Anti Kick",
        Default = false,
        Callback = function(Value)
            _G.ShurikenAntiKick = Value == true

            if Value then
                startAntiKick()
                startWatchdog()
            else
                -- 끄면 돌고 있던 본체는 곧바로 멈추고(번호가 바뀜), 표창은 전부 지움
                antiKickGeneration += 1

                akClearAll()
            end
        end
    })
    end
end


