-- =============================================
-- Anti-Lag (Resonance 원본)
-- PlayerScripts 의 CharacterAndBeamMove / StickyPartsTouchDetection 을 꺼서 줄 렉, 수리검 렉을 막음
-- =============================================
local function applyAntiLag(enabled)
    runtimeFlags.AntiLag = enabled
    local playerScripts = LocalPlayer:FindFirstChild("PlayerScripts")
    local characterAndBeamMove = playerScripts and playerScripts:FindFirstChild("CharacterAndBeamMove")
    local stickyPartsTouchDetection = playerScripts and playerScripts:FindFirstChild("StickyPartsTouchDetection")
    if characterAndBeamMove then
        characterAndBeamMove.Enabled = not enabled
    end
    if stickyPartsTouchDetection then
        stickyPartsTouchDetection.Enabled = not enabled
    end
    -- Resonance 원본의 Shuriken-Lag 처리 (StickyWeld 를 떼어 둠). Resonance 블록이 로드돼 있을 때만
    local setShur = getgenv()._8minSetAntiShurikenLag
    if setShur then pcall(setShur, enabled) end
    if enabled then
        task.delay(1.5, function()
            if not runtimeFlags.AntiLag then return end
            for _, player in ipairs(Players:GetPlayers()) do
                local character = player.Character
                if character then
                    for _, child in ipairs(character:GetChildren()) do
                        if child.Name == "GrabParts" then
                            child:Destroy()
                        end
                    end
                end
            end
        end)
    end
end

