        runtimeFlags.AutoAntiLag = value
    end,
})

-- Fake Pos 토글 항목
AntisGroup:AddToggle("FakePosToggle", {
    Text = "Desync",
    Default = false,
    Callback = function(Value)
        _G.FakePosEnabled = Value

        if Value then
            pcall(function()
                setfflag("S2PhysicsSenderRate", 1000)
            end)

            task.spawn(function()
                local dsfs = 0
                local issyncinrn = false

                while _G.FakePosEnabled do
                    local character = LocalPlayer.Character
                    local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")

                    if character and humanoidRootPart then
                        if issyncinrn then
                            task.wait()
                        else
                            if dsfs <= 0 then
                                issyncinrn = true
                                pcall(function()
                                    sethiddenproperty(humanoidRootPart, "PhysicsRepRootPart", nil)
                                end)

                                task.wait(0.1)

                                pcall(function()
                                    sethiddenproperty(humanoidRootPart, "PhysicsRepRootPart", humanoidRootPart)
                                end)
                                issyncinrn = false
                                dsfs = 20
                            else
                                dsfs = dsfs - 1
                                pcall(function()
                                    sethiddenproperty(humanoidRootPart, "PhysicsRepRootPart", humanoidRootPart)
                                end)
                            end
                        end
                    end

                    task.wait(1 / 240)
                end
            end)
        end
    end
})


