-- =============================================
-- [Auto Anti Lag 감지 루프]
-- =============================================
local lastAutoLagCheck = 0
RunService.RenderStepped:Connect(function(dt)
    if not runtimeFlags.AutoAntiLag or os.clock() - lastAutoLagCheck < 2.5 or dt <= 0 then
        return
    end
    lastAutoLagCheck = os.clock()
    local fps = math.floor(1 / dt)
    if fps < settings.AntiLagSens and Toggles.AntiLag and not Toggles.AntiLag.Value then
        notify("Anti Lag enabled: FPS is too low", "Auto Anti Lag", "warn")
        Toggles.AntiLag:SetValue(true)
    end
end)

-- =============================================
-- [Anti-Invis 루프] (runtimeFlags.AntiInvis 를 켜고 이 함수를 호출하면 동작)
-- =============================================
local antiInvisGeneration = 0
local function startAntiInvisLoop()
    antiInvisGeneration += 1
    local generation = antiInvisGeneration
    task.spawn(getgenv()._8minLoop("Anti Invis", function()
        while runtimeFlags.AntiInvis and generation == antiInvisGeneration and task.wait(0.1) do
            for _, player in ipairs(Players:GetPlayers()) do
                if player ~= LocalPlayer then
                    local _, rootPart, humanoid = H.charp(player)
                    if rootPart then
                        rootPart.Massless = false
                    end
                    if humanoid and humanoid.Sit and humanoid.SeatPart then
                        local seatWeld = humanoid.SeatPart:FindFirstChild("SeatWeld")
                        if seatWeld and not seatWeld.Enabled then
                            seatWeld.Enabled = true
                        end
                    end
                end
            end
        end
    end))
end

end)()



-- ==========================================================
-- [Grab 탭] Grab 토글 1개 + Grab Type 드롭다운 (Loop Grab / Kick Grab)
-- 필요한 것: Tabs (메인 스크립트 헤더에 이미 있음)
-- 섹션 전체를 함수로 감싸서 로컬 변수 200개 한도에 걸리지 않게 함
-- ==========================================================
;(function()

-- =============================================
-- 감지 알림: 다른 사람이 Line Lag / Packet Lag 를 걸면, 킥 당하면 누군지 알려줌
-- =============================================
do
    local Players = game:GetService("Players")
    local RS = game:GetService("ReplicatedStorage")
    local LP = Players.LocalPlayer
    local lagNotifyOn, kickNotifyOn, friendNotifyOn, grabbedNotifyOn = true, true, true, true

    local function nfy(text, title, kind)
        local fn = getgenv()._8minNotify
        if fn then fn(text, title, kind) end
    end

    pcall(function()
        local grp = Tabs.Notifications:AddLeftGroupbox("Notifications", "bell")
        grp:AddToggle("LagNotify", {
            Text = "Lag Notify",
            Default = true,
            Tooltip = "Tell me who is line-lagging / packet-lagging the server.",
            Callback = function(Value) lagNotifyOn = Value end,
        })
        grp:AddToggle("KickNotify", {
            Text = "Kick Notify",
            Default = true,
            Tooltip = "Tell me who got kicked from the server.",
            Callback = function(Value) kickNotifyOn = Value end,
        })
        grp:AddToggle("GucciNotify", {
            Text = "Gucci Notify",
            Default = true,
            Tooltip = "Show how long Gucci took and whether it worked.",
            Callback = function(Value) getgenv()._8minNotifyGucci = Value end,
        })
        local sgrp = (Tabs.Music or Tabs.Notifications):AddLeftGroupbox("Sound Effects", "volume-2")
        sgrp:AddToggle("NotifySound", {
            Text = "Notification Sound",
            Default = true,
            Tooltip = "Play a sound when a notification appears.",
            Callback = function(Value) getgenv()._8minNotifySound = Value end,
        })
        sgrp:AddSlider("NotifyVolume", {
            Text = "Sound Volume",
            Default = 1, Min = 0, Max = 5, Rounding = 1,
            Callback = function(Value) getgenv()._8minNotifyVolume = Value end,
        })
        sgrp:AddInput("NotifySoundId", {
            Text = "Custom Sound ID",
            Default = "",
            Placeholder = "140207837688369 (default)",
            Finished = true,
            Callback = function(Value)
                local id = tostring(Value or ""):match("%d+")
                getgenv()._8minNotifySoundId = id and ("rbxassetid://" .. id) or nil
            end,
        })
        grp:AddToggle("FriendNotify", {
            Text = "Friend Notify",
            Default = true,
            Tooltip = "Tell me when a friend leaves the server.",
            Callback = function(Value) friendNotifyOn = Value end,
        })
        grp:AddToggle("GrabbedNotify", {
            Text = "Grabbed Notify",
            Default = true,
            Tooltip = "Tell me who is grabbing me.",
            Callback = function(Value) grabbedNotifyOn = Value end,
        })
        grp:AddToggle("BlobGuardNotify", {
            Text = "Blob Guard Notify",
            Default = true,
            Tooltip = "Tell me when an enemy Blobman comes close or grabs me (needs Anti Blobman / Anti Grab on).",
            Callback = function(Value) getgenv()._8minNotifyBlob = Value end,
        })
        grp:AddToggle("LoopTPNotify", {
            Text = "Loop TP Notify",
            Default = true,
            Tooltip = "Tell me when a Loop TP is turned on.",
            Callback = function(Value) getgenv()._8minNotifyLoopTP = Value end,
        })
        grp:AddToggle("BreakPlotNotify", {
            Text = "Break Plot Notify",
            Default = true,
            Tooltip = "Tell me whether breaking a plot (barrier house) succeeded or failed.",
            Callback = function(Value) getgenv()._8minNotifyBreakPlot = Value end,
        })
        grp:AddButton({
            Text = "Test Notification",
            Func = function()
                nfy("This is how notifications look.", "Notification Test", "info")
            end,
        })
    end)

    -- 이벤트 인자에서 플레이어를 찾음 (Player / 캐릭터 / 캐릭터의 파트 / 이름)
    local function playerFromArg(a)
        if typeof(a) == "Instance" then
            if a:IsA("Player") then return a end
            local model = a:FindFirstAncestorOfClass("Model") or a
            local p = Players:GetPlayerFromCharacter(model)
            if p then return p end
            if model.Parent then
                p = Players:GetPlayerFromCharacter(model.Parent)
                if p then return p end
            end
        elseif typeof(a) == "string" then
            return Players:FindFirstChild(a)
        end
        return nil
    end
    local function label(p, raw)
        if p then return string.format("%s (@%s)", p.DisplayName, p.Name) end
        return tostring(raw)
    end

    task.spawn(function()
        local GE = RS:WaitForChild("GrabEvents", 15)
        if not GE then return end

        -- Packet Lag 감지: ExtendGrabLine 으로 큰 문자열이 들어오면 (몇 MB 인지 같이 표시)
        local ext = GE:WaitForChild("ExtendGrabLine", 10)
        if ext then
            local lastPacket = {}
            ext.OnClientEvent:Connect(function(a1, data)
                if not lagNotifyOn then return end
                if typeof(data) ~= "string" or #data <= 300 then return end
                local p = playerFromArg(a1)
                if p == LP then return end
                local key = p or "?"
                if lastPacket[key] and os.clock() - lastPacket[key] < 5 then return end
                lastPacket[key] = os.clock()
                nfy(string.format("%s\nSize: %.2f MB", label(p, a1), #data / (1024 * 1024)), "Packet Lag", "warn")
            end)
        end

        -- Line Lag 감지: CreateGrabLine 이 1초에 너무 많이 들어오면
        local create = GE:WaitForChild("CreateGrabLine", 10)
        if create then
            local buckets = {}
            local lastAlert = {}
            create.OnClientEvent:Connect(function(...)
                if not lagNotifyOn then return end
                local p
                for _, a in ipairs({ ... }) do
                    p = playerFromArg(a)
                    if p then break end
                end
                if p == LP then return end
                local key = p or "?"
                local b = buckets[key]
                if not b or os.clock() - b.t > 1 then
                    b = { t = os.clock(), n = 0 }
                    buckets[key] = b
                end
                b.n = b.n + 1
                if b.n >= 25 and (not lastAlert[key] or os.clock() - lastAlert[key] > 8) then
                    lastAlert[key] = os.clock()
                    nfy(string.format("%s\n%d calls / sec", label(p, (...)), b.n), "Line Lag", "warn")
                end
            end)
        end
    end)


    -- 친구가 서버에서 나가면 알림
    Players.PlayerRemoving:Connect(function(p)
        if not friendNotifyOn or p == LP then return end
        task.spawn(function()
            local ok, isFriend = pcall(function() return LP:IsFriendsWith(p.UserId) end)
            if ok and isFriend then
                nfy(label(p) .. "\nleft the server", "Friend Left", "info")
            end
        end)
    end)

    -- 누가 나를 잡는지 알림 (내 캐릭터 Head 의 PartOwner 값 = 잡고 있는 사람 이름)
    task.spawn(getgenv()._8minLoop("Grabbed notify", function()
        local lastGrabber = nil
        local lastNotifyAt = -1e9
        while true do
            task.wait(0.15)
            if grabbedNotifyOn then
                local char = LP.Character
                local head = char and char:FindFirstChild("Head")
                local po = head and head:FindFirstChild("PartOwner")
                local held = LP:FindFirstChild("IsHeld")
                local isHeld = (not held) or held.Value == true
                local who = po and po.Value
                if isHeld and who and who ~= "" and who ~= LP.Name then
                    if who ~= lastGrabber and (os.clock() - lastNotifyAt) >= 60 then
                        lastGrabber = who
                        lastNotifyAt = os.clock()
                        local gp = Players:FindFirstChild(who)
                        nfy((gp and label(gp) or who) .. "\nis grabbing you", "Grabbed", "warn")
                    end
                else
                    lastGrabber = nil
                end
            else
                lastGrabber = nil
            end
        end
    end))

    -- Kick 감지: 블랙홀 같은 킥 오브젝트가 생기면 가장 가까운 플레이어가 킥 당한 사람
    -- 큰 블랙홀(BlackHoleKick)만 킥으로 알림. 작은 블랙홀/트윈 등은 알리지 않음
    local KICK_NAMES = {
        ["blackholekick"] = true,
    }
    workspace.ChildAdded:Connect(function(obj)
        if not kickNotifyOn then return end
        if not (obj.Name and KICK_NAMES[obj.Name:lower()]) then return end
        task.wait(0.1)
        local pos
        if obj:IsA("BasePart") then
            pos = obj.Position
        else
            local part = obj:FindFirstChildWhichIsA("BasePart", true)
            if part then pos = part.Position end
        end
        if not pos then return end
        local closest, best = nil, math.huge
        for _, pl in ipairs(Players:GetPlayers()) do
            local hrp = pl.Character and pl.Character:FindFirstChild("HumanoidRootPart")
            if hrp then
                local dist = (hrp.Position - pos).Magnitude
                if dist < best then closest, best = pl, dist end
            end
        end
        if closest then
            nfy(label(closest), "Kicked", "fail")
        end
    end)
end

-- 제목 + 부제가 있는 접이식 탭박스 (그룹박스 안에 탭박스를 넣음). 안 되면 일반 탭박스로 대체
getgenv()._8minHeaderTabbox = function(tab, side, title, subtitle, icon)
    local ok, tbx = pcall(function()
        local gb = (side == "L") and tab:AddLeftGroupbox(title, icon) or tab:AddRightGroupbox(title, icon)
        local box = gb:AddTabbox()
        if not box then error("no nested tabbox") end
        pcall(function()
            local root = gb.Container
            for _ = 1, 3 do if root.Parent and root.Parent:IsA("GuiObject") then root = root.Parent end end
            for _, d in ipairs(root:GetDescendants()) do
                if d:IsA("TextLabel") and d.Text == title and not d:IsDescendantOf(gb.Container) then
                    d.RichText = true
                    d.Text = title .. '  <font color="rgb(125,128,145)" size="13">' .. subtitle .. '</font>'
                    break
                end
            end
        end)
        return box
    end)
    if ok and tbx then return tbx end
    return (side == "L") and tab:AddLeftTabbox() or tab:AddRightTabbox()
end

local GrabHeaderBox = getgenv()._8minHeaderTabbox(Tabs.Grab, "L", "Grab & Line", "Grab Line Settings", "spline")
local GrabGroup = GrabHeaderBox:AddTab("Grabs", "hand")
getgenv()._8minGrabLineTab = GrabHeaderBox:AddTab("Line", "spline")
local isMovable

-- =============================================
-- Loop Grab
-- =============================================
local function StopLoopGrab()
    getgenv().LoopGrabActive = false
    getgenv().FTargetGrabActive = false

    if getgenv().fGrabConnection then
        getgenv().fGrabConnection:Disconnect()
        getgenv().fGrabConnection = nil
    end
    if getgenv().LoopGrabInputConnection then
        getgenv().LoopGrabInputConnection:Disconnect()
        getgenv().LoopGrabInputConnection = nil
    end
    if getgenv().HyperGrabConnection then
        getgenv().HyperGrabConnection:Disconnect()
        getgenv().HyperGrabConnection = nil
    end
    if getgenv().SlowHoldConnection then
        getgenv().SlowHoldConnection:Disconnect()
        getgenv().SlowHoldConnection = nil
    end
end

local function StartLoopGrab(slow)
    if getgenv().LoopGrabActive then
        return
    end

    getgenv().LoopGrabActive = true

    local Players = game:GetService('Players')
    local ReplicatedStorage = game:GetService('ReplicatedStorage')
    local UserInputService = game:GetService('UserInputService')
    local RunService = game:GetService('RunService')
    local plr = Players.LocalPlayer

    local grabEvents = ReplicatedStorage:FindFirstChild('GrabEvents')
    local SetNetworkOwner = grabEvents and grabEvents:FindFirstChild('SetNetworkOwner')

    if not SetNetworkOwner then
        warn("Could not find the SetNetworkOwner remote!")
        getgenv().LoopGrabActive = false
        return
    end

    -- Slow Loop Grab: 호출을 천천히(0.12초에 1번) 보내는 느린 루프 그랩. 일반 Loop Grab 은 프레임당 8번.
    local callCount = slow and 4 or 3   -- Slow Loop Grab 은 프레임당 2번만 (렉 방지)
    local fireInterval = 0
    local lastFire = 0

    if getgenv().HyperGrabConnection then
        getgenv().HyperGrabConnection:Disconnect()
    end

    -- [최적화 1] 불필요한 연산을 루프 밖으로 빼고 리모트만 가볍게 고속 폭격
    getgenv().HyperGrabConnection = RunService.Heartbeat:Connect(function()
        if not getgenv().LoopGrabActive then
            if getgenv().HyperGrabConnection then
                getgenv().HyperGrabConnection:Disconnect()
                getgenv().HyperGrabConnection = nil
            end
            return
        end

        local grabParts = workspace:FindFirstChild('GrabParts')
        if not grabParts then return end

        local gp = grabParts:FindFirstChild('GrabPart')
        local weld = gp and gp:FindFirstChildOfClass('WeldConstraint')
        local part1 = weld and weld.Part1

        if not part1 then return end

        if fireInterval > 0 then
            if tick() - lastFire < fireInterval then return end
            lastFire = tick()
        end

        local ownerPlayer = nil
        for _, pl in ipairs(Players:GetPlayers()) do
            if pl.Character and part1:IsDescendantOf(pl.Character) then
                ownerPlayer = pl
                break
            end
        end

        if ownerPlayer then
            local tgtTorso = ownerPlayer.Character and ownerPlayer.Character:FindFirstChild('HumanoidRootPart')
            local myTorso = plr.Character and plr.Character:FindFirstChild('HumanoidRootPart')

            if tgtTorso and myTorso then
                local lookCFrame = CFrame.lookAt(myTorso.Position, tgtTorso.Position)
                -- 횟수는 그대로 유지하되 내부 연산을 최소화하여 패킷 다이어트
                for i = 1, callCount do
                    SetNetworkOwner:FireServer(tgtTorso, lookCFrame)
                end
            end
        else
            if part1.Parent then
                local myTorso = plr.Character and plr.Character:FindFirstChild('HumanoidRootPart')
                if myTorso then
                    local lookCFrame = CFrame.lookAt(myTorso.Position, part1.Position)
                    for i = 1, callCount do
                        SetNetworkOwner:FireServer(part1, lookCFrame)
                    end
                end
            end
        end
    end)

    if game.PlaceId == 6961824067 and grabEvents then
        local existingEndGrab = grabEvents:FindFirstChild('EndGrabEarly')

        if existingEndGrab then
            existingEndGrab:Destroy()
        end

        Instance.new('RemoteEvent', grabEvents).Name = 'EndGrabEarly'
    end

    getgenv().FTargetGrabActive = false
    getgenv().fGrabConnection = nil

    local function getCenterTarget()
        local cam = workspace.CurrentCamera
        local center = Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)
        local myTorso = plr.Character and plr.Character:FindFirstChild('HumanoidRootPart')

        if not myTorso then
            return nil
        end

        local closestTarget = nil
        local minScreenDist = math.huge

        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= plr and p.Character and p.Character:FindFirstChild('HumanoidRootPart') then
                local tgtTorso = p.Character.HumanoidRootPart
                local dist = (tgtTorso.Position - myTorso.Position).Magnitude

                if dist <= 25 then
                    local screenPos, onScreen = cam:WorldToViewportPoint(tgtTorso.Position)

                    if onScreen then
                        local screenDist = (Vector2.new(screenPos.X, screenPos.Y) - center).Magnitude

                        if screenDist < minScreenDist then
                            minScreenDist = screenDist
                            closestTarget = p
                        end
                    end
                end
            end
        end

        return closestTarget
    end

    if getgenv().LoopGrabInputConnection then
        getgenv().LoopGrabInputConnection:Disconnect()
        getgenv().LoopGrabInputConnection = nil
    end

    getgenv().LoopGrabInputConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if gameProcessed then
            return
        end
        if not getgenv().LoopGrabActive then
            return
        end
        if input.KeyCode == Enum.KeyCode.F then
            if getgenv().FTargetGrabActive then
                getgenv().FTargetGrabActive = false

                if getgenv().fGrabConnection then
                    getgenv().fGrabConnection:Disconnect()
                    getgenv().fGrabConnection = nil
                end
            else
                local target = getCenterTarget()

                if target then
                    getgenv().FTargetGrabActive = true
                    getgenv().FTargetGrabPlayer = target
                    local cam = workspace.CurrentCamera

                    -- [최적화 2] F키 타겟팅 구간도 무거운 CFrame 연산을 루프 밖으로 분리
                    getgenv().fGrabConnection = RunService.Heartbeat:Connect(function()
                        if not getgenv().FTargetGrabActive or not target or not target.Character then
                            getgenv().FTargetGrabActive = false
                            if getgenv().fGrabConnection then
                                getgenv().fGrabConnection:Disconnect()
                                getgenv().fGrabConnection = nil
                            end
                            return
                        end

                        local tgtTorso = target.Character:FindFirstChild('HumanoidRootPart')
                        local tgtHead = target.Character:FindFirstChild('Head')

                        if tgtTorso and tgtHead then
                            local hasPartOwner = tgtHead:FindFirstChild('PartOwner')
                            local targetPos = cam.CFrame.Position + (cam.CFrame.LookVector * 23)
                            local newCFrame = CFrame.new(targetPos)
                            local torsoCFrame = tgtTorso.CFrame

                            for i = 1, callCount do
                                SetNetworkOwner:FireServer(tgtTorso, torsoCFrame)

                                if hasPartOwner then
                                    tgtTorso.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                                    tgtTorso.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                                    tgtTorso.CFrame = newCFrame
                                    SetNetworkOwner:FireServer(tgtTorso, newCFrame)
                                end
                            end
                        end
                    end)
                end
            end
        end
    end)
end

-- =============================================
-- Kick Grab
-- =============================================
local kickToken = 0 -- 껐다 켜거나 타입을 바꿀 때 이전 스레드가 겹쳐 돌지 않게 구분

local function StopKickGrab()
    kickToken = kickToken + 1
    getgenv().KickGrabActive = false
    getgenv().FKeyAttackActive = false

    if getgenv().FKeyInputConnection then
        getgenv().FKeyInputConnection:Disconnect()
        getgenv().FKeyInputConnection = nil
    end
end

local function StartKickGrab()
    if getgenv().KickGrabActive then
        return
    end

    kickToken = kickToken + 1
    local myToken = kickToken

    getgenv().KickGrabActive = true
    getgenv().FKeyAttackActive = false

    local Players = game:GetService('Players')
    local ReplicatedStorage = game:GetService('ReplicatedStorage')
    local UserInputService = game:GetService('UserInputService')
    local RunService = game:GetService('RunService')
    local plr = Players.LocalPlayer
    local camera = workspace.CurrentCamera
    local GrabEvents = ReplicatedStorage:WaitForChild('GrabEvents')
    local CreateGrabLine = GrabEvents:WaitForChild('CreateGrabLine')
    local SetNetworkOwner = GrabEvents:WaitForChild('SetNetworkOwner')
    local DestroyGrabLine = GrabEvents:WaitForChild('DestroyGrabLine')

    -- WaitForChild 도중에 껐거나 타입을 바꿨다면 시작하지 않음
    if myToken ~= kickToken then
        return
    end

    -- 켜 둔 동안만 계속 (에러로 죽은 반복문을 다시 시작할지 정하는 데도 씀)
    local function kickGrabWanted()
        return getgenv().KickGrabActive and myToken == kickToken
    end

    -- [1] SetNetworkOwner 전용: 스레드 13개로 폭격
    for i = 1, 3 do
        task.spawn(getgenv()._8minLoop("Kick Grab owner", function()
            while getgenv().KickGrabActive and myToken == kickToken do
                local grabParts = workspace:FindFirstChild('GrabParts')

                if grabParts then
                    local gp = grabParts:FindFirstChild('GrabPart')
                    local weld = gp and gp:FindFirstChildOfClass('WeldConstraint')
                    local part1 = weld and weld.Part1

                    if part1 then
                        local ownerPlayer = nil

                        for _, pl in ipairs(Players:GetPlayers()) do
                            if pl.Character and part1:IsDescendantOf(pl.Character) then
                                ownerPlayer = pl
                                break
                            end
                        end

                        if ownerPlayer then
                            local tgtTorso = ownerPlayer.Character and ownerPlayer.Character:FindFirstChild('HumanoidRootPart')
                            local myTorso = plr.Character and plr.Character:FindFirstChild('HumanoidRootPart')

                            if tgtTorso and myTorso then
                                pcall(function()
                                    SetNetworkOwner:FireServer(tgtTorso, CFrame.lookAt(myTorso.Position, tgtTorso.Position))
                                end)
                            end
                        end
                    end
                end

                RunService.Heartbeat:Wait()
            end
        end, kickGrabWanted))
    end

    -- [2] DestroyGrabLine 전용: 독자 실행 (핑 안정화)
    task.spawn(getgenv()._8minLoop("Kick Grab destroy", function()
        local lastDestroyTick = 0
        while getgenv().KickGrabActive and myToken == kickToken do
            local grabParts = workspace:FindFirstChild('GrabParts')

            if grabParts then
                local gp = grabParts:FindFirstChild('GrabPart')
                local weld = gp and gp:FindFirstChildOfClass('WeldConstraint')
                local part1 = weld and weld.Part1

                if part1 then
                    local ownerPlayer = nil

                    for _, pl in ipairs(Players:GetPlayers()) do
                        if pl.Character and part1:IsDescendantOf(pl.Character) then
                            ownerPlayer = pl
                            break
                        end
                    end

                    if ownerPlayer then
                        local tgtHead = ownerPlayer.Character and ownerPlayer.Character:FindFirstChild('Head')
                        local currentTime = tick()

                        if DestroyGrabLine and tgtHead and (currentTime - lastDestroyTick >= 0.04) then
                            pcall(function()
                                DestroyGrabLine:FireServer(tgtHead)
                            end)
                            lastDestroyTick = currentTime
                        end
                    end
                end
            end

            RunService.Heartbeat:Wait()
        end
    end, kickGrabWanted))

    local function getScreenCenterTarget()
        local screenCenter = Vector2.new(camera.ViewportSize.X / 2, camera.ViewportSize.Y / 2)
        local ray = camera:ViewportPointToRay(screenCenter.X, screenCenter.Y)
        local raycastParams = RaycastParams.new()

        raycastParams.FilterType = Enum.RaycastFilterType.Exclude

        if plr.Character then
            raycastParams.FilterDescendantsInstances = {
                plr.Character,
            }
        end

        local result = workspace:Raycast(ray.Origin, ray.Direction * 1000, raycastParams)

        if result and result.Instance then
            for _, pl in ipairs(Players:GetPlayers()) do
                if pl ~= plr and pl.Character and result.Instance:IsDescendantOf(pl.Character) then
                    return pl
                end
            end
        end

        return nil
    end

    local fAttackTarget = nil

    local function stopFKeyAttack()
        getgenv().FKeyAttackActive = false
        fAttackTarget = nil
    end

    local function startFKeyAttack(targetPlayer)
        getgenv().FKeyAttackActive = true
        fAttackTarget = targetPlayer

        -- 공격을 계속할지 (내가 죽었다 살아나거나 대상이 리스폰해도 멈추지 않고 이어감. 대상이 나가면 끝냄)
        local function fAttackWanted()
            if not (getgenv().FKeyAttackActive and fAttackTarget and myToken == kickToken) then
                return false
            end

            if not fAttackTarget.Parent then
                stopFKeyAttack()

                return false
            end

            return true
        end

        -- F키 타겟팅 - SetNetworkOwner 13개 스레드
        for j = 1, 8 do
            task.spawn(getgenv()._8minLoop("F-key attack", function()
                while fAttackWanted() do
                    local myChar = plr.Character
                    local myRoot = myChar and myChar:FindFirstChild('HumanoidRootPart')
                    local tgtChar = fAttackTarget.Character
                    local tgtRoot = tgtChar and tgtChar:FindFirstChild('HumanoidRootPart')

                    if not myRoot or not tgtRoot then
                        -- 캐릭터가 아직 없으면(죽음/리스폰 중) 끝내지 않고 기다렸다가 이어감
                        RunService.Heartbeat:Wait()
                        continue
                    end

                    local camCF = camera.CFrame
                    local teleportPos = camCF.Position + camCF.LookVector * 20

                    pcall(function()
                        tgtRoot.CFrame = CFrame.new(teleportPos)
                    end)

                    local grabCFrame = CFrame.new(-9.0301513671875E-2, 0.4190945625305176, 0.4999980926513672, 0.39632707834243774, 0, -0.9181094169616699, -1.0944717132588266E-7, 1, -4.7245869438938826E-8, 0.9181094169616699, 5.9604644775390625e-8, 0.39632707834243774)

                    pcall(function()
                        CreateGrabLine:FireServer(tgtRoot, grabCFrame)
                        SetNetworkOwner:FireServer(tgtRoot, CFrame.lookAt(myRoot.Position, tgtRoot.Position))
                    end)

                    RunService.Heartbeat:Wait()
                end
            end, fAttackWanted))
        end

        -- F키 타겟팅 - DestroyGrabLine 독자 스레드
        task.spawn(getgenv()._8minLoop("F-key destroy", function()
            local lastFDestroyTick = 0.15
            while fAttackWanted() do
                local tgtChar = fAttackTarget.Character
                local tgtRoot = tgtChar and tgtChar:FindFirstChild('HumanoidRootPart')

                if not tgtRoot then
                    RunService.Heartbeat:Wait()
                    continue
                end

                local currentTime = tick()
                if DestroyGrabLine and (currentTime - lastFDestroyTick >= 0.01) then
                    pcall(function()
                        DestroyGrabLine:FireServer(tgtRoot)
                    end)
                    lastFDestroyTick = currentTime
                end

                RunService.Heartbeat:Wait()
            end
        end, fAttackWanted))
    end

    getgenv().FKeyInputConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if gameProcessed then
            return
        end
        if input.KeyCode ~= Enum.KeyCode.F then
            return
        end
        if getgenv().FKeyAttackActive then
            stopFKeyAttack()
            return
        end

        local target = getScreenCenterTarget()

        if not target then
            return
        end

        local myChar = plr.Character
        local myRoot = myChar and myChar:FindFirstChild('HumanoidRootPart')
        local tgtChar = target.Character
        local tgtRoot = tgtChar and tgtChar:FindFirstChild('HumanoidRootPart')

        if not myRoot or not tgtRoot then
            return
        end

        local distance = (myRoot.Position - tgtRoot.Position).Magnitude

        if distance > 25 then
            return
        end

        startFKeyAttack(target)
    end)

    if game.PlaceId ~= 6961824067 then
        return
    end

    local G = game:GetService('ReplicatedStorage'):WaitForChild('GrabEvents')
    local endGrabEarly = G:FindFirstChild('EndGrabEarly')
    if endGrabEarly then
        endGrabEarly:Destroy()
    end

    Instance.new('RemoteEvent', G).Name = 'EndGrabEarly'
end

-- =============================================
-- Massless Grab (잡은 물건의 무게 제거)
-- =============================================
local masslessConn = nil
local MasslessSense = 30  -- Responsiveness (낮을수록 부드럽게, 높을수록 빡빡하게)

local function StopMasslessGrab()
    if masslessConn then
        masslessConn:Disconnect()
        masslessConn = nil
    end
end

-- Massless Grab: 잡기 줄(GrabParts.DragPart)의 AlignPosition/AlignOrientation 힘을 무한대로
-- (참고 허브와 같은 방식: 물건의 질량 속성은 건드리지 않음)
local function StartMasslessGrab()
    StopMasslessGrab()
    masslessConn = workspace.ChildAdded:Connect(function(m)
        if m.Name ~= "GrabParts" then return end
        task.spawn(function()
            local dp = m:WaitForChild("DragPart", 1)
            if not dp then return end
            local ap = dp:WaitForChild("AlignPosition", 1)
            local ao = dp:WaitForChild("AlignOrientation", 1)
            if not (ap and ao) then return end
            pcall(function()
                ap.Responsiveness = MasslessSense
                ap.MaxForce = math.huge
                ap.MaxVelocity = math.huge
                ao.Responsiveness = MasslessSense
                ao.MaxTorque = math.huge
            end)
        end)
    end)
end

-- =============================================
-- Kill / Void / Invisible Grab
-- =============================================
local specialConn = nil
local ragdollToy = nil
local ragdollSpawning = false
local specialMode = nil
local specialHooked = false

local function getHeldPart()
    local grabParts = workspace:FindFirstChild("GrabParts")
    local gp = grabParts and grabParts:FindFirstChild("GrabPart")
    local weld = gp and gp:FindFirstChildOfClass("WeldConstraint")
    return weld and weld.Part1, grabParts
end

-- 발신 CreateGrabLine 차단 (Invisible Grab 중 다른 사람에게도 줄이 안 보이게)
local function installGrabLineHook()
    if specialHooked or not hookmetamethod then return end
    specialHooked = true
    local old
    local wrap = newcclosure or function(f) return f end
    old = hookmetamethod(game, "__namecall", wrap(function(self, ...)
        local method = getnamecallmethod()
        if getgenv()._8minHideGrabLine and method == "FireServer"
            and typeof(self) == "Instance" and self.Name == "CreateGrabLine" then
            return
        end
        setnamecallmethod(method)
        return old(self, ...)
    end))
end

local ragdollOutlineConn = nil

-- 판자에 붙는 하얀 테두리/하이라이트(Highlight, SelectionBox 등)를 전부 지움.
-- 판자 자체는 투명해져도 이 테두리는 남아서 허공에 하얀 상자로 보이던 문제를 막음.
local function isOutlineClass(d)
    return d:IsA("Highlight") or d:IsA("SelectionBox") or d:IsA("SelectionSphere")
        or d:IsA("BoxHandleAdornment") or d:IsA("SphereHandleAdornment")
        or d:IsA("CylinderHandleAdornment") or d:IsA("ConeHandleAdornment")
        or d:IsA("SelectionPartLasso") or d:IsA("SelectionPointLasso")
end

local function belongsToToy(d, toy)
    if d:IsDescendantOf(toy) then return true end
    local ok, ad = pcall(function() return d.Adornee end)
    return ok and typeof(ad) == "Instance" and (ad == toy or ad:IsDescendantOf(toy))
end

local function killToyOutlines(toy)
    if ragdollOutlineConn then
        ragdollOutlineConn:Disconnect()
        ragdollOutlineConn = nil
    end

    local function check(d)
        if isOutlineClass(d) and belongsToToy(d, toy) then
            pcall(function() d.Enabled = false end)
            pcall(function() d.Adornee = nil end)
            pcall(function() d:Destroy() end)
        elseif d:IsA("BasePart") and d:IsDescendantOf(toy) then
            pcall(function() d.LocalTransparencyModifier = 1 end)
        end
    end

    -- 판자 안의 것만 정리 (월드 전체를 훑으면 렉이 걸려서 하지 않음)
    for _, d in ipairs(toy:GetDescendants()) do check(d) end
    ragdollOutlineConn = toy.DescendantAdded:Connect(function(d)
        check(d)
    end)
end

local ragdollHideConn = nil
local toyOrigTransparency = setmetatable({}, { __mode = "k" })
local toyHidden = false

-- 판자 보이기/숨기기 (원래 투명도를 기억해 두었다가 다시 보이게 할 수 있음)
local function setToyHidden(toy, hidden)
    if toyHidden == hidden and toyOrigTransparency[toy] then return end
    toyHidden = hidden
    toyOrigTransparency[toy] = toyOrigTransparency[toy] or {}
    local store = toyOrigTransparency[toy]
    for _, d in ipairs(toy:GetDescendants()) do
        if d:IsA("BasePart") or d:IsA("Decal") or d:IsA("Texture") then
            if store[d] == nil then store[d] = d.Transparency end
            d.Transparency = hidden and 1 or store[d]
        elseif d:IsA("Highlight") or d:IsA("SelectionBox") or d:IsA("BillboardGui") then
            pcall(function() d.Enabled = not hidden end)
        end
    end
    if hidden then
        if ragdollHideConn then ragdollHideConn:Disconnect() end
        ragdollHideConn = toy.DescendantAdded:Connect(function(d)
            if d:IsA("BasePart") or d:IsA("Decal") or d:IsA("Texture") then
                d.Transparency = 1
            end
        end)
    elseif ragdollHideConn then
        ragdollHideConn:Disconnect()
        ragdollHideConn = nil
    end
end

local ragdollLastSeen = 0
local function isRagdolledHumanoid(hum)
    local ok, st = pcall(function() return hum:GetState() end)
    -- 앉아 있는(Sit) 것은 레그돌이 아님: 예전에는 hum.Sit 도 레그돌로 봐서, 구찌 등에 앉아 있는 대상은 "이미 레그돌" 이라고 판단해 판자로 때리지 않았음.
    -- 게임이 직접 쓰는 Ragdolled 값이 있으면 그것만 기준으로 삼음
    local ragValue = hum:FindFirstChild("Ragdolled")
    if ragValue and ragValue:IsA("BoolValue") then
        local now = tick()
        if ragValue.Value then ragdollLastSeen = now end
        return (now - ragdollLastSeen) < 0.5
    end
    local rag = hum.PlatformStand
        or (ok and (st == Enum.HumanoidStateType.Physics
            or st == Enum.HumanoidStateType.Ragdoll
            or st == Enum.HumanoidStateType.FallingDown
            or st == Enum.HumanoidStateType.PlatformStanding))
    if not rag then
        -- 상태값으로 안 잡히는 레그돌: 관절(Motor6D)이 꺼졌거나 BallSocket 으로 바뀐 경우도 레그돌로 봄
        local model = hum.Parent
        if model then
            for _, d in ipairs(model:GetDescendants()) do
                if d:IsA("BallSocketConstraint") or (d:IsA("Motor6D") and d.Enabled == false) then
                    rag = true
                    break
                end
            end
        end
    end
    -- 깜빡임 방지: 레그돌이 아니라고 0.5초 연속으로 나와야 "풀렸다"고 판단 (안 풀렸는데 또 때리는 것 방지)
    local now = tick()
    if rag then ragdollLastSeen = now end
    return (now - ragdollLastSeen) < 0.5
end

local ragdollHitStart = nil
local ragdollRestUntil = 0
local ragdollRefreshAt = nil

local function ReleaseRagdollToy()
    if ragdollOutlineConn then
        ragdollOutlineConn:Disconnect()
        ragdollOutlineConn = nil
    end
    ragdollHitStart = nil
    ragdollRestUntil = 0
    toyHidden = false
    if ragdollHideConn then
        ragdollHideConn:Disconnect()
        ragdollHideConn = nil
    end
    local toy = ragdollToy
    ragdollToy = nil
    if toy and toy.Parent and H and H.dt then
        task.spawn(function() pcall(H.dt, toy) end)
    end
end

local function StopSpecialGrab()
    ReleaseRagdollToy()
    if specialConn then
        specialConn:Disconnect()
        specialConn = nil
    end
    getgenv()._8minHideGrabLine = false
    specialMode = nil
end

local function StartSpecialGrab(mode)
    StopSpecialGrab()
    specialMode = mode
    local RunService = game:GetService("RunService")

    if mode == "Invisible Grab" then
        getgenv()._8minHideGrabLine = true
        installGrabLineHook()
    end

    specialConn = RunService.Heartbeat:Connect(function()
        local part1, grabParts = getHeldPart()

        -- Ragdoll(슬로우): 잡은 게 풀려도 마지막으로 잡은 상대를 계속(새로 잡거나 끌 때까지) 레그돌 + 고정 시도
        if specialMode == "Ragdoll Grab" then
            local g = getgenv()
            if part1 then
                g._8minRagVictim, g._8minRagVictimAt = part1, tick()
            elseif g._8minRagVictim and g._8minRagVictim.Parent and tick() - (g._8minRagVictimAt or 0) < 1e9 then
                part1 = g._8minRagVictim
            end
        end

        if specialMode == "Invisible Grab" then
            -- 내 화면의 줄/빔 숨김
            if grabParts then
                for _, d in ipairs(grabParts:GetDescendants()) do
                    if d:IsA("Beam") then
                        d.Enabled = false
                    elseif d:IsA("BasePart") and d.Name ~= "GrabPart" then
                        d.Transparency = 1
                    end
                end
            end
            return
        end

        if not part1 or not isMovable(part1) then
            ReleaseRagdollToy()
            return
        end
        local root = part1.AssemblyRootPart or part1
        local destroyY = workspace.FallenPartsDestroyHeight
        local pos = root.Position

        if specialMode == "Noclip Grab" then
            -- 잡은 모델 전체 충돌 제거 (벽/바닥 통과)
            local model = part1:FindFirstAncestorOfClass("Model") or part1.Parent
            pcall(function()
                for _, d in ipairs(model:GetDescendants()) do
                    if d:IsA("BasePart") then d.CanCollide = false end
                end
                part1.CanCollide = false
            end)
            return
        end

        if specialMode == "Ragdoll Grab" then
            local model = part1:FindFirstAncestorOfClass("Model")
            local hum = model and model:FindFirstChildOfClass("Humanoid")
            if not hum then return end

            -- 판자 소환 (한 번만, 소환 중 중복 방지)
            if not ragdollToy and not ragdollSpawning and H and H.st then
                ragdollSpawning = true
                task.spawn(function()
                    local ok, toy = pcall(H.st, "PalletLightBrown")
                    ragdollToy = ok and toy or nil
                    ragdollHitStart = nil
                    if ragdollToy then killToyOutlines(ragdollToy) end
                    ragdollSpawning = false
                end)
            end

            local toy = ragdollToy
            if toy and toy.Parent then
                local main = toy:FindFirstChild("Main") or toy.PrimaryPart or toy:FindFirstChildWhichIsA("BasePart")
                local now = tick()

                -- 레그돌이 아직 아니면 때림. 레그돌이 되면(또는 0.4초 때린 뒤) 1.5초 쉼 → 계속 때려서 캐릭터가 요동치지 않게
                local isRag = isRagdolledHumanoid(hum)
                local hitting = false
                if isRag then
                    -- 레그돌이 풀리지 않게: 걸려 있는 동안에도 1초마다 아주 잠깐(0.12초) 가볍게 다시 때려서 레그돌 시간을 계속 연장
                    ragdollRestUntil = 0
                    ragdollRefreshAt = ragdollRefreshAt or (now + 1.0)
                    if now >= ragdollRefreshAt then
                        ragdollHitStart = ragdollHitStart or now
                        hitting = true
                        if now - ragdollHitStart > 0.12 then
                            hitting = false
                            ragdollHitStart = nil
                            ragdollRefreshAt = now + 1.0
                        end
                    else
                        ragdollHitStart = nil
                    end
                else
                    ragdollRefreshAt = nil
                    hitting = now >= ragdollRestUntil
                    if hitting then
                        ragdollHitStart = ragdollHitStart or now
                        if now - ragdollHitStart > 0.25 then
                            ragdollRestUntil = now + 0.35   -- 안 걸렸으면 아주 잠깐 쉬고 바로 재시도
                            ragdollHitStart = nil
                            hitting = false
                        end
                    end
                end

                if main then
                    pcall(function()
                        if hitting then
                            -- 판자를 상대 몸에 겁나 빠르게 때려 박음 (맞아야 레그돌이 됨)
                            -- 다른 사람 눈에 덜 띄게 몸 바로 옆(몸에 거의 겹치는 거리)에서 때림
                            local off = Vector3.new(math.random(-2, 2), math.random(0, 1), math.random(-2, 2))
                            if off.Magnitude < 1 then off = Vector3.new(1.5, 0.5, 0) end
                            main.CFrame = CFrame.new(root.Position + off) * CFrame.Angles(math.random() * 6, math.random() * 6, math.random() * 6)
                            main.AssemblyLinearVelocity = (-off).Unit * 120
                            main.AssemblyAngularVelocity = Vector3.zero
                        else
                            -- 쉬는 동안엔 판자를 멀리 치워 둠 (몸에 닿지 않게)
                            -- (다른 사람에게는 판자가 투명해지지 않으므로 맵 아래 깊숙이 치움: 파괴 높이 바로 위까지)
                            local parkY = math.max(workspace.FallenPartsDestroyHeight + 40, root.Position.Y - 250)
                            main.CFrame = CFrame.new(root.Position.X, parkY, root.Position.Z)
                            main.AssemblyLinearVelocity = Vector3.zero
                            main.AssemblyAngularVelocity = Vector3.zero
                        end
                    end)
                end

                setToyHidden(toy, not hitting)
            end

            -- 상대가 날아가려는 걸 막음: 속도를 계속 0 으로 (Floppy 스타일에서는 흐느적거리게 그대로 둠)
            if getgenv()._8minSlowStyle ~= "Floppy" then
                pcall(function()
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyAngularVelocity = Vector3.zero
                end)
            end
            return
        end

        pcall(function()
            if specialMode == "Kill Grab" then
                -- 파괴 높이보다 한참 아래로 보내고 아래로 계속 밀어서 즉사
                root.CFrame = CFrame.new(pos.X, destroyY - 3000, pos.Z)
                root.AssemblyLinearVelocity = Vector3.new(0, -10000, 0)
                local model = part1:FindFirstAncestorOfClass("Model")
                local head = model and model:FindFirstChild("Head")
                if head then head.CFrame = CFrame.new(pos.X, destroyY - 3000, pos.Z) end
            elseif specialMode == "Void Grab" then
                root.AssemblyLinearVelocity = Vector3.zero
                -- 공허 근처(파괴 높이 바로 위)에 계속 붙잡아 둠
                root.CFrame = CFrame.new(pos.X, destroyY + 150, pos.Z)
            end
        end)
    end)
end

-- =============================================
-- UI: Grab Type 드롭다운 + Grab 토글
-- =============================================
local grabEnabled = false
local grabType = "Loop Grab"

-- =============================================
-- Slow Loop Grab 고정력 강화: 한 번 잡으면 놓치지 않도록 소유권을 계속 되찾고 제자리에 묶어 둠
-- =============================================
local function StartSlowHold()
    if getgenv().SlowHoldConnection then
        getgenv().SlowHoldConnection:Disconnect()
        getgenv().SlowHoldConnection = nil
    end

    local grabEvents = game:GetService("ReplicatedStorage"):FindFirstChild("GrabEvents")
    local SetNetworkOwner = grabEvents and grabEvents:FindFirstChild("SetNetworkOwner")
    if not SetNetworkOwner then return end

    local RunService = game:GetService("RunService")
    local me = game:GetService("Players").LocalPlayer
    local lastRoot, lastHum, lostAt = nil, nil, 0
    local lastPos = nil
    local lockedRoot, lockedRot = nil, nil   -- 잡은 순간의 방향을 기억해서 스핀하지 않게 고정
    local EXTRA_CALLS = 2      -- 루프 그랩 호출에 더해서 프레임당 추가로 보내는 SetNetworkOwner 수 (많으면 렉)
    local KEEP_AFTER_LOSS = 1e9  -- 잡은 게 풀려도 이 시간(초) 동안은 계속 되찾으려고 시도

    getgenv().SlowHoldConnection = RunService.Heartbeat:Connect(function()
        local myRoot = me.Character and me.Character:FindFirstChild("HumanoidRootPart")
        if not myRoot then return end

        local part1, grabParts = getHeldPart()
        local model = part1 and part1:FindFirstAncestorOfClass("Model")
        local root = model and model ~= me.Character and model:FindFirstChild("HumanoidRootPart")
        local hum = model and model:FindFirstChildOfClass("Humanoid")

        if root and hum then
            -- 잡고 있는 중: 소유권 계속 강화 + 잡은 지점에 고정 + 속도 0 (몸부림으로 빠져나가지 못하게)
            lastRoot, lastHum, lostAt = root, hum, 0
            lastPos = root.Position
            -- 잡고 있는 동안에도 소유권을 계속 되찾아서 풀리지 않게 유지 (판자 레그돌이 없어졌으니 떨림 원인 아님)
            for _ = 1, EXTRA_CALLS do
                pcall(function()
                    SetNetworkOwner:FireServer(root, CFrame.lookAt(myRoot.Position, root.Position))
                end)
            end
            if getgenv()._8minSlowStyle ~= "Floppy" then
                pcall(function()
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyAngularVelocity = Vector3.zero
                end)
            end
            if getgenv()._8minSlowStyle == "Floppy" then
                -- 흐느적: 고정/속도 0 없이 소유권만 유지하고, 몸을 느리게 좌우로 흔들어 줌
                pcall(function()
                    local t = tick()
                    root.AssemblyAngularVelocity = Vector3.new(math.sin(t * 1.7) * 1.4, math.sin(t * 0.9) * 0.8, math.cos(t * 1.3) * 1.4)
                end)
            else
            pcall(function()
                    local gp = grabParts and grabParts:FindFirstChild("GrabPart")
                    if lockedRoot ~= root then
                        lockedRoot = root
                        lockedRot = root.CFrame.Rotation
                    end
                    -- 매 프레임 위치를 덮어쓰면 서버/용접과 싸우면서 캐릭터가 요동침.
                    -- 잡은 지점에서 크게 벗어났을 때(탈출 시도)만 되돌리고, 방향은 그대로 유지
                    if gp and (root.Position - gp.Position).Magnitude > 3 then
                        root.CFrame = CFrame.new(gp.Position) * lockedRot
                    end
                end)
            end
        elseif lastRoot and lastRoot.Parent and lastHum and lastHum.Parent and lastHum.Health > 0
            and (lastRoot.Position - myRoot.Position).Magnitude <= 30 then
            -- (내 범위 30칸을 벗어난 대상은 더 이상 잡으려 하지 않음: 아래 else 에서 놓음)
            -- 풀려 버린 경우: 잠깐 동안 즉시 다시 소유권을 되찾고 제자리에 묶어 둠
            if lostAt == 0 then lostAt = tick() end
            if tick() - lostAt < KEEP_AFTER_LOSS then
                for _ = 1, EXTRA_CALLS do
                    pcall(function()
                        SetNetworkOwner:FireServer(lastRoot, CFrame.lookAt(myRoot.Position, lastRoot.Position))
                    end)
                end
                pcall(function()
                    -- 풀린 뒤에도 마지막 잡은 자리에 계속 붙잡아 둠 (바닥으로 떨어져 풀려나지 않게)
                    if getgenv()._8minSlowStyle == "Floppy" then
                        local t = tick()
                        lastRoot.AssemblyAngularVelocity = Vector3.new(math.sin(t * 1.7) * 1.4, math.sin(t * 0.9) * 0.8, math.cos(t * 1.3) * 1.4)
                    else
                        if lastPos then lastRoot.CFrame = CFrame.new(lastPos) * (lockedRot or CFrame.new().Rotation) end
                        lastRoot.AssemblyLinearVelocity = Vector3.zero
                        lastRoot.AssemblyAngularVelocity = Vector3.zero
                    end
                end)
            else
                lastRoot, lastHum = nil, nil
            end
        end
    end)
end

-- =============================================
-- PCLD Kick Grab
--   Kick Grab 으로 계속 잡다가, 대상의 heldtime(탈출까지 남은 초)이 0 이 되는 순간
--   같은 프레임에 [HRP 소유권 + sethiddenproperty(HRP, "PhysicsRepRootPart", HRP) + PCLD 소유권] 을 같이 쓰고
--   PCLD 를 내가 그랩 라인으로 놓은 자리(GrabPart 위치)에 월드 좌표로 고정해 둔다.
--   heldtime 숫자를 못 찾으면: 서버가 놓아주는 순간(IsHeld 꺼짐) → 그것도 없으면 PKG_TIMEOUT 초 뒤에 씀
-- =============================================
local PKG_PCLD_NAME = "PlayerCharacterLocationDetector"
local PKG_TIMEOUT = 6
local PKG_ZERO = 0.0005
local pkgToken = 0
local pkgOrder = "HRP > Hidden > PCLD"   -- 0초에 같은 프레임에 쓰는 순서 (드롭다운)
local pkgHiddenMode = "HRP -> HRP"   -- 히든 속성(PhysicsRepRootPart) 조합 (드롭다운)
local pkgOffX, pkgOffY, pkgOffZ = 0, 15, 0   -- Kick Settings: 잡은 자리에서 얼마나 띄울지 (Y = Kick Height)
local pkgRagdoll, pkgRemoveAK = true, true   -- Ragdoll Target / Remove Anti-Kick
local pkgExtraMs = 80    -- 0 이 늦으면 올림 (슬라이더). 핑/2 + 한 프레임에 더해서 먼저 보냄

local function StopPcldKickGrab()
    pkgToken = pkgToken + 1
    getgenv().PcldKickActive = false
    -- EKI 원리: 끝날 때 히든 속성을 nil 로 되돌림
    local lt = getgenv()._8minPcldLastTgt
    if lt and lt.Parent then pcall(function() sethiddenproperty(lt, "PhysicsRepRootPart", nil) end) end
    getgenv()._8minPcldLastTgt = nil
end

local function StartPcldKickGrab()
    if getgenv().PcldKickActive then return end
    pkgToken = pkgToken + 1
    local myToken = pkgToken
    getgenv().PcldKickActive = true

    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local plr = Players.LocalPlayer

    local function wanted()
        return getgenv().PcldKickActive and myToken == pkgToken
    end

    -- 서버까지 가는 시간(핑의 절반) + 한 프레임: 0 이 되는 때에 서버에 도착하도록 이만큼 먼저 보냄
    local leadCache, leadAt = 0.05, 0
    local function leadTime()
        local t = tick()
        if t - leadAt >= 0.5 then
            leadAt = t
            pcall(function()
                local ms = game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue()
                if type(ms) == "number" then leadCache = math.clamp(ms / 2000, 0, 0.4) + 0.017 end
            end)
        end
        return leadCache + pkgExtraMs / 1000
    end

    -- 히든 속성 쓰기: 모드에 따라 (대상, 값) 조합이 달라짐. pcld 가 없으면 PCLD 가 들어가는 모드는 건너뜀
    local function writeHidden(tgtRoot, pcld)
        local mode = pkgHiddenMode
        local function put(inst, v)
            if inst and inst.Parent then
                pcall(function() sethiddenproperty(inst, "PhysicsRepRootPart", v) end)
            end
        end
        if mode == "HRP -> HRP" then put(tgtRoot, tgtRoot)
        elseif mode == "HRP -> PCLD" then if pcld then put(tgtRoot, pcld) end
        elseif mode == "PCLD -> PCLD" then if pcld then put(pcld, pcld) end
        elseif mode == "PCLD -> HRP" then if pcld then put(pcld, tgtRoot) end
        elseif mode == "HRP+PCLD -> HRP" then put(tgtRoot, tgtRoot); if pcld then put(pcld, tgtRoot) end
        elseif mode == "HRP -> nil" then put(tgtRoot, nil)
        end
    end

    -- 지금 잡고 있는 다른 플레이어
    local function heldPlayer()
        local gps = workspace:FindFirstChild("GrabParts")
        local gp = gps and gps:FindFirstChild("GrabPart")
        local weld = gp and gp:FindFirstChildOfClass("WeldConstraint")
        local p1 = weld and weld.Part1
        if not p1 then return nil end
        for _, pl in ipairs(Players:GetPlayers()) do
            if pl ~= plr and pl.Character and p1:IsDescendantOf(pl.Character) then
                return pl
            end
        end
        return nil
    end

    -- 대상 PCLD: 대상 몸 가까이에 있고, 내 몸보다 대상에 더 가까운 것
    local function findPcld(tgtRoot, myRoot)
        local best, bestD = nil, 6
        for _, o in ipairs(workspace:GetChildren()) do
            if o.Name == PKG_PCLD_NAME and o:IsA("BasePart") then
                local d = (o.Position - tgtRoot.Position).Magnitude
                local dm = myRoot and (o.Position - myRoot.Position).Magnitude or math.huge
                if d < bestD and d < dm then best, bestD = o, d end
            end
        end
        return best
    end

    -- heldtime 숫자 찾기 (이름에 held/hold time, escape, struggle 이 든 숫자 속성/NumberValue/글자)
    local function nameOk(n)
        n = string.lower(n)
        return n:find("heldtime", 1, true) or n:find("held_time", 1, true) or n:find("holdtime", 1, true)
            or n:find("hold_time", 1, true) or n:find("escape", 1, true) or n:find("struggle", 1, true)
    end
    -- 글자가 숫자 하나만 적힌 것이면 그 숫자 ("3", "2.5", "2.5s")
    local function numOf(lab)
        local t = lab.Text
        if type(t) ~= "string" then return nil end
        local n = string.match(t, "^%s*(%d+%.?%d*)%s*[sS]?%s*$")
        return n and tonumber(n) or nil
    end
    local function readSrc(src)
        local inst = src.inst
        if not inst or not inst.Parent then return nil end
        if src.kind == "attr" then
            local v = inst:GetAttribute(src.attr)
            return type(v) == "number" and v or nil
        elseif src.kind == "value" then
            return tonumber(inst.Value)
        else
            return tonumber(string.match(inst.Text or "", "%d+%.?%d*"))
        end
    end
    local function findSrc(pl, bad)
        local roots = { pl, pl.Character, plr.Character, plr:FindFirstChild("PlayerGui") }
        for _, r in ipairs(roots) do
            if r then
                local list = r:GetDescendants()
                list[#list + 1] = r
                for _, o in ipairs(list) do
                    if o:IsA("NumberValue") or o:IsA("IntValue") then
                        if nameOk(o.Name) and not bad[o] then return { kind = "value", inst = o } end
                    elseif (o:IsA("TextLabel") or o:IsA("TextBox")) and nameOk(o.Name) and not bad[o] then
                        return { kind = "text", inst = o }
                    end
                    if nameOk(o.Name) or r == o then
                        for k, v in pairs(o:GetAttributes()) do
                            if type(v) == "number" and nameOk(k) and not bad[o] then
                                return { kind = "attr", inst = o, attr = k }
                            end
                        end
                    end
                end
            end
        end
        return nil
    end

    -- 0초에 쓰는 한 묶음: 순서를 모드로 고름 (모두 같은 프레임, 사이에 대기 없음)
    -- Resonance PCLD Kick(EKI) 원리: 대상 HRP 가 내 소유면 히든 속성(PhysicsRepRootPart)을 HRP 자신으로, 아니면 nil 로
    local function eki(t)
        if not t or not t.Parent then return end
        local own = false
        pcall(function() own = H.ispartowner(t) == true end)
        getgenv()._8minPcldLastTgt = t
        pcall(function() sethiddenproperty(t, "PhysicsRepRootPart", own and t or nil) end)
    end
    local function writeBundle(tgtRoot, pcld, skyCF, count, pcldCount)
        count = count or 1
        pcldCount = pcldCount or count
        -- 같은 프레임에 정확히 count 번: 리모트와 잡기 CFrame 을 한 번만 준비하고 FireServer 만 연달아 호출 (중간에 대기 없음)
        local function hrp()
            if count <= 1 then
                pcall(function() H.grab(tgtRoot) end)
                return
            end
            local ok = pcall(function()
                local _, myRoot, hum = H.charp()
                if not myRoot or not hum or hum.Health == 0 or not tgtRoot.Parent then error("no char") end
                refreshRemotes()
                local sno = remotes.sno
                if not sno then error("no remote") end
                local cf = CFrame.new((myRoot.CFrame * CFrame.new(0, 1.593, 0)).Position, tgtRoot.Position)
                for _ = 1, count do
                    sno:FireServer(tgtRoot, cf)
                end
            end)
            if not ok then
                pcall(function() H.grab(tgtRoot) end)
            end
        end
        local function hid() writeHidden(tgtRoot, pcld) end
        local function pc()
            if pcld then
                for _ = 1, pcldCount do pcall(function() H.grab(pcld) end) end
                if skyCF then pcall(function() pcld.CFrame = skyCF end) end
            end
        end
        local map = { H = hrp, D = hid, P = pc }
        local code = ({
            ["HRP > Hidden > PCLD"] = "HDP",
            ["HRP > PCLD > Hidden"] = "HPD",
            ["PCLD > HRP > Hidden"] = "PHD",
            ["PCLD > Hidden > HRP"] = "PDH",
            ["Hidden > HRP > PCLD"] = "DHP",
            ["Hidden > PCLD > HRP"] = "DPH",
        })[pkgOrder] or "HDP"
        for i = 1, 3 do
            map[string.sub(code, i, i)]()
        end
    end

    task.spawn(getgenv()._8minLoop("PCLD Kick Grab", function()
        local ses = nil
        while wanted() do
            RunService.Heartbeat:Wait()
            local pl = heldPlayer()
            local now = tick()

            if pl and (not ses or ses.player ~= pl) then
                ses = { player = pl, t0 = now, bad = {}, probeAt = 0, probeAt2 = 0, lastSeen = now }
            elseif pl then
                ses.lastSeen = now
                -- 마지막으로 라인이 놓아 둔 자리를 기억 (라인을 놓은 뒤에도 그 자리를 씀)
                local gps0 = workspace:FindFirstChild("GrabParts")
                local gp0 = gps0 and gps0:FindFirstChild("GrabPart")
                if gp0 and gp0:IsA("BasePart") then ses.lastGp = gp0.Position end
            elseif ses and now - ses.lastSeen > 0.15 then
                -- 내가 놓으면 바로 끝: 더 이상 잡지도 쓰지도 않음
                ses = nil
            end

            local char = ses and ses.player.Character
            local tgt = char and char:FindFirstChild("HumanoidRootPart")
            local myChar = plr.Character
            local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if not (ses and tgt and myRoot) then continue end

            if not ses.fired then
                local elapsed = now - ses.t0
                local zero = false

                -- 1) 잡으면 옆에 뜨는 탈출 숫자: 화면/대상/GrabParts 의 글자 중 "줄어드는 숫자" 를 찾아 그게 0 이 되는 순간
                --    (이름은 안 봄. 숫자만 적힌 글자가 계속 줄어들기만 하면 그것으로 봄. 글자가 사라져도 0 으로 침)
                if not ses.src and elapsed <= 3 and now - ses.probeAt >= 0.3 then
                    ses.probeAt = now
                    ses.cands = ses.cands or {}
                    local roots = { char, workspace:FindFirstChild("GrabParts"), plr:FindFirstChild("PlayerGui"), ses.player:FindFirstChild("PlayerGui") }
                    for _, r in ipairs(roots) do
                        if r then
                            for _, o in ipairs(r:GetDescendants()) do
                                if (o:IsA("TextLabel") or o:IsA("TextBox")) and not ses.cands[o] then
                                    ses.cands[o] = { drops = 0, rises = 0 }
                                end
                            end
                        end
                    end
                end
                if not ses.src and ses.cands then
                    for lab, c in pairs(ses.cands) do
                        if not lab.Parent then
                            ses.cands[lab] = nil
                        else
                            local v = numOf(lab)
                            if v ~= nil then
                                if c.last ~= nil then
                                    if v < c.last - 0.0005 then c.drops = c.drops + 1
                                    elseif v > c.last + 0.0005 then c.rises = c.rises + 1 end
                                end
                                c.last = v
                                if c.drops >= 2 and c.rises == 0 and v > PKG_ZERO then
                                    ses.src = { kind = "label", inst = lab }
                                    ses.armed, ses.lastV, ses.changedAt = true, v, now
                                    ses.cands = nil
                                    break
                                end
                            end
                        end
                    end
                end
                if not ses.src and elapsed <= 3 and now - ses.probeAt2 >= 0.5 then
                    ses.probeAt2 = now
                    ses.src = findSrc(ses.player, ses.bad)
                    ses.armed, ses.lastV, ses.changedAt = false, nil, now
                end
                if ses.src then
                    local inst = ses.src.inst
                    local v
                    if ses.src.kind == "label" then
                        if not inst.Parent or inst.Visible == false then v = 0 else v = numOf(inst) end
                    else
                        v = readSrc(ses.src)
                    end
                    if v ~= nil then
                        if ses.lastV == nil or math.abs(v - ses.lastV) > 0.0001 then ses.changedAt = now end
                        local prevV = ses.lastV
                        ses.lastV = v
                        if v > PKG_ZERO then ses.armed = true
                        elseif ses.armed then zero = true end

                        -- 미리 예측: 0 까지 남은 시간이 (핑/2 + 한 프레임) 이하가 되면 지금 보냄
                        if not zero and ses.armed then
                            local lead = leadTime()
                            ses.hist = ses.hist or {}
                            ses.hist[#ses.hist + 1] = { now, v }
                            if #ses.hist > 8 then table.remove(ses.hist, 1) end
                            local h1, hn = ses.hist[1], ses.hist[#ses.hist]
                            if #ses.hist >= 3 and hn[1] - h1[1] > 0.1 and h1[2] > hn[2] + 0.0005 then
                                local rate = (h1[2] - hn[2]) / (hn[1] - h1[1])
                                if rate > 0 and v / rate <= lead then zero = true end
                            end
                            -- 1,2,3 처럼 정수로 줄어드는 글자: 마지막 1 이 켜진 뒤 (한 칸 시간 - lead) 가 지나면 지금 보냄
                            if not zero and prevV and math.abs(v - prevV) > 0.0001 then
                                ses.tick = ses.tick or {}
                                ses.tick.period = ses.tick.at and (now - ses.tick.at) or nil
                                ses.tick.at = now
                            end
                            local tk = ses.tick
                            if not zero and tk and tk.period and tk.at and v > 0 and v <= 1.0001 and v == math.floor(v)
                                and now - tk.at >= tk.period - lead then
                                zero = true
                            end
                        end
                    end
                    if now - ses.changedAt > 1.5 and not zero then
                        ses.bad[inst] = true -- 안 변하는 숫자는 탈출 숫자가 아님
                        ses.src = nil
                    end
                end

                -- 2) 숫자가 없으면 서버가 놓아주는 순간 (IsHeld 켜졌다가 꺼짐)
                if not ses.src then
                    local flag = ses.player:FindFirstChild("IsHeld")
                    if flag and flag:IsA("BoolValue") and elapsed >= 0.25 then
                        if flag.Value then ses.sawHeld = true
                        elseif ses.sawHeld then zero = true end
                    end
                end

                -- 3) 그것도 없으면 시간으로
                if elapsed >= PKG_TIMEOUT then zero = true end

                local reason = ses.src and "number" or (ses.sawHeld and "IsHeld" or "timeout")

                if zero and pl then
                    -- heldtime 0: 그 순간에 딱 다시 잡음 (HRP 소유권 + 히든 속성 + PCLD 소유권을 같은 프레임에. 잡기 라인은 새로 안 만듦)
                    local pcld = findPcld(tgt, myRoot) or ses.pcld
                    local gps = workspace:FindFirstChild("GrabParts")
                    local gpart = gps and gps:FindFirstChild("GrabPart")
                    local at = (gpart and gpart:IsA("BasePart")) and gpart.Position or ses.lastGp or tgt.Position
                    ses.skyCF = CFrame.new(at + Vector3.new(pkgOffX, pkgOffY, pkgOffZ))
                    -- Kick Settings: 상대 안티킥 표창 제거 + 레그돌
                    if pkgRemoveAK and tgt.Parent then
                        pcall(function()
                            for _, d in ipairs(tgt.Parent:GetDescendants()) do
                                if d:IsA("BasePart") then
                                    for _, c in ipairs(d:GetConnectedParts()) do
                                        if c.Name == "StickyPart" and c.Parent and (c.Parent.Name == "NinjaShuriken" or c.Parent.Name == "ShurikenRSC") then
                                            H.dt(c.Parent)
                                        end
                                    end
                                end
                            end
                        end)
                    end
                    if pkgRagdoll and tgt.Parent then
                        task.spawn(function() pcall(H.ragdoll, tgt.Parent) end)
                    end
                    -- 0초 한 프레임에 몸(HRP) 소유권 + 히든 속성 + PCLD 소유권을 한 번씩 (순서는 드롭다운)
                    writeBundle(tgt, pcld, ses.skyCF)
                    -- EKI 원리: 잡은 뒤 0.2초 / 0.6초 뒤에 소유권을 확인하고 히든 속성을 씀
                    task.delay(0.2, function() if wanted() then eki(tgt) end end)
                    task.delay(0.6, function() if wanted() then eki(tgt) end end)
                    -- 타이밍이 한두 프레임 어긋나도 걸리도록 바로 다음 두 프레임에도 같은 묶음을 한 번씩 더 보냄 (잡고 있는 동안만)
                    do
                        local sesRef, tgtRef, pcldRef, skyRef = ses, tgt, pcld, ses.skyCF
                        task.spawn(function()
                            for _ = 1, 2 do
                                RunService.Heartbeat:Wait()
                                if not wanted() or ses ~= sesRef or not heldPlayer() then return end
                                writeBundle(tgtRef, pcldRef, skyRef)
                            end
                        end)
                    end
                    print(string.format("[8min PCLD Kick] 0초 재잡기 (%s) 남은값=%s 앞당김=%.0fms PCLD %s", reason, tostring(ses.lastV), leadTime() * 1000, pcld and "found" or "NOT FOUND"))
                    ses.pcld = pcld
                    ses.hiddenAt = now
                    ses.firedAt = now
                    -- 다시 잡았으니 heldtime 이 새로 시작함: 다음 0 을 또 기다림 (잡고 있는 동안 계속 반복)
                    ses.t0 = now
                    ses.src, ses.cands, ses.armed, ses.lastV, ses.sawHeld = nil, nil, false, nil, nil
                    ses.hist, ses.tick = nil, nil
                    ses.probeAt, ses.probeAt2 = 0, 0
                    ses.bad = {}
                end
            end

            -- 한 번이라도 재잡기를 했다면 PCLD 를 그 자리에 계속 둠 (히든 속성도 주기적으로)
            if ses.skyCF and pl then
                local pcld = ses.pcld
                if not pcld or not pcld.Parent then
                    pcld = findPcld(tgt, myRoot)
                    ses.pcld = pcld
                end
                if pcld then
                    pcall(function() H.grab(pcld) end)
                    local owned = false
                    pcall(function() owned = H.ispartowner(pcld) == true end)
                    if ses.wasOwned and not owned then
                        -- 오너십을 잃은 순간: 마지막 재잡기 뒤 몇 초 만에 잃었는지 찍고, 바로 몸+PCLD+히든 속성을 다시 같이 씀
                        print(string.format("[8min PCLD Kick] PCLD 오너십 잃음 (재잡기 후 %.2f초)", now - (ses.firedAt or now)))
                        writeBundle(tgt, pcld, nil)
                        writeBundle(tgt, pcld, nil)
                    end
                    ses.wasOwned = owned
                    if owned then
                        pcall(function()
                            pcld.CFrame = ses.skyCF
                            pcld.AssemblyLinearVelocity = Vector3.zero
                            pcld.AssemblyAngularVelocity = Vector3.zero
                        end)
                    end
                end
                if now - (ses.hiddenAt or 0) >= 0.15 then
                    ses.hiddenAt = now
                    -- 잡고 있는 동안 0.15초마다 같은 묶음(몸 소유권 + 히든 속성 + PCLD 소유권)을 다시 써서 계속 내 것으로 유지
                    writeBundle(tgt, ses.pcld, nil)
                    eki(tgt)
                end
            end
        end
    end, wanted))
end

-- 아래에서 정의되는 함수/변수 미리 선언 (RefreshGrab 에서 사용)
local StartSuperGrab, StopSuperGrab, StartSpinGrab, StopSpinGrab
local superEnabled, spinEnabled
local grabModes = {}   -- 선택된 그랩 모드들 (다중 선택)

local function RefreshGrab()
    -- 전부 끈 다음, 켜져 있으면 선택한 모드들을 시작
    StopLoopGrab()
    StopKickGrab()
    StopPcldKickGrab()
    StopMasslessGrab()
    StopSpecialGrab()
    StopSuperGrab()
    StopSpinGrab()
    superEnabled = false
    spinEnabled = false

    if not grabEnabled then
        return
    end

    local m = grabModes
    local loopStarted = false

    -- 상대에게 직접 작용하는 모드(하나만 동시에 가능): Slow Loop > Kill > Void > Invisible > Noclip
    if m["Slow Loop Grab"] then
        -- 루프 그랩(SetNetworkOwner 호출) + 레그돌 판자로 상대를 레그돌 상태로 만듦
        StartLoopGrab(true)
        loopStarted = true
        StartSpecialGrab("Ragdoll Grab")
        StartSlowHold()
    else
        -- Kill/Void/Invisible/Noclip/Massless/Spin/Fling/Ragdoll/TP 그랩은 Resonance 엔진이 처리함 (아래 Resonance 이식 블록)
    end

    if m["Loop Grab"] and not loopStarted then StartLoopGrab() end
    if m["Kick Grab"] or m["PCLD Kick Grab"] then task.spawn(StartKickGrab) end
    if m["PCLD Kick Grab"] then task.spawn(StartPcldKickGrab) end
end

local MasslessSlider, SuperSlider, SpinSlider = nil, nil, nil
local function updateGrabSliders()
    local function vis(sl, on)
        if sl and sl.SetVisible then pcall(function() sl:SetVisible(on) end) end
    end
    vis(MasslessSlider, grabModes["Massless Grab"] == true)
    vis(SuperSlider, grabModes["Super Strength Grab"] == true)
    vis(SpinSlider, grabModes["Spin Grab"] == true)
end

getgenv()._8minPcldStart = StartPcldKickGrab
getgenv()._8minPcldStop = StopPcldKickGrab
GrabGroup:AddDropdown("GrabType", {
    Text = "Grab Mode",
    Values = { "Loop Grab", "Kick Grab", "PCLD Kick Grab", "Massless Grab", "Kill Grab", "Void Grab", "Invisible Grab", "Slow Loop Grab", "Noclip Grab", "Super Strength Grab", "Spin Grab" },
    Default = {},
    Multi = true,
    Tooltip = "Pick one or more grab modes. They all run together when the toggle is ON (Kill/Void/Invisible/Noclip/Slow Loop: only one of them at a time).",
    Callback = function(Value)
        local m = {}
        if type(Value) == "table" then
            for k, v in pairs(Value) do
                if type(k) == "number" then m[v] = true elseif v then m[k] = true end
            end
        elseif Value then
            m[Value] = true
        end
        grabModes = m
        updateGrabSliders()
        if grabEnabled then
            RefreshGrab()
        end
    end,
})

GrabGroup:AddToggle("GrabEnabled", {
    Text = "Toggle",
    Default = false,
    Callback = function(Value)
        grabEnabled = Value
        RefreshGrab()
    end,
}):AddKeyPicker("GrabEnabledKey", {
    Default = "None",
    Mode = "Toggle",
    Text = "Grab",
    NoUI = false,
    Callback = function(Value)
        if Library.Toggles and Library.Toggles.GrabEnabled then
            Library.Toggles.GrabEnabled:SetValue(Value)
        end
    end,
})

pcall(function() GrabGroup:AddDivider("Grab Settings") end)

getgenv()._8minSlowStyle = "Fixed"   -- 흐느적(Floppy) 옵션은 제거됨: 항상 고정

GrabGroup:AddDropdown("PcldWriteOrder", {
    Text = "PCLD Write Order",
    Values = { "HRP > Hidden > PCLD", "HRP > PCLD > Hidden", "PCLD > HRP > Hidden", "PCLD > Hidden > HRP", "Hidden > HRP > PCLD", "Hidden > PCLD > HRP" },
    Default = "HRP > Hidden > PCLD",
    Multi = false,
    Tooltip = "PCLD Kick Grab: order of the three writes sent in the same frame at 0 (HRP ownership / PhysicsRepRootPart / PCLD ownership). Try them one by one.",
    Callback = function(Value)
        pkgOrder = tostring(Value or "HRP > Hidden > PCLD")
    end,
})

GrabGroup:AddDropdown("PcldHiddenMode", {
    Text = "PCLD Hidden Prop",
    Values = { "HRP -> HRP", "HRP -> PCLD", "PCLD -> PCLD", "PCLD -> HRP", "HRP+PCLD -> HRP", "HRP -> nil", "None" },
    Default = "HRP -> HRP",
    Multi = false,
    Tooltip = "PCLD Kick Grab: which PhysicsRepRootPart write to use (target -> value). Try them one by one.",
    Callback = function(Value)
        pkgHiddenMode = tostring(Value or "HRP -> HRP")
    end,
})

GrabGroup:AddSlider("PcldLeadMs", {
    Text = "PCLD Lead (ms)",
    Default = 80, Min = 0, Max = 400, Rounding = 0,
    Tooltip = "PCLD Kick Grab: send the re-grab this many ms earlier (on top of ping/2). Raise it if the 0 moment is late, lower it if it fires too early.",
    Callback = function(Value)
        pkgExtraMs = tonumber(Value) or 80
    end,
})

GrabGroup:AddToggle("PcldRagdollTarget", {
    Text = "Ragdoll Target",
    Default = true,
    Tooltip = "PCLD Kick Grab: ragdoll the target when kicking.",
    Callback = function(Value) pkgRagdoll = Value == true end,
})
GrabGroup:AddToggle("PcldRemoveAntiKick", {
    Text = "Remove Anti-Kick",
    Default = true,
    Tooltip = "PCLD Kick Grab: delete the target's anti-kick shurikens when kicking.",
    Callback = function(Value) pkgRemoveAK = Value == true end,
})
