-- =============================================
-- Super Grab (잡고 놓으면 멀리 날려보냄) + 강도 슬라이더
-- =============================================
-- 지형/맵(고정된 파트)은 건드리지 않도록 걸러내는 함수
function isMovable(part)
    if not part or not part.Parent then return false end
    if part:IsA("Terrain") then return false end
    local root = part.AssemblyRootPart or part
    if part.Anchored or root.Anchored then return false end
    -- 매우 큰 파트(맵 바닥 등)는 제외
    local sz = root.Size
    if sz.X > 60 or sz.Y > 60 or sz.Z > 60 then return false end
    return true
end

superEnabled = false
local superPower = 4000
local superConn = nil

function StopSuperGrab()
    if superConn then
        superConn:Disconnect()
        superConn = nil
    end
end

function StartSuperGrab()
    StopSuperGrab()

    local RunService = game:GetService("RunService")
    local cam = workspace.CurrentCamera
    local heldPart = nil      -- 지금 잡고 있는 파트
    local throwPart = nil     -- 방금 놓은 파트 (날리는 중)
    local throwDir = nil
    local throwUntil = 0

    superConn = RunService.Heartbeat:Connect(function()
        if not superEnabled then
            StopSuperGrab()
            return
        end

        cam = workspace.CurrentCamera or cam
        local grabParts = workspace:FindFirstChild("GrabParts")
        local gp = grabParts and grabParts:FindFirstChild("GrabPart")
        local weld = gp and gp:FindFirstChildOfClass("WeldConstraint")
        local part1 = weld and weld.Part1

        if part1 and isMovable(part1) then
            -- 잡는 중: 던질 방향은 카메라가 보는 쪽으로 계속 갱신
            heldPart = part1
            throwDir = cam.CFrame.LookVector
        elseif heldPart then
            -- 방금 놓음 → 일정 시간 동안 속도를 몰아줘서 멀리 날림
            throwPart = heldPart
            heldPart = nil
            throwUntil = tick() + 0.4
        end

        if throwPart and tick() < throwUntil and throwDir then
            local root = throwPart.AssemblyRootPart or throwPart
            if root and root.Parent then
                pcall(function()
                    root.AssemblyLinearVelocity = throwDir * superPower + Vector3.new(0, superPower * 0.05, 0)
                end)
            end
        elseif throwPart and tick() >= throwUntil then
            throwPart = nil
        end
    end)
end

