-- Spin Grab (잡으면 빙글빙글 돎)
-- =============================================
spinEnabled = false
local spinLevel = 5   -- 1~10
local spinConn = nil

function StopSpinGrab()
    if spinConn then
        spinConn:Disconnect()
        spinConn = nil
    end
end

function StartSpinGrab()
    StopSpinGrab()

    local RunService = game:GetService("RunService")
    local plr = game:GetService("Players").LocalPlayer

    spinConn = RunService.Heartbeat:Connect(function()
        if not spinEnabled then
            StopSpinGrab()
            return
        end

        local part1 = getHeldPart()
        if not part1 or not isMovable(part1) then return end

        local myChar = plr.Character
        if myChar and part1:IsDescendantOf(myChar) then return end

        local model = part1:FindFirstAncestorOfClass("Model")
        local root = (model and (model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart))
            or part1.AssemblyRootPart or part1
        if not root then return end

        pcall(function()
            root.AssemblyAngularVelocity = Vector3.new(0, spinLevel * 12, 0)
            root.CFrame = root.CFrame * CFrame.Angles(0, math.rad(spinLevel * 7), 0)
        end)
    end)
end

