-- =============================================
-- Line Lag (CreateGrabLine 폭격) 강도 1~10
-- =============================================
local lineLagEnabled = false
local lineLagPower = 5      -- 1~10 단계
local lineLagConn = nil     -- (호환용) 이전 버전 변수
local lineLagToken = 0

local function StopLineLag()
    lineLagToken = lineLagToken + 1
    if lineLagConn then
        lineLagConn:Disconnect()
        lineLagConn = nil
    end
end

-- 참고 허브 방식(호출 수만 낮춤): 0.1초마다 CreateGrabLine 을 레벨 수만큼 호출. 줄의 끝을 하늘 높이(9e9)로 보냄.
local function StartLineLag()
    StopLineLag()
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local grabEvents = ReplicatedStorage:FindFirstChild("GrabEvents")
    local CreateGrabLine = grabEvents and grabEvents:FindFirstChild("CreateGrabLine")
    if not CreateGrabLine then
        warn("Could not find the CreateGrabLine remote!")
        return
    end
    local myToken = lineLagToken
    task.spawn(function()
        while lineLagEnabled and lineLagToken == myToken do
            local spawnLoc = workspace:FindFirstChild("SpawnLocation") or workspace:FindFirstChild("Spawn")
            if not spawnLoc then
                local pl = game:GetService("Players").LocalPlayer
                spawnLoc = pl.Character and pl.Character:FindFirstChild("HumanoidRootPart")
            end
            if spawnLoc then
                -- 호출 수를 크게 낮춤: 레벨 n = 초당 n x 10번 (레벨 1 = 10/s, 레벨 10 = 100/s)
                -- 한꺼번에 보내지 않고 0.1초마다 나눠서 보내 핑이 튀지 않게 함
                local perTick = lineLagPower
                for _ = 1, perTick do
                    pcall(function()
                        CreateGrabLine:FireServer(spawnLoc, CFrame.new(0, 9e9, 0))
                    end)
                end
            end
            task.wait(0.1)
        end
    end)
end

