local function updateHighlight(target, enabled, fillColor, outlineColor, name, fillTransparency)
    if not target then return end
    local highlight = target:FindFirstChild(name)
    fillTransparency = fillTransparency or 0.5

    if enabled then
        if not highlight then
            highlight = Instance.new("Highlight")
            highlight.Name = name
            highlight.Adornee = target
            highlight.Parent = target
            highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        end
        if highlight.FillTransparency ~= fillTransparency then highlight.FillTransparency = fillTransparency end
        if highlight.FillColor ~= fillColor then highlight.FillColor = fillColor end
        if highlight.OutlineColor ~= outlineColor then highlight.OutlineColor = outlineColor end
        if not highlight.Enabled then highlight.Enabled = true end
    else
        if highlight then highlight:Destroy() end
    end
end

-- Player "Transparent" mode: the body becomes clean reflective glass (same look as PCLD 3D).
-- Everything is client-side only. Original values are saved so they can be restored exactly.
local savedProps = setmetatable({}, { __mode = "k" }) -- [Instance] = { PropertyName = originalValue }

local function setSaved(inst, prop, value)
    local saved = savedProps[inst]
    if not saved then
        saved = {}
        savedProps[inst] = saved
    end
    if saved[prop] == nil then saved[prop] = inst[prop] end
    if inst[prop] ~= value then inst[prop] = value end
end

local function restoreBodyGlass()
    for inst, props in pairs(savedProps) do
        if inst.Parent then
            for prop, value in pairs(props) do
                pcall(function() inst[prop] = value end)
            end
        end
        savedProps[inst] = nil
    end
end

local function applyBodyGlass(character, transparency, reflectance, tint)
    for _, d in ipairs(character:GetDescendants()) do
        if d:IsA("BasePart") then
            if d.Name ~= "HumanoidRootPart" then
                local saved = savedProps[d]
                local originalTransparency = saved and saved.Transparency or d.Transparency
                if originalTransparency < 1 then -- skip parts that are invisible by design
                    setSaved(d, "Transparency", math.max(originalTransparency, transparency))
                    setSaved(d, "Material", Enum.Material.Glass)
                    setSaved(d, "Color", tint)
                    setSaved(d, "Reflectance", reflectance)
                    if d:IsA("MeshPart") then setSaved(d, "TextureID", "") end
                end
            end
        elseif d:IsA("Decal") or d:IsA("Texture") then
            setSaved(d, "Transparency", 1) -- hide face / stickers for a clean glass body
        elseif d:IsA("Shirt") then
            setSaved(d, "ShirtTemplate", "")
        elseif d:IsA("Pants") then
            setSaved(d, "PantsTemplate", "")
        elseif d:IsA("ShirtGraphic") then
            setSaved(d, "Graphic", "")
        end
    end
end

