end

local function updatePlayerHighlight(player, character, enabled, fillColor, outlineColor, fillTransparency)
    if not (enabled and character) then
        removePlayerHighlight(player)
        return
    end

    local highlight = playerHighlights[player]
    if not highlight or not highlight.Parent then
        highlight = Instance.new("Highlight")
        highlight.Name = "PlayerESP"
        highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        highlight.OutlineTransparency = 0
        highlight.Parent = espContainer
        playerHighlights[player] = highlight
    end

    if highlight.Adornee ~= character then highlight.Adornee = character end
    if highlight.FillColor ~= fillColor then highlight.FillColor = fillColor end
    if highlight.OutlineColor ~= outlineColor then highlight.OutlineColor = outlineColor end
    if highlight.FillTransparency ~= fillTransparency then highlight.FillTransparency = fillTransparency end
    if not highlight.Enabled then highlight.Enabled = true end
end

Players.PlayerRemoving:Connect(removePlayerHighlight)

-- Highlights are checked every frame (no gaps); the heavier body-transparency pass runs every 0.1s
local bodyTimer = 0
RunService.RenderStepped:Connect(function(dt)
    bodyTimer = bodyTimer + dt
    local doBodyPass = bodyTimer >= 0.1
    if doBodyPass then bodyTimer = 0 end

    local enabled = Toggles.PlayerEspToggle and Toggles.PlayerEspToggle.Value
    local fillColor = Options.PlayerEspFillColor and Options.PlayerEspFillColor.Value or Color3.fromRGB(255, 0, 255)
    local outlineColor = Options.PlayerEspOutlineColor and Options.PlayerEspOutlineColor.Value or Color3.fromRGB(255, 255, 255)
    local mode = Options.PlayerEspMode and Options.PlayerEspMode.Value or "Colored"
    local colorTransparency = Options.PlayerEspFillTransparency and Options.PlayerEspFillTransparency.Value or 0.3
    local bodyTransparency = Options.PlayerEspBodyTransparency and Options.PlayerEspBodyTransparency.Value or 0.8
    local bodyReflectance = Options.PlayerEspReflectance and Options.PlayerEspReflectance.Value or 0.85

    local transparentMode = enabled and mode == "Transparent"
    if doBodyPass and not transparentMode then restoreBodyGlass() end

    for _, otherPlayer in ipairs(Players:GetPlayers()) do
        if otherPlayer ~= plr then
            -- pcall per player so one broken character cannot stop the others
            pcall(function()
                local character = otherPlayer.Character
                -- Colored: body painted with the fill color. Transparent: outline only, body see-through.
                updatePlayerHighlight(otherPlayer, character, enabled, fillColor, outlineColor,
                    transparentMode and 1 or colorTransparency)
                if doBodyPass and transparentMode and character then
                    applyBodyGlass(character, bodyTransparency, bodyReflectance, fillColor)
                end
            end)
        end
    end
end)

--=============================================
-- PCLD ESP (translucent fill + thin outline + smooth follow)
--=============================================
-- pcldEntries[pcldPart] = { box = SelectionBox, proxy = Part }
-- The SelectionBox adorns a proxy part that smoothly follows the real PCLD.
local pcldEntries = {}

-- true  = real 3D glass part (hidden behind walls)
-- false = flat overlay that is always visible on top of everything
local function getPcld3D()
    if Toggles.PcldEsp3D then return Toggles.PcldEsp3D.Value end
    return false
end

local function getPcldStyle()
    local fillColor = Options.PcldEspFillColor and Options.PcldEspFillColor.Value or Color3.fromRGB(205, 232, 255)
    local outlineColor = Options.PcldEspOutlineColor and Options.PcldEspOutlineColor.Value or Color3.fromRGB(255, 255, 255)
    local fillTransparency = Options.PcldEspFillTransparency and Options.PcldEspFillTransparency.Value or 0.8
    local outlineTransparency = Options.PcldEspOutlineTransparency and Options.PcldEspOutlineTransparency.Value or 0.3
    local thickness = Options.PcldEspLineThickness and Options.PcldEspLineThickness.Value or 0.006
    local reflectance = Options.PcldEspReflectance and Options.PcldEspReflectance.Value or 0.85
    return fillColor, outlineColor, fillTransparency, outlineTransparency, thickness, reflectance
end

local function applyPcldStyle(entry)
    local fillColor, outlineColor, fillT, outlineT, thickness, reflectance = getPcldStyle()
    local proxy = entry.proxy

    if getPcld3D() then
        -- Clean reflective glass body (real part, depth-tested like a real object)
        proxy.Material = Enum.Material.Glass
        proxy.CastShadow = false
        proxy.Color = fillColor
        proxy.Transparency = fillT
        proxy.Reflectance = reflectance
        entry.fill.Visible = false
    else
        -- Flat overlay that shows through walls
        proxy.Transparency = 1
        proxy.Reflectance = 0
        entry.fill.Visible = true
        entry.fill.Color3 = fillColor
        entry.fill.Transparency = fillT
        entry.fill.AlwaysOnTop = true
    end
    -- Edges only: SelectionBox with a fully transparent surface
    entry.box.Color3 = outlineColor
    entry.box.Transparency = outlineT
    entry.box.LineThickness = thickness
    entry.box.SurfaceTransparency = 1
end

local function isPcldPart(obj)
    return obj and obj:IsA("BasePart") and
        (obj.Name == "PlayerCharacterLocationDetector" or obj.Name == "me")
end

local function destroyPcldEntry(obj)
    local entry = pcldEntries[obj]
    if entry then
        if entry.fill then entry.fill:Destroy() end
        if entry.box then entry.box:Destroy() end
        if entry.proxy then entry.proxy:Destroy() end
        pcldEntries[obj] = nil
    end
end

local function addPcldEntry(obj)
    if not isPcldPart(obj) or pcldEntries[obj] then return end

    local proxy = Instance.new("Part")
    proxy.Name = "PcldSmoothProxy"
    proxy.Anchored = true
    proxy.CanCollide = false
    proxy.CanQuery = false
    proxy.CanTouch = false
    proxy.CastShadow = false
    proxy.Transparency = 1
    proxy.Size = obj.Size
    proxy.CFrame = obj.CFrame
    proxy.Parent = workspace.CurrentCamera

    local fill = Instance.new("BoxHandleAdornment")
    fill.Name = "PcldFill"
    fill.Adornee = proxy
    fill.Size = proxy.Size
    fill.ZIndex = 1
    fill.Parent = proxy

    local box = Instance.new("SelectionBox")
    box.Name = "PcldSelectionBox"
    box.Adornee = proxy
    box.Parent = proxy

    local entry = { box = box, fill = fill, proxy = proxy }
    applyPcldStyle(entry)
    pcldEntries[obj] = entry
end

local function refreshPcldStyle()
    for obj, entry in pairs(pcldEntries) do
        if obj.Parent and entry.box.Parent then
            applyPcldStyle(entry)
        else
            destroyPcldEntry(obj)
        end
    end
end

local function clearPcldEntries()
    for obj in pairs(pcldEntries) do
        destroyPcldEntry(obj)
    end
end

local function PcldViewF()
    if Toggles.PcldEspToggle and Toggles.PcldEspToggle.Value then
        -- Handle PCLDs that already exist; new ones are caught by DescendantAdded below
        for _, obj in ipairs(Workspace:GetDescendants()) do
            addPcldEntry(obj)
        end
    else
        clearPcldEntries()
    end
end

-- Smooth follow: runs every frame, but only touches existing proxies
local TELEPORT_SNAP_DISTANCE = 50 -- studs; snap instantly if the PCLD jumps farther than this
RunService.RenderStepped:Connect(function(dt)
    if next(pcldEntries) == nil then return end

    local smoothness = Options.PcldEspSmoothness and Options.PcldEspSmoothness.Value or 0.5
    local alpha = 1
    if smoothness > 0 then
        local speed = 30 * (1 - smoothness) + 2 -- higher smoothness = slower follow
        alpha = 1 - math.exp(-speed * dt)
    end

    for obj, entry in pairs(pcldEntries) do
        local proxy = entry.proxy
        if obj.Parent and proxy and proxy.Parent then
            local targetCFrame = obj.CFrame
            if alpha >= 1 or (proxy.Position - targetCFrame.Position).Magnitude > TELEPORT_SNAP_DISTANCE then
                proxy.CFrame = targetCFrame
                proxy.Size = obj.Size
            else
                proxy.CFrame = proxy.CFrame:Lerp(targetCFrame, alpha)
                proxy.Size = proxy.Size:Lerp(obj.Size, alpha)
            end
            entry.fill.Size = proxy.Size
        else
            destroyPcldEntry(obj)
        end
    end
end)

Workspace.DescendantAdded:Connect(function(obj)
    if Toggles.PcldEspToggle and Toggles.PcldEspToggle.Value then
        addPcldEntry(obj)
    end
end)

Workspace.DescendantRemoving:Connect(destroyPcldEntry)

Toggles.PcldEspToggle:OnChanged(PcldViewF)
for _, id in ipairs({
    "PcldEspFillColor", "PcldEspOutlineColor",
    "PcldEspFillTransparency", "PcldEspOutlineTransparency", "PcldEspLineThickness",
    "PcldEspReflectance",
}) do
    Options[id]:OnChanged(refreshPcldStyle)
end
Toggles.PcldEsp3D:OnChanged(refreshPcldStyle)

--=============================================
-- Sticky ESP
--=============================================
local stickyTimer = 0
RunService.RenderStepped:Connect(function(dt)
    stickyTimer = stickyTimer + dt
    if stickyTimer < 0.3 then return end
    stickyTimer = 0

    pcall(function()
        local enabled = Toggles.StickyEspToggle and Toggles.StickyEspToggle.Value
        local fillColor = Options.StickyEspFillColor and Options.StickyEspFillColor.Value or Color3.fromRGB(150, 255, 0)
        local outlineColor = Options.StickyEspOutlineColor and Options.StickyEspOutlineColor.Value or Color3.fromRGB(255, 0, 0)

        local targetNames = {
            "NinjaKunai", "NinjaShuriken", "NinjaKatana",
            "ToolCleaver", "ToolDiggingForkRusty",
            "ToolPencil", "ToolPickaxe", "AG"
        }

        for _, folder in ipairs(Workspace:GetChildren()) do
            if folder:IsA("Folder") and folder.Name:match("SpawnedInToys$") then
                for _, item in ipairs(folder:GetChildren()) do
                    if item:IsA("Model") and table.find(targetNames, item.Name) then
                        updateHighlight(item, enabled, fillColor, outlineColor, "StickyESP")
                    end
                end
            end
        end

        local plotItems = Workspace:FindFirstChild("PlotItems")
        if plotItems then
            for i = 1, 5 do
                local plot = plotItems:FindFirstChild("Plot" .. i)
                if plot then
                    for _, item in ipairs(plot:GetChildren()) do
                        if item:IsA("Model") and table.find(targetNames, item.Name) then
                            updateHighlight(item, enabled, fillColor, outlineColor, "StickyESP")
                        end
                    end
                end
            end
        end
    end)
end)


--=============================================
-- [Screen] ESP 탭 오른쪽 그룹박스: Third Person(무한 줌) / 오른손 투명
-- 섹션을 함수로 감싸서 로컬 변수 200개 한도에 걸리지 않게 함
--=============================================
;(function()

local function PickIconScreen(candidates)
    for _, name in ipairs(candidates) do
        local ok, found = pcall(function() return Library:GetIcon(name) end)
        if ok and found then
            return name
        end
    end
    return candidates[1]
end

local ScreenGroup = Tabs.ESP:AddRightGroupbox("Screen", PickIconScreen({ "monitor", "tv", "screen-share", "camera" }))

-- =============================================
-- Music 탭: Sounds (래그돌 / 킥 / 그랩 효과음)
--   Ragdoll Sound: 게임의 "RagdollHit" 소리가 날 때 그 소리를 끄고 고른 소리로 바꿔 틀어 줌 (위치는 그 소리가 난 곳)
--   Kick Sound   : Workspace 에 "blackholekick" 이 생길 때 그 자리에서 소리를 틀어 줌
--   Grab Sound   : 내가 잡을 때(내 몸 30 스터드 안에 GrabParts 가 생길 때) 소리를 틀어 줌
--   Notify on Kick: 킥이 난 자리 가까이(60 스터드 안)에 있는 사람 이름을 알림으로 띄움 (Notifications 탭의 Kick Notify 와 같이 움직임)
-- =============================================
do
    local Players_ = game:GetService("Players")
    local SoundService_ = game:GetService("SoundService")
    local lp = Players_.LocalPlayer
    local SOUND_IDS = {
        Skeet = 83717596220569, Fatality = 115982072912004, Bell = 139452805868562, Click = 87437544236708,
        UwU = 124356179581089, Neverlose = 8679627751, Hitmarker = 4817809188,
    }
    local NAMES = { "Skeet", "Fatality", "Bell", "Click", "UwU", "Neverlose", "Hitmarker" }
    local onRagdoll, onKick, onGrab, notifyKick = false, false, false, false
    local pickRagdoll, pickKick, pickGrab = "Skeet", "Fatality", "Hitmarker"
    local volume = 1.8
    local conns = {}
    local kickSeen = {}
    local lastGrab = 0

    local function playAt(position, name)
        local id = SOUND_IDS[name] or SOUND_IDS.Skeet
        local emitter
        local parent = SoundService_
        if position and position ~= Vector3.zero then
            emitter = Instance.new("Part")
            emitter.Name = "8minSoundEmitter"
            emitter.Anchored = true
            emitter.CanCollide = false
            emitter.Transparency = 1
            emitter.Size = Vector3.one
            emitter.Position = position
            emitter.Parent = workspace
            parent = emitter
        end
        local snd = Instance.new("Sound")
        snd.Name = "8minHitSound"
        snd.SoundId = "rbxassetid://" .. id
        snd.Volume = volume
        if emitter then snd.RollOffMaxDistance = 350 end
        snd.Parent = parent
        snd:Play()
        task.spawn(function()
            pcall(function() snd.Ended:Wait() end)
            pcall(function() snd:Destroy() end)
            if emitter then pcall(function() emitter:Destroy() end) end
        end)
    end

    local function posOf(inst)
        if inst:IsA("BasePart") then return inst.Position end
        if inst:IsA("Model") then
            local bp = inst.PrimaryPart or inst:FindFirstChildWhichIsA("BasePart", true)
            if bp then return bp.Position end
        end
        local par = inst.Parent
        if par and par:IsA("BasePart") then return par.Position end
        return nil
    end

    -- 래그돌 소리 바꿔치기
    local hooked = setmetatable({}, { __mode = "k" })
    local function hookRagdollSound(snd)
        if hooked[snd] or not snd:IsA("Sound") or string.lower(snd.Name) ~= "ragdollhit" then return end
        hooked[snd] = true
        conns[#conns + 1] = snd.Played:Connect(function()
            if not onRagdoll then return end
            pcall(function() snd.Volume = 0 end)
            pcall(function() snd:Stop() end)
            local par = snd.Parent
            playAt(par and par:IsA("BasePart") and par.Position or nil, pickRagdoll)
        end)
    end
    pcall(function()
        for _, root in ipairs({ workspace, SoundService_ }) do
            for _, d in ipairs(root:GetDescendants()) do hookRagdollSound(d) end
        end
    end)
    conns[#conns + 1] = SoundService_.DescendantAdded:Connect(hookRagdollSound)

    conns[#conns + 1] = workspace.DescendantAdded:Connect(function(d)
        if d:IsA("Sound") then hookRagdollSound(d) end
        local lname = string.lower(d.Name)

        -- 킥
        if (onKick or notifyKick) and lname:find("blackholekick", 1, true) then
            task.wait(0.01)
            local position = posOf(d)
            if onKick and position then playAt(position, pickKick) end
            if notifyKick and position and d.Parent == workspace and lname == "blackholekick" then
                local best, bestD = nil, 60
                for _, pl in ipairs(Players_:GetPlayers()) do
                    local hrp = pl.Character and pl.Character:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        local dist = (hrp.Position - position).Magnitude
                        if dist < bestD then best, bestD = pl, dist end
                    end
                end
                if best and tick() - (kickSeen[best.Name] or 0) > 1 then
                    kickSeen[best.Name] = tick()
                    local fn = getgenv()._8minNotify
                    if fn then pcall(fn, best.Name .. " kicked", "Kick Detected", "info") end
                end
            end
        end

        -- 그랩
        if onGrab and (lname == "grabparts" or lname == "grabpart" or lname:find("grabparts", 1, true)) then
            local position = posOf(d)
            local hrp = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
            if position and hrp and (position - hrp.Position).Magnitude <= 30 and tick() - lastGrab > 0.25 then
                lastGrab = tick()
                playAt(nil, pickGrab)
            end
        end
    end)

    local SoundsBox = Tabs.Music:AddLeftGroupbox("Sounds", "volume-2")
    SoundsBox:AddToggle("HitSoundRagdoll", { Text = "Ragdoll Sound", Default = false, Callback = function(v) onRagdoll = v end })
    SoundsBox:AddToggle("HitSoundKick", { Text = "Kick Sound", Default = false, Callback = function(v) onKick = v end })
    SoundsBox:AddToggle("HitSoundGrab", { Text = "Grab Sound", Default = false, Callback = function(v) onGrab = v end })
    SoundsBox:AddDropdown("HitSoundRagdollPick", { Text = "Ragdoll Sound", Values = NAMES, Default = "Skeet", Multi = false,
        Callback = function(v) pickRagdoll = tostring(v) end })
    SoundsBox:AddDropdown("HitSoundKickPick", { Text = "Kick Sound", Values = NAMES, Default = "Fatality", Multi = false,
        Callback = function(v) pickKick = tostring(v) end })
    SoundsBox:AddDropdown("HitSoundGrabPick", { Text = "Grab Sound", Values = NAMES, Default = "Hitmarker", Multi = false,
        Callback = function(v) pickGrab = tostring(v) end })
    SoundsBox:AddSlider("HitSoundVolume", { Text = "Volume", Default = 18, Min = 1, Max = 50, Rounding = 0,
        Callback = function(v) volume = (tonumber(v) or 18) / 10 end })
    SoundsBox:AddToggle("HitSoundNotifyKick", { Text = "Notify on Kick", Default = false,
        Tooltip = "Show a notification with the name of the player closest to a kick.",
        Callback = function(v) notifyKick = v end })

    getgenv()._8minOnCleanup(function()
        for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
        table.clear(conns)
        onRagdoll, onKick, onGrab, notifyKick = false, false, false, false
    end)
end

-- =============================================
-- FPS / Ping HUD
--   화면 위쪽 가운데에 작은 알약 모양 표시줄: "8min | NN Fps | NN ms"
--   FPS = Heartbeat 가 0.5초 동안 몇 번 돌았는지, 핑 = Stats.Network.ServerStatsItem["Data Ping"]
--   마우스/터치로 끌어서 옮길 수 있음. 끄거나 스크립트를 다시 실행/Unload 하면 사라짐
-- =============================================
do
    local RunService_ = game:GetService("RunService")
    local UIS_ = game:GetService("UserInputService")
    local hudGui, hudConn, dragConn = nil, nil, nil
    local hudPos = UDim2.new(0.5, 0, 0, 14)   -- 끌어서 옮긴 위치를 껐다 켜도 기억

    local function stopHud()
        if hudConn then pcall(function() hudConn:Disconnect() end) hudConn = nil end
        if dragConn then pcall(function() dragConn:Disconnect() end) dragConn = nil end
        if hudGui then pcall(function() hudGui:Destroy() end) hudGui = nil end
    end

    local function startHud()
        stopHud()
        local gui = Instance.new("ScreenGui")
        gui.Name = "8minFpsHud"
        gui.IgnoreGuiInset = true
        gui.ResetOnSpawn = false
        gui.DisplayOrder = 999990
        local okParent = pcall(function() gui.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
        if not okParent then
            gui.Parent = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
        end
        hudGui = gui

        local frame = Instance.new("Frame")
        frame.AnchorPoint = Vector2.new(0.5, 0)
        frame.Position = hudPos
        frame.Size = UDim2.fromOffset(244, 34)
        frame.BackgroundColor3 = Color3.fromRGB(16, 16, 24)
        frame.BackgroundTransparency = 0.15
        frame.BorderSizePixel = 0
        frame.Parent = gui
        local corner = Instance.new("UICorner"); corner.CornerRadius = UDim.new(0, 10); corner.Parent = frame
        local stroke = Instance.new("UIStroke"); stroke.Color = Color3.fromRGB(126, 118, 190); stroke.Transparency = 0.45; stroke.Parent = frame

        local function label(text, x, w, bold)
            local l = Instance.new("TextLabel")
            l.BackgroundTransparency = 1
            l.AnchorPoint = Vector2.new(0, 0.5)
            l.Position = UDim2.new(0, x, 0.5, 0)
            l.Size = UDim2.fromOffset(w, 18)
            l.Font = bold and Enum.Font.GothamBold or Enum.Font.GothamMedium
            l.Text = text
            l.TextColor3 = Color3.fromRGB(229, 231, 241)
            l.TextSize = bold and 14 or 13
            l.TextXAlignment = Enum.TextXAlignment.Left
            l.Parent = frame
            return l
        end
        local function divider(x)
            local d = Instance.new("Frame")
            d.BackgroundColor3 = Color3.fromRGB(126, 118, 190)
            d.BackgroundTransparency = 0.34
            d.BorderSizePixel = 0
            d.AnchorPoint = Vector2.new(0, 0.5)
            d.Position = UDim2.new(0, x, 0.5, 0)
            d.Size = UDim2.fromOffset(1, 14)
            d.Parent = frame
        end
        -- 메인 아이콘 (로딩 화면과 같은 8min 아이콘)
        local icon = Instance.new("ImageLabel")
        icon.BackgroundTransparency = 1
        icon.AnchorPoint = Vector2.new(0, 0.5)
        icon.Position = UDim2.new(0, 9, 0.5, 0)
        icon.Size = UDim2.fromOffset(24, 24)
        icon.ScaleType = Enum.ScaleType.Fit
        icon.Image = "rbxassetid://89769574"
        icon.Parent = frame
        label("8min", 40, 44, true)
        divider(90)
        local fpsLabel = label("0 Fps", 100, 56)
        divider(160)
        local pingLabel = label("0 ms", 170, 66)

        -- FPS / 핑 갱신 (0.5초마다)
        local frames, last = 0, tick()
        hudConn = RunService_.Heartbeat:Connect(function()
            frames += 1
            local now = tick()
            if now - last < 0.5 then return end
            local fps = math.floor(frames / (now - last) + 0.5)
            frames, last = 0, now
            local ping = 0
            pcall(function()
                ping = math.floor(game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue() + 0.5)
            end)
            fpsLabel.Text = string.format("%d Fps", fps)
            pingLabel.Text = string.format("%d ms", ping)
            -- 핑이 높을수록 색을 바꿈: 초록 < 100, 노랑 < 200, 빨강
            pingLabel.TextColor3 = ping < 100 and Color3.fromRGB(140, 235, 160)
                or (ping < 200 and Color3.fromRGB(240, 220, 120) or Color3.fromRGB(245, 120, 120))
        end)

        -- 끌어서 옮기기
        local dragging, startMouse, startPos = false, nil, nil
        frame.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging, startMouse, startPos = true, input.Position, frame.Position
            end
        end)
        frame.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = false
                hudPos = frame.Position
            end
        end)
        dragConn = UIS_.InputChanged:Connect(function(input)
            if not dragging then return end
            if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
            local d = input.Position - startMouse
            frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
        end)
    end

    ScreenGroup:AddToggle("FpsPingHud", {
        Text = "FPS / Ping HUD",
        Default = true,
        Tooltip = "Shows a small draggable bar with your FPS and ping at the top of the screen.",
        Callback = function(Value)
            if Value then
                startHud()
                pcall(function() DraggableLabel:SetVisible(false) end)   -- 예전 글자 표시줄은 겹치니 숨김
            else
                stopHud()
                pcall(function() DraggableLabel:SetVisible(true) end)
            end
        end,
    })

    -- 스크립트를 켜면 바로 나오게 (저장된 설정에서 꺼 둔 경우는 그대로 꺼짐)
    if Toggles.FpsPingHud and Toggles.FpsPingHud.Value then
        startHud()
        pcall(function() DraggableLabel:SetVisible(false) end)
    end

    getgenv()._8minOnCleanup(stopHud)
end


--=============================================
-- Third Person (줌 거리 무제한)
--=============================================
local TP = {
    Enabled = false,
    Original = nil,   -- 켜기 전 카메라 설정 (끄면 이걸로 복구)
    PullUntil = 0,    -- 켠 직후 카메라를 한 번 뒤로 빼는 동안은 최소 줌을 건드리지 않음
}

local function saveOriginalCamera()
    if TP.Original then return end
    TP.Original = {
        Min = plr.CameraMinZoomDistance,
        Max = plr.CameraMaxZoomDistance,
        Mode = plr.CameraMode,
    }
end

local function applyThirdPerson()
    saveOriginalCamera()

    if plr.CameraMode ~= Enum.CameraMode.Classic then
        plr.CameraMode = Enum.CameraMode.Classic
    end
    if plr.CameraMaxZoomDistance ~= math.huge then
        plr.CameraMaxZoomDistance = math.huge
    end
    if os.clock() >= TP.PullUntil and plr.CameraMinZoomDistance > 0.5 then
        plr.CameraMinZoomDistance = 0.5
    end
end

local function pullCameraOut()
    -- 1인칭으로 고정된 게임에서도 바로 뒤로 빠지도록 잠깐만 최소 거리를 늘렸다가 되돌림
    TP.PullUntil = os.clock() + 0.4
    plr.CameraMinZoomDistance = 12
    task.delay(0.3, function()
        if TP.Enabled then
            plr.CameraMinZoomDistance = 0.5
        end
    end)
end

local function restoreCamera()
    local original = TP.Original
    if not original then return end
    TP.Original = nil
    plr.CameraMaxZoomDistance = math.max(original.Max, original.Min)
    plr.CameraMinZoomDistance = original.Min
    plr.CameraMaxZoomDistance = original.Max
    plr.CameraMode = original.Mode
end

local ThirdPersonToggle = ScreenGroup:AddToggle("ThirdPersonToggle", {
    Text = "Third Person",
    Default = false,
    Tooltip = "Unlimited zoom distance. Scroll to zoom in or out.",
    Callback = function(Value)
        TP.Enabled = Value
        if Value then
            applyThirdPerson()
            pullCameraOut()
        else
            restoreCamera()
        end
    end,
})

ThirdPersonToggle:AddKeyPicker("ThirdPersonKey", {
    Default = "None",
    Mode = "Toggle",
    SyncToggleState = true,
    Text = "Third Person keybind",
    NoUI = false,
})

--=============================================
-- 오른손 투명 (내 화면에서만)
--=============================================
local HAND_PART_NAMES = {
    ["Right Arm"] = true,    -- R6
    RightHand = true,        -- R15
    RightLowerArm = true,
    RightUpperArm = true,
}

local handEnabled = false
local handTransparency = 0.7
local handSaved = setmetatable({}, { __mode = "k" }) -- [Part] = 원래 투명도

local function restoreHand()
    for part, original in pairs(handSaved) do
        if part.Parent then
            part.Transparency = original
        end
        handSaved[part] = nil
    end
end

local function applyHand()
    local char = plr.Character
    if not char then return end

    for _, part in ipairs(char:GetChildren()) do
        if part:IsA("BasePart") and HAND_PART_NAMES[part.Name] then
            local original = handSaved[part]
            if original == nil then
                original = part.Transparency
                if original < 1 then -- 원래부터 안 보이는 파트는 건드리지 않음
                    handSaved[part] = original
                end
            end
            if original ~= nil and original < 1 then
                local target = math.max(original, handTransparency)
                if part.Transparency ~= target then
                    part.Transparency = target
                end
            end
        end
    end
end

-- 그랩으로 뭔가 잡고 있을 때, 오른손(팔)이 잡은 물체 쪽으로 쭉 뻗도록 어깨 관절을 돌림 (R6 전용, 내 화면에서만)
local function getHeldTargetPosition()
    local grabParts = workspace:FindFirstChild("GrabParts")
    if not grabParts then return nil end

    local grabPart = grabParts:FindFirstChild("GrabPart")
    local weld = grabPart and grabPart:FindFirstChildOfClass("WeldConstraint")
    local held = weld and weld.Part1
    if held and held.Parent then
        return held.Position
    end
    if grabPart and grabPart:IsA("BasePart") then
        return grabPart.Position
    end
    return nil
end

local function reachRightHand(char)
    local torso = char:FindFirstChild("Torso")
    local motor = torso and torso:FindFirstChild("Right Shoulder")
    if not motor or not motor:IsA("Motor6D") then return end

    local targetPos = getHeldTargetPosition()
    if not targetPos then return end

    local shoulderWorld = torso.CFrame * motor.C0
    local toTarget = targetPos - shoulderWorld.Position
    if toTarget.Magnitude < 0.5 then return end
    local direction = toTarget.Unit

    -- 팔의 아래쪽(-Y)이 잡은 물체를 향하도록 방향을 만듦
    local y = -direction
    local x = workspace.CurrentCamera.CFrame.RightVector
    x = x - x:Dot(y) * y
    if x.Magnitude < 0.01 then
        x = Vector3.zAxis - Vector3.zAxis:Dot(y) * y
    end
    x = x.Unit
    local z = x:Cross(y)
    local wanted = CFrame.fromMatrix(Vector3.zero, x, y, z)

    local shoulderRot = shoulderWorld - shoulderWorld.Position
    local c1Rot = motor.C1 - motor.C1.Position
    motor.Transform = shoulderRot:Inverse() * wanted * c1Rot
end

-- 1인칭에서는 카메라 스크립트가 몸 파트를 LocalTransparencyModifier 로 숨기기 때문에,
-- 카메라 스크립트가 돈 직후(우선순위 +1)에 오른손만 다시 0 으로 돌려서 투명한 손이 보이게 함
local HAND_RENDER_NAME = "RightHandStayVisible"

local function stopHandVisible()
    pcall(function() RunService:UnbindFromRenderStep(HAND_RENDER_NAME) end)
end

local function startHandVisible()
    stopHandVisible()
    RunService:BindToRenderStep(HAND_RENDER_NAME, Enum.RenderPriority.Camera.Value + 1, function()
        local char = plr.Character
        if not char then return end
        for _, part in ipairs(char:GetChildren()) do
            if part:IsA("BasePart") and HAND_PART_NAMES[part.Name] and handSaved[part] ~= nil then
                if part.LocalTransparencyModifier ~= 0 then
                    part.LocalTransparencyModifier = 0
                end
            end
        end

        pcall(reachRightHand, char)
    end)
end

ScreenGroup:AddToggle("TransparentRightHand", {
    Text = "Transparent Right Hand",
    Default = false,
    Tooltip = "Your right hand becomes see-through, and stays visible in first person.",
    Callback = function(Value)
        handEnabled = Value
        if Value then
            applyHand()
            startHandVisible()
        else
            stopHandVisible()
            restoreHand()
        end
    end,
})

ScreenGroup:AddSlider("RightHandTransparency", {
    Text = "Right Hand Transparency",
    Default = 0.7, Min = 0, Max = 1, Rounding = 2,
    Callback = function(Value)
        handTransparency = Value
        if handEnabled then applyHand() end
    end,
})

--=============================================
-- 게임이 설정을 되돌려도 유지 (값 비교만 하는 가벼운 검사)
--=============================================
local screenTimer = 0
RunService.RenderStepped:Connect(function(dt)
    screenTimer = screenTimer + dt
    if screenTimer < 0.1 then return end
    screenTimer = 0

    if TP.Enabled then pcall(applyThirdPerson) end
    if handEnabled then pcall(applyHand) end
end)

end)()


-- ==========================================================
-- [Visual & Audio] Sounds / Line / Skybox 탭박스
-- 필요한 것: Tabs, Library, Options, Toggles (메인 스크립트 헤더에 이미 있음)
-- 어느 탭에 넣을지는 아래 TargetTab 한 줄만 바꾸면 됨 (지금은 ESP 탭 오른쪽)
-- 섹션 전체를 함수로 감싸서 로컬 변수 200개 한도에 걸리지 않게 함
-- ==========================================================
;(function()

local Lighting = game:GetService("Lighting")
local SoundService = game:GetService("SoundService")
local Workspace = game:GetService("Workspace")
local RunService = game:GetService("RunService")
local Players = game:GetService("Players")
local Terrain = Workspace.Terrain
local LocalPlayer = Players.LocalPlayer

-- 스크립트를 다시 실행하면 이전에 켜 둔 것(연결, 반복 작업, 바꿔 둔 줄/하늘/구름)을 먼저 되돌리고 새로 시작함
local vaGeneration = (getgenv().VA_Generation or 0) + 1
if getgenv().VA_Cleanup then
    pcall(getgenv().VA_Cleanup)
end
getgenv().VA_Generation = vaGeneration
getgenv().VA_Cleanup = nil

local function alive()
    return getgenv().VA_Generation == vaGeneration
end

local vaConnections = {}
local function conn(signal, callback)
    local connection = signal:Connect(callback)
    vaConnections[#vaConnections + 1] = connection
    return connection
end

local TargetTab = Tabs.ESP

-- 시작할 때 라이브러리가 부르는 콜백으로 값이 바뀌지 않도록 잠깐 무시
local ready = false
task.delay(1.5, function() ready = true end)

local function PickIconVA(candidates)
    for _, name in ipairs(candidates) do
        local ok, found = pcall(function() return Library:GetIcon(name) end)
        if ok and found then
            return name
        end
    end
    return candidates[1]
end

local function Divider(group, text)
    local ok = pcall(function() group:AddDivider(text) end)
    if not ok then
        pcall(function() group:AddLabel(text) end)
    end
end

-- 이미지 ID / 링크 -> rbxassetid://숫자
local function parseImageId(text)
    if type(text) ~= "string" then return nil end
    text = (text:gsub("^%s+", "")):gsub("%s+$", "")
    if text == "" then return nil end
    if text:match("^rbxassetid://") or text:match("^rbxasset://") or text:match("^rbxthumb://") then
        return text
    end
    local digits = text:match("(%d+)")
    if digits then
        return "rbxassetid://" .. digits
    end
    return nil
end

-- =============================================
-- 탭박스 만들기
-- =============================================
local hasTabbox = TargetTab.AddRightTabbox ~= nil
local Tabbox = hasTabbox and getgenv()._8minHeaderTabbox(TargetTab, "R", "Audio & Line & Skybox", "Settings", "sliders-horizontal") or nil

local function addSection(name, icons)
    if Tabbox then
        local icon = PickIconVA(icons)
        local ok, section = pcall(function() return Tabbox:AddTab(name, icon) end)
        if ok and section then return section end
        return Tabbox:AddTab(name)
    end
    -- 탭박스를 못 쓰는 라이브러리면 그룹박스로 대체
    return TargetTab:AddRightGroupbox("Visual & Audio - " .. name, PickIconVA(icons))
end

local SoundsSection = addSection("Sounds", { "volume-2", "music", "speaker" })
local LineSection = addSection("Line", { "route", "spline", "waypoints" })
getgenv()._8minLineSection = LineSection
local SkyboxSection = addSection("Skybox", { "cloud", "cloud-sun", "sun" })

-- =============================================
-- 공용: 무지개 색 / 주기 반복
-- =============================================
local hue = 0

-- =============================================
-- SOUNDS
-- =============================================
local screamPct, ambiencePct = 100, 100
local muteJuke = false

local JUKE_WORDS = { "jukebox", "boombox", "radio", "speaker", "musicbox" }
local AMBIENCE_WORDS = { "ambien", "wind", "bird", "forest", "ocean", "wave", "rain", "nature", "cricket", "crowd" }

local function nameHas(text, words)
    text = text:lower()
    for _, w in ipairs(words) do
        if text:find(w, 1, true) then
            return true
        end
    end
    return false
end

local soundCategory = setmetatable({}, { __mode = "k" }) -- [Sound] = "Scream" | ... | false
local soundState = setmetatable({}, { __mode = "k" })    -- [Sound] = { orig, applied }  (우리가 건드린 소리만)
local categorized = setmetatable({}, { __mode = "k" })   -- 분류된 소리 모음
local soundWatch = setmetatable({}, { __mode = "k" })    -- [Sound] = 볼륨 감시 연결
local mutedLogCount = 0

-- Sound 뿐 아니라 새 오디오 API 의 AudioPlayer 도 같은 방식으로 다룸
local function isSoundLike(d)
    return d:IsA("Sound") or d:IsA("AudioPlayer")
end

local function soundIdOf(sound)
    if sound:IsA("Sound") then return tostring(sound.SoundId) end
    local ok, value = pcall(function() return sound.AssetId end)
    return ok and tostring(value) or ""
end

local function loopedOf(sound)
    if sound:IsA("Sound") then return sound.Looped end
    local ok, value = pcall(function() return sound.Looping end)
    return ok and value or false
end

local function inToyFolder(sound)
    local p = sound.Parent
    for _ = 1, 10 do
        if not p or p == game then break end
        if p.Name:match("SpawnedInToys$") or p.Name == "PlotItems" then
            return true
        end
        p = p.Parent
    end
    return false
end

local function ancestorNames(sound)
    local names = { sound.Name }
    local p = sound.Parent
    for _ = 1, 6 do
        if not p or p == Workspace or p == game then break end
        names[#names + 1] = p.Name
        p = p.Parent
    end
    return table.concat(names, " ")
end

local function classify(sound)
    local cached = soundCategory[sound]
    if cached ~= nil then return cached end

    local category = false
    if sound.Name == "8minHubMusic" then
        category = false -- 이 허브의 뮤직 플레이어는 건드리지 않음
    elseif nameHas(sound.Name, { "scream" }) then
        category = "Scream"
    else
        local names = ancestorNames(sound)
        local looped = loopedOf(sound)
        if nameHas(names, JUKE_WORDS) then
            category = "Jukebox"
        elseif looped and inToyFolder(sound) then
            -- 플레이어가 꺼낸 장난감 안에서 반복 재생되는 소리 = 붐박스/주크박스 같은 음악
            category = "Jukebox"
        elseif nameHas(names, AMBIENCE_WORDS) or (looped and sound:IsDescendantOf(SoundService)) then
            category = "Ambience"
        end
    end

    soundCategory[sound] = category
    if category then categorized[sound] = true end
    return category
end

local function multiplierFor(category)
    if category == "Scream" then return screamPct / 100 end
    if category == "Ambience" then return ambiencePct / 100 end
    if category == "Jukebox" then return muteJuke and 0 or 1 end
    return 1
end

local watchSound

local function applySound(sound)
    local category = classify(sound)
    if not category then return end

    local mult = multiplierFor(category)
    local state = soundState[sound]

    if not state then
        if mult == 1 then return end
        state = { orig = sound.Volume, applied = sound.Volume }
        soundState[sound] = state
        watchSound(sound)

        -- 어떤 소리가 꺼졌는지 F9 콘솔에서 확인할 수 있게 (처음 25개만)
        if mult == 0 and mutedLogCount < 25 then
            mutedLogCount = mutedLogCount + 1
            print(("[8min] muted %s sound: %s | %s"):format(category, sound:GetFullName(), soundIdOf(sound)))
        end
    end

    -- 게임이 직접 볼륨을 바꿨다면 그 값을 새 원본으로 봄 (부동소수 오차는 무시)
    if math.abs(sound.Volume - state.applied) > 0.001 then
        state.orig = sound.Volume
    end

    -- 볼륨을 바꾸기 전에 먼저 기록해 둬야, 바뀐 걸 감지하는 이벤트가 우리가 바꾼 걸 '게임이 바꾼 것'으로 오해하지 않음
    local target = state.orig * mult
    state.applied = target
    if math.abs(sound.Volume - target) > 0.0005 then
        sound.Volume = target
    end

    if mult == 1 then
        soundState[sound] = nil -- 원래대로 돌아왔으니 더는 건드리지 않음
    end
end

-- 게임이 볼륨을 다시 올리거나, 소리가 재생되는 순간 바로 다시 적용
watchSound = function(sound)
    if soundWatch[sound] then return end
    local connections = {
        sound:GetPropertyChangedSignal("Volume"):Connect(function()
            pcall(applySound, sound)
        end),
    }
    if sound:IsA("Sound") then
        connections[#connections + 1] = sound.Played:Connect(function()
            pcall(applySound, sound)
        end)
    end
    soundWatch[sound] = connections
end

local function refreshSounds()
    for sound in pairs(categorized) do
        if sound.Parent then
            pcall(applySound, sound)
        end
    end
end

local function scanSounds()
    local count = 0
    for _, root in ipairs({ Workspace, SoundService }) do
        for _, d in ipairs(root:GetDescendants()) do
            if isSoundLike(d) then
                pcall(applySound, d)
            end
            count = count + 1
            if count % 800 == 0 then task.wait() end
        end
    end
end

-- 게임 어디에 생기는 소리든 잡음 (워크스페이스, 사운드서비스, PlayerGui, 카메라 등)
local newSoundLogCount = 0

conn(game.DescendantAdded, function(d)
    if isSoundLike(d) then
        -- 음소거를 켜 둔 상태에서 새로 생긴 소리를 콘솔(F9)에 남겨서, 어떤 소리가 안 꺼지는지 알 수 있게 함
        if muteJuke and newSoundLogCount < 40 and d.Name ~= "8minHubMusic" then
            newSoundLogCount = newSoundLogCount + 1
            print(("[8min] new sound: %s | %s | %s | Looped=%s"):format(
                d.ClassName, d:GetFullName(), soundIdOf(d), tostring(loopedOf(d))))
        end
        pcall(applySound, d)           -- 소리가 나기 전에 바로 처리
        task.defer(function()
            pcall(applySound, d)
        end)
    end
end)

SoundsSection:AddSlider("VAAmbience", {
    Text = "Ambience",
    Default = 100, Min = 0, Max = 100, Rounding = 0,
    Callback = function(Value)
        ambiencePct = Value
        if ready then refreshSounds() end
    end,
})

SoundsSection:AddSlider("VAScreams", {
    Text = "Screams",
    Default = 100, Min = 0, Max = 100, Rounding = 0,
    Callback = function(Value)
        screamPct = Value
        if ready then refreshSounds() end
    end,
})

SoundsSection:AddToggle("VAMuteJukebox", {
    Text = "Mute Jukeboxes & Boomboxes",
    Default = false,
    Callback = function(Value)
        muteJuke = Value
        if ready then refreshSounds() end
    end,
})

-- =============================================
-- LINE (그랩 라인 꾸미기)
-- =============================================
-- 체인/로프 텍스처 이미지 ID 를 알면 여기에 적으세요. 적으면 그 이미지로 그려지고,
-- 안 적으면 아래 PRESET 의 색 띠 모양으로 그려집니다.
local LINE_TEXTURES = {
    -- ["Chain 1"] = "rbxassetid://123456789",
    -- ["Rope"] = "rbxassetid://123456789",
}

-- 이미지 (가로가 선의 폭 방향, 세로가 선의 길이 방향)
local LINE_TEXTURE_DATA = {
    ["Low Quality"] = "",
    ["Gamepass Line"] = "",
    ["Chain 1"] = "",
    ["Chain 2"] = "",
    ["Chain 3"] = "",
    ["Chain 4"] = "",
    ["Rope"] = "",
}

-- 같은 이미지를 90도 돌린 버전 (위 이미지가 옆으로 누워 보이면 아래 TEXTURE_ACROSS_WIDTH 를 false 로)
local LINE_TEXTURE_DATA_ALONG = {
    ["Low Quality"] = "",
    ["Gamepass Line"] = "",
    ["Chain 1"] = "",
    ["Chain 2"] = "",
    ["Chain 3"] = "",
    ["Chain 4"] = "",
    ["Rope"] = "",
}

local TEXTURE_ACROSS_WIDTH = true

-- 위 이미지 데이터(base64)를 파일로 저장한 뒤 getcustomasset 으로 텍스처 주소를 얻음
-- (writefile / getcustomasset 을 지원하는 실행기에서만 동작, 아니면 색 띠 모양으로 대체)
local B64_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local B64_INDEX = {}
for i = 1, 64 do
    B64_INDEX[B64_CHARS:sub(i, i)] = i - 1
end

local function b64decode(data)
    data = data:gsub("[^%w%+/=]", "")
    local out, n = {}, 0
    for i = 1, #data, 4 do
        local c3, c4 = data:sub(i + 2, i + 2), data:sub(i + 3, i + 3)
        local a = B64_INDEX[data:sub(i, i)]
        local b = B64_INDEX[data:sub(i + 1, i + 1)]
        local c = B64_INDEX[c3]
        local d = B64_INDEX[c4]
        local triple = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
        n = n + 1
        out[n] = string.char(math.floor(triple / 65536) % 256)
        if c3 ~= "=" then
            n = n + 1
            out[n] = string.char(math.floor(triple / 256) % 256)
        end
        if c4 ~= "=" then
            n = n + 1
            out[n] = string.char(triple % 256)
        end
    end
    return table.concat(out)
end

local generatedTextures = {}
local function getGeneratedTexture(name)
    local cached = generatedTextures[name]
    if cached ~= nil then
        return cached or nil
    end

    local result = false
    local source = TEXTURE_ACROSS_WIDTH and LINE_TEXTURE_DATA or LINE_TEXTURE_DATA_ALONG
    local encoded = source[name]
    if encoded and writefile and getcustomasset then
        local ok, asset = pcall(function()
            local fileName = "8min_line3_" .. (TEXTURE_ACROSS_WIDTH and "a_" or "b_") .. (name:gsub("%s", "_")) .. ".png"
            writefile(fileName, b64decode(encoded))
            return getcustomasset(fileName)
        end)
        if ok and asset then
            result = asset
        end
    end

    generatedTextures[name] = result
    return result or nil
end

-- 파티클 모양 이미지 (흰색 + 투명도, 색은 Particle Color 로 입혀짐)
local PARTICLE_TEXTURE_DATA = {
    ["Star4"] = "",
    ["DotGlow"] = "",
    ["Flame"] = "",
    ["Matrix"] = "",
    ["Heart"] = "",
    ["Orb"] = "",
    ["Smoke"] = "",
    ["Star8"] = "",
    ["Bubble"] = "",
}

local particleTextures = {}
local function getParticleTexture(key)
    local cached = particleTextures[key]
    if cached ~= nil then
        return cached or nil
    end

    local result = false
    local encoded = PARTICLE_TEXTURE_DATA[key]
    if encoded and writefile and getcustomasset then
        local ok, asset = pcall(function()
            local fileName = "8min_particle_" .. key .. ".png"
            writefile(fileName, b64decode(encoded))
            return getcustomasset(fileName)
        end)
        if ok and asset then
            result = asset
        end
    end

    particleTextures[key] = result
    return result or nil
end

-- 줄마다 폭/한 번 반복되는 길이(tile)/꼬임(braid)/물결(wave)
