local TEXTURE_WIDTH = {
    ["Low Quality"] = 0.6, ["Gamepass Line"] = 0.8,
    ["Chain 1"] = 0.9, ["Chain 2"] = 0.9, ["Chain 3"] = 0.9, ["Chain 4"] = 0.9,
    ["Rope"] = 0.5,
}

local function resolveLineTexture(name)
    if LINE_TEXTURES[name] then
        local id = parseImageId(LINE_TEXTURES[name])
        if id then return id end
    end
    return getGeneratedTexture(name)
end

-- 두 색을 번갈아 칠한 띠 모양 ColorSequence (키포인트는 최대 20개라 띠는 최대 10개)
local function bands(colorA, colorB, count)
    local n = math.clamp(count, 2, 10)
    local keys = {}
    for i = 0, n - 1 do
        local color = (i % 2 == 0) and colorA or colorB
        local startT = i / n
        local endT = (i == n - 1) and 1 or ((i + 1) / n - 0.001)
        keys[#keys + 1] = ColorSequenceKeypoint.new(startT, color)
        keys[#keys + 1] = ColorSequenceKeypoint.new(endT, color)
    end
    return ColorSequence.new(keys)
end

local LINE_ORDER = { "Low Quality", "Default Line", "Gamepass Line", "Chain 1", "Chain 2", "Chain 3", "Chain 4", "Rope" }

-- "Default Line" 은 게임 원래 모양 (아무것도 바꾸지 않음)
