local STYLE_ORDER = { "Stardust & Galaxy", "Flame Burst", "Cyber Matrix", "Heart Glow", "Magic Orbs", "Smoke Vapor", "Cosmic Sparkles", "Bubble Stream" }
local POINT_ORDER = { "Beam Endpoint", "Entire Beam Line", "Continuous Wave Motion", "Pulse Orbit" }

local lineEnabled = false
local lineChoice = LINE_ORDER[1]

local particlesEnabled = false
local selectedStyles = { [STYLE_ORDER[1]] = true }
local particlePoint = POINT_ORDER[1]
local particleRate = 20
local rainbowParticles = false

local grabBeams = setmetatable({}, { __mode = "k" })      -- 그랩 라인으로 보이는 Beam 들
local lineOriginal = setmetatable({}, { __mode = "k" })   -- [Beam] = 원래 속성들
local lineApplied = setmetatable({}, { __mode = "k" })    -- [Beam] = 지금 적용 중인 프리셋 정보
local strands = setmetatable({}, { __mode = "k" })        -- [Beam] = { 꼬임용 추가 가닥들 }
local beamGameColor = setmetatable({}, { __mode = "k" })  -- [Beam] = 게임 안에서 설정한 줄 색 (칠하기 직전의 색)

local function seqEqual(a, b)
    local ka, kb = a.Keypoints, b.Keypoints
    if #ka ~= #kb then return false end
    for i = 1, #ka do
        if math.abs(ka[i].Time - kb[i].Time) > 0.001 or ka[i].Value ~= kb[i].Value then
            return false
        end
    end
    return true
end
local curveBase = setmetatable({}, { __mode = "k" })      -- [Beam] = 게임이 정한 원래 곡선 값
local CollectionService = game:GetService("CollectionService")
local EMITTER_TAG, NODE_TAG = "VAEmitter", "VANode"
local liveEmitters = {}   -- 지금 우리가 관리 중인 파티클 (여기에 없는 태그 파티클은 남은 찌꺼기로 보고 지움)
local liveNodes = {}
-- 주의: 일부러 약한 참조(weak)로 만들지 않음. 줄(Beam)이 사라진 뒤에도 그 파티클을 찾아서 지워야 하기 때문
local beamParticles = {}  -- [Beam] = { emitters, nodes, factors, mode }

local nodeFolder = nil
local function makeNode()
    if not nodeFolder or not nodeFolder.Parent then
        nodeFolder = Instance.new("Folder")
        nodeFolder.Name = "VABeamNodes"
        nodeFolder.Parent = Workspace.CurrentCamera
    end
    local part = Instance.new("Part")
    part.Anchored = true
    part.CanCollide = false
    part.CanQuery = false
    part.CanTouch = false
    part.CastShadow = false
    part.Transparency = 1
    part.Size = Vector3.new(0.2, 0.2, 0.2)
    part.Parent = nodeFolder
    CollectionService:AddTag(part, NODE_TAG)
    liveNodes[part] = true
    return part
end

local allBeams = setmetatable({}, { __mode = "k" }) -- 월드에 있는 모든 Beam (그랩 라인 후보)
local beamLogCount = 0

local function isGrabBeam(inst)
    if not inst:IsA("Beam") then return false end
    if inst:GetAttribute("VAStrand") then return false end
    if inst:FindFirstAncestor("GrabParts") then return true end

    local name = inst.Name:lower()
    if name:find("grab", 1, true) or name:find("beampart", 1, true) then return true end

    local parentName = inst.Parent and inst.Parent.Name:lower() or ""
    if parentName:find("grab", 1, true) ~= nil or parentName:find("beampart", 1, true) ~= nil then
        return true
    end

    -- 내 캐릭터에 붙어 있는 빔 (그랩 중일 때만 후보로 봄)
    if Workspace:FindFirstChild("GrabParts") and LocalPlayer.Character then
        local a0, a1 = inst.Attachment0, inst.Attachment1
        if (a0 and a0:IsDescendantOf(LocalPlayer.Character)) or (a1 and a1:IsDescendantOf(LocalPlayer.Character)) then
            return true
        end
    end
    return false
end

local function beamIsActive(beam)
    if not beam.Parent or not beam.Enabled then return false end
    local a0, a1 = beam.Attachment0, beam.Attachment1
    if not (a0 and a1) then return false end
    if not (a0:IsDescendantOf(Workspace) and a1:IsDescendantOf(Workspace)) then return false end

    -- 뭔가를 잡고 있을 때(GrabParts 가 있을 때)만 파티클을 켬. 놓으면 바로 꺼서 남지 않게 함
    if not Workspace:FindFirstChild("GrabParts") then
        return false
    end
    return true
end

local function registerGrabBeam(beam)
    if grabBeams[beam] then return end
    grabBeams[beam] = true
    if beamLogCount < 15 then
        beamLogCount = beamLogCount + 1
        print("[8min] grab line found: " .. beam:GetFullName())
    end
end

-- 라인 모양 ---------------------------------------------------
local BEAM_LOOK_PROPS = { "Color", "Width0", "Width1", "Segments", "LightEmission", "Texture", "TextureMode", "TextureLength", "FaceCamera" }

local function destroyStrands(beam)
    local extras = strands[beam]
    if extras then
        for _, strand in ipairs(extras) do
            pcall(function() strand:Destroy() end)
        end
        strands[beam] = nil
    end
end

local function restoreBeamLook(beam)
    local base = curveBase[beam]
    if base then
        pcall(function()
            beam.CurveSize0 = base.c0
            beam.CurveSize1 = base.c1
        end)
        curveBase[beam] = nil
    end
    destroyStrands(beam)

    local original = lineOriginal[beam]
    if original then
        for _, prop in ipairs(BEAM_LOOK_PROPS) do
            pcall(function() beam[prop] = original[prop] end)
        end
        -- 색은 처음 저장한 값이 아니라, 게임 안에서 설정된 최신 색으로 돌려놓음
        local gameColor = beamGameColor[beam]
        if gameColor then
            pcall(function() beam.Color = gameColor end)
        end
        lineOriginal[beam] = nil
    end
    beamGameColor[beam] = nil
    lineApplied[beam] = nil
end

-- 빔 하나를 프리셋 모양으로 칠함
local function paintBeam(target, preset, shape, textureId, tint)
    local width = shape.width or preset.width
    if shape.solid then
        -- 이미지 없이 단색 (아주 가는 줄은 무늬가 보이지 않으므로)
        target.Color = tint
        target.Width0 = width
        target.Width1 = width
        target.Segments = 20
        target.LightEmission = 0
        target.Texture = ""
        target.FaceCamera = true
    elseif textureId then
        target.Color = tint
        target.Width0 = width
        target.Width1 = width
        target.Segments = 20
        target.LightEmission = 0
        target.Texture = textureId
        target.TextureMode = Enum.TextureMode.Wrap
        target.TextureLength = shape.tile or (width * 4)
        target.FaceCamera = true
    else
        -- 이미지를 못 쓰는 경우: 색 띠 모양으로 대체
        target.Color = tint
        target.Width0 = width
        target.Width1 = width
        target.Segments = math.max(preset.segments, 20)
        target.LightEmission = preset.light
        target.Texture = ""
    end
end

local function applyBeamLook(beam, name)
    local preset = LINE_PRESETS[name]
    if not preset then
        restoreBeamLook(beam)
        return
    end
    local applied = lineApplied[beam]
    if applied and applied.name == name then return end

    if not lineOriginal[beam] then
        local saved = {}
        for _, prop in ipairs(BEAM_LOOK_PROPS) do
            saved[prop] = beam[prop]
        end
        lineOriginal[beam] = saved
        beamGameColor[beam] = beam.Color
    end
    local tint = beamGameColor[beam] or beam.Color

    local shape = LINE_SHAPES[name] or {}
    local textureId = resolveLineTexture(name)

    paintBeam(beam, preset, shape, textureId, tint)

    -- 꼬인 줄: 반대쪽으로 휘는 가닥을 하나 더 만들어 X 모양으로 엇갈리게 함
    destroyStrands(beam)
    local oldBase = curveBase[beam]
    if oldBase then
        -- 이전 모양(꼬임/물결)으로 바뀌어 있던 곡선을 원래 값으로 되돌린 뒤 새로 시작
        pcall(function()
            beam.CurveSize0 = oldBase.c0
            beam.CurveSize1 = oldBase.c1
        end)
        curveBase[beam] = nil
    end
    if shape.braid then
        local strand = beam:Clone()
        if strand then
            strand:SetAttribute("VAStrand", true)
            strand.Name = "VAStrand"
            for _, child in ipairs(strand:GetChildren()) do
                child:Destroy()
            end
            paintBeam(strand, preset, shape, textureId, tint)
            strand.Parent = beam.Parent
            strands[beam] = { strand }
        end
    end
    lineApplied[beam] = { name = name, texture = beam.Texture, width = beam.Width0, ourColor = beam.Color }
end

-- 파티클 ------------------------------------------------------
local function destroyBeamParticles(beam)
    local entry = beamParticles[beam]
    if entry then
        for _, emitter in ipairs(entry.emitters) do
            liveEmitters[emitter] = nil
            pcall(function() emitter:Destroy() end)
        end
        for _, node in ipairs(entry.nodes) do
            liveNodes[node] = nil
            pcall(function() node:Destroy() end)
        end
        beamParticles[beam] = nil
    end
end

local function createBeamParticles(beam)
    destroyBeamParticles(beam)
    if not particlesEnabled then return end
    if not beamIsActive(beam) then return end

    local baseColor = (Options.VABeamParticleColor and Options.VABeamParticleColor.Value) or Color3.fromRGB(0, 220, 255)
    local entry = { emitters = {}, nodes = {}, factors = {}, mode = particlePoint }

    -- 파티클이 나올 위치(앵커)
    local anchors = {}
    if particlePoint == "Beam Endpoint" then
        local attachment = beam.Attachment1 or beam.Attachment0
        if attachment then
            anchors = { attachment }
        elseif beam.Parent and beam.Parent:IsA("BasePart") then
            anchors = { beam.Parent }
        end
    else
        local count = (particlePoint == "Pulse Orbit") and 1 or 6
        for i = 1, count do
            local node = makeNode()
            entry.nodes[i] = node
            anchors[i] = node
        end
    end

    for _, anchor in ipairs(anchors) do
        for _, styleName in ipairs(STYLE_ORDER) do
            if selectedStyles[styleName] then
                for _, spec in ipairs(BEAM_STYLES[styleName]) do
                    local emitter = Instance.new("ParticleEmitter")
                    emitter.Name = "VABeamParticles"
                    emitter.Texture = (spec.texKey and getParticleTexture(spec.texKey)) or spec.tex
                    emitter.Color = ColorSequence.new({
                        ColorSequenceKeypoint.new(0, baseColor:Lerp(spec.tint0, spec.mix)),
                        ColorSequenceKeypoint.new(1, spec.tint1),
                    })
                    emitter.Size = NumberSequence.new({
                        NumberSequenceKeypoint.new(0, spec.size),
                        NumberSequenceKeypoint.new(1, 0),
                    })
                    emitter.Transparency = NumberSequence.new({
                        NumberSequenceKeypoint.new(0, spec.t0 or 0),
                        NumberSequenceKeypoint.new(1, 1),
                    })
                    emitter.Lifetime = spec.life
                    emitter.Speed = spec.speed
                    emitter.SpreadAngle = Vector2.new(spec.spread, spec.spread)
                    emitter.LightEmission = spec.light
                    emitter.Acceleration = spec.accel
                    emitter.Rotation = spec.norot and NumberRange.new(0, 0) or NumberRange.new(0, 360)
                    emitter.RotSpeed = spec.norot and NumberRange.new(0, 0) or NumberRange.new(-60, 60)

                    local factor = (spec.rate or 1) / #anchors
                    emitter.Rate = math.max(0.5, particleRate * factor)
                    emitter.Parent = anchor
                    CollectionService:AddTag(emitter, EMITTER_TAG)
                    liveEmitters[emitter] = true

                    entry.emitters[#entry.emitters + 1] = emitter
                    entry.factors[emitter] = factor
                end
            end
        end
    end

    beamParticles[beam] = entry
end

local function destroyAllBeamParticles()
    for beam in pairs(beamParticles) do
        destroyBeamParticles(beam)
    end
end

-- 우리가 만들었지만 더는 관리하지 않는 파티클/노드(줄이 이미 사라진 경우 등)를 찾아서 지움
local function sweepLeftoverParticles()
    for _, emitter in ipairs(CollectionService:GetTagged(EMITTER_TAG)) do
        if not liveEmitters[emitter] then
            pcall(function() emitter:Destroy() end)
        end
    end
    for _, node in ipairs(CollectionService:GetTagged(NODE_TAG)) do
        if not liveNodes[node] then
            pcall(function() node:Destroy() end)
        end
    end
end

local function refreshBeamParticles()
    if not particlesEnabled then
        destroyAllBeamParticles()
        sweepLeftoverParticles()
        return
    end
    for beam in pairs(grabBeams) do
        if beam.Parent then
            createBeamParticles(beam)
        end
    end
end

local function updateBeam(beam)
    -- 라인 모양
    if lineEnabled and LINE_PRESETS[lineChoice] then
        applyBeamLook(beam, lineChoice)
    elseif lineApplied[beam] ~= nil or lineOriginal[beam] ~= nil then
        restoreBeamLook(beam)
    end

    -- 파티클 (라인이 사라졌거나 멈춰 있으면 파티클도 바로 지움)
    if particlesEnabled and beamIsActive(beam) then
        if beamParticles[beam] == nil then
            createBeamParticles(beam)
        end
    elseif beamParticles[beam] ~= nil then
        destroyBeamParticles(beam)
    end
end

local function refreshLines()
    for beam in pairs(grabBeams) do
        if beam.Parent then
            pcall(updateBeam, beam)
        end
    end
end

local function scanBeams()
    local count = 0
    for _, d in ipairs(Workspace:GetDescendants()) do
        if d:IsA("Beam") then
            allBeams[d] = true
            if isGrabBeam(d) then
                registerGrabBeam(d)
            end
        end
        count = count + 1
        if count % 800 == 0 then task.wait() end
    end
end

conn(Workspace.DescendantAdded, function(d)
    if d:IsA("Beam") then
        allBeams[d] = true
        local function check()
            if d.Parent and isGrabBeam(d) then
                registerGrabBeam(d)
                pcall(updateBeam, d)
            end
        end
        task.defer(check)
        task.delay(0.15, check) -- 연결(Attachment)이 나중에 지정되는 경우를 위해 한 번 더
    end
end)

-- 라인이 매 프레임 렌더되기 직전에, 게임이 되돌려 놓은 모양이 있으면 다시 입힘
pcall(function() RunService:UnbindFromRenderStep("VALineEnforce") end)
local shapeClock = 0

-- 꼬임/물결: 게임이 정한 곡선 위에 일정한 값을 더해서 줄 모양을 만듦
local function stepBeamShape(beam)
    local applied = lineApplied[beam]
    if not applied then return end
    local shape = LINE_SHAPES[applied.name]
    if not (shape and (shape.braid or shape.wave)) then return end

    local base = curveBase[beam]
    if not base then
        base = { c0 = beam.CurveSize0, c1 = beam.CurveSize1, w0 = beam.CurveSize0, w1 = beam.CurveSize1 }
        curveBase[beam] = base
    end
    -- 우리가 쓴 값이 아닌 게 들어 있으면 게임이 곡선을 바꾼 것이니 그 값을 새 기준으로
    if math.abs(beam.CurveSize0 - base.w0) > 0.001 then base.c0 = beam.CurveSize0 end
    if math.abs(beam.CurveSize1 - base.w1) > 0.001 then base.c1 = beam.CurveSize1 end

    local offset = 0
    if shape.braid then
        offset = shape.braid
    elseif shape.wave then
        offset = shape.wave * math.sin(shapeClock * (shape.speed or 3))
    end

    base.w0 = base.c0 + offset
    base.w1 = base.c1 - offset
    beam.CurveSize0 = base.w0
    beam.CurveSize1 = base.w1

    local extras = strands[beam]
    if extras then
        for _, strand in ipairs(extras) do
            if strand.Parent then
                if strand.Attachment0 ~= beam.Attachment0 then strand.Attachment0 = beam.Attachment0 end
                if strand.Attachment1 ~= beam.Attachment1 then strand.Attachment1 = beam.Attachment1 end
                strand.Enabled = beam.Enabled
                strand.Transparency = beam.Transparency
                strand.CurveSize0 = base.c0 - offset
                strand.CurveSize1 = base.c1 + offset
            end
        end
    end
end

RunService:BindToRenderStep("VALineEnforce", Enum.RenderPriority.Last.Value, function(dt)
    if not lineEnabled then return end
    shapeClock = shapeClock + dt
    for beam in pairs(grabBeams) do
        local applied = lineApplied[beam]
        if beam.Parent and applied and (beam.Texture ~= applied.texture or beam.Width0 ~= applied.width) then
            lineApplied[beam] = nil
            pcall(applyBeamLook, beam, lineChoice)
        end
        if beam.Parent then
            local current = lineApplied[beam]
            if current and current.ourColor and not seqEqual(beam.Color, current.ourColor) then
                -- 게임 안에서 줄 색을 바꿨다면 그 색을 새 기준으로 (무늬는 흰색/회색이라 그 색으로 물듦)
                beamGameColor[beam] = beam.Color
                current.ourColor = beam.Color
            end
            pcall(stepBeamShape, beam)
        end
    end
end)

-- "라인을 따라 / 물결 / 궤도" 모드에서 파티클 위치를 매 프레임 옮김
local particleClock = 0
conn(RunService.RenderStepped, function(dt)
    particleClock = particleClock + dt

    for beam, entry in pairs(beamParticles) do
        local nodes = entry.nodes
        if not beamIsActive(beam) then
            destroyBeamParticles(beam)
        elseif #nodes > 0 then
            local a0, a1 = beam.Attachment0, beam.Attachment1
            if a0 and a1 then
                local p0, p1 = a0.WorldPosition, a1.WorldPosition
                local delta = p1 - p0
                local forward = delta.Magnitude > 0.01 and delta.Unit or Vector3.zAxis

                local side = forward:Cross(Vector3.yAxis)
                if side.Magnitude < 0.01 then side = Vector3.xAxis else side = side.Unit end
                local up = forward:Cross(side)

                if entry.mode == "Pulse Orbit" then
                    local radius = 1.5 + math.sin(particleClock * 3) * 0.8
                    local angle = particleClock * 4
                    nodes[1].Position = p1 + side * math.cos(angle) * radius + up * math.sin(angle) * radius
                else
                    for i, node in ipairs(nodes) do
                        local t = i / (#nodes + 1)
                        local pos = p0:Lerp(p1, t)
                        if entry.mode == "Continuous Wave Motion" then
                            pos = pos + side * math.sin(particleClock * 4 + t * 10) * 1.2
                                + up * math.cos(particleClock * 3 + t * 8) * 0.6
                        end
                        node.Position = pos
                    end
                end
            end
        end
    end
end)

-- 멀티 선택 드롭다운 값 -> { [이름] = true }
local function parseSelection(Value)
    local set = {}
    if type(Value) == "table" then
        for k, v in pairs(Value) do
            if type(k) == "string" and v == true then
                set[k] = true
            elseif type(v) == "string" then
                set[v] = true
            end
        end
    elseif type(Value) == "string" then
        set[Value] = true
    end
    if next(set) == nil then
        set[STYLE_ORDER[1]] = true
    end
    return set
end

