-- Fling Trajectory
Divider(LineSection, "Fling Trajectory")

local flingEnabled = false
local rainbowTrajectory = false
local FLING_STEPS = 40
local flingSegments = {}
local flingFolder = nil

local flingToggle = LineSection:AddToggle("VAEnableFlingTrajectory", {
    Text = "Enable Fling Trajectory",
    Default = false,
    Tooltip = "Visualize flight path and landing spot of what you are holding",
