    Default = Color3.fromRGB(0, 255, 160),
    Title = "Trajectory Color",
})

LineSection:AddToggle("VARainbowTrajectory", {
    Text = "Rainbow Trajectory",
    Default = false,
    Callback = function(Value)
        rainbowTrajectory = Value
    end,
})

local function ensureSegments(count)
    if not flingFolder or not flingFolder.Parent then
        flingFolder = Instance.new("Folder")
        flingFolder.Name = "VAFlingTrajectory"
        flingFolder.Parent = Workspace.CurrentCamera
        flingSegments = {}
    end
    while #flingSegments < count do
        local part = Instance.new("Part")
        part.Anchored = true
        part.CanCollide = false
        part.CanQuery = false
        part.CanTouch = false
        part.CastShadow = false
        part.Material = Enum.Material.Neon
        part.Transparency = 1
        part.Size = Vector3.new(0.18, 0.18, 0.18)
        part.Parent = flingFolder
        flingSegments[#flingSegments + 1] = part
    end
end

local function hideSegmentsFrom(index)
    for i = index, #flingSegments do
        if flingSegments[i].Transparency ~= 1 then
            flingSegments[i].Transparency = 1
        end
    end
end

local function getHeldPart()
    local grabParts = Workspace:FindFirstChild("GrabParts")
    if not grabParts then return nil end
    local grabPart = grabParts:FindFirstChild("GrabPart")
    local weld = grabPart and grabPart:FindFirstChildOfClass("WeldConstraint")
    local held = weld and weld.Part1
    if held and held.Parent then
        return held
    end
    return nil
end

conn(RunService.RenderStepped, function()
    if not flingEnabled then
        if #flingSegments > 0 then hideSegmentsFrom(1) end
        return
    end

    local held = getHeldPart()
    if not held then
        if #flingSegments > 0 then hideSegmentsFrom(1) end
        return
    end

    ensureSegments(FLING_STEPS)

    local ignore = { flingFolder }
    if LocalPlayer.Character then ignore[#ignore + 1] = LocalPlayer.Character end
    local heldModel = held:FindFirstAncestorOfClass("Model")
    if heldModel then ignore[#ignore + 1] = heldModel else ignore[#ignore + 1] = held end
    local grabParts = Workspace:FindFirstChild("GrabParts")
    if grabParts then ignore[#ignore + 1] = grabParts end

    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = ignore

    local baseColor = (Options.VAFlingColor and Options.VAFlingColor.Value) or Color3.fromRGB(0, 255, 160)
    local gravity = Vector3.new(0, -Workspace.Gravity, 0)
    local step = 0.07
    local pos = held.Position
    local vel = held.AssemblyLinearVelocity
    local used = 0

    for i = 1, FLING_STEPS do
        local nextPos = pos + vel * step + gravity * (0.5 * step * step)
        local nextVel = vel + gravity * step
        local delta = nextPos - pos

        local endPos = nextPos
        local hit = nil
        if delta.Magnitude > 0.001 then
            hit = Workspace:Raycast(pos, delta, params)
            if hit then endPos = hit.Position end
        end

        local segment = flingSegments[i]
        local length = (endPos - pos).Magnitude
        if length > 0.01 then
            segment.Size = Vector3.new(0.18, 0.18, length)
            segment.CFrame = CFrame.lookAt(pos, endPos) * CFrame.new(0, 0, -length / 2)
            segment.Color = rainbowTrajectory and Color3.fromHSV((hue + i * 0.03) % 1, 1, 1) or baseColor
            segment.Transparency = 0.15
        else
            segment.Transparency = 1
        end

        used = i
        if hit then break end
        pos, vel = nextPos, nextVel
    end

    hideSegmentsFrom(used + 1)
end)

