-- =============================================
local customSkyOn = false
local skyText = ""
local ourSky = nil
local hiddenSkies = {}

local timeTouched, sunSizeTouched, sunColorTouched = false, false, false
local timeOfDay, sunSize, sunRays = 14, 30, 0
local rainbowSunRays = false

local raysCreated, raysOriginalIntensity = false, nil

local cloudsEnabled, rainbowClouds = false, false
local cloudCover, cloudDensity = 0.57, 0.57
local cloudsCreated, cloudsOriginal = false, nil

local function getClouds()
    return Terrain:FindFirstChildOfClass("Clouds")
end

local function removeCustomSky()
    if ourSky then
        pcall(function() ourSky:Destroy() end)
        ourSky = nil
    end
    for _, sky in ipairs(hiddenSkies) do
        if sky then
            pcall(function() sky.Parent = Lighting end)
        end
    end
    hiddenSkies = {}
end

local function applyCustomSky()
    local id = parseImageId(skyText)
    if not (customSkyOn and id) then
        removeCustomSky()
        return
    end

    if not ourSky then
        -- 원래 하늘은 지우지 않고 잠깐 빼 둠 (끄면 다시 돌려놓음)
        for _, child in ipairs(Lighting:GetChildren()) do
            if child:IsA("Sky") then
                hiddenSkies[#hiddenSkies + 1] = child
                child.Parent = nil
            end
        end
        ourSky = Instance.new("Sky")
        ourSky.Name = "VACustomSky"
        ourSky.Parent = Lighting
    end

    ourSky.SkyboxBk = id
    ourSky.SkyboxDn = id
    ourSky.SkyboxFt = id
    ourSky.SkyboxLf = id
    ourSky.SkyboxRt = id
    ourSky.SkyboxUp = id
    ourSky.SunAngularSize = sunSize
end

conn(Lighting.ChildAdded, function(child)
    if customSkyOn and ourSky and child:IsA("Sky") and child ~= ourSky then
        task.defer(function()
            hiddenSkies[#hiddenSkies + 1] = child
            child.Parent = nil
        end)
    end
end)

local function applySunSize()
    if not sunSizeTouched then return end
    local sky = Lighting:FindFirstChildOfClass("Sky")
    if not sky then
        sky = Instance.new("Sky")
        sky.Name = "VASunSky"
        sky.Parent = Lighting
    end
    if math.abs(sky.SunAngularSize - sunSize) > 0.01 then
        sky.SunAngularSize = sunSize
    end
end

local function applySunRays()
    local rays = Lighting:FindFirstChildOfClass("SunRaysEffect")
    if sunRays > 0 then
        if not rays then
            rays = Instance.new("SunRaysEffect")
            rays.Name = "VASunRays"
            rays.Parent = Lighting
            raysCreated = true
        elseif raysOriginalIntensity == nil and not raysCreated then
            raysOriginalIntensity = rays.Intensity
        end
        rays.Intensity = sunRays / 100
    elseif rays then
        if raysCreated then
            rays:Destroy()
            raysCreated = false
        elseif raysOriginalIntensity ~= nil then
            rays.Intensity = raysOriginalIntensity
            raysOriginalIntensity = nil
        end
    end
end

local function applySunColor()
    if rainbowSunRays or not sunColorTouched then return end
    local color = (Options.VASunRaysColor and Options.VASunRaysColor.Value) or Color3.new(1, 1, 1)
    Lighting.ColorShift_Top = color
end

local function restoreClouds()
    local clouds = getClouds()
    if cloudsCreated then
        if clouds then clouds:Destroy() end
        cloudsCreated = false
    elseif clouds and cloudsOriginal then
        clouds.Enabled = cloudsOriginal.Enabled
        clouds.Cover = cloudsOriginal.Cover
        clouds.Density = cloudsOriginal.Density
        clouds.Color = cloudsOriginal.Color
    end
    cloudsOriginal = nil
end

local function applyClouds()
    if not cloudsEnabled then
        restoreClouds()
        return
    end

    local clouds = getClouds()
    if not clouds then
        clouds = Instance.new("Clouds")
        clouds.Parent = Terrain
        cloudsCreated = true
    elseif not cloudsOriginal and not cloudsCreated then
        cloudsOriginal = {
            Enabled = clouds.Enabled,
            Cover = clouds.Cover,
            Density = clouds.Density,
            Color = clouds.Color,
        }
    end

    if not clouds.Enabled then clouds.Enabled = true end
    if math.abs(clouds.Cover - cloudCover) > 0.001 then clouds.Cover = cloudCover end
    if math.abs(clouds.Density - cloudDensity) > 0.001 then clouds.Density = cloudDensity end
    if not rainbowClouds then
        local color = (Options.VACloudColor and Options.VACloudColor.Value) or Color3.new(1, 1, 1)
        if clouds.Color ~= color then clouds.Color = color end
    end
end

