-- 이전 버전에서 남은 파티클 찌꺼기를 한 번 지움 (이름으로 찾음)
task.spawn(function()
    local count = 0
    for _, d in ipairs(Workspace:GetDescendants()) do
        if d.Name == "VABeamParticles" and d:IsA("ParticleEmitter") and not liveEmitters[d] then
            pcall(function() d:Destroy() end)
        end
        count = count + 1
        if count % 800 == 0 then task.wait() end
    end
    local camera = Workspace.CurrentCamera
    local oldNodes = camera and camera:FindFirstChild("VABeamNodes")
    if oldNodes and not nodeFolder then
        pcall(function() oldNodes:Destroy() end)
    end
end)

local noBeamSince, noBeamReported = nil, false

task.spawn(getgenv()._8minLoop("bg-9770", function()
    while task.wait(0.4) and alive() do
        -- 우리가 건드린 소리만 다시 확인
        for sound in pairs(soundState) do
            if sound.Parent then
                pcall(applySound, sound)
            end
        end

        -- 커스텀 라인을 껐는데 바뀐 채 남아 있는 줄이 있으면 되돌림
        if not lineEnabled then
            for beam in pairs(lineOriginal) do
                if beam.Parent then
                    pcall(restoreBeamLook, beam)
                end
            end
        end

        -- 줄이 사라진 파티클/노드 청소 (켜 둔 파티클이 줄이 없어져도 남던 문제)
        for beam in pairs(beamParticles) do
            if not beamIsActive(beam) then
                destroyBeamParticles(beam)
            end
        end
        if not particlesEnabled then destroyAllBeamParticles() end
        sweepLeftoverParticles()

        -- 그랩 중이면 GrabParts 안과 내 캐릭터에 붙은 빔을 다시 찾아 봄
        local grabParts = Workspace:FindFirstChild("GrabParts")
        if grabParts then
            for _, d in ipairs(grabParts:GetDescendants()) do
                if d:IsA("Beam") and not d:GetAttribute("VAStrand") then
                    allBeams[d] = true
                    registerGrabBeam(d)
                end
            end
            for beam in pairs(allBeams) do
                if beam.Parent and not grabBeams[beam] and isGrabBeam(beam) then
                    registerGrabBeam(beam)
                end
            end
        end

        -- 잡고 있는데 그랩 라인을 못 찾으면 콘솔(F9)에 월드의 빔 목록을 알려줌
        if (lineEnabled or particlesEnabled) and grabParts then
            local found = false
            for beam in pairs(grabBeams) do
                if beam.Parent then found = true break end
            end
            if found then
                noBeamSince = nil
            else
                noBeamSince = noBeamSince or os.clock()
                if not noBeamReported and os.clock() - noBeamSince > 1.5 then
                    noBeamReported = true
                    print("[8min] grab line not found. Beams in the world:")
                    local shown = 0
                    for beam in pairs(allBeams) do
                        if beam.Parent and shown < 12 then
                            shown = shown + 1
                            print("   " .. beam:GetFullName() .. " | Enabled=" .. tostring(beam.Enabled))
                        end
                    end
                end
            end
        else
            noBeamSince = nil
            noBeamReported = false
        end

        -- 그랩 라인
        for beam in pairs(grabBeams) do
            if beam.Parent then
                pcall(updateBeam, beam)
            else
                destroyBeamParticles(beam)
                grabBeams[beam] = nil
            end
        end

        -- 하늘/조명 (사용자가 한 번이라도 건드린 값만 유지)
        pcall(function()
            if timeTouched and math.abs(Lighting.ClockTime - timeOfDay) > 0.05 then
                Lighting.ClockTime = timeOfDay
            end
            applySunSize()
            if cloudsEnabled then applyClouds() end
        end)
    end
end))

local rainbowTimer = 0
conn(RunService.Heartbeat, function(dt)
    hue = (hue + dt * 0.15) % 1

    rainbowTimer = rainbowTimer + dt
    if rainbowTimer < 0.08 then return end
    rainbowTimer = 0

    local color = Color3.fromHSV(hue, 1, 1)

    if rainbowParticles then
        local sequence = ColorSequence.new(color)
        for _, entry in pairs(beamParticles) do
            for _, emitter in ipairs(entry.emitters) do
                emitter.Color = sequence
            end
        end
    end

    if rainbowClouds and cloudsEnabled then
        local clouds = getClouds()
        if clouds then clouds.Color = color end
    end

    if rainbowSunRays then
        Lighting.ColorShift_Top = color
    end
end)

-- =============================================
-- 다시 실행할 때 이전 것을 깨끗이 되돌리는 정리 함수
-- =============================================
getgenv().VA_Cleanup = function()
    for _, connection in ipairs(vaConnections) do
        pcall(function() connection:Disconnect() end)
    end
    pcall(function() RunService:UnbindFromRenderStep("VALineEnforce") end)
    pcall(function() RunService:UnbindFromRenderStep("RightHandStayVisible") end)

    for beam in pairs(lineOriginal) do
        pcall(restoreBeamLook, beam)
    end
    pcall(destroyAllBeamParticles)
    pcall(sweepLeftoverParticles)
    for sound, state in pairs(soundState) do
        pcall(function() sound.Volume = state.orig end)
    end

    pcall(removeCustomSky)
    pcall(restoreClouds)
    pcall(function()
        if flingFolder then flingFolder:Destroy() end
        if nodeFolder then nodeFolder:Destroy() end
    end)
end

end)()






