-- 모드 선택
--   Bring : 내가 상대 위치로 가서 잡고 → 내 원래 자리로 끌고 옴
--   Kick  : 내가 상대 위치로 가서 잡고 → 상대를 공허로 보냄
OwnerGroup:AddDropdown("SetOwnerKickMode", {
    Text = "Mode",
    Values = { "Bring", "Kick" },
    Default = 1,
    Tooltip = "Bring: go to the target, grab it and drag it back to you. Kick: go to the target, grab it and send it into the void.",
    Callback = function(v)
        getgenv().KickMode = v
    end,
})

local GRAB_CALLS_PER_FRAME = 8   -- 잡는 중 프레임당 SetNetworkOwner 호출 수
local HOLD_CALLS_PER_FRAME = 3   -- 끌고 오는 중(소유권 유지) 호출 수
local GRAB_TIMEOUT = 0.6         -- 이 시간 안에 소유권이 확인 안 돼도 끌고 오기 시작

local function ownsPart(part)
    if type(isnetworkowner) == "function" then
        local ok, owned = pcall(isnetworkowner, part)
        if ok and type(owned) == "boolean" then return owned end
    end
    local ok, age = pcall(function() return part.ReceiveAge end)
    return ok and age == 0
end

local function stopKickLoop()
    kickLoopRunning = false
    if kickConnection then
        kickConnection:Disconnect()
        kickConnection = nil
    end
end

local function startKickLoop()
    if not selectedKickPlayer then return end
    if kickConnection then kickConnection:Disconnect() kickConnection = nil end

    kickLoopRunning = true

    local grabEvents = rs:FindFirstChild("GrabEvents")
    local setOwner = grabEvents and grabEvents:FindFirstChild("SetNetworkOwner")
    local destroyLine = grabEvents and grabEvents:FindFirstChild("DestroyGrabLine")

    -- 라인(CreateGrabLine)은 보내지 않음 → 라인이 보이지 않음. SetNetworkOwner + DestroyGrabLine 만 호출.
    local function spam(tHRP, myHRP, n)
        for _ = 1, n do
            if setOwner then
                pcall(function()
                    setOwner:FireServer(tHRP, CFrame.lookAt(myHRP.Position, tHRP.Position))
                end)
            end
        end
        if destroyLine then
            pcall(function() destroyLine:FireServer(tHRP) end)
        end
    end

    local phase = "grab"        -- grab: 상대에게 가서 잡는 중 / carry: 끌고 오는 중
    local homeCF = nil          -- 내가 출발한 자리
    local grabStart = 0

    kickConnection = RunService.Heartbeat:Connect(function()
        if not kickLoopRunning or not selectedKickPlayer then return end

        local myChar = plr.Character
        local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
        local tChar = selectedKickPlayer.Character
        local tHRP = tChar and tChar:FindFirstChild("HumanoidRootPart")
        local tHum = tChar and tChar:FindFirstChild("Humanoid")
        if not (myHRP and tHRP and tHum and tHum.Health > 0) then
            phase = "grab"
            homeCF = nil
            return
        end

        if phase == "grab" then
            if not homeCF then
                homeCF = myHRP.CFrame
                grabStart = tick()
            end

            -- 상대 바로 옆으로 이동해서 잡음
            myHRP.CFrame = tHRP.CFrame * CFrame.new(0, 0, 2)
            myHRP.AssemblyLinearVelocity = Vector3.zero
            spam(tHRP, myHRP, GRAB_CALLS_PER_FRAME)

            if ownsPart(tHRP) or tick() - grabStart > GRAB_TIMEOUT then
                phase = "carry"
                myHRP.CFrame = homeCF       -- 내 원래 자리로 돌아감
                myHRP.AssemblyLinearVelocity = Vector3.zero
            end
        else
            -- 끌고 오기: 소유권 유지 + 상대를 목적지에 고정
            spam(tHRP, myHRP, HOLD_CALLS_PER_FRAME)

            local dest
            if getgenv().KickMode == "Kick" then
                local void = (workspace.FallenPartsDestroyHeight or -500) - 3000
                dest = CFrame.new(tHRP.Position.X, void, tHRP.Position.Z)
            else
                dest = myHRP.CFrame * CFrame.new(0, 0, -4)
            end

            tHRP.CFrame = dest
            tHRP.AssemblyLinearVelocity = Vector3.zero
            tHRP.AssemblyAngularVelocity = Vector3.zero
        end
    end)
end

OwnerGroup:AddToggle("SetOwnerKickToggle", { Text = "Run", Default = false }):OnChanged(function(v)
    if v and not selectedKickPlayer then
        Library:Notify("Please select a target first!")
        return
    end
    if v then startKickLoop() else stopKickLoop() end
end)




-- ==========================================================
-- 아이콘 이름 자동 선택: 후보 중 라이브러리에 실제로 있는 첫 번째 이름을 사용
-- (없는 이름을 넣으면 아이콘이 안 뜨기 때문에, 못 찾으면 fallback 사용)
-- ==========================================================
local function PickIcon(candidates, fallback)
    for _, name in ipairs(candidates) do
        local ok, found = pcall(function() return Library:GetIcon(name) end)
        if ok and found then
            return name
        end
    end
    -- GetIcon 으로 확인이 안 되는 라이브러리면 첫 번째 후보를 그대로 사용
    local canCheck = pcall(function() return Library:GetIcon("settings") end)
    if canCheck then
        return fallback or "settings"
    end
    return candidates[1]
end

