                Ft = "rbxassetid://15502524520", Lf = "rbxassetid://15502522129",
                Rt = "rbxassetid://15502523711", Up = "rbxassetid://15502526102",
                Sun = "rbxasset://sky/sun.jpg", Moon = "rbxasset://sky/moon.jpg",
            },
            Water = { WaveSize = 1, WaveSpeed = 9, Reflectance = 1, Transparency = 0.07, Color = Color3.fromRGB(0, 100, 200) },
        },
    }

    local OCEAN = { Size = 8000, Depth = 20, Level = -14, Chunk = 1000, SpawnClear = 750 }

    ----------------------------------------------------------
    -- 상태 변수
    ----------------------------------------------------------
    local currentShaderMode = ShaderModeList[1]
    local executeOn = false
    local OceanToken = 0        -- 바다 채우기/지우기 작업 취소용
    local OceanApplied = false
    local PreviewImage = nil
    local StatusLabel = nil

    local function SetStatus(text)
        if StatusLabel then
            pcall(function() StatusLabel:SetText("Status: " .. tostring(text)) end)
        end
    end

    ----------------------------------------------------------
    -- 원래 상태 백업 (Clear Shader 에서 이걸로 복구)
    ----------------------------------------------------------
    local OrigLight = {}
    local BackupLightingObjs = {}
    local BackupTerrainObjs = {}
    local OrigOceanTransparency = {}
    local OceanColorOverride = nil -- 사용자가 고른 바다 색 (nil = 선택 안 함)
    local OrigOceanColors = {}

    local function TryClone(inst)
        local ok, c = pcall(function() return inst:Clone() end)
        if ok then return c end
        return nil
    end

    pcall(function()
        for _, k in ipairs({ "ClockTime", "Brightness", "ExposureCompensation", "GlobalShadows", "OutdoorAmbient", "Ambient" }) do
            OrigLight[k] = Lighting[k]
        end
        for _, v in ipairs(Lighting:GetChildren()) do
            if (v:IsA("Sky") or v:IsA("Atmosphere") or v:IsA("Clouds")) and not v:GetAttribute(TAG) then
                local c = TryClone(v)
                if c then table.insert(BackupLightingObjs, c) end
            end
        end
        for _, v in ipairs(Terrain:GetChildren()) do
            if v:IsA("Clouds") then
                local c = TryClone(v)
                if c then table.insert(BackupTerrainObjs, c) end
            end
        end
    end)

    ----------------------------------------------------------
    -- 하늘 / 조명 / 물
    ----------------------------------------------------------
    local function HasOurSky()
        for _, v in ipairs(Lighting:GetChildren()) do
            if v:IsA("Sky") and v:GetAttribute(TAG) then return true end
        end
        return false
    end

    local function ClearSkyObjects()
        for _, v in ipairs(Terrain:GetChildren()) do
            if v:IsA("Clouds") then v:Destroy() end
        end
        for _, v in ipairs(Lighting:GetChildren()) do
            if v:IsA("Clouds") or v:IsA("Sky") or v:IsA("Atmosphere") then v:Destroy() end
        end
    end

    local function ApplySky(cfg)
        ClearSkyObjects()
        local s = cfg.Sky
        local sky = Instance.new("Sky")
        sky.Name = "Sky"
        sky:SetAttribute(TAG, true)
        sky.SkyboxBk = s.Bk
        sky.SkyboxDn = s.Dn
        sky.SkyboxFt = s.Ft
        sky.SkyboxLf = s.Lf
        sky.SkyboxRt = s.Rt
        sky.SkyboxUp = s.Up
        sky.SunTextureId = s.Sun
        sky.MoonTextureId = s.Moon
        if s.Stars then sky.StarCount = s.Stars end
        if s.SunSize then sky.SunAngularSize = s.SunSize end
        if s.MoonSize then sky.MoonAngularSize = s.MoonSize end
        sky.CelestialBodiesShown = true
        sky.Parent = Lighting
    end

    local function ApplyLighting(light)
        if not light then return end
        for k, v in pairs(light) do
            pcall(function() Lighting[k] = v end)
        end
    end

    local function ApplyWater(w)
        Terrain.WaterWaveSize = w.WaveSize
        Terrain.WaterWaveSpeed = w.WaveSpeed
        Terrain.WaterReflectance = w.Reflectance
        Terrain.WaterTransparency = w.Transparency
        Terrain.WaterColor = OceanColorOverride or w.Color
    end

    ----------------------------------------------------------
    -- 게임/다른 스크립트가 하늘을 되돌리는 경우를 막는 감시(Guard)
    ----------------------------------------------------------
    local Guard = { Conns = {}, Active = false }

    local function SameValue(a, b)
        if type(a) == "number" and type(b) == "number" then
            return math.abs(a - b) < 0.001
        end
        return a == b
    end

    local function StopGuard()
        Guard.Active = false
        for _, c in ipairs(Guard.Conns) do
            pcall(function() c:Disconnect() end)
        end
        Guard.Conns = {}
    end

    local function StartGuard(cfg)
        StopGuard()
        Guard.Active = true

        -- 다른 Sky / Atmosphere / Clouds 가 새로 생기면 바로 지움
        table.insert(Guard.Conns, Lighting.ChildAdded:Connect(function(child)
            if not Guard.Active then return end
            if child:IsA("Sky") and child:GetAttribute(TAG) then return end
            if child:IsA("Sky") or child:IsA("Atmosphere") or child:IsA("Clouds") then
                task.defer(function() pcall(function() child:Destroy() end) end)
            end
        end))

        -- 우리 Sky 가 지워지면 다시 만듦
        table.insert(Guard.Conns, Lighting.ChildRemoved:Connect(function(child)
            if not Guard.Active then return end
            if child:IsA("Sky") and child:GetAttribute(TAG) then
                task.defer(function()
                    if Guard.Active and not HasOurSky() then
                        pcall(ApplySky, cfg)
                    end
                end)
            end
        end))

        -- 조명값을 바꿔놓으면 다시 되돌림
        if cfg.Light then
            for k, v in pairs(cfg.Light) do
                table.insert(Guard.Conns, Lighting:GetPropertyChangedSignal(k):Connect(function()
                    if Guard.Active and not SameValue(Lighting[k], v) then
                        pcall(function() Lighting[k] = v end)
                    end
                end))
            end
        end
    end

    ----------------------------------------------------------
    -- 바다 (Terrain 물 + 기존 바다 모델 숨김)
    ----------------------------------------------------------
    local function HideOldOcean()
        pcall(function()
            local model = workspace.Map.AlwaysHereTweenedObjects.Ocean.Object:FindFirstChild("ObjectModel")
            if model then
                for _, prt in ipairs(model:GetChildren()) do
                    if prt:IsA("Part") then
                        if OrigOceanTransparency[prt] == nil then
                            OrigOceanTransparency[prt] = prt.Transparency
                        end
                        prt.Transparency = 1
                    end
                end
            end
        end)
    end

    local function RestoreOldOcean()
        for prt, tr in pairs(OrigOceanTransparency) do
            pcall(function() prt.Transparency = tr end)
        end
        OrigOceanTransparency = {}
    end

    -- 게임 원래 바다(모델)에도 색을 입힘: Terrain.WaterColor 는 Terrain 물에만 적용되기 때문
    local function GetOldOceanModel()
        local model = nil
        pcall(function()
            model = workspace.Map.AlwaysHereTweenedObjects.Ocean.Object:FindFirstChild("ObjectModel")
        end)
        return model
    end

    local function TintOldOcean(color)
        local model = GetOldOceanModel()
        if not model then return end
        for _, d in ipairs(model:GetDescendants()) do
            if d:IsA("BasePart") then
                pcall(function()
                    if OrigOceanColors[d] == nil then OrigOceanColors[d] = d.Color end
                    d.Color = color
                end)
            end
        end
    end

    local function RestoreOldOceanColors()
        for part, color in pairs(OrigOceanColors) do
            pcall(function() part.Color = color end)
        end
        OrigOceanColors = {}
    end

    local function ForEachChunk(fn, token)
        local steps = math.ceil(OCEAN.Size / OCEAN.Chunk)
        local startOffset = -OCEAN.Size / 2
        local y = OCEAN.Level - (OCEAN.Depth / 2)
        for ix = 0, steps - 1 do
            for iz = 0, steps - 1 do
                if token ~= OceanToken then return false end
                local cx = startOffset + (ix * OCEAN.Chunk) + (OCEAN.Chunk / 2)
                local cz = startOffset + (iz * OCEAN.Chunk) + (OCEAN.Chunk / 2)
                fn(cx, y, cz)
                task.wait()
            end
        end
        return true
    end

    local function FillOcean(token)
        return ForEachChunk(function(cx, y, cz)
            Terrain:FillBlock(CFrame.new(cx, y, cz), Vector3.new(OCEAN.Chunk, OCEAN.Depth, OCEAN.Chunk), Enum.Material.Water)
        end, token)
    end

    -- 물(Water) 복셀만 Air 로 바꿔서, 다른 지형은 건드리지 않음
    local function RemoveOceanWater(token)
        return ForEachChunk(function(cx, y, cz)
            local half = OCEAN.Chunk / 2
            local hy = OCEAN.Depth / 2
            local region = Region3.new(Vector3.new(cx - half, y - hy, cz - half), Vector3.new(cx + half, y + hy, cz + half)):ExpandToGrid(4)
            local ok = pcall(function()
                Terrain:ReplaceMaterial(region, 4, Enum.Material.Water, Enum.Material.Air)
            end)
            if not ok then
                Terrain:FillBlock(CFrame.new(cx, y, cz), Vector3.new(OCEAN.Chunk, OCEAN.Depth, OCEAN.Chunk), Enum.Material.Air)
            end
        end, token)
    end

    -- 화면에 보이는 상태 라벨용: Sky 가 살아있는지 / 바다 복셀이 물인지
    local function DescribeState()
        local skyText = HasOurSky() and "OK" or "None"
        local waterText = "?"
        pcall(function()
            local region = Region3.new(Vector3.new(496, -28, 496), Vector3.new(504, -20, 504))
            local materials = Terrain:ReadVoxels(region, 4)
            waterText = string.gsub(tostring(materials[1][1][1]), "Enum.Material.", "")
        end)
        return "Sky " .. skyText .. " / Water " .. waterText
    end

    ----------------------------------------------------------
    -- 적용 / 복구
    ----------------------------------------------------------
    local function ApplyShader(mode)
        local cfg = ShaderData[mode]
        if not cfg then return end

        StopGuard()
        OceanToken = OceanToken + 1
        local token = OceanToken
        OceanApplied = true

        SetStatus("Applying: " .. mode)
        ApplySky(cfg)
        ApplyLighting(cfg.Light)
        ApplyWater(cfg.Water)
        HideOldOcean()
        StartGuard(cfg)

        if FillOcean(token) then
            Terrain:FillBlock(
                CFrame.new(0, OCEAN.Level - (OCEAN.Depth / 2), 0),
                Vector3.new(OCEAN.SpawnClear, OCEAN.Depth, OCEAN.SpawnClear),
                Enum.Material.Air
            )
            ApplyWater(cfg.Water)
            task.wait(2)
            if token == OceanToken then
                SetStatus(mode .. " applied | " .. DescribeState())
            end
        end
    end

    local function SafeApply(mode)
        local ok, err = pcall(ApplyShader, mode)
        if not ok then
            warn("[Shader error] " .. tostring(err))
            SetStatus("Error: " .. tostring(err))
            pcall(function() Library:Notify("Shader error: " .. tostring(err), 6) end)
        end
    end

    local function ClearShader()
        OceanToken = OceanToken + 1
        local token = OceanToken
        StopGuard()
        SetStatus("Restoring...")

        -- 하늘 / 구름 / 대기: 원래 있던 것으로 복구 (원래 없었으면 없는 채로 = 기본 하늘)
        ClearSkyObjects()
        for _, obj in ipairs(BackupLightingObjs) do
            local c = TryClone(obj)
            if c then c.Parent = Lighting end
        end
        for _, obj in ipairs(BackupTerrainObjs) do
            local c = TryClone(obj)
            if c then c.Parent = Terrain end
        end

        -- 조명값 복구
        for k, v in pairs(OrigLight) do
            pcall(function() Lighting[k] = v end)
        end

        -- 예전 버전이 남겼을 수 있는 색상 조절 효과/패널 정리
        local cc = Lighting:FindFirstChild("UIToggleColorCorrection")
        if cc then cc:Destroy() end
        local pg = plr:FindFirstChild("PlayerGui")
        local oldPanel = pg and pg:FindFirstChild("LightingControlGui")
        if oldPanel then oldPanel:Destroy() end

        -- 숨겼던 원래 바다 모델 복구 + 우리가 만든 물만 제거
        RestoreOldOcean()
        RestoreOldOceanColors()
        OceanColorOverride = nil
        if OceanApplied then
            if RemoveOceanWater(token) then
                OceanApplied = false
                SetStatus("Restored (original sky/water)")
            end
        else
            SetStatus("Restored (original sky)")
        end
    end

    local function SafeClear()
        local ok, err = pcall(ClearShader)
        if not ok then
            warn("[Shader restore error] " .. tostring(err))
            SetStatus("Restore error: " .. tostring(err))
        end
    end

    ----------------------------------------------------------
    -- UI (생성 순서 = 화면 순서: 드롭다운 → 사진 → 실행 → 지우기 → 상태)
    ----------------------------------------------------------
    ShaderGroup:AddDropdown("ShaderMode", {
