            task.spawn(function()
                currentShaderMode = Value
                local cfg = ShaderData[Value]
                if cfg and PreviewImage then PreviewImage.Image = cfg.Preview end
                if executeOn then SafeApply(Value) end -- 실행 중에 바꾸면 바로 교체
            end)
        end
    })

    PreviewImage = Instance.new("ImageLabel")
    PreviewImage.Name = "ShaderPreviewImage"
    PreviewImage.Size = UDim2.new(1, -16, 0, 220)
