    local ExecuteToggle = ShaderGroup:AddToggle("ExecuteShaderToggle", {
        Text = "Execute Shader",
        Default = false,
        Callback = function(Value)
            executeOn = Value
            if Value then
                task.spawn(function() SafeApply(currentShaderMode) end)
            else
                OceanToken = OceanToken + 1
                StopGuard()
                SetStatus("Turned off (use Clear Shader to revert)")
            end
        end
    })

    local ClearToggle = nil
    ClearToggle = ShaderGroup:AddToggle("ClearShaderToggle", {
        Text = "Clear Shader",
        Default = false,
        Callback = function(Value)
            if not Value then return end
            task.spawn(function()
                pcall(function() ExecuteToggle:SetValue(false) end)
                SafeClear()
                pcall(function() ClearToggle:SetValue(false) end)
            end)
        end
    })

    pcall(function()
        StatusLabel = ShaderGroup:AddLabel("Status: idle", true)
    end)

    ----------------------------------------------------------
    -- [Weather] 눈/비 - Shader Settings 바로 다음(미리보기 옆)
    ----------------------------------------------------------
    ;(function()
        local WeatherPlayers = game:GetService("Players")
        local WeatherRunService = game:GetService("RunService")
        local WeatherWorkspace = game:GetService("Workspace")
        local weatherPlr = WeatherPlayers.LocalPlayer

        local WeatherGroup = ShaderTab:AddLeftGroupbox("Weather", PickIcon({ "cloud-snow", "cloud-rain", "snowflake", "cloud" }))

        local weatherType = "Snow"      -- "Snow" | "Rain"
        local weatherTarget = "World"   -- "World" | "UI" | "World + UI"
        local weatherEnabled = false
        local weatherSpeed = 50         -- 1~100
        local weatherSize = 50          -- 1~100

        local WorldFollower = Instance.new("Part")
        WorldFollower.Name = "Weather8minFollower"
        WorldFollower.Size = Vector3.new(400, 1, 400)
        WorldFollower.Transparency = 1
        WorldFollower.Anchored = true
        WorldFollower.CanCollide = false
        WorldFollower.CanQuery = false
        WorldFollower.CanTouch = false

        local worldEmitter = Instance.new("ParticleEmitter")
        worldEmitter.Name = "Weather8minEmitter"
        worldEmitter.Texture = "rbxasset://textures/particles/smoke_main.dds"
        worldEmitter.EmissionDirection = Enum.NormalId.Bottom
        worldEmitter.Enabled = false
        worldEmitter.LightEmission = 0
        worldEmitter.Transparency = NumberSequence.new(0.2)
        worldEmitter.Parent = WorldFollower

        local worldFollowConn = nil

        local function StartWorldFollow()
            if worldFollowConn then return end
            worldFollowConn = WeatherRunService.Heartbeat:Connect(function()
                local cam = WeatherWorkspace.CurrentCamera
                if cam then
                    WorldFollower.CFrame = CFrame.new(cam.CFrame.Position + Vector3.new(0, 60, 0))
                end
            end)
        end

        local function StopWorldFollow()
            if worldFollowConn then
                worldFollowConn:Disconnect()
                worldFollowConn = nil
            end
        end

        local UIWeatherGui = Instance.new("ScreenGui")
        UIWeatherGui.Name = "Weather8minUI"
        UIWeatherGui.ResetOnSpawn = false
        UIWeatherGui.IgnoreGuiInset = true
        UIWeatherGui.DisplayOrder = 998

        local guiOk = pcall(function() UIWeatherGui.Parent = game:GetService("CoreGui") end)
        if not guiOk then UIWeatherGui.Parent = weatherPlr:WaitForChild("PlayerGui") end

        local UI_PARTICLE_COUNT = 55
        local uiParticles = {}
        local uiConn = nil

        local function MakeUIParticle()
            local f = Instance.new("TextLabel")
            f.BackgroundColor3 = Color3.new(1, 1, 1)
            f.BackgroundTransparency = 0
            f.BorderSizePixel = 0
            f.AnchorPoint = Vector2.new(0.5, 0.5)
            f.Visible = false
            f.Text = ""
            f.TextScaled = true
            f.Font = Enum.Font.SourceSansBold
            f.TextColor3 = Color3.fromRGB(255, 90, 140)
            f.Parent = UIWeatherGui

            local corner = Instance.new("UICorner")
            corner.CornerRadius = UDim.new(1, 0)
            corner.Parent = f

            return f
        end

        for i = 1, UI_PARTICLE_COUNT do
            table.insert(uiParticles, {
                Frame = MakeUIParticle(),
                X = math.random(),
                Y = math.random(),
                Speed = 0.6 + math.random() * 0.8,
                Drift = (math.random() - 0.5),
            })
        end

        local function StyleUIParticlesFor(kind, sizePercent)
            local sizeAlpha = math.clamp(sizePercent, 1, 100) / 100
            for _, p in ipairs(uiParticles) do
                local corner = p.Frame:FindFirstChildOfClass("UICorner")
                if kind == "Snow" then
                    p.Frame.Text = ""
                    p.Frame.BackgroundTransparency = 0.1
                    p.Frame.BackgroundColor3 = Color3.new(1, 1, 1)
                    local s = 3 + sizeAlpha * 7
                    p.Frame.Size = UDim2.new(0, s, 0, s)
                    if corner then corner.CornerRadius = UDim.new(1, 0) end
                elseif kind == "Heart" then
                    p.Frame.BackgroundTransparency = 1
                    p.Frame.Text = "\226\157\164" -- ❤
                    p.Frame.TextColor3 = Color3.fromRGB(255, 90, 140)
                    p.Frame.TextTransparency = 0
                    local s = 10 + sizeAlpha * 18
                    p.Frame.Size = UDim2.new(0, s, 0, s)
                    if corner then corner.CornerRadius = UDim.new(0, 0) end
                else -- Rain
                    p.Frame.Text = ""
                    p.Frame.BackgroundTransparency = 0.25
                    p.Frame.BackgroundColor3 = Color3.fromRGB(190, 210, 255)
                    local w = 1.5 + sizeAlpha * 1.5
                    local h = 10 + sizeAlpha * 14
                    p.Frame.Size = UDim2.new(0, w, 0, h)
                    if corner then corner.CornerRadius = UDim.new(0, 2) end
                end
            end
        end

        local function StartUIWeather(kind, speedPercent, sizePercent)
            StyleUIParticlesFor(kind, sizePercent)
            for _, p in ipairs(uiParticles) do
                p.Frame.Visible = true
            end

            if uiConn then uiConn:Disconnect() end
            uiConn = WeatherRunService.RenderStepped:Connect(function(dt)
                local speedAlpha = math.clamp(speedPercent, 1, 100) / 100
                local fallRate = (kind == "Rain") and (1.1 + speedAlpha * 2.2) or (0.15 + speedAlpha * 0.5)

                for _, p in ipairs(uiParticles) do
                    p.Y = p.Y + fallRate * p.Speed * dt
                    local driftAlpha = (kind == "Snow" or kind == "Heart") and 0.06 or 0.01
                    p.X = p.X + p.Drift * driftAlpha * dt

                    if p.Y > 1.05 then
                        p.Y = -0.05
                        p.X = math.random()
                    end
                    if p.X < -0.05 then p.X = 1.05 elseif p.X > 1.05 then p.X = -0.05 end

                    p.Frame.Position = UDim2.new(p.X, 0, p.Y, 0)
                end
            end)
        end

        local function StopUIWeather()
            if uiConn then
                uiConn:Disconnect()
                uiConn = nil
            end
            for _, p in ipairs(uiParticles) do
                p.Frame.Visible = false
            end
        end

        local function ApplyWorldParams()
            local speedAlpha = math.clamp(weatherSpeed, 1, 100) / 100
            local sizeAlpha = math.clamp(weatherSize, 1, 100) / 100

            if weatherType == "Snow" then
                worldEmitter.Color = ColorSequence.new(Color3.new(1, 1, 1))
                worldEmitter.Rate = 350
                worldEmitter.Lifetime = NumberRange.new(4, 7)
                worldEmitter.Speed = NumberRange.new(4 + speedAlpha * 8, 7 + speedAlpha * 10)
                worldEmitter.Size = NumberSequence.new(0.3 + sizeAlpha * 1.0)
                worldEmitter.RotSpeed = NumberRange.new(-30, 30)
                worldEmitter.Acceleration = Vector3.new(0, -8 - speedAlpha * 6, 0)
                worldEmitter.SpreadAngle = Vector2.new(15, 15)
            else
                worldEmitter.Color = ColorSequence.new(Color3.fromRGB(190, 210, 255))
                worldEmitter.Rate = 700
                worldEmitter.Lifetime = NumberRange.new(1.2, 2)
                worldEmitter.Speed = NumberRange.new(30 + speedAlpha * 40, 45 + speedAlpha * 50)
                worldEmitter.Size = NumberSequence.new(0.15 + sizeAlpha * 0.35)
                worldEmitter.RotSpeed = NumberRange.new(0, 0)
                worldEmitter.Acceleration = Vector3.new(0, -60 - speedAlpha * 40, 0)
                worldEmitter.SpreadAngle = Vector2.new(3, 3)
            end
        end

        ----------------------------------------------------------
        -- [월드 하트] ParticleEmitter는 텍스트를 못 그려서,
        -- BillboardGui(하트 글자)를 단 파트를 눈처럼 떨어뜨림
        ----------------------------------------------------------
        local HEART_COUNT = 180
        local worldHeartParts = {}
        local worldHeartConn = nil

        local function EnsureWorldHeartParts()
            if #worldHeartParts > 0 then return end
            for i = 1, HEART_COUNT do
                local part = Instance.new("Part")
                part.Name = "Weather8minHeart"
                part.Size = Vector3.new(0.2, 0.2, 0.2)
                part.Transparency = 1
                part.Anchored = true
                part.CanCollide = false
                part.CanQuery = false
                part.CanTouch = false
                part.CastShadow = false

                local billboard = Instance.new("BillboardGui")
                billboard.Size = UDim2.new(0, 30, 0, 30)
                billboard.AlwaysOnTop = true
                billboard.Parent = part

                local label = Instance.new("TextLabel")
                label.BackgroundTransparency = 1
                label.Size = UDim2.new(1, 0, 1, 0)
                label.Text = "\226\157\164" -- ❤
                label.TextColor3 = Color3.fromRGB(255, 90, 140)
                label.TextScaled = true
                label.Font = Enum.Font.SourceSansBold
                label.Parent = billboard

                table.insert(worldHeartParts, {
                    Part = part,
                    OffsetX = (math.random() - 0.5) * 80,
                    OffsetZ = (math.random() - 0.5) * 80,
                    Height = math.random() * 60,
                })
            end
        end

        local function StartWorldHearts()
            EnsureWorldHeartParts()
            for _, h in ipairs(worldHeartParts) do
                h.Part.Parent = WeatherWorkspace
            end
            if worldHeartConn then return end
            worldHeartConn = WeatherRunService.Heartbeat:Connect(function(dt)
                local speedAlpha = math.clamp(weatherSpeed, 1, 100) / 100
                local sizeAlpha = math.clamp(weatherSize, 1, 100) / 100
                local fallSpeed = 4 + speedAlpha * 10
                local cam = WeatherWorkspace.CurrentCamera
                if not cam then return end
                for _, h in ipairs(worldHeartParts) do
                    h.Height = h.Height - fallSpeed * dt
                    if h.Height < -5 then
                        h.Height = 55
                        h.OffsetX = (math.random() - 0.5) * 80
                        h.OffsetZ = (math.random() - 0.5) * 80
                    end
                    h.Part.CFrame = CFrame.new(cam.CFrame.Position + Vector3.new(h.OffsetX, h.Height - 10, h.OffsetZ))
                    local bb = h.Part:FindFirstChildOfClass("BillboardGui")
                    if bb then
                        local s = 20 + sizeAlpha * 25
                        bb.Size = UDim2.new(0, s, 0, s)
                    end
                end
            end)
        end

        local function StopWorldHearts()
            if worldHeartConn then
                worldHeartConn:Disconnect()
                worldHeartConn = nil
            end
            for _, h in ipairs(worldHeartParts) do
                if h.Part then h.Part.Parent = nil end
            end
        end

        local function RefreshWeather()
            if not weatherEnabled then return end

            local wantsWorld = (weatherTarget == "World" or weatherTarget == "World + UI")

            if weatherType == "Heart" then
                worldEmitter.Enabled = false
                StopWorldFollow()
                if wantsWorld then
                    StartWorldHearts()
                else
                    StopWorldHearts()
                end
            else
                StopWorldHearts()
                if wantsWorld then
                    if WorldFollower.Parent == nil then WorldFollower.Parent = WeatherWorkspace end
                    ApplyWorldParams()
                    worldEmitter.Enabled = true
                    StartWorldFollow()
                else
                    worldEmitter.Enabled = false
                    StopWorldFollow()
                end
            end

            if weatherTarget == "UI" or weatherTarget == "World + UI" then
                StartUIWeather(weatherType, weatherSpeed, weatherSize)
            else
                StopUIWeather()
            end
        end

        local function StopAllWeather()
            worldEmitter.Enabled = false
            StopWorldFollow()
            StopWorldHearts()
            StopUIWeather()
        end

        ----------------------------------------------------------
        -- [네온 테두리] 토글로 켜고 끄기
        ----------------------------------------------------------
        local neonGlowStroke, neonLineStroke = nil, nil
        local neonConn = nil

        local cachedNeonRoots = nil -- 한 번 찾으면 재사용 (매번 전체 스캔하면 렉 생김)

        local function FindWindowRoots()
            if cachedNeonRoots then
                return cachedNeonRoots, "cache"
            end

            -- 1차: 라이브러리 내부 속성 이름 추측 (있으면 바로 사용)
            local guesses = {}
            pcall(function() table.insert(guesses, Window.Holder) end)
            pcall(function() table.insert(guesses, Window.Root) end)
            pcall(function() table.insert(guesses, Window.Main) end)
            pcall(function() table.insert(guesses, Window.Frame) end)
            pcall(function() table.insert(guesses, Window.Container) end)
            pcall(function() table.insert(guesses, Window.Background) end)
            pcall(function() table.insert(guesses, Window.Instance) end)
            pcall(function() table.insert(guesses, Window.Gui) end)
            for _, g in ipairs(guesses) do
                if typeof(g) == "Instance" and g:IsA("GuiObject") then
                    cachedNeonRoots = { g }
                    return cachedNeonRoots, "guess"
                end
            end

            -- 2차(안전망): GetDescendants()로 전체를 훑으면(특히 CoreGui) 렉이 생길 수 있어서,
            -- 각 ScreenGui 바로 밑 2단계까지만(얕게) 확인함
            local candidates = {}

            local function checkObj(obj)
                if obj:IsA("GuiObject") and not obj:IsA("UIStroke") then
                    local ok, sz = pcall(function() return obj.AbsoluteSize end)
                    if ok and sz.X > 250 and sz.Y > 150 then
                        table.insert(candidates, obj)
                    end
                end
            end

            local function shallowScan(container)
                if not container then return end
                pcall(function()
                    for _, screenGui in ipairs(container:GetChildren()) do
                        if screenGui:IsA("ScreenGui") or screenGui:IsA("Folder") then
                            for _, lvl1 in ipairs(screenGui:GetChildren()) do
                                checkObj(lvl1)
                                if lvl1:IsA("GuiObject") then
                                    for _, lvl2 in ipairs(lvl1:GetChildren()) do
                                        checkObj(lvl2)
                                    end
                                end
                            end
                        end
                    end
                end)
            end

            pcall(function() shallowScan(weatherPlr:FindFirstChildOfClass("PlayerGui")) end)
            if #candidates == 0 then
                pcall(function() shallowScan(game:GetService("CoreGui")) end)
            end

            table.sort(candidates, function(a, b)
                return (a.AbsoluteSize.X * a.AbsoluteSize.Y) > (b.AbsoluteSize.X * b.AbsoluteSize.Y)
            end)

            -- 너무 많이 꾸미지 않도록 제일 큰 것 3개까지만
            local top = {}
            for i = 1, math.min(3, #candidates) do
                table.insert(top, candidates[i])
            end

            cachedNeonRoots = top
            return top, "scan"
        end

        local function StartNeonBorder()
            if neonConn then return end
            local roots, how = FindWindowRoots()
            if #roots == 0 then
                SetStatus("Neon: no window frame found")
                return
            end

            neonGlowStroke = {}
            neonLineStroke = {}
            for _, root in ipairs(roots) do
                local glow = Instance.new("UIStroke")
                glow.Name = "NeonGlowOuter"
                glow.Thickness = 8
                glow.Transparency = 0.45
                glow.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
                glow.LineJoinMode = Enum.LineJoinMode.Round
                glow.Parent = root
                table.insert(neonGlowStroke, glow)

                local line = Instance.new("UIStroke")
                line.Name = "NeonGlowInner"
                line.Thickness = 2
                line.Transparency = 0
                line.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
                line.LineJoinMode = Enum.LineJoinMode.Round
                line.Parent = root
                table.insert(neonLineStroke, line)
            end

            SetStatus("Neon: applied (" .. how .. ", " .. #roots .. " panel(s))")

            local hue = 0.92
            neonConn = WeatherRunService.Heartbeat:Connect(function(dt)
                hue = (hue + dt * 0.08) % 1
                local color = Color3.fromHSV(hue, 0.85, 1)
                for _, s in ipairs(neonLineStroke) do s.Color = color end
                for _, s in ipairs(neonGlowStroke) do s.Color = color end
            end)
        end

        local function StopNeonBorder()
            if neonConn then
                neonConn:Disconnect()
                neonConn = nil
            end
            if neonGlowStroke then
                for _, s in ipairs(neonGlowStroke) do pcall(function() s:Destroy() end) end
            end
            if neonLineStroke then
                for _, s in ipairs(neonLineStroke) do pcall(function() s:Destroy() end) end
            end
            neonGlowStroke, neonLineStroke = nil, nil
        end

        WeatherGroup:AddDropdown("WeatherType", {
            Text = "Weather Type",
            Values = { "Snow", "Rain", "Heart" },
            Default = 1,
            Callback = function(Value)
                weatherType = Value
                RefreshWeather()
            end
        })

        WeatherGroup:AddDropdown("WeatherTarget", {
            Text = "Apply To",
            Values = { "World", "UI", "World + UI" },
            Default = 1,
            Callback = function(Value)
                weatherTarget = Value
                RefreshWeather()
            end
        })

        WeatherGroup:AddToggle("WeatherEnabled", {
            Text = "Enable Weather",
            Default = false,
            Callback = function(Value)
                weatherEnabled = Value
                if Value then
                    RefreshWeather()
                else
                    StopAllWeather()
                end
            end
        })

        WeatherGroup:AddSlider("WeatherSpeed", {
            Text = "Weather Speed",
            Default = 50,
            Min = 1,
            Max = 100,
            Rounding = 0,
            Callback = function(Value)
                weatherSpeed = Value
                RefreshWeather()
            end
        })

        WeatherGroup:AddSlider("WeatherSize", {
            Text = "Weather Size",
            Default = 50,
            Min = 1,
            Max = 100,
            Rounding = 0,
            Callback = function(Value)
                weatherSize = Value
                RefreshWeather()
            end
        })

        WeatherGroup:AddToggle("NeonBorderToggle", {
            Text = "Neon Border",
            Default = false,
            Callback = function(Value)
                if Value then StartNeonBorder() else StopNeonBorder() end
            end
        })
    end)()

    ----------------------------------------------------------
    -- [쉐이더 조명] - 드롭다운(색 선택) + 슬라이더(세기 조절)
    ----------------------------------------------------------
    local LightingColorGroup = ShaderTab:AddRightGroupbox("Shader Lighting", PickIcon({ "sun", "lightbulb", "lamp" }))

    local ColorPresets = {
        ["Red"] = Color3.fromRGB(255, 60, 60),
        ["Yellow"] = Color3.fromRGB(255, 235, 60),
        ["Orange"] = Color3.fromRGB(255, 150, 40),
        ["Sky Blue"] = Color3.fromRGB(120, 210, 255),
        ["Blue"] = Color3.fromRGB(60, 120, 255),
        ["Navy"]   = Color3.fromRGB(40, 50, 160),
        ["Purple"] = Color3.fromRGB(160, 70, 220),
        ["Black"] = Color3.fromRGB(10, 10, 10),
        ["Gray"] = Color3.fromRGB(150, 150, 150),
        ["White"] = Color3.fromRGB(255, 255, 255),
    }

    local LightColorList = {
        "Red", "Yellow", "Orange", "Sky Blue", "Blue",
        "Navy", "Purple", "Black", "Gray", "White",
    }

    local currentLightColor = LightColorList[1]
    local currentLightIntensity = 50 -- 0~100 (%)

    local function GetOrMakeColorCorrection()
        local cc = Lighting:FindFirstChild("UIToggleColorCorrection")
        if not cc then
            cc = Instance.new("ColorCorrectionEffect")
            cc.Name = "UIToggleColorCorrection"
            cc.Parent = Lighting
        end
        return cc
    end

    local function ApplyLightColor()
        pcall(function()
            local target = ColorPresets[currentLightColor]
            if not target then return end
            local cc = GetOrMakeColorCorrection()
            local alpha = currentLightIntensity / 100
            -- 세기 0% = 흰색(효과 없음), 100% = 선택한 색이 완전히
            cc.TintColor = Color3.new(1, 1, 1):Lerp(target, alpha)
            cc.Saturation = alpha * 0.4
            cc.Brightness = (alpha * 0.3) - 0.15 -- lets Black/White presets darken or brighten the scene
            SetStatus(currentLightColor .. " light (" .. currentLightIntensity .. "%)")
        end)
    end

    LightingColorGroup:AddDropdown("LightColorMode", {
        Text = "Select Light Color",
        Values = LightColorList,
        Default = 1,
        Callback = function(Value)
            currentLightColor = Value
            ApplyLightColor()
        end
    })

    LightingColorGroup:AddSlider("LightIntensity", {
        Text = "Light Intensity",
        Default = 50,
        Min = 0,
        Max = 100,
        Rounding = 0,
        Callback = function(Value)
            currentLightIntensity = Value
            ApplyLightColor()
        end
    })

    LightingColorGroup:AddButton({
        Text = "Light Color On",
        Func = function()
            ApplyLightColor()
        end
    })

    LightingColorGroup:AddButton({
        Text = "Light Color Off",
        Func = function()
            pcall(function()
                local cc = Lighting:FindFirstChild("UIToggleColorCorrection")
                if cc then
                    cc.TintColor = Color3.new(1, 1, 1)
                    cc.Saturation = 0
                    cc.Brightness = 0
                end
                SetStatus("Light color off")
            end)
        end
    })

    ----------------------------------------------------------
    -- [Ocean Color] - Shader Lighting 바로 아래
    ----------------------------------------------------------
    local OceanColorGroup = ShaderTab:AddRightGroupbox("Ocean Color", PickIcon({ "waves", "droplets", "droplet", "palette" }))

    local OceanColorPresets = {
        ["Red"] = Color3.fromRGB(200, 40, 40),
        ["Orange"] = Color3.fromRGB(220, 120, 30),
        ["Yellow"] = Color3.fromRGB(210, 190, 40),
        ["Green"] = Color3.fromRGB(30, 160, 90),
        ["Blue"] = Color3.fromRGB(0, 100, 200),
        ["Navy"] = Color3.fromRGB(10, 30, 90),
        ["Purple"] = Color3.fromRGB(120, 50, 170),
        ["White"] = Color3.fromRGB(230, 235, 240),
        ["Black"] = Color3.fromRGB(10, 10, 12),
        ["Pink"] = Color3.fromRGB(230, 110, 170),
    }
    local OceanColorList = {
        "Red", "Orange", "Yellow", "Green", "Blue",
        "Navy", "Purple", "White", "Black", "Pink",
    }
    local currentOceanColor = OceanColorList[1]

    local oceanColorReady = false -- 라이브러리가 시작할 때 부르는 콜백으로 바로 색이 바뀌는 걸 막음
    task.delay(1, function() oceanColorReady = true end)

    local function ApplyOceanColor()
        pcall(function()
            local color = OceanColorPresets[currentOceanColor]
            if not color then return end
            OceanColorOverride = color
            Terrain.WaterColor = color      -- Terrain 물 (Execute Shader 를 켰을 때 보이는 바다)
            TintOldOcean(color)             -- 게임 원래 바다 모델
            SetStatus("Ocean color: " .. currentOceanColor)
        end)
    end

    -- 게임이나 쉐이더가 물 색을 되돌리면 다시 덮어씀
    Terrain:GetPropertyChangedSignal("WaterColor"):Connect(function()
        if OceanColorOverride and Terrain.WaterColor ~= OceanColorOverride then
            Terrain.WaterColor = OceanColorOverride
        end
    end)

    OceanColorGroup:AddDropdown("OceanColorMode", {
        Text = "Select Ocean Color",
        Values = OceanColorList,
        Default = 1,
        Callback = function(Value)
            currentOceanColor = Value
            if oceanColorReady then ApplyOceanColor() end
        end
    })

    OceanColorGroup:AddButton({
        Text = "Apply Ocean Color",
        Func = function()
            ApplyOceanColor()
        end
    })
end)()

-- ==========================================================
-- [Shader 탭] Forest - 에셋 ID로 나무를 불러와 주변에 심기
-- ==========================================================
;(function()
    local Players = game:GetService("Players")
    local Workspace = game:GetService("Workspace")
    local plr = Players.LocalPlayer

    local TREE_ASSET_ID = 17093918340

    local ForestGroup = Tabs.Shader:AddLeftGroupbox("Forest", PickIcon({ "trees", "tree-pine", "tree-deciduous", "leaf" }))

    local treeCount = 30
    local forestRadius = 150
    local treeScale = 1
    local templateModel = nil
    local forestFolder = nil
    local forestToken = 0

    local function Notify(text)
        pcall(function() Library:Notify(text, 4) end)
    end

    local function LoadTemplate()
        if templateModel then return templateModel end
        local obj = nil

        -- 1순위: 실행기에서 흔히 되는 방식
        pcall(function()
            local objects = game:GetObjects("rbxassetid://" .. TREE_ASSET_ID)
            obj = objects and objects[1]
        end)

        -- 2순위: InsertService
        if not obj then
            pcall(function()
                local container = game:GetService("InsertService"):LoadAsset(TREE_ASSET_ID)
                obj = container and container:GetChildren()[1]
            end)
        end

        templateModel = obj
        return obj
    end

    local function RemoveForest()
        forestToken = forestToken + 1
        if forestFolder then
            pcall(function() forestFolder:Destroy() end)
            forestFolder = nil
        end
    end

    local function GroundY(x, z, ignore)
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = ignore
        local origin = Vector3.new(x, 500, z)
        local result = Workspace:Raycast(origin, Vector3.new(0, -1000, 0), params)
        if result then return result.Position.Y end
        return nil
    end

    local function SpawnForest()
        RemoveForest()
        local myToken = forestToken

        local template = LoadTemplate()
        if not template then
            Notify("Forest: tree asset could not be loaded")
            return
        end

        local char = plr.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not root then
            Notify("Forest: character not found")
            return
        end

        forestFolder = Instance.new("Folder")
        forestFolder.Name = "Forest8min"
        forestFolder.Parent = Workspace

        local center = root.Position
        local placed = 0

        for i = 1, treeCount do
            if myToken ~= forestToken then return end

            local angle = math.random() * math.pi * 2
            local dist = math.sqrt(math.random()) * forestRadius
            local x = center.X + math.cos(angle) * dist
            local z = center.Z + math.sin(angle) * dist

            local y = GroundY(x, z, { forestFolder, char })
            if y then
                local tree = template:Clone()
                pcall(function()
                    if tree:IsA("Model") then
                        tree:ScaleTo(treeScale * (0.8 + math.random() * 0.5))
                    end
                end)
                for _, d in ipairs(tree:GetDescendants()) do
                    if d:IsA("BasePart") then
                        d.Anchored = true
                    end
                end
                tree.Parent = forestFolder
                pcall(function()
                    if tree:IsA("Model") then
                        tree:PivotTo(CFrame.new(x, y, z) * CFrame.Angles(0, math.random() * math.pi * 2, 0))
                    end
                end)
                placed = placed + 1
            end

            if i % 5 == 0 then task.wait() end
        end

        Notify("Forest: placed " .. placed .. " trees")
    end

    ForestGroup:AddToggle("ForestEnabled", {
        Text = "Spawn Forest",
        Default = false,
        Callback = function(Value)
            if Value then
                task.spawn(SpawnForest)
            else
                RemoveForest()
            end
        end
    })

    ForestGroup:AddSlider("ForestTreeCount", {
        Text = "Tree Count",
        Default = 30,
        Min = 5,
        Max = 200,
        Rounding = 0,
        Callback = function(Value)
            treeCount = Value
        end
    })

    ForestGroup:AddSlider("ForestRadius", {
        Text = "Forest Radius",
        Default = 150,
        Min = 30,
        Max = 500,
        Rounding = 0,
        Callback = function(Value)
            forestRadius = Value
        end
    })

    ForestGroup:AddSlider("ForestTreeScale", {
        Text = "Tree Size",
        Default = 10,
        Min = 1,
        Max = 30,
        Rounding = 0,
        Callback = function(Value)
            treeScale = Value / 10
        end
    })

    ForestGroup:AddButton({
        Text = "Respawn Forest",
        Func = function()
            task.spawn(SpawnForest)
        end
    })

    ForestGroup:AddButton({
        Text = "Remove Forest",
        Func = function()
            RemoveForest()
        end
    })
end)()

-- ==========================================================
-- [Shader 탭] Realistic Lighting - 시간대별 하늘/조명 프리셋
-- (깨끗하게 새로 작성한 버전, 원본 코드 복사 아님)
-- ==========================================================
;(function()
    local Lighting = game:GetService("Lighting")
    local Terrain = workspace:FindFirstChildOfClass("Terrain")

    local ShaderTab = Tabs.Shader
    local RLGroup = ShaderTab:AddRightGroupbox("Realistic Lighting", PickIcon({ "sunset", "sun-medium", "sun" }))

    ----------------------------------------------------------
    -- 원래 상태 저장 (끄면 이걸로 복구)
    ----------------------------------------------------------
    local RL_Original = {
        Brightness = Lighting.Brightness,
        Exposure = Lighting.ExposureCompensation,
        ClockTime = Lighting.ClockTime,
        OutdoorAmbient = Lighting.OutdoorAmbient,
        Ambient = Lighting.Ambient,
        FogColor = Lighting.FogColor,
        FogStart = Lighting.FogStart,
        FogEnd = Lighting.FogEnd,
        ShadowSoftness = Lighting.ShadowSoftness,
        GlobalShadows = Lighting.GlobalShadows,
    }
    local RL_OriginalSky = nil
    pcall(function()
        local sky = Lighting:FindFirstChildOfClass("Sky")
        if sky then RL_OriginalSky = sky:Clone() end
    end)
    local RL_OriginalCloud = nil
    local RL_Clouds = Terrain and Terrain:FindFirstChildOfClass("Clouds")
    if RL_Clouds then
        RL_OriginalCloud = { Cover = RL_Clouds.Cover, Density = RL_Clouds.Density }
    end

    ----------------------------------------------------------
    -- 프리셋 (시간대별 느낌)
    ----------------------------------------------------------
    local RL_Presets = {
        Morning   = { time = 7,  brightness = 2.2, exposure = 0.2, ambient = Color3.fromRGB(150, 150, 160), outdoor = Color3.fromRGB(180, 175, 190), fogColor = Color3.fromRGB(210, 215, 230) },
        Midday    = { time = 12, brightness = 3.0, exposure = 0.3, ambient = Color3.fromRGB(170, 170, 170), outdoor = Color3.fromRGB(200, 200, 200), fogColor = Color3.fromRGB(220, 225, 235) },
        Afternoon = { time = 15, brightness = 2.6, exposure = 0.25, ambient = Color3.fromRGB(160, 150, 140), outdoor = Color3.fromRGB(195, 180, 160), fogColor = Color3.fromRGB(215, 205, 190) },
        Evening   = { time = 18, brightness = 1.6, exposure = 0.15, ambient = Color3.fromRGB(120, 95, 90), outdoor = Color3.fromRGB(190, 140, 110), fogColor = Color3.fromRGB(200, 150, 130) },
        Night     = { time = 21, brightness = 0.6, exposure = 0.05, ambient = Color3.fromRGB(40, 45, 70), outdoor = Color3.fromRGB(45, 50, 80), fogColor = Color3.fromRGB(20, 22, 40) },
        Midnight  = { time = 0,  brightness = 0.3, exposure = 0.0, ambient = Color3.fromRGB(20, 22, 40), outdoor = Color3.fromRGB(20, 22, 45), fogColor = Color3.fromRGB(8, 9, 18) },
    }
    local RL_PresetOrder = { "Morning", "Midday", "Afternoon", "Evening", "Night", "Midnight" }

    ----------------------------------------------------------
    -- 상태
    ----------------------------------------------------------
    local RL_Enabled = false
    local RL_SelectedPreset = "Morning"
    local RL_BloomObj, RL_ColorCorrectionObj, RL_AtmosphereObj, RL_SkyObj = nil, nil, nil, nil

    -- 슬라이더로 덮어쓸 수 있는 값 (nil이면 프리셋 값 사용)
    local RL_Override = {
        Brightness = nil,
        Exposure = nil,
        BloomIntensity = 0.15,
        Saturation = 0.0,
        SunSize = 12,
        SunRays = 0.05,
        FogEnd = 1500,
        FogStart = 0,
        ShadowSoftness = 0.2,
        CloudDensity = nil,
        CloudCover = nil,
    }

    local function RL_RemoveOwnedEffects()
        for _, obj in ipairs({ RL_BloomObj, RL_ColorCorrectionObj, RL_AtmosphereObj, RL_SkyObj }) do
            if obj then pcall(function() obj:Destroy() end) end
        end
        RL_BloomObj, RL_ColorCorrectionObj, RL_AtmosphereObj, RL_SkyObj = nil, nil, nil, nil
    end

    local function RL_Apply()
        if not RL_Enabled then return end
        local preset = RL_Presets[RL_SelectedPreset] or RL_Presets.Morning

        Lighting.ClockTime = preset.time
        Lighting.Brightness = RL_Override.Brightness or preset.brightness
        Lighting.ExposureCompensation = RL_Override.Exposure or preset.exposure
        Lighting.OutdoorAmbient = preset.outdoor
        Lighting.Ambient = preset.ambient
        Lighting.FogColor = preset.fogColor
        Lighting.FogStart = RL_Override.FogStart
        Lighting.FogEnd = RL_Override.FogEnd
        Lighting.ShadowSoftness = RL_Override.ShadowSoftness
        Lighting.GlobalShadows = true

        RL_RemoveOwnedEffects()

        local bloom = Instance.new("BloomEffect")
        bloom.Name = "RealisticLightingBloom"
        bloom.Intensity = RL_Override.BloomIntensity
        bloom.Threshold = 1.2
        bloom.Size = 24
        bloom.Parent = Lighting
        RL_BloomObj = bloom

        local cc = Instance.new("ColorCorrectionEffect")
        cc.Name = "RealisticLightingColorCorrection"
        cc.Saturation = RL_Override.Saturation
        cc.Parent = Lighting
        RL_ColorCorrectionObj = cc

        local atmosphere = Instance.new("Atmosphere")
        atmosphere.Name = "RealisticLightingAtmosphere"
        atmosphere.Density = 0.3
        atmosphere.Offset = 0.25
        atmosphere.Glare = 0.2
        atmosphere.Haze = 1.2
        atmosphere.Parent = Lighting
        RL_AtmosphereObj = atmosphere

        local existingSky = Lighting:FindFirstChildOfClass("Sky")
        if existingSky then existingSky:Destroy() end

        local sky = Instance.new("Sky")
        sky.Name = "RealisticLightingSky"
        sky.SkyboxUp = "rbxassetid://323493360"
        sky.SkyboxLf = "rbxassetid://323494252"
        sky.SkyboxBk = "rbxassetid://323494035"
        sky.SkyboxFt = "rbxassetid://323494130"
        sky.SkyboxDn = "rbxassetid://323494368"
        sky.SkyboxRt = "rbxassetid://323494067"
        sky.SunAngularSize = RL_Override.SunSize
        sky.Parent = Lighting
        RL_SkyObj = sky

        if RL_Clouds then
            if RL_Override.CloudDensity then RL_Clouds.Density = RL_Override.CloudDensity end
            if RL_Override.CloudCover then RL_Clouds.Cover = RL_Override.CloudCover end
        end
    end

    local function RL_Reset()
        RL_RemoveOwnedEffects()
        Lighting.Brightness = RL_Original.Brightness
        Lighting.ExposureCompensation = RL_Original.Exposure
        Lighting.ClockTime = RL_Original.ClockTime
        Lighting.OutdoorAmbient = RL_Original.OutdoorAmbient
        Lighting.Ambient = RL_Original.Ambient
        Lighting.FogColor = RL_Original.FogColor
        Lighting.FogStart = RL_Original.FogStart
        Lighting.FogEnd = RL_Original.FogEnd
        Lighting.ShadowSoftness = RL_Original.ShadowSoftness
        Lighting.GlobalShadows = RL_Original.GlobalShadows

        if RL_OriginalSky then
            local currentSky = Lighting:FindFirstChildOfClass("Sky")
            if currentSky then currentSky:Destroy() end
            RL_OriginalSky:Clone().Parent = Lighting
        end

        if RL_Clouds and RL_OriginalCloud then
            RL_Clouds.Cover = RL_OriginalCloud.Cover
            RL_Clouds.Density = RL_OriginalCloud.Density
        end
    end

    ----------------------------------------------------------
    -- UI
    ----------------------------------------------------------
    RLGroup:AddDropdown("RealisticLightingPreset", {
        Text = "Time of Day",
        Values = RL_PresetOrder,
        Default = 1,
        Callback = function(Value)
            RL_SelectedPreset = Value
            RL_Apply()
        end
    })

    RLGroup:AddToggle("RealisticLightingEnabled", {
        Text = "Enable Realistic Lighting",
        Default = false,
        Callback = function(Value)
            RL_Enabled = Value
            if Value then RL_Apply() else RL_Reset() end
        end
    })

    RLGroup:AddSlider("RealisticLightingBrightness", {
        Text = "Brightness", Default = 50, Min = 0, Max = 100, Rounding = 0,
        Callback = function(Value)
            RL_Override.Brightness = (Value / 100) * 6
            RL_Apply()
        end
    })

    RLGroup:AddSlider("RealisticLightingExposure", {
        Text = "Exposure", Default = 20, Min = 0, Max = 100, Rounding = 0,
        Callback = function(Value)
            RL_Override.Exposure = (Value / 100) * 1
            RL_Apply()
        end
    })

    RLGroup:AddSlider("RealisticLightingBloom", {
        Text = "Bloom Intensity", Default = 15, Min = 0, Max = 100, Rounding = 0,
        Callback = function(Value)
            RL_Override.BloomIntensity = (Value / 100) * 2
            RL_Apply()
        end
    })

    RLGroup:AddSlider("RealisticLightingSaturation", {
        Text = "Saturation", Default = 50, Min = 0, Max = 100, Rounding = 0,
        Callback = function(Value)
            RL_Override.Saturation = ((Value - 50) / 50) -- -1 ~ 1
            RL_Apply()
        end
    })

    RLGroup:AddSlider("RealisticLightingSunSize", {
        Text = "Sun Size", Default = 20, Min = 0, Max = 100, Rounding = 0,
        Callback = function(Value)
            RL_Override.SunSize = (Value / 100) * 40
            RL_Apply()
        end
    })

    RLGroup:AddSlider("RealisticLightingFog", {
        Text = "Fog Distance", Default = 50, Min = 1, Max = 100, Rounding = 0,
        Callback = function(Value)
            RL_Override.FogEnd = 300 + (Value / 100) * 4700
            RL_Apply()
        end
    })

    RLGroup:AddSlider("RealisticLightingShadow", {
        Text = "Shadow Softness", Default = 20, Min = 0, Max = 100, Rounding = 0,
        Callback = function(Value)
            RL_Override.ShadowSoftness = Value / 100
            RL_Apply()
        end
    })

    if RL_Clouds then
        RLGroup:AddSlider("RealisticLightingCloudDensity", {
            Text = "Cloud Density", Default = 50, Min = 0, Max = 100, Rounding = 0,
            Callback = function(Value)
                RL_Override.CloudDensity = Value / 100
                RL_Apply()
            end
        })
        RLGroup:AddSlider("RealisticLightingCloudCover", {
            Text = "Cloud Cover", Default = 50, Min = 0, Max = 100, Rounding = 0,
            Callback = function(Value)
                RL_Override.CloudCover = Value / 100
                RL_Apply()
            end
        })
    end
end)()

-- ==========================================================
-- [Music 탭] 자체 완결형 (Tabs.Music 만 있으면 동작)
-- ==========================================================
;(function()
    local Players = game:GetService("Players")
    local SoundService = game:GetService("SoundService")
    local plr = Players.LocalPlayer

    local MusicTab = Tabs.Music
    local MusicGroup = MusicTab:AddRightGroupbox("Music Player", PickIcon({ "music", "music-2", "headphones" }))

    ----------------------------------------------------------
    -- 재생 목록 (이름 = SoundId). 원하는 곡의 rbxassetid로 교체하세요.
    -- 예: ["내 노래"] = "rbxassetid://1234567890",
    ----------------------------------------------------------
    local Tracks = {
        ["Track 1"] = "rbxassetid://1836795796",
        ["Track 2"] = "rbxassetid://112958080870893",
        ["Track 3"] = "rbxassetid://84788905950545",
        ["Track 4"] = "rbxassetid://131132606860411",
        ["Track 5"] = "rbxassetid://120831336003196",
        ["My Upload"] = "rbxassetid://127517345261179",
        ["Track 6"] = "rbxassetid://113569041065798",
        ["Track 7"] = "rbxassetid://78940023629847",
        ["Track 8"] = "rbxassetid://70463369953060",
        ["Track 9"] = "rbxassetid://81795177334107",
        ["Track 10"] = "rbxassetid://114058489248277",
        ["Track 11"] = "rbxassetid://99432323445876",
        ["Track 12"] = "rbxassetid://129192240417969",
        ["Track 13"] = "rbxassetid://93479068595609",
        ["Track 14"] = "rbxassetid://125264227638318",
    }

    local TrackList = {
        "Track 1", "Track 2", "Track 3", "Track 4", "Track 5", "My Upload",
        "Track 6", "Track 7", "Track 8", "Track 9", "Track 10",
        "Track 11", "Track 12", "Track 13", "Track 14",
    }
    local currentTrack = TrackList[1]

    ----------------------------------------------------------
    -- Sound 인스턴스 (하나만 만들어서 재사용)
    ----------------------------------------------------------
    local sound = Instance.new("Sound")
    sound.Name = "8minHubMusic"
    sound.Looped = true
    sound.Volume = 0.5
    sound.SoundId = Tracks[currentTrack]
    sound.Parent = SoundService

    local StatusLabel = nil
    local function SetStatus(text)
        if StatusLabel then
            pcall(function() StatusLabel:SetText("Status: " .. tostring(text)) end)
        end
    end

    local ContentProvider = game:GetService("ContentProvider")
    local playToken = 0

    local function PlayTrack(name)
        local id = Tracks[name]
        if not id or id == "rbxassetid://0" then
            SetStatus(name .. " : SoundId is still empty")
            return
        end

        playToken = playToken + 1
        local myToken = playToken

        sound:Stop()
        sound.SoundId = id
        sound:Play()
        SetStatus("Playing: " .. name)

        task.spawn(function()
            -- 실제로 재생 위치가 움직이는지 확인해서, 안 움직이면(=소리 안 남) 알려줌
            task.wait(1.5)
            if myToken ~= playToken then return end
            local p1 = sound.TimePosition
            task.wait(1)
            if myToken ~= playToken then return end
            local p2 = sound.TimePosition

            if p2 <= p1 then
                SetStatus(name .. " : does not seem to be playing (check volume/permissions)")
            end
        end)
    end

    ----------------------------------------------------------
    -- UI
    ----------------------------------------------------------
    MusicGroup:AddDropdown("MusicTrack", {
        Text = "Select Track",
        Values = TrackList,
        Default = 1,
        Callback = function(Value)
            currentTrack = Value
            if sound.IsPlaying then
                PlayTrack(Value)
            end
        end
    })

    MusicGroup:AddToggle("MusicPlayToggle", {
        Text = "Play",
        Default = false,
        Callback = function(Value)
            if Value then
                PlayTrack(currentTrack)
            else
                sound:Stop()
                SetStatus("Stopped")
            end
        end
    })

    MusicGroup:AddToggle("MusicLoopToggle", {
        Text = "Loop",
        Default = true,
        Callback = function(Value)
            sound.Looped = Value
        end
    })

    MusicGroup:AddSlider("MusicVolume", {
        Text = "Volume",
        Default = 50,
        Min = 0,
        Max = 100,
        Rounding = 0,
        Callback = function(Value)
            sound.Volume = Value / 100
        end
    })

    pcall(function()
        StatusLabel = MusicGroup:AddLabel("Status: Idle", true)
    end)
end)()


--=============================================
-- =====================================================================
-- [Target 탭 + Miscellaneous + Anti Network Ownership]  (레퍼런스 허브에서 이식)
-- 이 블록은 자체 완결형: 자기만의 H / settings / state 를 안에서 새로 만들어 기존 코드와 충돌하지 않음
-- =====================================================================
;(function()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local PhysicsService = game:GetService("PhysicsService")
local LocalPlayer = Players.LocalPlayer
local Mouse = LocalPlayer:GetMouse()
local H = {}
local settings = {
    CounterMethod = "Kill",
    TargetedLimbCA = "All",
    AntiLagSens = 3,
    AGType = "Normal",
    GucciType = "CreatureBlobman",
    AntiInputType = "FoodHamburger",
    InputLgDelay = 0.05,
    AILTransparency = 1,
    NKOffset = 15,
    NKDelayMode = "Slower but better",
}

local runtimeFlags = {
    AntiGrab = false,
    GucciAntiGrab = false,
    AntiBlobman = false,
    AntiInputLag = false,
    AntiExplosion = false,
    AntiBurn = false,
    AntiVoid = false,
    AntiKick = false,
    AntiKick2 = false,
    AntiSticky = false,
    AntiSnowball = false,
    AntiBanana = false,
    AntiPaint = false,
    AntiPoison = false,
    AntiLag = false,
    AutoAntiLag = true,
    AntiInvis = false,
    AutoReset = true,
    LoopTP = false,
    DestroyVoid = true,
    WaterWalk = false,
    DeleteBarriers = false,
    OtherInvCollisions = false,
    CounterAttack = false,
    LoopApplyMethodT = false,
    LoopApplyMethodTServer = false,
    RagdollInNK = true,
    RagdollInRG = false,
    DeleteShurInNK = true,
}
local state = {
    SelectedPlayers = {},
    TargetMethods = {},
    Whitelisted = {},
    PlayerDropdowns = {},
    WhoGrabbed = nil,
    KickFlags = 0,
    LastKickFlagTime = 0,
    States = {
        Owning = false,
        Spawning = false,
        Ragdolling = false,
        Escaping = false,
    },
    BrokenPlots = {},
    FailedToys = {},
    GrabbableParts = setmetatable({}, {__mode = "k"}),

    LimbOffsetsRL = {
        Head = CFrame.new(0, 1.5, 0),
        ["Left Arm"] = CFrame.new(-1.5, 0, 0),
        ["Right Arm"] = CFrame.new(1.5, 0, 0),
        ["Left Leg"] = CFrame.new(-0.5, -2, 0),
        ["Right Leg"] = CFrame.new(0.5, -2, 0),
        Torso = CFrame.new(),
    },
    NetworkKickQueue = {},
    DestroyThread = nil,
    AKType = "Shuriken",
    AntiKickSettings = {
        Highlight = false,
        HighlightFill = Color3.new(1, 0, 0),
        HighlightOutl = Color3.new(1, 1, 1),
        HighlightFT = 0.5,
        HighlightOT = 0,
        Transparency = 0.9,
    },
}

local adapters = {}
local activeConnections: {[string]: any} = {}
local loopGenerations: {[string]: number} = {}
local targetErrorTimes: {[string]: number} = {}
local networkKickLocks = setmetatable({}, {__mode = "k"})
local selectedKickActive = setmetatable({}, {__mode = "k"})
local actionQueues = {}
local actionQueueRunning = {}
local disableVoidToggle: any = nil
local function notify(message, title)
    if Library and Library.Notify then
        pcall(function()
            Library:Notify(message, title)
        end)
    else
        warn((title and (title .. ": ") or "") .. tostring(message))
    end
end

local function methodSelected(methods, name)
    if type(methods) ~= "table" then
        return methods == name
    end
    if methods[name] ~= nil then
        return methods[name] == true or methods[name] == name
    end
    for key, value in pairs(methods) do
        if key == name or value == name then
            return true
        end
    end
    return false
end
local remotes = {}
local remoteRoot = nil

local function locateRemoteRoot()
    local function isRemoteRoot(candidate)
        return candidate
            and candidate:FindFirstChild("GrabEvents")
            and candidate:FindFirstChild("MenuToys")
            and candidate:FindFirstChild("CharacterEvents")
    end

    if isRemoteRoot(ReplicatedStorage) then
        return ReplicatedStorage
    end
    for _, descendant in ipairs(ReplicatedStorage:GetDescendants()) do
        if isRemoteRoot(descendant) then
            return descendant
        end
    end
    return ReplicatedStorage
end

local function refreshRemotes()
    remoteRoot = locateRemoteRoot()
    local grabEvents = ReplicatedStorage:FindFirstChild("GrabEvents")
    local menuToys = remoteRoot and remoteRoot:FindFirstChild("MenuToys")
    local characterEvents = remoteRoot and remoteRoot:FindFirstChild("CharacterEvents")
    local playerEvents = remoteRoot and remoteRoot:FindFirstChild("PlayerEvents")

    remotes.sno = grabEvents and grabEvents:FindFirstChild("SetNetworkOwner") or nil
    remotes.cgl = grabEvents and grabEvents:FindFirstChild("CreateGrabLine") or nil
    remotes.dgl = grabEvents and grabEvents:FindFirstChild("DestroyGrabLine") or nil
    remotes.Struggle = characterEvents and characterEvents:FindFirstChild("Struggle") or nil
    remotes.RagdollRemote = characterEvents and characterEvents:FindFirstChild("RagdollRemote") or nil
    remotes.spe = playerEvents and playerEvents:FindFirstChild("StickyPartEvent") or nil
    remotes.spawnEvent = menuToys and menuToys:FindFirstChild("SpawnToyRemoteFunction") or nil
    remotes.destroyToyEvent = menuToys and menuToys:FindFirstChild("DestroyToy") or nil
    return remoteRoot
end

refreshRemotes()

local function fireRemote(remote, ...)
    if not remote then
        return false, nil
    end
    local ok, result = pcall(function(...)
        if remote:IsA("RemoteFunction") then
            return remote:InvokeServer(...)
        end
        remote:FireServer(...)
        return true
    end, ...)
    return ok, result
end

function H.charp(player)
    player = player or LocalPlayer
    local character = player and player.Character
    if not character then
        return nil, nil, nil
    end
    local rootPart = character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("Torso")
    local humanoid = character:FindFirstChildWhichIsA("Humanoid")
    return character, rootPart, humanoid
end

function H.getMagnitude(partA, partB)
    if not partA or not partB or not partA:IsA("BasePart") or not partB:IsA("BasePart") then
        return math.huge
    end
    return (partA.Position - partB.Position).Magnitude
end

function H.isnetworkowner(part)
    if typeof(part) ~= "Instance" or not part:IsA("BasePart") then
        return false
    end

    local checkPart = part
    if part.Massless and part.AssemblyRootPart then
        checkPart = part.AssemblyRootPart
    end
    if not checkPart or checkPart.Anchored then
        return false
    end

    if type(isnetworkowner) == "function" then
        local ok, owned = pcall(isnetworkowner, checkPart)
        if ok and type(owned) == "boolean" then
            return owned
        end
    end

    local ok, receiveAge = pcall(function()
        return checkPart.ReceiveAge
    end)
    return ok and receiveAge == 0
end

function H.ispartowner(part)
    if typeof(part) ~= "Instance" or not part:IsA("BasePart") then
        return false
    end

    -- PCLD(Workspace 직속)는 PartOwner 값이 없음 → 네트워크 오너십으로 판단 (아래 재귀 검색이 Workspace 전체를 훑는 것도 방지)
    if part.Name == "PlayerCharacterLocationDetector" and part.Parent == Workspace then
        return H.isnetworkowner(part)
    end

    if part.Name == "HumanoidRootPart" then
        local parent = part.Parent
        if parent then
            local head = parent:FindFirstChild("Head")
            if head then
                local owner = head:FindFirstChild("PartOwner")
                if owner then
                    return owner.Value == LocalPlayer.Name
                end
            end
        end
    end

    local owner = part:FindFirstChild("PartOwner")
    if owner and owner.Value == LocalPlayer.Name then
        return true
    end

    local parent = part.Parent
    if not parent then
        return false
    end

    owner = parent:FindFirstChild("PartOwner", true)
    if not owner then
        return false
    end

    return owner.Value == LocalPlayer.Name
end

function H.WhichPlot(player)
    if typeof(player) ~= "Instance" or not player:IsA("Player") then
        return nil, nil
    end

    local plots = Workspace:FindFirstChild("Plots")
    if not plots then
        return nil, nil
    end

    for _, plot in pairs(plots:GetChildren()) do
        local plotArea = plot:FindFirstChild("PlotArea")
        if plotArea and plotArea:IsA("BasePart") then
            local ok, parts = pcall(function()
                return Workspace:GetPartsInPart(plotArea)
            end)

            if ok and type(parts) == "table" then
                for _, part in pairs(parts) do
                    local character = part and part.Parent
                    local foundPlayer = character and Players:GetPlayerFromCharacter(character)
                    if foundPlayer == player then
                        local inOwnedPlot = player:FindFirstChild("InOwnedPlot")
                        return plot, inOwnedPlot and inOwnedPlot.Value
                    end
                end
            end
        end
    end

    return nil, nil
end

local function removeSpawnSound(toy)
    task.spawn(function()
        local main = toy and toy:WaitForChild("Main", 0.4)
        local sound = main and main:WaitForChild("ItemSpawnSound", 0.4)
        if sound then
            sound:Destroy()
        end
    end)
end

function H.BreakPlot(target)
    if adapters.BreakPlot then
        return adapters.BreakPlot(target)
    end
    if typeof(target) ~= "Instance" then
        return false
    end

    local plot = target
    local inPlot = nil
    if target:IsA("Player") then
        inPlot = target:FindFirstChild("InPlot")
        if not inPlot then return false end
        plot = H.WhichPlot(target)
        if not plot then return false end
    end
    if typeof(plot) ~= "Instance" then return false end
    if state.BrokenPlots[plot.Name] then return true end

    local plotArea = plot:FindFirstChild("PlotArea")
    if not plotArea then return false end
    refreshRemotes()
    if not remotes.spe then return false end

    local toy = H.st("NinjaShuriken")
    if not toy then return false end
    removeSpawnSound(toy)

    toy.Parent = nil

    local stickyPart = toy:WaitForChild("StickyPart", 0.4)
    local stickyWeld = stickyPart and stickyPart:WaitForChild("StickyWeld", 0.4)
    if not stickyPart or not stickyWeld then
        H.dt(toy)
        return false
    end

    local targetCFrame = CFrame.new(1099511627776,1099511627776,1099511627776)
    if plot.Name == "Plot5" then
        targetCFrame = CFrame.new(2147483648,2147483648,2147483648)
    end

    if not H.sno(stickyPart) then
        H.dt(toy)
        return false
    end
    fireRemote(remotes.spe, stickyPart, plotArea, targetCFrame)

    local started = tick()
    while stickyWeld.Parent and tick()-started <= 0.8 do
        if stickyWeld.Part1 == plotArea and (not inPlot or inPlot.Value ~= true) then
            break
        end
        task.wait()
    end
    if not stickyWeld.Parent or stickyWeld.Part1 ~= plotArea or (inPlot and inPlot.Value == true) then
        H.dt(toy)
        return false
    end

    state.BrokenPlots[plot.Name] = toy
    pcall(function()
        toy.Destroying:Once(function()
            if state.BrokenPlots[plot.Name] == toy then state.BrokenPlots[plot.Name] = nil end
        end)
    end)
    return toy
end

local function performOwnershipGrabLoop(part, timeout, localRoot, localHead, humanoid, moveLocal)
    local savedRootCFrame = CFrame.new()
    local savedHeadCFrame = CFrame.new()
    local desiredRootCFrame = CFrame.new()
    local heartbeatConnection = nil

    local function setupHiddenMove()
        savedRootCFrame = localRoot.CFrame
        savedHeadCFrame = localHead.CFrame
        desiredRootCFrame = localRoot.CFrame

        pcall(function()
            RunService:UnbindFromRenderStep("RSCClient")
        end)

        RunService:BindToRenderStep(
            "RSCClient",
            Enum.RenderPriority.Camera.Value - 1,
            function()
                if localRoot.Parent then
                    localRoot.CFrame = savedRootCFrame
                end
                if localHead.Parent then
                    localHead.CFrame = savedHeadCFrame
                end
            end
        )

        heartbeatConnection = RunService.Heartbeat:Connect(function()
            if not localRoot.Parent or not localHead.Parent then
                return
            end

            savedRootCFrame = localRoot.CFrame
            savedHeadCFrame = localHead.CFrame
            localRoot.CFrame = desiredRootCFrame
            localHead.CFrame = desiredRootCFrame
        end)
    end

    local function cleanupHiddenMove()
        pcall(function()
            RunService:UnbindFromRenderStep("RSCClient")
        end)

        if heartbeatConnection then
            heartbeatConnection:Disconnect()
            heartbeatConnection = nil
        end

        if localHead.Parent then
            localHead.CFrame = savedHeadCFrame
        end
        if localRoot.Parent then
            localRoot.CFrame = savedRootCFrame
        end
    end

    timeout = tonumber(timeout) or 0.65
    local started = tick()

    local ok, err = pcall(function()
        if moveLocal then
            setupHiddenMove()
        end

        while part.Parent
            and not H.ispartowner(part)
            and humanoid.Health ~= 0
            and localRoot.Parent
            and tick() - started < timeout
        do
            if moveLocal then
                desiredRootCFrame = part.CFrame - Vector3.new(0, 22, 0)
            end

            RunService.Heartbeat:Wait()
            H.grab(part, moveLocal and desiredRootCFrame or nil)
        end
    end)

    if moveLocal then
        pcall(cleanupHiddenMove)
    end

    return ok, err
end

function H.sno(part, duration)
    if adapters.sno then
        return adapters.sno(part, duration)
    end
    if typeof(part) ~= "Instance" or not part:IsA("BasePart") or not part.Parent then
        return false
    end

    local character, localRoot, humanoid = H.charp()
    local localHead = character and character:FindFirstChild("Head")
    local ragdolled = humanoid and humanoid:FindFirstChild("Ragdolled")

    if not character
        or not localHead
        or not localRoot
        or not humanoid
        or not ragdolled
        or humanoid.Health <= 0
    then
        return false
    end

    local spawnLocation = Workspace:FindFirstChild("SpawnLocation")
    if not spawnLocation or H.getMagnitude(part, spawnLocation) > 10000000 then
        return false
    end

    if H.ispartowner(part) then
        return true
    end

    local moveLocal = (localRoot.Position - part.Position).Magnitude >= 31

    if moveLocal and state.States.Owning == true then
        return false
    end

    local brokenPlotToy = nil
    if part.Name == "HumanoidRootPart" or part.Name == "Torso" then
        local targetPlayer = part.Parent and Players:FindFirstChild(part.Parent.Name)
        if targetPlayer and targetPlayer:IsA("Player") then
            local _, _, targetHumanoid = H.charp(targetPlayer)
            if not targetHumanoid or targetHumanoid.Health == 0 then
                return false
            end

            local inPlot = targetPlayer:FindFirstChild("InPlot")
            if inPlot and inPlot.Value == true then
                brokenPlotToy = H.BreakPlot(targetPlayer)
                if not brokenPlotToy then
                    return false
                end
            end
        end
    end

    state.States.Owning = true
    local ok, err = performOwnershipGrabLoop(
        part,
        duration,
        localRoot,
        localHead,
        humanoid,
        moveLocal
    )
    state.States.Owning = false

    if typeof(brokenPlotToy) == "Instance" then
        task.delay(1, H.dt, brokenPlotToy)
    end

    if not ok then
        warn("[Resonance sno] " .. tostring(err))
        return false
    end

    return H.ispartowner(part)
end

function H.unsno(part)
    if adapters.unsno then
        return adapters.unsno(part)
    end
    if not part then
        return false
    end
    refreshRemotes()
    if remotes.dgl then
        local ok = fireRemote(remotes.dgl, part)
        return ok
    end
    return false
end

function H.teleport(subject, target, offset)
    if not subject then
        return false
    end

    local part = subject
    if typeof(subject) == "Instance" and subject:IsA("Model") then
        part = subject.PrimaryPart or subject:FindFirstChildWhichIsA("BasePart", true)
    end
    if typeof(part) ~= "Instance" or not part:IsA("BasePart") then
        return false
    end

    local targetCFrame = nil
    if typeof(target) == "CFrame" then
        targetCFrame = target
    elseif typeof(target) == "Vector3" then
        targetCFrame = CFrame.new(target)
    elseif typeof(target) == "Instance" then
        if target:IsA("BasePart") then
            targetCFrame = target.CFrame
        elseif target:IsA("Model") then
            targetCFrame = target:GetPivot()
        end
    end
    if not targetCFrame then
        return false
    end
    if typeof(offset) == "CFrame" then
        targetCFrame = targetCFrame * offset
    end

    part.CFrame = targetCFrame
    H.resetVelocity(part)
    return true
end

function H.resetVelocity(part)
    if part and part:IsA("BasePart") then
        part.AssemblyLinearVelocity = Vector3.zero
        part.AssemblyAngularVelocity = Vector3.zero
    end
end

function H.FormatPlayer(player)
    if typeof(player) ~= "Instance" or not player:IsA("Player") then
        return tostring(player)
    end
    if player == LocalPlayer then
        return "You"
    end
    if player.DisplayName == player.Name then
        return player.Name
    end
    return string.format("%s (@%s)", player.DisplayName, player.Name)
end

function H.findNicePart(model)
    if typeof(model) ~= "Instance" or not model:IsA("Model") then
        return nil
    end
    local cached = state.GrabbableParts[model]
    if cached then
        if cached.Parent and cached:IsA("BasePart") and cached.CanQuery and cached.Name ~= "Button" then
            return cached
        end
        state.GrabbableParts[model] = nil
    end

    for _,child in pairs(model:GetChildren()) do
        if child:IsA("BasePart") and child.CanQuery and child.Name ~= "Button" then
            state.GrabbableParts[model] = child
            return child
        end
    end
    return nil
end

function H.DestroyObject(object)
    if adapters.DestroyObject then return adapters.DestroyObject(object) end
    if typeof(object) ~= "Instance" or not object:IsA("Model") then return false end
    local part = H.findNicePart(object)
    if not part or not H.sno(part) then return false end

    if disableVoidToggle and type(disableVoidToggle.SetDisabled) == "function" then
        pcall(function() disableVoidToggle:SetDisabled(true) end)
    end

    Workspace.FallenPartsDestroyHeight = 0/0
    object:PivotTo(CFrame.new(0,-11111,0))
    if state.DestroyThread then pcall(task.cancel,state.DestroyThread) end
    state.DestroyThread=task.delay(0.25,function()
        Workspace.FallenPartsDestroyHeight=-10000
        task.wait()
        Workspace.FallenPartsDestroyHeight=runtimeFlags.DestroyVoid and (0/0) or -100
        if disableVoidToggle and type(disableVoidToggle.SetDisabled) == "function" then
            pcall(function() disableVoidToggle:SetDisabled(false) end)
        end
    end)
    return true
end

function H.getInventory(player)
    if adapters.getInventory then
        return adapters.getInventory(player)
    end
    if typeof(player) ~= "Instance" or not player:IsA("Player") then
        return nil, nil
    end

    local spawned = Workspace:FindFirstChild(player.Name .. "SpawnedInToys")
    local plotInventory = nil

    local plots = Workspace:FindFirstChild("Plots")
    local plotItems = Workspace:FindFirstChild("PlotItems")
    if plots and plotItems then
        for _, plot in pairs(plots:GetChildren()) do
            local plotSign = plot:FindFirstChild("PlotSign")
            local owners = plotSign and plotSign:FindFirstChild("ThisPlotsOwners")
            if owners then
                for _, owner in pairs(owners:GetChildren()) do
                    if owner:IsA("StringValue") and owner.Value == player.Name then
                        plotInventory = plotItems:FindFirstChild(plot.Name)
                    end
                end
            end
        end
    end

    return spawned, plotInventory
end

function H.kill(player)
    local _, rootPart, humanoid = H.charp(player)
    if humanoid and humanoid.Health ~= 0 and rootPart then
        local _ = Workspace:FindFirstChild("SpawnLocation") and H.getMagnitude(Workspace.SpawnLocation, rootPart)
        if H.sno(rootPart) then
            humanoid.BreakJointsOnDeath = false
            humanoid.Sit = false
            humanoid:ChangeState(Enum.HumanoidStateType.Dead)
            H.teleport(rootPart, CFrame.new(0, 9000000000, 0))
            task.delay(2, H.unsno, rootPart)
        end
    end
end

function H.void(player)
    local _, rootPart, humanoid = H.charp(player)
    if humanoid and humanoid.Health ~= 0 and rootPart then
        local spawn = Workspace:FindFirstChild("SpawnLocation")
        if (not spawn or H.getMagnitude(spawn, rootPart) < 15000) and H.sno(rootPart) then
            H.teleport(rootPart, CFrame.new(0, 9000000000, 0))
            rootPart.Velocity = Vector3.new(0, 9000000000, 0)
            task.delay(0.35, H.unsno, rootPart)
        end
    end
end

function H.grab(part, cframe)
    if adapters.grab then
        return adapters.grab(part, cframe)
    end

    local _, localRoot, humanoid = H.charp()
    if not localRoot or not humanoid or humanoid.Health == 0 then
        return
    end
    if not part or not part.Parent or not part:IsA("BasePart") then
        return
    end

    refreshRemotes()
    if not remotes.sno then
        return
    end

    local sourceCFrame = cframe
    if not sourceCFrame then
        sourceCFrame = localRoot.CFrame
    end
    if typeof(sourceCFrame) ~= "CFrame" then
        return
    end

    sourceCFrame = sourceCFrame * CFrame.new(0, 1.593, 0)
    local grabCFrame = CFrame.new(sourceCFrame.Position, part.Position)
    remotes.sno:FireServer(part, grabCFrame)
end
local function collectInventoryModels(player)
    local first, second = H.getInventory(player)
    local result = {}
    if first then
        for _, child in ipairs(first:GetChildren()) do
            table.insert(result, child)
        end
    end
    if second then
        for _, child in ipairs(second:GetChildren()) do
            table.insert(result, child)
        end
    end
    return result
end

local function breakVehicleSeat(seat, localHumanoid, localRoot, targetRoot)

    if runtimeFlags.GucciAntiGrab then
        return false
    end
    if not seat or not seat.Parent then
        return false
    end
    if not (seat:IsA("VehicleSeat") or seat:IsA("Seat")) then
        return false
    end
    if seat.Occupant or seat:GetAttribute("broken") then
        return false
    end
    if not localHumanoid or localHumanoid.Health == 0 or not localRoot then
        return false
    end

    localHumanoid.Sit = false

    if runtimeFlags.RagdollInRG and targetRoot then
        H.sno(targetRoot, 1.5)
    end

    local _savedLocalCFrame = localRoot.CFrame
    seat.CanCollide = false

    local gotSeatWeld = false
    local connection
    connection = seat.ChildAdded:Connect(function(child)
        if child.Name == "SeatWeld" then
            pcall(function()
                child.Enabled = false
            end)
            child:Destroy()
            gotSeatWeld = true
        end
    end)

    local started = tick()
    while seat.Parent
        and localHumanoid.Parent
        and not gotSeatWeld
        and tick() - started <= 0.5
    do

        RunService.Heartbeat:Wait()
        seat:Sit(localHumanoid)
    end

    localHumanoid.Sit = false

    local originalParent = seat.Parent
    task.delay(0.5, function()
        if seat and originalParent then
            pcall(function()
                seat.Parent = ReplicatedStorage
                task.wait()
                seat.Parent = originalParent
            end)
        end
    end)

    if gotSeatWeld then
        seat:SetAttribute("broken", true)
        if connection then
            connection:Disconnect()
        end

        local watch
        watch = seat.ChildAdded:Connect(function(child)
            if child.Name ~= "SeatWeld" then
                return
            end

            local _, currentLocalRoot = H.charp()
            local part1 = nil
            pcall(function()
                part1 = child.Part1
            end)

            if part1 ~= currentLocalRoot then
                seat:SetAttribute("broken", false)
                if watch then
                    watch:Disconnect()
                end
            end
        end)

        return true
    end

    localHumanoid.Sit = true
    task.wait(0.05)
    localHumanoid.Sit = false
    if connection then
        connection:Disconnect()
    end
    return false
end

local function applySeatBreakerToInventory(folder, localHumanoid, localRoot, targetRoot)
    if not folder then
        return
    end

    for _, model in ipairs(folder:GetChildren()) do
        if model:IsA("Model") then
            local seat = model:FindFirstChildWhichIsA("VehicleSeat")
                or model:FindFirstChildWhichIsA("Seat")
            if seat then
                breakVehicleSeat(seat, localHumanoid, localRoot, targetRoot)
            end
        end
    end
end

function H.RemoveGucci(player)
    if adapters.RemoveGucci then
        return adapters.RemoveGucci(player)
    end

    local _, localRoot, localHumanoid = H.charp()
    local _, targetRoot, targetHumanoid = H.charp(player)
    local spawnedInventory, plotInventory = H.getInventory(player)

    if not localHumanoid
        or localHumanoid.Health <= 0
        or not localRoot
        or not spawnedInventory
        or not targetHumanoid
    then
        return false
    end

    local seatPart = targetHumanoid.SeatPart

    if not seatPart then
        applySeatBreakerToInventory(
            spawnedInventory,
            localHumanoid,
            localRoot,
            targetRoot
        )
        if plotInventory then
            applySeatBreakerToInventory(
                plotInventory,
                localHumanoid,
                localRoot,
                targetRoot
            )
        end
        return nil
    end

    if targetHumanoid.Sit then
        applySeatBreakerToInventory(
            spawnedInventory,
            localHumanoid,
            localRoot,
            targetRoot
        )
        if plotInventory then
            applySeatBreakerToInventory(
                plotInventory,
                localHumanoid,
                localRoot,
                targetRoot
            )
        end
        return nil
    end

    seatPart:SetAttribute("broken", false)
    return breakVehicleSeat(
        seatPart,
        localHumanoid,
        localRoot,
        targetRoot
    )
end

function H.DeleteSeatables(player)
    if adapters.DeleteSeatables then
        return adapters.DeleteSeatables(player)
    end

    local _, localRoot, localHumanoid = H.charp()
    local spawnedInventory, plotInventory = H.getInventory(player)

    if not localHumanoid
        or localHumanoid.Health <= 0
        or not localRoot
        or not spawnedInventory
    then
        return false
    end

    local function processFolder(folder)
        if not folder then
            return
        end

        for _, model in ipairs(folder:GetChildren()) do
            if model:IsA("Model") then
                local part = model.PrimaryPart or H.findNicePart(model)
                if part
                    and part:IsA("BasePart")
                    and part.Velocity.Magnitude <= 10
                then
                    local vehicleSeat = model:FindFirstChild("VehicleSeat")
                    if vehicleSeat and not vehicleSeat.Occupant then
                        H.DestroyObject(model)
                    end
                end
            end
        end
    end

    processFolder(spawnedInventory)
    if plotInventory then
        processFolder(plotInventory)
    end
    return nil
end

function H.EatAntiInput(player)
    if adapters.EatAntiInput then
        return adapters.EatAntiInput(player)
    end

    local targetCharacter = player and player.Character
    local targetLeftArm = targetCharacter and targetCharacter:FindFirstChild("Left Arm")
    local localCharacter, _, localHumanoid = H.charp()
    local localLeftArm = localCharacter and localCharacter:FindFirstChild("Left Arm")
    local leftGrip = localLeftArm and localLeftArm:FindFirstChild("LeftGripAttachment")
    local plotItems = Workspace:FindFirstChild("PlotItems")

    if not targetLeftArm
        or not localCharacter
        or not leftGrip
        or not localHumanoid
        or localHumanoid.Health == 0
        or not plotItems
    then
        return false
    end

    local changed = false
    for _, connected in pairs(targetLeftArm:GetConnectedParts()) do
        if connected.Name == "HoldPart"
            and not connected:IsDescendantOf(plotItems)
        then
            local item = connected.Parent
            local holdRemote = connected:WaitForChild("HoldItemRemoteFunction", 0.45)
            local dropRemote = connected:WaitForChild("DropItemRemoteFunction", 0.45)
            local rigid = connected:WaitForChild("RigidConstraint", 0.45)

            if holdRemote and dropRemote and rigid then
                rigid.Enabled = false
                local started = tick()

                while localCharacter.Parent
                    and item.Parent
                    and leftGrip.Parent
                    and rigid.Parent
                    and rigid.Attachment1 ~= leftGrip
                    and localHumanoid.Health ~= 0
                    and tick() - started < 1
                do
                    task.spawn(function()
                        local ok, err = pcall(function()
                            holdRemote:InvokeServer(item, localCharacter)
                        end)
                        if not ok then
                            warn("[Resonance Destroy Food/hold] " .. tostring(err))
                        end
                    end)
                    task.wait()
                end

                if rigid.Parent and rigid.Attachment1 == leftGrip then
                    changed = true
                    task.spawn(function()
                        local ok, err = pcall(function()
                            dropRemote:InvokeServer(item)
                        end)
                        if not ok then
                            warn("[Resonance Destroy Food/drop] " .. tostring(err))
                        end
                    end)
                    pcall(function()
                        dropRemote:Destroy()
                    end)
                end
            end
        end
    end

    return changed
end

function H.RemoveInvisibility(player)
    if adapters.RemoveInvisibility then
        return adapters.RemoveInvisibility(player)
    end

    local _, rootPart, humanoid = H.charp(player)
    if not rootPart or not humanoid or humanoid.Health == 0 then
        return false
    end

    rootPart.Massless = false
    return true
end

local function destroyNamedMover(rootPart, name)
    local object = rootPart and rootPart:FindFirstChild(name)
    if object then
        object:Destroy()
    end
end

-- 킥 오너십 해제: 슬로우 방식 (다음 프레임에 해제)
local function releaseKickOwnership(rootPart)
    task.spawn(function()
        task.wait()
        H.unsno(rootPart)
    end)
end

function H.ToggleCollisions(character, enabled, skipRagdollLimb, lowPhysical)
    if adapters.ToggleCollisions then
        return adapters.ToggleCollisions(
            character,
            enabled,
            skipRagdollLimb,
            lowPhysical
        )
    end

    if typeof(character) ~= "Instance"
        or not character:IsA("Model")
    then
        return
    end

    for _, child in pairs(
        character:GetChildren()
    ) do
        if child:IsA("BasePart") then
            if enabled then
                if child.Name == "Torso"
                    or child.Name == "Head"
                then
                    child.CanCollide = true
                end
            else
                child.CanCollide = false

                if not skipRagdollLimb then
                    local ragdollPart =
                        child:FindFirstChild(
                            "RagdollLimbPart"
                        )

                    if ragdollPart then
                        ragdollPart.CanCollide =
                            false
                    end
                end
            end

            if child.Name ~= "HumanoidRootPart" then
                local properties = nil

                if lowPhysical then
                    properties =
                        PhysicalProperties.new(
                            0.01,
                            0.01,
                            0.01,
                            0.01,
                            0.01
                        )
                end

                child.CustomPhysicalProperties =
                    properties
            end
        end
    end
end

function H.ToggleMotor6D(character, enabled, force)
    if adapters.ToggleMotor6D then
        return adapters.ToggleMotor6D(character, enabled, force)
    end

    if typeof(character) ~= "Instance" or not character:IsA("Model") then
        return false
    end

    local humanoid = character:FindFirstChild("Humanoid")
    local torso = character:FindFirstChild("Torso")
    if not humanoid or not torso then
        return false
    end

    local ragdolled = humanoid:FindFirstChild("Ragdolled")
    if not ragdolled then
        return false
    end

    if ragdolled.Value ~= true then
        for _, child in pairs(torso:GetChildren()) do
            if child:IsA("Motor6D") then
                child.Enabled = enabled
            end
        end
        return true
    end

    if not force then
        return false
    end

    local limbs = {
        "Left Leg",
        "Right Leg",
        "Left Arm",
        "Right Arm",
        "Head",
    }

    for _, name in pairs(limbs) do
        local part = character:FindFirstChild(name)
        if part then
            local socket = part:FindFirstChild("BallSocketConstraint")
            if socket then
                socket.Enabled = enabled
            end
        end
    end

    return true
end

function H.RepositionLimbs(character, resetVelocity)
    if adapters.RepositionLimbs then
        return adapters.RepositionLimbs(character, resetVelocity)
    end

    if typeof(character) ~= "Instance" or not character:IsA("Model") then
        return false
    end

    local root = character:FindFirstChild("HumanoidRootPart")
    if not root then
        return false
    end

    local weldHRP = root:FindFirstChild("WeldHRP")
    local torso = character:FindFirstChild("Torso")
    if not torso then
        return false
    end

    local neck = torso:FindFirstChild("Neck")
    if neck and neck.Enabled == true then
        return false
    end

    if weldHRP and not weldHRP.Parent then
        weldHRP = nil
    end

    for limbName, offset in pairs(state.LimbOffsetsRL) do
        local part = character:FindFirstChild(limbName)
        if part and part:IsA("BasePart") then
            part.CFrame = root.CFrame * offset
            if resetVelocity then
                H.resetVelocity(part)
            end
        end
    end

    return true
end

function H.removesticky(character)
    if adapters.removesticky then
        return adapters.removesticky(character)
    end

    if typeof(character) ~= "Instance"
        or not character:IsA("Model")
        or not character.Parent
    then
        return false
    end

    local targetRoot =
        character:FindFirstChild("HumanoidRootPart")
        or character:FindFirstChild("Torso")

    if not targetRoot or not targetRoot:IsA("BasePart") then
        return false
    end

    local plotItems = Workspace:FindFirstChild("PlotItems")
    local modelSet = setmetatable({}, {__mode = "k"})

    local function registerModel(value)
        if typeof(value) ~= "Instance" then
            return
        end

        local model = value

        if value:IsA("BasePart") then
            model = value.Parent
        end

        if model
            and model:IsA("Model")
            and model ~= character
            and model.Parent
        then
            modelSet[model] = true
        end
    end

    for _, descendant in pairs(character:GetDescendants()) do
        if descendant:IsA("BasePart") then
            for _, connected in pairs(descendant:GetConnectedParts()) do
                if connected.Name == "StickyPart" then
                    for _, child in pairs(connected:GetChildren()) do
                        if child:IsA("TouchInterest") then
                            child:Destroy()
                        end
                    end

                    registerModel(connected)
                end
            end
        end
    end

    local player = Players:GetPlayerFromCharacter(character)

    if player then
        local spawned, plotInventory = H.getInventory(player)

        if spawned then
            for _, child in pairs(spawned:GetChildren()) do
                registerModel(child)
            end
        end

        if plotInventory then
            for _, child in pairs(plotInventory:GetChildren()) do
                registerModel(child)
            end
        end
    end

    local removed = false

    for model in pairs(modelSet) do
        if model.Parent then
            local okPivot, modelPivot =
                pcall(
                    model.GetPivot,
                    model
                )

            if okPivot
                and (modelPivot.Position - targetRoot.Position).Magnitude <= 10
            then
                local part = H.findNicePart(model)

                if part and part:IsA("BasePart") then
                    local bodyVelocity =
                        part:FindFirstChild("RscBV")

                    if bodyVelocity
                        and not bodyVelocity:IsA("BodyVelocity")
                    then
                        bodyVelocity:Destroy()
                        bodyVelocity = nil
                    end

                    if not bodyVelocity then
                        bodyVelocity =
                            Instance.new("BodyVelocity")

                        bodyVelocity.Velocity =
                            Vector3.new(
                                0,
                                -50000,
                                0
                            )

                        bodyVelocity.MaxForce =
                            Vector3.new(
                                math.huge,
                                math.huge,
                                math.huge
                            )

                        bodyVelocity.Name = "RscBV"
                        bodyVelocity.Parent = part
                    end

                    H.ToggleCollisions(
                        model,
                        false
                    )

                    local inPlotItems =
                        plotItems
                        and model:IsDescendantOf(
                            plotItems
                        )

                    if not inPlotItems then
                        H.grab(part)
                    end

                    local sticky =
                        model:FindFirstChild(
                            "StickyPart"
                        )

                    if sticky then
                        for _, child in pairs(
                            sticky:GetChildren()
                        ) do
                            child:Destroy()
                        end
                    end

                    model:PivotTo(
                        CFrame.new(
                            0,
                            -50000,
                            0
                        )
                    )

                    task.delay(
                        1,
                        H.unsno,
                        part
                    )

                    removed = true
                end
            end
        end
    end

    return removed
end

function H.ragdoll(subject, duration)
    if adapters.ragdoll then
        return adapters.ragdoll(
            subject,
            duration
        )
    end

    local character = nil
    local targetPart = nil
    local humanoid = nil

    if typeof(subject) ~= "Instance" then
        return
    end

    if subject:IsA("Player") then
        character = subject.Character

        if character then
            targetPart =
                character:FindFirstChild(
                    "Torso"
                )

            humanoid =
                character:FindFirstChild(
                    "Humanoid"
                )
        end
    elseif subject:IsA("Model") then
        character = subject

        local head =
            character:FindFirstChild(
                "Head"
            )

        targetPart =
            character:FindFirstChild(
                "Torso"
            )

        humanoid =
            character:FindFirstChild(
                "Humanoid"
            )

        if not head then
            return
        end
    elseif subject:IsA("BasePart") then
        targetPart = subject

        if subject.Parent
            and subject.Parent:IsA("Model")
        then
            character = subject.Parent

            humanoid =
                character:FindFirstChild(
                    "Humanoid"
                )
        end
    else
        return
    end

    if not targetPart
        or not targetPart:IsA("BasePart")
        or not targetPart.Parent
        or not humanoid
    then
        return
    end

    local ragdolled =
        humanoid:FindFirstChild(
            "Ragdolled"
        )

    if not ragdolled then
        return
    end

    if ragdolled.Value ~= false then
        return
    end

    if state.States.Ragdolling then
        return
    end

    targetPart.CanCollide = false
    state.States.Ragdolling = true

    local spawnedFolder =
        Workspace:FindFirstChild(
            LocalPlayer.Name
                .. "SpawnedInToys"
        )

    if not spawnedFolder then
        state.States.Ragdolling = false
        return
    end

    local toy =
        spawnedFolder:FindFirstChild(
            "RagdollRSC"
        )

    if not toy then
        toy = H.st(
            "PalletLightBrown"
        )
    end

    if not toy then
        state.States.Ragdolling = false
        return
    end

    local soundPart =
        toy:WaitForChild(
            "SoundPart",
            0.5
        )

    if not soundPart
        or not soundPart:IsA("BasePart")
    then
        state.States.Ragdolling = false
        H.dt(toy)
        return
    end

    local main =
        toy:WaitForChild(
            "Main",
            0.5
        )

    if not main
        or not main:IsA("BasePart")
    then
        state.States.Ragdolling = false
        H.dt(toy)
        return
    end

    if not H.sno(soundPart) then
        state.States.Ragdolling = false
        H.dt(toy)
        return
    end

    toy.Name = "RagdollRSC"

    local bodyPosition =
        main:FindFirstChild(
            "RagdollBP"
        )

    if bodyPosition
        and not bodyPosition:IsA(
            "BodyPosition"
        )
    then
        bodyPosition:Destroy()
        bodyPosition = nil
    end

    if not bodyPosition then
        bodyPosition =
            Instance.new(
                "BodyPosition"
            )

        bodyPosition.Name =
            "RagdollBP"

        bodyPosition.D = 1500

        bodyPosition.MaxForce =
            Vector3.new(
                math.huge,
                math.huge,
                math.huge
            )

        bodyPosition.Position =
            Vector3.new(
                0,
                100000,
                0
            )

        bodyPosition.Parent =
            main
    else
        bodyPosition.D = 1500

        bodyPosition.MaxForce =
            Vector3.new(
                math.huge,
                math.huge,
                math.huge
            )

        bodyPosition.Position =
            Vector3.new(
                0,
                100000,
                0
            )
    end

    local started = tick()

    while toy.Parent
        and soundPart.Parent
        and targetPart.Parent
        and ragdolled.Parent
        and ragdolled.Value ~= true
        and tick() - started <= 0.5
    do
        soundPart.Position =
            targetPart.Position

        soundPart.Velocity =
            Vector3.new(
                0,
                -10,
                0
            )

        task.wait(0.1)
    end

    state.States.Ragdolling = false

    return ragdolled.Value
end

function H.st(name, cframe)
    if adapters.st then return adapters.st(name,cframe) end
    if type(name) ~= "string" or state.FailedToys[name] then return nil end
    local _,root=H.charp()
    if not root or state.States.Spawning then return nil end

    local inPlot=LocalPlayer:FindFirstChild("InPlot")
    local inOwned=LocalPlayer:FindFirstChild("InOwnedPlot")
    local hiddenSpawn=inPlot ~= nil and inPlot.Value == true
    if hiddenSpawn then hiddenSpawn=not (inOwned ~= nil and inOwned.Value == true) end
    if hiddenSpawn and state.States.Owning then return nil end

    refreshRemotes()
    if not remotes.spawnEvent or not remotes.spawnEvent:IsA("RemoteFunction") then return nil end
    local spawnedFolder=Workspace:FindFirstChild(LocalPlayer.Name.."SpawnedInToys")
    if not spawnedFolder then return nil end

    state.States.Spawning=true
    if hiddenSpawn then state.States.Owning=true end
    local childConn,heartbeatConn=nil,nil
    local renderBound=false
    local savedCF=root.CFrame
    local result=nil

    local function cleanup()
        if renderBound then pcall(function() RunService:UnbindFromRenderStep("STClient") end); renderBound=false end
        if heartbeatConn then heartbeatConn:Disconnect(); heartbeatConn=nil end
        if childConn then childConn:Disconnect(); childConn=nil end
        if hiddenSpawn and root and root.Parent then root.CFrame=savedCF end
        state.States.Spawning=false
        if hiddenSpawn then state.States.Owning=false end
    end

    local ok,err=pcall(function()
        local canSpawnToy=LocalPlayer:FindFirstChild("CanSpawnToy")
        if canSpawnToy then
            while canSpawnToy.Value == false do
                task.wait()
                if not root.Parent then return end
            end
        end
        local base=hiddenSpawn and CFrame.new(0,25,0) or (root.CFrame+Vector3.new(0,15,0))
        local requested=typeof(cframe)=="CFrame" and cframe or base
        local spawnCF=CFrame.new(requested.Position)+Vector3.new(0,0,20)
        local rotate=Workspace:FindFirstChild("RotateOrientPart")
        local rotation=rotate and rotate.Rotation or Vector3.zero

        childConn=spawnedFolder.ChildAdded:Connect(function(child)
            if child.Name == name then
                result=child
                if childConn then childConn:Disconnect(); childConn=nil end
            end
        end)
        savedCF=root.CFrame
        if hiddenSpawn then
            local hiddenCF=CFrame.new(0,10,0)
            pcall(function() RunService:UnbindFromRenderStep("STClient") end)
            RunService:BindToRenderStep("STClient",Enum.RenderPriority.Camera.Value-1,function()
                if root.Parent then root.CFrame=savedCF end
            end)
            renderBound=true
            heartbeatConn=RunService.Heartbeat:Connect(function()
                if root.Parent then savedCF=root.CFrame; root.CFrame=hiddenCF end
            end)
        end
        local function invokeSpawn()
            fireRemote(remotes.spawnEvent,name,spawnCF,rotation)
        end
        task.spawn(invokeSpawn)
        local started=tick()
        while true do
            RunService.Heartbeat:Wait()
            if hiddenSpawn then task.spawn(invokeSpawn) end
            if result or tick()-started > 1.3 then break end
        end
    end)
    cleanup()
    if not ok then warn(("[Resonance st] %s"):format(tostring(err))); return nil end
    if not result then
        state.FailedToys[name]=true
        task.delay(2,function() state.FailedToys[name]=nil end)
    end
    return result
end

function H.dt(model)
    if adapters.dt then return adapters.dt(model) end
    if typeof(model) ~= "Instance" or not model:IsA("Model") then return false end
    refreshRemotes()
    if not remotes.destroyToyEvent then return false end
    local ok=fireRemote(remotes.destroyToyEvent,model)
    return ok == true
end
local function removeTargetAntiKickShuriken(targetCharacter)
    if not targetCharacter then
        return
    end
    local function destroyStickyOwner(part)
        if not part or not part:IsA("BasePart") then
            return
        end
        for _, connected in ipairs(part:GetConnectedParts()) do
            if connected.Name == "StickyPart" then
                local model = connected.Parent
                if model and (model.Name == "NinjaShuriken" or model.Name == "ShurikenRSC") then
                    H.dt(model)
                end
            end
        end
    end
    for _, descendant in ipairs(targetCharacter:GetDescendants()) do
        if descendant:IsA("BasePart") then
            destroyStickyOwner(descendant)
        end
    end
end


-- 레그돌: 에러나 타임아웃으로 Ragdolling 플래그가 안 풀려서 영영 레그돌이 안 걸리는 상황 방지
local kickRagdollStartedAt = 0
local function spawnKickRagdoll(character)
    if state.States.Ragdolling then
        if tick() - kickRagdollStartedAt < 6 then
            return
        end
        state.States.Ragdolling = false
    end
    kickRagdollStartedAt = tick()
    task.spawn(function()
        local ok, err = pcall(H.ragdoll, character)
        if not ok then
            state.States.Ragdolling = false
            warn("[Resonance Target/Kick ragdoll] " .. tostring(err))
        end
    end)
end

-- ============================================================
-- 호출(리모트 전송) 자동 조절: 핑이 오르면 킥 패스(잡기/해제 호출) 빈도를 낮추고, 안정되면 다시 올림
--  * 패스 1번 = 잡기(SNO_BURST 번) + 해제 호출. 원본은 대상 수 × 프레임마다 보내서 대상이 늘면 핑이 터짐
--  * 토큰 단위: 패스 1번 = 1토큰, 추가 잡기 1번 = 0.5토큰 (SNO_BURST=3 이면 패스당 약 2토큰)
--  * 토큰 버킷으로 "초당 패스 수"의 총량을 제한하고, 한도는 핑 기준 AIMD(오르면 ×0.75, 안정되면 +)로 자동 조절
--  * 핑이 안 읽히면 고정 한도(48 토큰/s) 사용. 수동 상한(settings.NKRate)은 UI 에서 뺐으므로 0 = 상한 없음 (자동 조절만 동작)
-- ============================================================
local KickRate = {}
do
    local StatsService = game:GetService("Stats")
    local RATE_MIN = 20        -- 총 토큰/초 하한 (이 밑으로는 안 내려감, 패스당 2토큰이면 10패스/초)
    local RATE_MAX = 240       -- 총 토큰/초 상한 (핑이 안정적일 때만 이 근처까지 올라감)
    local RATE_START = 90      -- 시작값: 한 명 기준 원본 속도(30패스/초) × 패스당 약 2토큰 + 여유
    local RATE_FALLBACK = 48   -- 핑을 못 읽을 때 고정값
    local BURST = 6            -- 쌓아둘 수 있는 최대 토큰 (렉 후 한꺼번에 몰아 보내기 방지)

    local tokens = BURST
    local lastRefill = tick()
    local rate = RATE_START
    local softCeiling = RATE_MAX
    local pingSmooth, basePing, excess = nil, nil, 0
    local lastSample, lastTune, lastDecrease, lastActive = 0, 0, 0, 0

    local function readPing()
        local ok, value = pcall(function()
            return StatsService.Network.ServerStatsItem["Data Ping"]:GetValue()
        end)
        if ok and type(value) == "number" and value > 0 then
            return value
        end
        return nil
    end

    -- 기준 핑 = "내가 호출을 안 보낼 때의 핑"
    --  * 더 낮은 핑이 나오면 바로 기준으로 삼음
    --  * 쉬는 동안(킥 안 돌릴 때)은 현재 핑을 천천히 따라감 → 킥 시작 전의 정상 핑이 기준이 됨
    --  * 킥이 도는 동안은 기준을 올리지 않음 → 내 호출 때문에 핑이 올라간 걸 "원래 핑"으로 착각하지 않음
    --  * 단, 호출을 최소로 줄였는데도 계속 높으면 내 탓이 아니므로(서버 렉 등) 기준을 서서히 올려 줌
    --    (쉬는 동안 잰 정상 핑보다 최대 +150ms까지만)
    local idleBase = nil
    local function updateBaseline(ms, dt, active)
        if not basePing or ms < basePing then
            basePing = ms
            if not active then
                idleBase = basePing
            end
            return
        end
        local high = math.max(45, basePing * 0.4)
        if not active then
            if ms - basePing <= high then
                basePing = basePing + (ms - basePing) * 0.05
            else
                basePing = basePing + 4 * dt
            end
            idleBase = basePing
        elseif rate <= RATE_MIN + 0.01 and ms - basePing > math.max(20, basePing * 0.15) then
            if basePing < (idleBase or basePing) + 150 then
                basePing = basePing + 3 * dt
            end
        end
    end

    local function manualCap()
        local cap = settings.NKRate or 0
        if cap > 0 then
            return cap
        end
        return nil
    end

    -- 지금 허용되는 초당 패스 수 (nil = 제한 없음)
    local function effectiveRate()
        local cap = manualCap()
        if runtimeFlags.NKAutoRate ~= false then
            local value = pingSmooth and rate or RATE_FALLBACK
            if cap and cap < value then
                value = cap
            end
            return value
        end
        return cap
    end

    -- 패스 1번 시작해도 되는지 (토큰 1개 사용)
    function KickRate.take()
        local limit = effectiveRate()
        if limit == nil then
            return true
        end
        local now = tick()
        local dt = now - lastRefill
        lastRefill = now
        if dt < 0 then
            dt = 0
        elseif dt > 0.25 then
            dt = 0.25
        end
        tokens = math.min(BURST, tokens + limit * dt)
        if tokens >= 0.999 then
            tokens -= 1
            return true
        end
        return false
    end

    -- 패스가 평소보다 호출을 많이 썼을 때(끌어오기 등) 추가로 토큰 차감
    function KickRate.charge(amount)
        tokens = math.max(-BURST, tokens - (amount or 1))
    end

    -- 킥 루프가 돌고 있다고 알림 (조절기는 이때만 한도를 움직임)
    function KickRate.activity()
        lastActive = tick()
    end

    function KickRate.info()
        local now = tick()
        return {
            active = now - lastActive < 1,
            rate = effectiveRate(),
            auto = runtimeFlags.NKAutoRate ~= false,
            ping = pingSmooth,
            excess = excess,
        }
    end

    RunService.Heartbeat:Connect(function()
        local now = tick()

        if now - lastSample >= 0.1 then
            local sampleDt = math.min(now - lastSample, 1)
            lastSample = now
            local ms = readPing()
            if ms then
                pingSmooth = pingSmooth and (pingSmooth * 0.6 + ms * 0.4) or ms
                updateBaseline(pingSmooth, sampleDt, now - lastActive < 0.6)
                excess = pingSmooth - basePing
            end
        end

        if now - lastTune >= 0.25 then
            lastTune = now
            local active = now - lastActive < 0.6
            if not active then
                -- 쉬는 동안엔 시작값으로 되돌려 둠 (다음 킥을 낮은 한도로 시작하지 않게)
                if now - lastActive > 3 then
                    rate = RATE_START
                    softCeiling = RATE_MAX
                end
            elseif pingSmooth and basePing then
                local high = math.max(45, basePing * 0.4)
                local low = math.max(20, basePing * 0.15)
                if excess > high then
                    if now - lastDecrease >= 0.5 then
                        lastDecrease = now
                        softCeiling = rate * 0.85
                        rate = math.max(RATE_MIN, rate * 0.75)
                    end
                elseif excess < low then
                    local step = rate >= softCeiling and 0.5 or 2
                    rate = math.min(RATE_MAX, rate + step)
                    softCeiling = math.min(RATE_MAX, softCeiling + 0.1)
                end
            end
        end
    end)
end

local function cleanupNetworkKickPlayer(player)
    local character, rootPart, humanoid = H.charp(player)
    if not character or not rootPart or not humanoid then
        return false
    end

    local kickAP = rootPart:FindFirstChild("KickAP")
    local kickAO = rootPart:FindFirstChild("KickAO")
    local weldHRP = rootPart:FindFirstChild("WeldHRP")

    if kickAP then
        kickAP:Destroy()
    end

    if kickAO then
        kickAO:Destroy()
    end

    if settings.NKEki then
        pcall(function() sethiddenproperty(rootPart, "PhysicsRepRootPart", nil) end)
    end

    -- 정리할 때 HRP 를 쥔 채로 두지 않음 (잡힌 상태가 남으면 상대 화면에 탈출이 계속 떠 있음)
    releaseKickOwnership(rootPart)

    local ragdolled = humanoid:FindFirstChild("Ragdolled")
    if ragdolled and ragdolled.Value == true and weldHRP then
        weldHRP.Enabled = true
    end

    task.spawn(H.ToggleMotor6D, character, true, true)
    task.spawn(H.ToggleCollisions, character, true)

    return true
end

local function createNetworkKickMovers(rootPart, kickPosition)
    local bodyPosition = Instance.new("BodyPosition")
    bodyPosition.Name = "KickAP"
    bodyPosition.D = 500
    bodyPosition.MaxForce = Vector3.new(
        math.huge,
        math.huge,
        math.huge
    )
    bodyPosition.Position = kickPosition
    bodyPosition.Parent = rootPart

    local bodyGyro = Instance.new("BodyGyro")
    bodyGyro.Name = "KickAO"
    bodyGyro.D = 500
    bodyGyro.MaxTorque = Vector3.new(
        math.huge,
        math.huge,
        math.huge
    )
    bodyGyro.CFrame = CFrame.new()
    bodyGyro.Parent = rootPart

    return bodyPosition, bodyGyro
end

local function prepareNetworkKickMovers(rootPart, kickPosition)
    local bodyPosition = rootPart:FindFirstChild("KickAP")
    local bodyGyro = rootPart:FindFirstChild("KickAO")
    local weldHRP = rootPart:FindFirstChild("WeldHRP")

    if not bodyPosition or not bodyGyro then
        if bodyPosition then
            bodyPosition:Destroy()
        end

        if bodyGyro then
            bodyGyro:Destroy()
        end

        bodyPosition, bodyGyro =
            createNetworkKickMovers(
                rootPart,
                kickPosition
            )
    end

    if weldHRP then
        weldHRP.Enabled = false
    end

    bodyPosition.Position = kickPosition

    return bodyPosition, bodyGyro, weldHRP
end

local kickStickyAt = setmetatable({}, {__mode = "k"})
local kickReleaseSkip = setmetatable({}, {__mode = "k"})

-- 셋오너(SetNetworkOwner) 호출량: 패스당 SNO_BURST 번 (첫 번째는 원본 그대로, 나머지는 같은 프레임에 추가).
-- 추가분은 호출 예산에서 차감(1번당 0.5) → 핑이 오르면 Auto Rate 가 패스 빈도를 알아서 낮춤
local SNO_BURST = 3
local function grabBurst(part)
    H.grab(part)
    for _ = 2, SNO_BURST do
        H.grab(part)
    end
    KickRate.charge(0.5 * (SNO_BURST - 1))
end

-- 슬로우 킥 원본 타이밍: 잡기 → 다음 프레임에 해제 (잡기 호출 수만 SNO_BURST 로 늘림)
local function plainKickHold(player, targetRoot)
    grabBurst(targetRoot)
    -- 해제(DestroyGrabLine) 호출 줄이기: 2패스 중 1번은 해제 생략 (다음 잡기가 어차피 덮어씀)
    kickReleaseSkip[player] = ((kickReleaseSkip[player] or 0) + 1) % 2
    if kickReleaseSkip[player] ~= 0 then
        releaseKickOwnership(targetRoot)
    end
end

local function getRecoveredKickPosition(localRoot, index, count)
    if settings.NKPosition == "Above Head" then
        return localRoot.Position + Vector3.new(0, settings.NKOffset, 0)
    end
    local angle = (index - 1) * ((2 * math.pi) / count)
    return localRoot.Position + Vector3.new(
        math.cos(angle) * (settings.NKRadius or 10),
        settings.NKOffset,
        math.sin(angle) * (settings.NKRadius or 10)
    )
end

local function performNetworkKickPass(player, index, count, persistent)
    if adapters.NetworkKick then
        return adapters.NetworkKick(
            player,
            persistent == true,
            false,
            settings,
            runtimeFlags,
            state
        )
    end

    if typeof(player) ~= "Instance"
        or not player:IsA("Player")
        or player == LocalPlayer
        or not player.Parent
    then
        return false
    end

    local localCharacter, localRoot, localHumanoid = H.charp()
    if not localCharacter
        or not localRoot
        or not localHumanoid
        or localHumanoid.Health <= 0
    then
        return false
    end

    local inPlot = LocalPlayer:FindFirstChild("InPlot")
    if inPlot and inPlot.Value == true then
        return false
    end

    local targetCharacter, targetRoot, targetHumanoid = H.charp(player)
    if not targetCharacter
        or not targetRoot
        or not targetHumanoid
        or targetHumanoid.Health <= 0
    then
        return false
    end

    local torso = targetCharacter:FindFirstChild("Torso")
    if not torso then
        return false
    end

    local kickPosition =
        getRecoveredKickPosition(
            localRoot,
            index,
            count
        )

    prepareNetworkKickMovers(
        targetRoot,
        kickPosition
    )

    local distance =
        H.getMagnitude(
            localRoot,
            targetRoot
        )

    if distance > 33 then
        local pulled = H.sno(targetRoot)

        -- 끌어오기는 잡기 신호를 여러 번 쓰므로(성공/실패 상관없이) 그만큼 호출 예산에서 차감
        KickRate.charge(2)

        if not pulled then
            return false
        end

        H.teleport(
            targetRoot,
            kickPosition
        )
    end

    -- 슬로우 킥 원본 타이밍
    plainKickHold(player, targetRoot)
    if settings.NKEki then
        pcall(function() sethiddenproperty(targetRoot, "PhysicsRepRootPart", targetRoot) end)
    end

    if runtimeFlags.RagdollInNK then
        spawnKickRagdoll(targetCharacter)
    end

    if runtimeFlags.DeleteShurInNK then
        -- removesticky 는 캐릭터 전체를 훑어서 무거움 → 플레이어당 0.4초에 한 번만
        local now = tick()
        if now - (kickStickyAt[player] or 0) >= 0.4 then
            kickStickyAt[player] = now
            task.spawn(
                H.removesticky,
                targetCharacter
            )
        end
    end

    H.ToggleCollisions(
        targetCharacter,
        false
    )
    H.RepositionLimbs(
        targetCharacter,
        true
    )

    if not persistent then
        task.delay(0.5, function()
            pcall(
                cleanupNetworkKickPlayer,
                player
            )
            networkKickLocks[player] = nil
        end)
    end

    return true
end

function H.NetworkKick(player, loopCall, isServer)
    if typeof(player) ~= "Instance"
        or not player:IsA("Player")
        or player == LocalPlayer
    then
        return false
    end

    state.NetworkKickQueue[player] = {
        loopCall = loopCall == true,
        isServer = isServer == true,
        queuedAt = tick(),
    }

    return true
end

local function runNetworkKickWorker()
    local lastTried = setmetatable({}, {__mode = "k"})
    while task.wait() do
        local candidates = {}

        for player, request in pairs(state.NetworkKickQueue) do
            if player.Parent
                and not state.Whitelisted[player]
                and not networkKickLocks[player]
            then
                table.insert(candidates, {
                    player = player,
                    request = request,
                    tried = lastTried[player] or 0,
                })
            else
                state.NetworkKickQueue[player] = nil
            end
        end

        local batch = {}

        if #candidates > 0 then
            KickRate.activity()

            -- 가장 오래 못 받은 사람부터 (호출 예산이 모자라도 모두에게 돌아가게)
            table.sort(candidates, function(a, b)
                return a.tried < b.tried
            end)

            for _, entry in ipairs(candidates) do
                if not KickRate.take() then
                    break
                end

                -- 예산을 받은 사람만 큐에서 꺼냄 (나머지는 다음 프레임에 이어서)
                state.NetworkKickQueue[entry.player] = nil
                lastTried[entry.player] = tick()
                table.insert(batch, entry)
            end
        end

        local count = #batch

        for index, entry in ipairs(batch) do
            local player = entry.player

            if player.Parent
                and not networkKickLocks[player]
            then
                networkKickLocks[player] = true

                local ok, result =
                    pcall(
                        performNetworkKickPass,
                        player,
                        index,
                        count,
                        false
                    )

                if not ok or result ~= true then
                    networkKickLocks[player] = nil
                end

                if not ok then
                    warn(
                        ("[Resonance Target/Kick] %s: %s"):format(
                            player.Name,
                            tostring(result)
                        )
                    )
                end
            end
        end
    end
end

function H.queue(key, callback, player)
    if key == nil or type(callback) ~= "function" or not player then
        return false
    end

    local list = actionQueues[key]
    if not list then
        list = {}
        actionQueues[key] = list
    end

    if not table.find(list, player) then
        table.insert(list, player)
    end

    if actionQueueRunning[key] then
        return true
    end

    actionQueueRunning[key] = true

    task.spawn(function()
        while #list > 0 do
            local item = table.remove(list, 1)
            if item and item.Parent then
                local ok, err = pcall(callback, item)
                if not ok then
                    warn(
                        ("[Resonance Target/queue:%s] %s"):format(
                            tostring(key),
                            tostring(err)
                        )
                    )
                end
                task.wait()
            end
        end
        actionQueueRunning[key] = nil
    end)

    return true
end

function H.clearAllQueues(toggleKey)
    if toggleKey then
        loopGenerations[toggleKey] = (loopGenerations[toggleKey] or 0) + 1
    else
        for key in pairs(loopGenerations) do
            loopGenerations[key] = loopGenerations[key] + 1
        end
    end

    for _, list in pairs(actionQueues) do
        table.clear(list)
    end

    table.clear(state.NetworkKickQueue)
end

function H.GetTargets(isServer, selectedPlayers)
    local result = {}
    if isServer then
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer
                and not state.Whitelisted[player]
                and not (state.FriendSkip and state.FriendSkip[player])
            then
                table.insert(result, player)
            end
        end
        return result
    end

    for player, enabled in pairs(selectedPlayers or {}) do
        local resolved = nil
        local selected = enabled ~= false

        if typeof(player) == "Instance" and player:IsA("Player") then
            resolved = player
        elseif type(player) == "string" then
            resolved = Players:FindFirstChild(player)
        elseif typeof(enabled) == "Instance" and enabled:IsA("Player") then
            resolved = enabled
            selected = true
        elseif type(enabled) == "string" then
            resolved = Players:FindFirstChild(enabled)
            selected = true
        end

        if resolved
            and selected
            and resolved ~= LocalPlayer
            and not state.Whitelisted[resolved]
        then
            table.insert(result, resolved)
        end
    end
    return result
end

function H.ProcessPlayer(player, loopCall, isServer, isBlob)
    if isBlob then
        return
    end

    if not player or player == LocalPlayer or state.Whitelisted[player] then
        return
    end

    local methods = state.TargetMethods

    if methodSelected(methods, "Kick") then
        if not loopCall or isServer then
            H.NetworkKick(player, loopCall, isServer)
        end
    end

    if methodSelected(methods, "Kill") then
        if loopCall then
            H.queue("Kill", H.kill, player)
        else
            H.kill(player)
        end
    end

    if methodSelected(methods, "Void") then
        if loopCall then
            H.queue("Void", H.void, player)
        else
            H.void(player)
        end
    end

    if methodSelected(methods, "Remove Gucci") then
        if loopCall then
            H.queue("Remove Gucci", H.RemoveGucci, player)
        else
            H.RemoveGucci(player)
        end
    end

    if methodSelected(methods, "Destroy Food") then
        if loopCall then
            H.queue("Destroy Food", H.EatAntiInput, player)
        else
            H.EatAntiInput(player)
        end
    end

    if methodSelected(methods, "Remove Invisibility") then
        H.RemoveInvisibility(player)
    end

    if methodSelected(methods, "Delete Seatables") then
        if loopCall then
            H.queue("Delete Seatables", H.DeleteSeatables, player)
        else
            H.DeleteSeatables(player)
        end
    end

    if methodSelected(methods, "Bring") then
        local _, targetRoot, targetHumanoid = H.charp(player)
        local _, localRoot = H.charp()
        if targetRoot
            and localRoot
            and targetHumanoid
            and targetHumanoid.Health ~= 0
            and H.sno(targetRoot)
        then
            H.teleport(
                targetRoot,
                localRoot,
                CFrame.new(0, 0, -5)
            )
            task.delay(0.2, H.unsno, targetRoot)
        end
    end
end

local function runSelectedNetworkKickLoop()
    local rotateStart = 1
    while task.wait() do
        local loopEnabled =
            runtimeFlags.LoopApplyMethodT == true

        local kickEnabled =
            methodSelected(
                state.TargetMethods,
                "Kick"
            )

        local inPlotObject =
            LocalPlayer:FindFirstChild("InPlot")

        local inPlot =
            inPlotObject
            and inPlotObject.Value == true

        for player in pairs(selectedKickActive) do
            if not player
                or not player.Parent
                or not loopEnabled
                or not kickEnabled
                or inPlot
                or state.SelectedPlayers[player] ~= true
            then
                pcall(
                    cleanupNetworkKickPlayer,
                    player
                )
                selectedKickActive[player] = nil
            end
        end

        if loopEnabled
            and kickEnabled
            and not inPlot
        then
            local _, localRoot, localHumanoid =
                H.charp()

            if localRoot
                and localHumanoid
                and localHumanoid.Health > 0
            then
                local batch = {}

                for player, enabled in pairs(
                    state.SelectedPlayers
                ) do
                    if enabled == true
                        and typeof(player) == "Instance"
                        and player:IsA("Player")
                        and player.Parent
                    then
                        table.insert(
                            batch,
                            player
                        )
                        selectedKickActive[player] = true
                    end
                end

                local count = #batch

                if count > 0 then
                    KickRate.activity()

                    -- 순서를 고정해서 Side 링 위치가 프레임마다 뒤바뀌며 흔들리지 않게 함
                    if count > 1 then
                        table.sort(batch, function(a, b)
                            return a.UserId < b.UserId
                        end)
                    end

                    if rotateStart > count then
                        rotateStart = 1
                    end

                    local lastDone = nil

                    for step = 0, count - 1 do
                        if runtimeFlags.LoopApplyMethodT ~= true then
                            break
                        end

                        local currentInPlot =
                            LocalPlayer:FindFirstChild("InPlot")

                        if currentInPlot
                            and currentInPlot.Value == true
                        then
                            break
                        end

                        local _, currentRoot, currentHumanoid =
                            H.charp()

                        if not currentRoot
                            or not currentHumanoid
                            or currentHumanoid.Health <= 0
                        then
                            break
                        end

                        -- 호출 예산이 없으면 이번 프레임은 여기까지 (다음 프레임에 이어서)
                        if not KickRate.take() then
                            break
                        end

                        local index = ((rotateStart - 1 + step) % count) + 1

                        pcall(
                            performNetworkKickPass,
                            batch[index],
                            index,
                            count,
                            true
                        )

                        lastDone = index
                    end

                    -- 다음 프레임은 방금 처리한 사람 다음부터 (예산이 모자랄 때 모두에게 돌아가게)
                    if lastDone then
                        rotateStart = (lastDone % count) + 1
                    end

                    -- 슬로우 킥 원본: 배치 끝나면 한 프레임 더 쉼
                    task.wait()
                end
            end
        end
    end
end

local function safeProcessPlayer(player, loopCall, isServer, isBlob)
    local ok, result = pcall(
        H.ProcessPlayer,
        player,
        loopCall,
        isServer,
        isBlob
    )

    if not ok then
        local key = typeof(player) == "Instance" and player.Name or tostring(player)
        local now = tick()
        local last = targetErrorTimes[key] or 0
        if now - last >= 1 then
            targetErrorTimes[key] = now
            warn(
                ("[Resonance Target] %s: %s"):format(
                    key,
                    tostring(result)
                )
            )
        end
        return false, result
    end

    return true, result
end

local function validateTargetRuntime()
    refreshRemotes()

    local missing = {}
    if not Workspace:FindFirstChild("SpawnLocation") then
        table.insert(missing, "workspace.SpawnLocation")
    end
    if not Workspace:FindFirstChild("Plots") then
        table.insert(missing, "workspace.Plots")
    end
    if not Workspace:FindFirstChild("PlotItems") then
        table.insert(missing, "workspace.PlotItems")
    end
    if not remotes.sno then
        table.insert(missing, "GrabEvents.SetNetworkOwner")
    end
    if not remotes.dgl then
        table.insert(missing, "GrabEvents.DestroyGrabLine")
    end

    if #missing > 0 then
        warn("[Resonance Target/self-check] missing: " .. table.concat(missing, ", "))
        return false, missing
    end

    return true, missing
end

H.ValidateTargetRuntime = validateTargetRuntime

-- 킥 루프들은 에러가 나서 죽어도 자동으로 다시 시작함 (예전에는 한 번 죽으면 스크립트를 다시 실행할 때까지 킥이 안 됐음)
task.spawn(getgenv()._8minLoop("Kick worker", runNetworkKickWorker))
task.spawn(getgenv()._8minLoop("Selected kick loop", runSelectedNetworkKickLoop))
task.defer(validateTargetRuntime)
local function syncSelectedPlayers(value)
    table.clear(state.SelectedPlayers)
    if typeof(value) == "Instance" and value:IsA("Player") then
        state.SelectedPlayers[value] = true
    elseif type(value) == "table" then
        for player, enabled in pairs(value) do
            if typeof(player) == "Instance" and player:IsA("Player") then
                state.SelectedPlayers[player] = enabled ~= false
            elseif typeof(enabled) == "Instance" and enabled:IsA("Player") then
                state.SelectedPlayers[enabled] = true
            end
        end
    end
end

local function processLoop(toggleKey, isServer, selectedPlayers, generation)
    while runtimeFlags[toggleKey]
        and loopGenerations[toggleKey] == generation
    do
        for _, player in ipairs(H.GetTargets(isServer, selectedPlayers)) do
            if not runtimeFlags[toggleKey]
                or loopGenerations[toggleKey] ~= generation
            then
                break
            end
            safeProcessPlayer(player, true, isServer, false)
        end
        task.wait()
    end
end

local function createLoopToggle(groupbox, id, toggleKey, isServer, isBlob, selectedPlayers)
    local label = isServer and "Server" or "Selected"
    local targetDescription = isServer and "all" or "selected"
    groupbox:AddToggle(id, {
        Text = label,
        Default = false,
        Tooltip = targetDescription .. " players",
        Callback = function(enabled)
            runtimeFlags[toggleKey] = enabled
            loopGenerations[toggleKey] = (loopGenerations[toggleKey] or 0) + 1
            local generation = loopGenerations[toggleKey]

            if enabled then
                task.spawn(
                    processLoop,
                    toggleKey,
                    isServer,
                    selectedPlayers,
                    generation
                )
            else
                H.clearAllQueues(toggleKey)
            end
        end,
    })
end

local function createApplyButton(groupbox, isServer, isBlob, selectedPlayers)
    local label = isServer and "Server" or "Selected"
    groupbox:AddButton({
        Text = label,
        Func = function()
            local targets = H.GetTargets(isServer, selectedPlayers)
            if #targets == 0 then
                notify("No valid targets selected.", "Target")
                return
            end

            for _, player in ipairs(targets) do
                safeProcessPlayer(player, false, isServer, isBlob)
            end
        end,
    })
end
local function getMap()
    return Workspace:FindFirstChild("Map")
end

local function getInOwnedPlotValue()
    local value = LocalPlayer:FindFirstChild("InOwnedPlot", true)
    if value and value:IsA("BoolValue") then
        return value.Value
    end
    return false
end
local function applyDisableVoid(enabled)

    runtimeFlags.DestroyVoid = enabled
    if enabled then
        Workspace.FallenPartsDestroyHeight = 0 / 0
    else
        Workspace.FallenPartsDestroyHeight = -100
    end
end

local function applyWaterWalk(enabled)
    runtimeFlags.WaterWalk = enabled
    local map = getMap()
    local always = map and map:FindFirstChild("AlwaysHereTweenedObjects")
    local ocean = always and always:FindFirstChild("Ocean")
    local object = ocean and ocean:FindFirstChild("Object")
    local objectModel = object and object:FindFirstChild("ObjectModel")
    if not objectModel then
        return
    end
    for _, child in ipairs(objectModel:GetChildren()) do
        if child:IsA("BasePart") then
            if enabled then
                child.CanCollide = true
                if child.Transparency ~= 1 then
                    child.Transparency = 0.5
                end
            else
                child.CanCollide = false
                if child.Transparency ~= 1 then
                    child.Transparency = 0
                end
            end
        end
    end
end

local function applyDeleteBarriers(enabled)
    runtimeFlags.DeleteBarriers = enabled
    local plots = Workspace:FindFirstChild("Plots")
    if not plots then
        return
    end
    for _, plot in ipairs(plots:GetChildren()) do
        local barrier = plot:FindFirstChild("Barrier")
        if barrier then
            for _, part in ipairs(barrier:GetChildren()) do
                if part:IsA("BasePart") and part.Name == "PlotBarrier" then
                    part.CanCollide = not enabled
                end
            end
        end
    end
end

local otherInvGeneration = 0
local function startOtherInvCollisions()
    otherInvGeneration += 1
    local generation = otherInvGeneration
    task.spawn(getgenv()._8minLoop("Other inv collisions", function()
        while runtimeFlags.OtherInvCollisions and generation == otherInvGeneration and task.wait(0.1) do
            local character = H.charp()
            if character then
                for _, part in ipairs(character:GetDescendants()) do
                    if part:IsA("BasePart") then
                        pcall(function()
                            PhysicsService:SetPartCollisionGroup(part, "PlotPlayers")
                        end)
                    end
                end
            end
        end
        local character = H.charp()
        if character then
            local collisionGroup = getInOwnedPlotValue() and "PlotPlayers" or "Players"
            for _, part in ipairs(character:GetDescendants()) do
                if part:IsA("BasePart") then
                    pcall(function()
                        PhysicsService:SetPartCollisionGroup(part, collisionGroup)
                    end)
                end
            end
        end
    end))
end
task.spawn(function()
    local antiInputToy = nil
    local endGrabEarly = nil
    local lastInputWarn = 0
    while true do
        task.wait(settings.InputLgDelay or 0.05)
        -- 한 번 에러가 나도 이 루프가 죽지 않게 매번 보호해서 실행 (예전에는 에러 한 번에 Anti Network Ownership 이 끝까지 멈췄음)
        local okInput, errInput = pcall(function()
        if runtimeFlags.AntiInputLag then
            refreshRemotes()
            local grabEvents = remoteRoot and remoteRoot:FindFirstChild("GrabEvents")
            if grabEvents and not endGrabEarly then
                local existing = grabEvents:FindFirstChild("EndGrabEarly")
                if existing then
                    existing:Destroy()
                end
                endGrabEarly = Instance.new("RemoteEvent")
                endGrabEarly.Name = "EndGrabEarly"
                endGrabEarly.Parent = grabEvents
            end

            local character, _, humanoid = H.charp()
            if not antiInputToy then
                antiInputToy = H.st(settings.AntiInputType, CFrame.new(0, 1e20, 0))
            end
            if antiInputToy and antiInputToy.Parent then
                local holdPart = antiInputToy:WaitForChild("HoldPart", 2)
                local holdRemote = holdPart and holdPart:WaitForChild("HoldItemRemoteFunction", 2)
                local dropRemote = holdRemote and holdPart:WaitForChild("DropItemRemoteFunction", 2)
                local rigid = holdPart and holdPart:FindFirstChild("RigidConstraint")

                for _, descendant in ipairs(antiInputToy:GetDescendants()) do
                    if descendant:IsA("BasePart") then
                        descendant.CanCollide = false
                        if descendant:IsA("MeshPart") or descendant.Name == "Part" then
                            descendant.Transparency = settings.AILTransparency
                        end
                    elseif descendant:IsA("Decal") then
                        descendant.Transparency = settings.AILTransparency
                    end
                end

                if character and humanoid and humanoid.Health > 0 and holdPart and holdRemote and dropRemote then
                    task.spawn(function()
                        pcall(function()
                            dropRemote:InvokeServer(antiInputToy, CFrame.new(0, 1e20, 0), Vector3.new())
                        end)
                    end)
                    task.spawn(function()
                        pcall(function()
                            holdRemote:InvokeServer(antiInputToy, character)
                        end)
                    end)
                    if rigid then
                        local leftArm = character:FindFirstChild("Left Arm")
                        local rightArm = character:FindFirstChild("Right Arm")
                        local leftGrip = leftArm and leftArm:FindFirstChild("LeftGripAttachment")
                        local rightGrip = rightArm and rightArm:FindFirstChild("RightGripAttachment")
                        local a1 = rigid.Attachment1
                        if a1 and a1 ~= leftGrip and a1 ~= rightGrip then
                            H.dt(antiInputToy)
                            antiInputToy = nil
                        end
                    end
                else
                    H.dt(antiInputToy)
                    antiInputToy = nil
                end
            end
        else
            if antiInputToy then
                H.dt(antiInputToy)
                antiInputToy = nil
            end
            if endGrabEarly then
                endGrabEarly:Destroy()
                endGrabEarly = nil
            end
        end
        end)

        if not okInput and os.clock() - lastInputWarn > 5 then
            lastInputWarn = os.clock()
            warn("[Anti Network Ownership] " .. tostring(errInput))
        end
    end
end)

-- 마지막으로 나를 잡은 사람 (Head.PartOwner)
local function bindWhoGrabbed(character)
    local head = character and character:WaitForChild("Head", 5)
    if not head then return end
    if activeConnections.WhoGrabbed then activeConnections.WhoGrabbed:Disconnect() end
    activeConnections.WhoGrabbed = head.ChildAdded:Connect(function(child)
        if child:IsA("StringValue") and child.Name == "PartOwner" then
            local p = Players:FindFirstChild(child.Value)
            if p and p ~= LocalPlayer then state.WhoGrabbed = H.FormatPlayer(p) end
        end
    end)
end
if LocalPlayer.Character then task.defer(bindWhoGrabbed, LocalPlayer.Character) end
