local function refreshTargetList()
    labelToPlayer = {}
    local values = {}
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer then
            local l = playerLabel(p)
            labelToPlayer[l] = p
            table.insert(values, l)
        end
    end
    table.sort(values)
    for p in pairs(state.SelectedPlayers) do
        if not p.Parent then state.SelectedPlayers[p] = nil end
    end
    if targetDropdown then
        pcall(function() targetDropdown:SetValues(values) end)
        pcall(function() targetDropdown:SetValue(currentSelectionLabels()) end)
    end
    return values
end
