            for _, folder in ipairs({ first or false, second or false }) do
                if folder then
                    for _, child in ipairs(folder:GetChildren()) do
                        local vs = child:FindFirstChild("VehicleSeat")
                        if vs then vs:SetAttribute("broken", false) end
                    end
                end
            end
        end
    end
end)

-- ===== Break Plot (Resonance 타겟 그룹들 뒤에 만들어지게 늦게 실행) =====
getgenv()._8minBreakPlotInit = function()
-- ===== Break Plot =====
local plotBox = TargetTab:AddRightGroupbox("Break Plot", "house")
pcall(function() plotBox:AddDivider("Plots") end)
local PLOT_NAMES = { "Tudor House", "PinkRoofHouse", "HauntedHouse", "JapaneseHouse", "BlueHouse" }
for i, nm in ipairs(PLOT_NAMES) do
    plotBox:AddToggle("BreakPlot" .. i, {
        Text = i .. " | " .. nm, Default = false,
        Callback = function(on)
            local plots = Workspace:FindFirstChild("Plots")
            local plot = plots and plots:FindFirstChild("Plot" .. i)
            if not plot then
                if on then notify("Plot" .. i .. " not found.", "Break Plot", "fail") end
                return
            end
            if on then
                task.spawn(function()
                    local r = H.BreakPlot(plot)
                    if not r then
                        notify("Failed to break " .. nm, "Break Plot", "fail")
                        pcall(function() Toggles["BreakPlot" .. i]:SetValue(false) end)
                    else
                        notify("Broke " .. nm .. " successfully", "Break Plot", "success")
                    end
                end)
            else
                local toy = state.BrokenPlots[plot.Name]
                if typeof(toy) == "Instance" then task.spawn(H.dt, toy) end
                state.BrokenPlots[plot.Name] = nil
            end
        end,
    })
end
pcall(function() plotBox:AddDivider() end)
local nearestLabel = plotBox:AddLabel("Nearest Location: -", true)
task.spawn(getgenv()._8minLoop("bg-16604", function()
    while task.wait(0.5) do
        pcall(function()
            local _, root = H.charp()
            local wps = Workspace:FindFirstChild("Waypoints")
            if not root or not wps then return end
            local best, bd = nil, math.huge
            for _, w in ipairs(wps:GetChildren()) do
                if w:IsA("BasePart") then
                    local d = (w.Position - root.Position).Magnitude
                    if d < bd then bd, best = d, w.Name end
                end
            end
            nearestLabel:SetText("Nearest Location: " .. tostring(best or "-"))
        end)
    end
end))
end

applyDisableVoid(true)
end)()


