        local s = { Value = v, Default = v, Type = "Stub" }
        for _, n in ipairs({ "SetValue", "SetVisible", "SetDisabled", "SetDisabledValues", "SetText", "SetValues", "OnChanged", "AddKeyPicker", "AddColorPicker", "Display", "Destroy", "SetMax", "SetMin" }) do
            s[n] = function(self, ...)
                if n == "SetValue" then self.Value = (...) end
                return self
            end
        end
        return s
    end

    local function proxyFor(realTbl, defaultV)
        local cache = {}
        return setmetatable({}, {
            __index = function(_, k)
                if type(k) ~= "string" then return nil end
                local r = realTbl[PREFIX .. k]
                if r ~= nil then return r end
                local s = cache[k]
