                local v = obj[name]
                if type(v) ~= "function" then return v end
                return function(_, ...)
                    local args = table.pack(...)
                    if PFX_FIRST[name] and type(args[1]) == "string" then
                        args[1] = PREFIX .. args[1]
                    elseif name == "AddLabel" and type(args[1]) == "string" and type(args[2]) == "table" then
                        args[1] = PREFIX .. args[1]
                    end
                    local r = v(obj, table.unpack(args, 1, args.n))
                    if r == obj then return px end
                    if type(r) == "table" and (r.AddKeyPicker or r.AddColorPicker or r.AddButton or r.AddTab or r.AddToggle) then
                        return wrap(r)
                    end
                    return r
                end
            end,
