						end

						local cFrame2 = (v22:FindFirstChild("Torso") or v23).CFrame
						local n40 = nil
						local n41 = nil

						if wingPhase then
							local n42 = cFrame2 * CFrame.new(0, 0.5, 0.55)
							local cframe = CFrame.Angles
							local n43

							if flight then
								n43 = -0.12
							else
								n43 = 0
