						local min = math.min
						local n43

						if flight then
							n43 = 12
						else
							n43 = 10
						end

						coconutForms.CapeWind = lerp(capeWind, vector3, min(n37 * n43, 1))
						local n44 = coconutForms.Counts.Cape / 3
						local n45 = 0.09 + math.min(coconutForms.CapeSpeed * 0.004, 0.28)
						local n46

						if flight then
							n46 = 0.1
						else
							n46 = 0
						end

						local n47 = n45 + n46
						local n48 = now3 * 1.17

						for i = #coconutForms.Models, 1, -1 do
