						coconutForms.WingStart = nil
						coconutForms.CapeStart = nil

						for _, v22 in coconutForms.Order, nil, nil do
							if selected[v22] and #offsets + coconutForms.Counts[v22] <= coconutForms.Limit then
								if v22 == "Boobs" then
									local n37 = #offsets + 1
