								tbl13.UpdateCharacterRoots()
								local n37 = 1

								while n37 <= #toysAuraSettings.Models do
									local v25 = toysAuraSettings.Models[n37]
									local parent2 = v25.Parent and tbl13.GetRoot(v25)

									if tbl7.ObjectStates[v25] then
										tbl13.ClearMovers(v25)
