				v28.CFrame = cFrame3
				local n36 = #tbl17 + 1
				local n37 = #tbl17 + 2
				tbl17[n36] = v27
				tbl17[n37] = v28
			end

			task.wait(0.35)

			for _, v26 in ipairs(tbl16) do
