		tbl14.Kill = function(arg)
			if not parent then
				return
			end
			local v22, v23, v24 = tbl12.Char()
			if not (v23 and v24 and v24.Health > 0) then
				return
			end
			local v25, v26, v27 = tbl12.Char(arg)
			if not (v26 and v27 and v27.Health > 0) then
