			end

			if not (v27.Sit and v27.SeatPart) then
				-- 소유권 탈취가 실패하면 더 긴 제한시간(1.2초)으로 최대 2번 더 시도
				local owned = tbl14.Release(arg)
				for _ = 1, 2 do
					if owned or not (v27.Parent and v27.Health > 0) then break end
					owned = tbl14.Release(arg, 1.2)
				end
				if owned then
					v27.BreakJointsOnDeath = false
					-- 한 번에 안 죽는 경우를 위해 죽을 때까지(최대 4프레임) 반복해서 적용
					for _ = 1, 4 do
						v27:ChangeState(Enum.HumanoidStateType.Dead)
						if v27.Health > 0 then pcall(function() v27.Health = 0 end) end
						task.wait()
						if not v27.Parent or v27.Health <= 0 then break end
						if not tbl12.IsNetworkOwner(v26) then
							tbl14.Release(arg, 0.5)
						end
					end
					return true
				end
			end

			if v27.Sit and v27.SeatPart and tbl14.Bring(arg) then
				tbl12.Kill(arg)
				return true
			end
		end

