				tbl12.Teleport(v26, n36)
				local v29, v30 = tbl12.CreateAlign(v26, true)
				v29.Position = n36.Position
				-- 고정력 강화: 정렬 힘을 크게 올리고, 매 Heartbeat 마다 위치/속도를 다시 고정
				pcall(function()
					v29.Responsiveness = 2000
					v30.Responsiveness = 2000
					v29.MaxVelocity = math.huge
				end)
				local holdConn
				holdConn = game:GetService("RunService").Heartbeat:Connect(function()
					if not (v29.Parent and v26.Parent and v23.Parent) then
						holdConn:Disconnect()
						return
					end
					v29.Position = (v23.CFrame * CFrame.new(options.BlobKickX.Value, options.BlobKickY.Value, options.BlobKickZ.Value)).Position
					pcall(tbl12.ResetVelocity, v26)
