						end
						tbl12.Grab(v26)
						task.wait()
					elseif tbl9.BKMethod == 1 then
						-- 빠르게: 잡기와 놓기를 같은 프레임에 연달아 (프레임당 2번)
						for _ = 1, 2 do
							v28.CreatureGrab:FireServer(nil, v26, v28.RightWeld)
							v28.CreatureDrop:FireServer(v28.RightWeld)
