					else
						v28.CreatureGrab:FireServer(nil, v26, v28.RightWeld)
						task.wait()
						v28.CreatureRelease:FireServer(v28.RightWeld)
						tbl12.Grab(v26)
						task.spawn(tbl12.Ragdoll, v25)

