			local EVADE_BIND = "8minBlobEvade"
			-- 서버에 보이는 가짜 위치 : 하늘 위 (낙사 판정 FallenPartsDestroyHeight 에 걸리지 않게 아래쪽이 아니라 위쪽)
			-- 상대 스크립트의 거리 제한(스폰에서 15000 / 원점에서 1,000,000)을 둘 다 넘도록 충분히 멀리
			local FAR_R, FAR_Y = 50000, 2000000
			local FAR_CHECK = 1000000

			local ours = setmetatable({}, { __mode = "k" })
			local memo = setmetatable({}, { __mode = "k" })
			local blobs = {}
			local lastScan, lastRel, relCount = -1e9, -1e9, 0
			local lastNote = {}
			local grabUntil, threatUntil, calmSince = 0, 0, os.clock()
			local ownLostAt = nil
			local evading, evadeHrp, evadeReal, evadeVel, evadeAng = false, nil, nil, Vector3.zero, 0
			local autoNet = false

			local guard = { On = false, Grab = false, GrabBy = nil, Near = false, NearBy = nil, Evading = false }
			tbl7.BlobGuard = guard
			tbl7.BlobGrab = false

			local function flagOn(key, default)
				local v = tbl8[key]
				if v == nil then
					return default
				end
				return v == true
			end

			local function label(owner)
				local p = owner and Players:FindFirstChild(owner)
				if p then
					return p.DisplayName .. " (@" .. p.Name .. ")"
				end
				return tostring(owner or "?")
			end

			local function note(key, text, kind, cooldown)
				if getgenv()._8minNotifyBlob == false then
					return
				end
				local now = os.clock()
				local last = lastNote[key]
				if last and now - last < (cooldown or 4) then
					return
				end
				lastNote[key] = now
				local f = getgenv()._8minNotify
				if f then
					pcall(f, text, "Blob Guard", kind or "warn")
				end
			end

			local function setNet(on)
				pcall(function()
					toggles.AntiInputLag:SetValue(on)
				end)
				if (tbl8.AntiInputLag == true) ~= on then
					pcall(tbl12.SetRuntimeToggle, "AntiInputLag", on)
				end
			end

			-- 남의 블롭맨 목록 (0.25초마다 갱신)
			local function rescan(now)
				local list = {}
				for _, folder in ipairs(workspace:GetChildren()) do
					local fname = folder.Name
					if #fname > SUFFIX_LEN and fname ~= OWN_FOLDER and string.sub(fname, -SUFFIX_LEN) == SUFFIX then
						for _, m in ipairs(folder:GetChildren()) do
							if m.Name == "CreatureBlobman" then
								local rd = m:FindFirstChild("RightDetector")
								local ld = m:FindFirstChild("LeftDetector")
								local bs = m:FindFirstChild("BlobmanSeatAndOwnerScript")
								local seat = m:FindFirstChild("VehicleSeat")
								local mm = memo[m]
								local ok, p = pcall(function()
									return (seat and seat.Position) or m:GetPivot().Position
								end)
								if ok and p then
									if not mm then
										mm = { Pos = p, Moved = now }
										memo[m] = mm
									elseif (p - mm.Pos).Magnitude > 3 then
										mm.Pos = p
										mm.Moved = now
									end
								end
								list[#list + 1] = {
									Model = m,
									Owner = string.sub(fname, 1, #fname - SUFFIX_LEN),
									Seat = seat,
									Memo = mm,
									RW = rd and rd:FindFirstChild("RightWeld"),
									RO = rd and rd:FindFirstChild("RightAlignOrientation"),
									LW = ld and ld:FindFirstChild("LeftWeld"),
									LO = ld and ld:FindFirstChild("LeftAlignOrientation"),
									Rel = bs and bs:FindFirstChild("CreatureRelease"),
									Drop = bs and bs:FindFirstChild("CreatureDrop"),
								}
							end
						end
					end
				end
				blobs = list
			end

			local function getAtts(c)
				return c.Attachment0, c.Attachment1
			end

			local function isOurs(att, char)
				if not att then
					return false
				end
				if ours[att] or att == tbl7.AntiBlobRootAtt then
					return true
				end
				return att:IsDescendantOf(char)
			end

			local function touches(c, char)
				if not c or not c.Parent then
					return false
				end
				local ok, a0, a1 = pcall(getAtts, c)
				if not ok then
					return false
				end
				return isOurs(a0, char) or isOurs(a1, char)
			end

			-- ===== Blob Evade : 서버에 보이는 위치만 먼 곳으로, 내 화면/조작은 진짜 위치 =====
			-- (Resonance 의 ClientVision 과 같은 방식: RenderStepped 에서 진짜 위치로 되돌리고, Heartbeat 에서 가짜 위치를 씀)
			local function stopEvade(restore)
				if not evading then
					return
				end
				evading = false
				guard.Evading = false
				pcall(RunService.UnbindFromRenderStep, RunService, EVADE_BIND)
				local h = evadeHrp
				if restore and h and h.Parent and evadeReal and h.Position.Y > FAR_CHECK then
					pcall(function()
						h.CFrame = evadeReal
						h.AssemblyLinearVelocity = evadeVel
					end)
				end
				evadeHrp, evadeReal = nil, nil
			end

			local function startEvade(hrp)
				if evading then
					return
				end
				evading = true
				guard.Evading = true
				evadeHrp, evadeReal, evadeVel = hrp, hrp.CFrame, hrp.AssemblyLinearVelocity
				pcall(RunService.UnbindFromRenderStep, RunService, EVADE_BIND)
				RunService:BindToRenderStep(EVADE_BIND, Enum.RenderPriority.Camera.Value - 1, function()
					if not evading or flag11 then
						pcall(RunService.UnbindFromRenderStep, RunService, EVADE_BIND)
						return
					end
					local h = evadeHrp
					-- 가짜 위치에 있을 때만 되돌린다 (평소 위치일 땐 건드리지 않음 → 캐릭터가 멈추는 일 방지)
					if h and h.Parent and evadeReal and h.Position.Y > FAR_CHECK then
						h.CFrame = evadeReal
						h.AssemblyLinearVelocity = evadeVel
					end
				end)
			end

			local function fakeStep(hrp, dt)
				if hrp.Position.Y < FAR_CHECK then
					evadeReal = hrp.CFrame
					evadeVel = hrp.AssemblyLinearVelocity
				end
				evadeAng = (evadeAng + dt * 9999) % 360
				local rad = math.rad(evadeAng)
				hrp.CFrame = CFrame.new(math.cos(rad) * FAR_R, FAR_Y, math.sin(rad) * FAR_R)
				hrp.AssemblyLinearVelocity = Vector3.zero
			end

			local function idle()
				if evading then
					stopEvade(true)
				end
				if autoNet then
					autoNet = false
					if tbl8.AntiInputLag then
						setNet(false)
					end
				end
				guard.Grab, guard.GrabBy, guard.Near, guard.NearBy = false, nil, false, nil
				tbl7.BlobGrab = false
				grabUntil, threatUntil, ownLostAt, relCount = 0, 0, nil, 0
			end

			local function neutralize(b, char)
				for _, c in ipairs({ b.RW, b.LW, b.RO, b.LO }) do
					if c and c.Parent and touches(c, char) then
						pcall(function()
							c.Enabled = false
						end)
					end
				end
			end

			local function step(dt)
				local now = os.clock()
				local char, hrp, hum = tbl12.Char()
				if not (char and hrp and hum) or hum.Health <= 0 then
					if evading then
						stopEvade(false)
					end
					guard.Grab, guard.Near = false, false
					tbl7.BlobGrab = false
					return
				end
				if evadeHrp and evadeHrp ~= hrp then
					stopEvade(false)
				end

				if now - lastScan >= 0.25 then
					lastScan = now
					rescan(now)
					local ra = hrp:FindFirstChild("RootAttachment")
					if ra and ra:IsA("Attachment") then
						ours[ra] = true
					end
				end

				local blobOn = tbl8.AntiBlobman == true
				local range = tbl9.BlobRange or 60
				local pos = hrp.Position
				if pos.Y > FAR_CHECK and evadeReal then
					pos = evadeReal.Position
				end

				-- 게임이 알려주는 "누가 잡고 있는지" (Head.PartOwner)
				local po = nil
				do
					local head = char:FindFirstChild("Head")
					local v = head and head:FindFirstChild("PartOwner")
					po = v and v.Value
					if po == "" or po == localPlayer.Name then
						po = nil
					end
				end

				-- 내 HRP 소유권을 잃었나 (ReceiveAge). Anti Network Ownership 가 켜져 있으면 원래 서버가 소유할 수 있어서 쓰지 않음
				local lost = false
				if not hum.SeatPart and not hrp.Anchored and not tbl8.AntiInputLag and not isHeld.Value and not tbl12.IsNetworkOwner(hrp) then
					ownLostAt = ownLostAt or now
					lost = (now - ownLostAt) > 0.2
				else
					ownLostAt = nil
				end

				local grabbing, grabBlob, grabCon = false, nil, nil
				local near, nearOwner, nearDist = false, nil, math.huge

				for i = 1, #blobs do
					local b = blobs[i]
					if b.Model.Parent then
						local seat = b.Seat
						local occupied = (seat == nil) or (seat.Parent ~= nil and seat.Occupant ~= nil)
						local d = math.huge
						if seat and seat.Parent then
							d = (seat.Position - pos).Magnitude
						end

						local con = nil
						if touches(b.RW, char) then
							con = b.RW
						elseif touches(b.LW, char) then
							con = b.LW
						elseif touches(b.RO, char) then
							con = b.RO
						elseif touches(b.LO, char) then
							con = b.LO
						end

						if con then
							grabbing, grabBlob, grabCon = true, b, con
						elseif occupied and d <= range * 1.5 and ((po and po == b.Owner) or lost) then
							grabbing, grabBlob = true, b
						end

						if occupied and d <= range then
							local mm = b.Memo
							if grabbing or not mm or now - mm.Moved < 8 then
								if d < nearDist then
									near, nearOwner, nearDist = true, b.Owner, d
								end
							end
						end
					end
				end

				-- 블롭맨이 아닌 잡기/Set Owner 킬: 내 몸 소유자 표시(PartOwner)가 있거나 소유권을 잃었으면 잡힌 걸로 보고 Anti Grab(Anti-Kill) 발동
				if not grabbing and tbl8.AntiGrab and (po or lost) then
					grabbing = true
					guard.GrabBy = po
				end

				-- ===== 잡힘 =====
				if grabbing then
					grabUntil = now + 0.8
					if grabBlob then
						guard.GrabBy = grabBlob.Owner
					end
				end
				local grabActive = now < grabUntil
				tbl7.BlobGrab = grabActive

				if grabActive and not guard.Grab then
					guard.Grab = true
					relCount = 0
					note("grab", label(guard.GrabBy) .. (grabBlob and "\nBlobman is grabbing you" or "\nSomeone is holding your body"), "fail", 3)
				elseif not grabActive and guard.Grab then
					guard.Grab = false
					relCount = 0
				end

				-- Anti Grab (Anti-Kill 등) 을 IsHeld 없이도 발동
				if grabActive and tbl8.AntiGrab and not tbl7.States["Anti Grab"] then
					pcall(tbl12.AntiGrab)
				end

				-- 반격 : 내 화면에서 상대 제약 무력화 + 서버에 해제 요청
				if grabActive and blobOn and grabBlob and flagOn("BlobCounter", true) then
					neutralize(grabBlob, char)
					if now - lastRel >= 0.05 and relCount < 60 then
						lastRel = now
						relCount += 1
						local b = grabBlob
						local weld = nil
						if grabCon == b.RW or grabCon == b.RO then
							weld = b.RW
						elseif grabCon == b.LW or grabCon == b.LO then
							weld = b.LW
						end
						if b.Rel then
							if weld then
								pcall(b.Rel.FireServer, b.Rel, weld)
							else
								if b.RW then
									pcall(b.Rel.FireServer, b.Rel, b.RW)
								end
								if b.LW then
									pcall(b.Rel.FireServer, b.Rel, b.LW)
								end
							end
						end
						if b.Drop and relCount % 2 == 0 then
							if weld then
								pcall(b.Drop.FireServer, b.Drop, weld)
							else
								if b.RW then
									pcall(b.Drop.FireServer, b.Drop, b.RW)
								end
								if b.LW then
									pcall(b.Drop.FireServer, b.Drop, b.LW)
								end
							end
						end
					end
				end

				-- ===== 접근 =====
				if blobOn and near then
					-- 회피 중에는 상대가 위치를 쫓아 왔다 갔다 해도 바로 풀리지 않게 더 오래 유지
					threatUntil = now + (evading and 3 or 1.5)
					if not guard.Near or guard.NearBy ~= nearOwner then
						guard.Near, guard.NearBy = true, nearOwner
						note("near:" .. tostring(nearOwner), label(nearOwner) .. "\nBlobman nearby (" .. math.floor(nearDist) .. " studs)", "warn", 15)
					end
				elseif guard.Near then
					guard.Near, guard.NearBy = false, nil
				end

				local threat = (blobOn and (now < threatUntil)) or (blobOn and grabActive)

				-- ===== Auto Anti Network Ownership =====
				if blobOn and flagOn("BlobAutoNet", false) then
					if threat then
						calmSince = now
						if not autoNet and not tbl8.AntiInputLag then
							autoNet = true
							setNet(true)
							note("net_on", "Anti Network Ownership ON (auto)", "info", 8)
						end
					elseif autoNet and now - calmSince > 4 then
						autoNet = false
						if tbl8.AntiInputLag then
							setNet(false)
						end
						note("net_off", "Anti Network Ownership OFF (auto)", "info", 8)
					end
				elseif autoNet then
					autoNet = false
					if tbl8.AntiInputLag then
						setNet(false)
					end
				end

				-- ===== Blob Evade =====
				local wantEvade = blobOn and tbl8.BlobEvade == true and threat and not hum.SeatPart and not tbl8.GucciAntiGrab
				if wantEvade then
					if not evading and hrp.Position.Y < FAR_CHECK then
						startEvade(hrp)
						note("evade_on", "Blob Evade ON\n" .. label((grabbing and grabBlob and grabBlob.Owner) or nearOwner or guard.GrabBy or guard.NearBy), "warn", 3)
					end
				elseif evading then
					stopEvade(true)
					note("evade_off", "Blob Evade OFF", "info", 3)
				end
				if evading then
					fakeStep(hrp, dt)
				end
			end

			local conn
			conn = RunService.Heartbeat:Connect(function(dt)
				if flag11 then
					pcall(idle)
					conn:Disconnect()
					return
				end
				if not (tbl8.AntiBlobman or tbl8.AntiGrab) then
					if guard.On then
						guard.On = false
						pcall(idle)
					end
					return
				end
				guard.On = true
				local ok, err = pcall(step, dt)
				if not ok then
					pcall(idle)
					if not guard.Failed then
						guard.Failed = true
						warn("[Blob Guard] " .. tostring(err))
					end
				end
			end)
		end)

		task.spawn(function()
			local v22 = nil
			local v23 = nil

			while true do
				task.wait(tbl9.InputLgDelay)

				if flag11 then
					if v22 then
						tbl12.DestroyToy(v22)
					end

					return
				else
					if not tbl8.AntiInputLag then
						if v22 then
							tbl12.DestroyToy(v22)
							v22 = nil
						end

						if not tbl12.WaitForRuntimeToggle("AntiInputLag") then
							break
						end
					end

					if not v23 or not v23.Parent then
						v23 = tbl12.DisableEndGrabEarly()
					end

					local v24, v25, v26 = tbl12.Char()

					if not v22 or not v22.Parent then
						v22 = tbl12.SpawnToy(tbl9.AntiInputType, CFrame.new(0, 1e20, 0), nil, true)
						if not v22 then
							continue
						end
					end

					local holdPart = v22 and v22:WaitForChild("HoldPart", 2)
					local holdItemRemoteFunction = holdPart and holdPart:WaitForChild("HoldItemRemoteFunction", 2)
					local dropItemRemoteFunction = holdItemRemoteFunction and holdPart:WaitForChild("DropItemRemoteFunction", 2)

					if v22.Name ~= tbl9.AntiInputType then
						tbl12.DestroyToy(v22)
					end

					pcall(function()
						if holdPart.RigidConstraint.Attachment1 ~= v24["Left Arm"].LeftGripAttachment and holdPart.RigidConstraint.Attachment1 ~= nil and holdPart.RigidConstraint.Attachment1 ~= v24["Right Arm"].RightGripAttachment then
							tbl12.DestroyToy(v22)
						end
					end)

					task.spawn(function()
						for _, v27 in pairs(v22:QueryDescendants("BasePart")) do
							v27.CanCollide = false

							if v27:IsA("MeshPart") or v27.Name == "Part" then
								v27.Transparency = tbl9.AILTransparency
							end
						end
					end)

					if v24 and v26 and v26.Health ~= 0 and holdItemRemoteFunction and dropItemRemoteFunction then
						task.spawn(function()
							local vector = Vector3.new
							dropItemRemoteFunction:InvokeServer(v22, CFrame.new(0, 1e20, 0), vector())
						end)

						task.spawn(function()
							holdItemRemoteFunction:InvokeServer(v22, v24)
						end)
					elseif not holdItemRemoteFunction or not dropItemRemoteFunction then
						tbl12.DestroyToy(v22)
						v22 = nil
					end
				end
			end
		end)

		if not tbl11.Explode then
			return
		end

		workspace.ChildAdded:Connect(function(child)
			local v22, v23, v24 = tbl12.Char()

			if child.Name == "Part" and tbl8.AntiExplosion and v23 and v24 then
				if (child.Position - v23.Position).Magnitude <= 20 then
					v23.Anchored = true
					task.wait(0.02)

					if not v24.SeatPart then
						v24.Sit = false
					end

					for _, v25 in pairs(v22:QueryDescendants("#RagdollLimbPart")) do
						v25.CanCollide = false
					end

					tbl12.ResetVelocity(v23)
					v23.Anchored = false
				end
			end
		end)

		task.spawn(function()
			local extinguishPart = map.Hole.PoisonSmallHole:FindFirstChild("ExtinguishPart")
			if not extinguishPart then
				return
			end

			if extinguishPart:FindFirstChild("Tex") then
				extinguishPart.Tex:Destroy()
			end

			extinguishPart.Transparency = 1

			local function fn21(character)
				if flag11 then
					return
				end
				local humanoidRootPart = character:WaitForChild("HumanoidRootPart", 2)
				if not humanoidRootPart then
					return
				end

				humanoidRootPart.ChildAdded:Connect(function(child)
					if flag11 then
						return
					end

					if child.Name == "FireParticleEmitter" and tbl8.AntiBurn then
						local cFrame2 = extinguishPart.CFrame
						local fireLight = humanoidRootPart:FindFirstChild("FireLight")

						if fireLight then
							fireLight:Destroy()
						end

						child.Enabled = false
						local screenOverlayGui = playerGui:FindFirstChild("ScreenOverlayGui")
						screenOverlayGui = screenOverlayGui and screenOverlayGui:FindFirstChild("FireFade")

						if screenOverlayGui then
							screenOverlayGui.Visible = false
						end

						while true do
							extinguishPart.CFrame = humanoidRootPart.CFrame
							task.wait()
							if not (not child.Parent or not humanoidRootPart.Parent) then
								continue
							end
							break
						end

						extinguishPart.CFrame = cFrame2
					end
				end)
			end

			localPlayer.CharacterAdded:Connect(fn21)
			local v22 = tbl12.Char()

			if v22 then
				fn21(v22)
			end
		end)

		task.spawn(function()
			while task.wait(0.03) do
				if flag11 then
					return
				end

				if not tbl8.AntiVoid and not tbl12.WaitForRuntimeToggle("AntiVoid") then
					return
				end
				local v22, v23 = tbl12.Char()
				local flag12

				if v23 then
					flag12 = v23.Position.Y >= 10000 or v23.Position.Y <= -500
				else
					flag12 = v23
				end

				flag12 = flag12 and not ((v23.Position - part3.Position).Magnitude < 150)

				if flag12 then
					tbl12.Teleport(v23, CFrame.new(0, 15, 0))
				end
			end
		end)

		do
			local function fn21()
				local n36 = os.clock() + 0.35

				repeat
					local v22 = tbl12.DetectPCLD(localPlayer)
					if v22 and v22.Parent and not tbl12.IsWaitingPCLD(v22) then
						return v22
					end
					task.wait(0.05)
				until flag11 or not tbl8.AntiKick or os.clock() >= n36
			end

			local function fn22(arg)
				local NinjaShuriken = tbl12.SpawnToy("NinjaShuriken", arg.CFrame + Vector3.new(0, 15, 0), 3, true)
				local stickyPart = NinjaShuriken and NinjaShuriken:WaitForChild("StickyPart", 1.5)
				local stickyWeld = stickyPart and stickyPart:WaitForChild("StickyWeld", 1.5)
				if stickyPart and stickyWeld and tbl12.SNO(stickyPart) then
					return NinjaShuriken, stickyPart, stickyWeld
				end
				tbl12.DestroyToy(NinjaShuriken)
			end

			task.spawn(function()
				while task.wait(0.03) do
					if flag11 then
						return
					end

					if not tbl8.AntiKick then
						if v18 then
							tbl12.DestroyToy(v18)
							v18 = nil
						end

						if not tbl12.WaitForRuntimeToggle("AntiKick") then
							return
						end
					end

					local antiKickSettings = tbl7.AntiKickSettings
					local v22, v23, v24 = tbl12.Char()
					local ragdollTouchedHitbox = v23 and v23:FindFirstChild("RagdollTouchedHitbox")

					if v23 and v24 and ragdollTouchedHitbox and v24.Health > 0 then
						if localPlayer.InPlot.Value then
							while true do
								task.wait()
								if not (not localPlayer.InPlot.Value or localPlayer.InOwnedPlot.Value) then
									continue
								end
								break
							end
						end

						if tbl9.AKType == "Shuriken" then
